values
('ps-7-5','ps','시편',7,5,'원수가 나의 영혼을 쫓아 잡아 내 생명을 땅에 짓밟게 하고 내 영광을 먼지 속에 살게 하소서 (셀라)',14001),
('ps-7-6','ps','시편',7,6,'여호와여 진노로 일어나사 내 대적들의 노를 막으시며 나를 위하여 깨소서 주께서 심판을 명령하셨나이다',14002),
('ps-7-7','ps','시편',7,7,'민족들의 모임이 주를 두르게 하시고 그 위 높은 자리에 돌아오소서',14003),
('ps-7-8','ps','시편',7,8,'여호와께서 만민에게 심판을 행하시오니 여호와여 나의 의와 나의 성실함을 따라 나를 심판하소서',14004),
('ps-7-9','ps','시편',7,9,'악인의 악을 끊고 의인을 세우소서 의로우신 하나님이 사람의 마음과 양심을 감찰하시나이다',14005),
('ps-7-10','ps','시편',7,10,'나의 방패는 마음이 정직한 자를 구원하시는 하나님께 있도다',14006),
('ps-7-11','ps','시편',7,11,'하나님은 의로우신 재판장이심이여 매일 분노하시는 하나님이시로다',14007),
('ps-7-12','ps','시편',7,12,'사람이 회개하지 아니하면 그가 그의 칼을 가심이여 그의 활을 이미 당기어 예비하셨도다',14008),
('ps-7-13','ps','시편',7,13,'죽일 도구를 또한 예비하심이여 그가 만든 화살은 불화살들이로다',14009),
('ps-7-14','ps','시편',7,14,'악인이 죄악을 낳음이여 재앙을 배어 거짓을 낳았도다',14010),
('ps-7-15','ps','시편',7,15,'그가 웅덩이를 파 만듦이여 제가 만든 함정에 빠졌도다',14011),
('ps-7-16','ps','시편',7,16,'그의 재앙은 자기 머리로 돌아가고 그의 포악은 자기 정수리에 내리리로다',14012),
('ps-7-17','ps','시편',7,17,'내가 여호와께 그의 의를 따라 감사함이여 지존하신 여호와의 이름을 찬양하리로다',14013),
('ps-8-1','ps','시편',8,1,'여호와 우리 주여 주의 이름이 온 땅에 어찌 그리 아름다운지요 주의 영광이 하늘을 덮었나이다',14014),
('ps-8-2','ps','시편',8,2,'주의 대적으로 말미암아 어린 아이들과 젖먹이들의 입으로 권능을 세우심이여 이는 원수들과 보복자들을 잠잠하게 하려 하심이니이다',14015),
('ps-8-3','ps','시편',8,3,'주의 손가락으로 만드신 주의 하늘과 주께서 베풀어 두신 달과 별들을 내가 보오니',14016),
('ps-8-4','ps','시편',8,4,'사람이 무엇이기에 주께서 그를 생각하시며 인자가 무엇이기에 주께서 그를 돌보시나이까',14017),
('ps-8-5','ps','시편',8,5,'그를 하나님보다 조금 못하게 하시고 영화와 존귀로 관을 씌우셨나이다',14018),
('ps-8-6','ps','시편',8,6,'주의 손으로 만드신 것을 다스리게 하시고 만물을 그의 발 아래 두셨으니',14019),
('ps-8-7','ps','시편',8,7,'곧 모든 소와 양과 들짐승이며',14020),
('ps-8-8','ps','시편',8,8,'공중의 새와 바다의 물고기와 바닷길에 다니는 것이니이다',14021),
('ps-8-9','ps','시편',8,9,'여호와 우리 주여 주의 이름이 온 땅에 어찌 그리 아름다운지요',14022),
('ps-9-1','ps','시편',9,1,'내가 전심으로 여호와께 감사하오며 주의 모든 기이한 일들을 전하리이다',14023),
('ps-9-2','ps','시편',9,2,'내가 주를 기뻐하고 즐거워하며 지존하신 주의 이름을 찬송하리니',14024),
('ps-9-3','ps','시편',9,3,'내 원수들이 물러갈 때에 주 앞에서 넘어져 망함이니이다',14025),
('ps-9-4','ps','시편',9,4,'주께서 나의 의와 송사를 변호하셨으며 보좌에 앉으사 의롭게 심판하셨나이다',14026),
('ps-9-5','ps','시편',9,5,'이방 나라들을 책망하시고 악인을 멸하시며 그들의 이름을 영원히 지우셨나이다',14027),
('ps-9-6','ps','시편',9,6,'원수가 끊어져 영원히 멸망하였사오니 주께서 무너뜨린 성읍들을 기억할 수 없나이다',14028),
('ps-9-7','ps','시편',9,7,'여호와께서 영원히 앉으심이여 심판을 위하여 보좌를 준비하셨도다',14029),
('ps-9-8','ps','시편',9,8,'공의로 세계를 심판하심이여 정직으로 만민에게 판결을 내리시리로다',14030),
('ps-9-9','ps','시편',9,9,'여호와는 압제를 당하는 자의 요새이시요 환난 때의 요새이시로다',14031),
('ps-9-10','ps','시편',9,10,'여호와여 주의 이름을 아는 자는 주를 의지하오리니 이는 주를 찾는 자들을 버리지 아니하심이니이다',14032),
('ps-9-11','ps','시편',9,11,'너희는 시온에 계신 여호와를 찬송하며 그의 행사를 백성 중에 선포할지어다',14033),
('ps-9-12','ps','시편',9,12,'피 흘림을 심문하시는 이가 그들을 기억하심이여 가난한 자의 부르짖음을 잊지 아니하시도다',14034),
('ps-9-13','ps','시편',9,13,'여호와여 내게 은혜를 베푸소서 나를 사망의 문에서 일으키시는 주여 나를 미워하는 자에게서 받는 나의 고통을 보소서',14035),
('ps-9-14','ps','시편',9,14,'그리하시면 내가 주의 찬송을 다 전할 것이요 딸 시온의 문에서 주의 구원을 기뻐하리이다',14036),
('ps-9-15','ps','시편',9,15,'이방 나라들은 자기가 판 웅덩이에 빠짐이여 자기가 숨긴 그물에 자기 발이 걸렸도다',14037),
('ps-9-16','ps','시편',9,16,'여호와께서 자기를 알게 하사 심판을 행하셨음이여 악인은 자기가 손으로 행한 일에 스스로 얽혔도다 (힉가욘, 셀라)',14038),
('ps-9-17','ps','시편',9,17,'악인들이 스올로 돌아감이여 하나님을 잊어버린 모든 이방 나라들이 그리하리로다',14039),
('ps-9-18','ps','시편',9,18,'궁핍한 자가 항상 잊어버림을 당하지 아니함이여 가난한 자들이 영원히 실망하지 아니하리로다',14040),
('ps-9-19','ps','시편',9,19,'여호와여 일어나사 인생으로 승리를 얻지 못하게 하시며 이방 나라들이 주 앞에서 심판을 받게 하소서',14041),
('ps-9-20','ps','시편',9,20,'여호와여 그들을 두렵게 하시며 이방 나라들이 자기는 인생일 뿐인 줄 알게 하소서 (셀라)',14042),
('ps-10-1','ps','시편',10,1,'여호와여 어찌하여 멀리 서시며 어찌하여 환난 때에 숨으시나이까',14043),
('ps-10-2','ps','시편',10,2,'악한 자가 교만하여 가련한 자를 심히 압박하오니 그들이 자기가 베푼 꾀에 빠지게 하소서',14044),
('ps-10-3','ps','시편',10,3,'악인은 그의 마음의 욕심을 자랑하며 탐욕을 부리는 자는 여호와를 배반하여 멸시하나이다',14045),
('ps-10-4','ps','시편',10,4,'악인은 그의 교만한 얼굴로 말하기를 여호와께서 이를 감찰하지 아니하신다 하며 그의 모든 사상에 하나님이 없다 하나이다',14046),
('ps-10-5','ps','시편',10,5,'그의 길은 언제든지 견고하고 주의 심판은 높아서 그에게 미치지 못하오니 그는 그의 모든 대적들을 멸시하며',14047),
('ps-10-6','ps','시편',10,6,'그의 마음에 이르기를 나는 흔들리지 아니하며 대대로 환난을 당하지 아니하리라 하나이다',14048),
('ps-10-7','ps','시편',10,7,'그의 입에는 저주와 거짓과 포악이 충만하며 그의 혀 밑에는 잔해와 죄악이 있나이다',14049),
('ps-10-8','ps','시편',10,8,'그가 마을 구석진 곳에 앉으며 그 은밀한 곳에서 무죄한 자를 죽이며 그의 눈은 가련한 자를 엿보나이다',14050),
('ps-10-9','ps','시편',10,9,'사자가 자기의 굴에 엎드림 같이 그가 은밀한 곳에 엎드려 가련한 자를 잡으려고 기다리며 자기 그물을 끌어당겨 가련한 자를 잡나이다',14051),
('ps-10-10','ps','시편',10,10,'그가 구푸려 엎드리니 그의 포악으로 말미암아 가련한 자들이 넘어지나이다',14052),
('ps-10-11','ps','시편',10,11,'그가 그의 마음에 이르기를 하나님이 잊으셨고 그의 얼굴을 가리셨으니 영원히 보지 아니하시리라 하나이다',14053),
('ps-10-12','ps','시편',10,12,'여호와여 일어나옵소서 하나님이여 손을 드옵소서 가난한 자들을 잊지 마옵소서',14054),
('ps-10-13','ps','시편',10,13,'어찌하여 악인이 하나님을 멸시하여 그의 마음에 이르기를 주는 감찰하지 아니하리라 하나이까',14055),
('ps-10-14','ps','시편',10,14,'주께서는 보셨나이다 주는 재앙과 원한을 감찰하시고 주의 손으로 갚으려 하시오니 외로운 자가 주를 의지하나이다 주는 벌써부터 고아를 도우시는 이시니이다',14056),
('ps-10-15','ps','시편',10,15,'악인의 팔을 꺾으소서 악한 자의 악을 더 이상 찾아낼 수 없을 때까지 찾으소서',14057),
('ps-10-16','ps','시편',10,16,'여호와께서는 영원무궁하도록 왕이시니 이방 나라들이 주의 땅에서 멸망하였나이다',14058),
('ps-10-17','ps','시편',10,17,'여호와여 주는 겸손한 자의 소원을 들으셨사오니 그들의 마음을 준비하시며 귀를 기울여 들으시고',14059),
('ps-10-18','ps','시편',10,18,'고아와 압제 당하는 자를 위하여 심판하사 세상에 속한 자가 다시는 위협하지 못하게 하시리이다',14060),
('ps-11-1','ps','시편',11,1,'내가 여호와께 피하였거늘 너희가 내 영혼에게 새 같이 네 산으로 도망하라 함은 어찌함인가',14061),
('ps-11-2','ps','시편',11,2,'악인이 활을 당기고 화살을 시위에 먹임이여 마음이 바른 자를 어두운 데서 쏘려 하는도다',14062),
('ps-11-3','ps','시편',11,3,'터가 무너지면 의인이 무엇을 하랴',14063),
('ps-11-4','ps','시편',11,4,'여호와께서는 그의 성전에 계시고 여호와의 보좌는 하늘에 있음이여 그의 눈이 인생을 통촉하시고 그의 안목이 그들을 감찰하시도다',14064),
('ps-11-5','ps','시편',11,5,'여호와는 의인을 감찰하시고 악인과 폭력을 좋아하는 자를 마음에 미워하시도다',14065),
('ps-11-6','ps','시편',11,6,'악인에게 그물을 던지시리니 불과 유황과 태우는 바람이 그들의 잔의 소득이 되리로다',14066),
('ps-11-7','ps','시편',11,7,'여호와는 의로우사 의로운 일을 좋아하시나니 정직한 자는 그의 얼굴을 뵈오리로다',14067),
('ps-12-1','ps','시편',12,1,'여호와여 도우소서 경건한 자가 끊어지며 충실한 자들이 인생 중에 없어지나이다',14068),
('ps-12-2','ps','시편',12,2,'그들이 이웃에게 각기 거짓을 말함이여 아첨하는 입술과 두 마음으로 말하는도다',14069),
('ps-12-3','ps','시편',12,3,'여호와께서 모든 아첨하는 입술과 자랑하는 혀를 끊으시리니',14070),
('ps-12-4','ps','시편',12,4,'그들이 말하기를 우리의 혀가 이기리라 우리 입술은 우리 것이니 우리를 주관할 자 누구리요 함이로다',14071),
('ps-12-5','ps','시편',12,5,'여호와의 말씀에 가련한 자들의 눌림과 궁핍한 자들의 탄식으로 말미암아 내가 이제 일어나 그를 그가 원하는 안전한 지대에 두리라 하시도다',14072),
('ps-12-6','ps','시편',12,6,'여호와의 말씀은 순결함이여 흙 도가니에 일곱 번 단련한 은 같도다',14073),
('ps-12-7','ps','시편',12,7,'여호와여 그들을 지키사 이 세대로부터 영원까지 보존하시리이다',14074),
('ps-12-8','ps','시편',12,8,'비열함이 인생 중에 높임을 받는 때에 악인들이 곳곳에서 날뛰는도다',14075),
('ps-13-1','ps','시편',13,1,'여호와여 어느 때까지니이까 나를 영원히 잊으시나이까 주의 얼굴을 나에게서 어느 때까지 숨기시겠나이까',14076),
('ps-13-2','ps','시편',13,2,'나의 영혼이 번민하고 종일토록 마음에 근심하기를 어느 때까지 하오며 내 원수가 나를 치며 자랑하기를 어느 때까지 하리이까',14077),
('ps-13-3','ps','시편',13,3,'여호와 내 하나님이여 나를 생각하사 응답하시고 나의 눈을 밝히소서 두렵건대 내가 사망의 잠을 잘까 하오며',14078),
('ps-13-4','ps','시편',13,4,'두렵건대 나의 원수가 이르기를 내가 그를 이겼다 할까 하오며 내가 흔들릴 때에 나의 대적들이 기뻐할까 하나이다',14079),
('ps-13-5','ps','시편',13,5,'나는 오직 주의 사랑을 의지하였사오니 나의 마음은 주의 구원을 기뻐하리이다',14080),
('ps-13-6','ps','시편',13,6,'내가 여호와를 찬송하리니 이는 주께서 내게 은덕을 베푸심이로다',14081),
('ps-14-1','ps','시편',14,1,'어리석은 자는 그의 마음에 이르기를 하나님이 없다 하는도다 그들은 부패하고 그 행실이 가증하니 선을 행하는 자가 없도다',14082),
('ps-14-2','ps','시편',14,2,'여호와께서 하늘에서 인생을 굽어살피사 지각이 있어 하나님을 찾는 자가 있는가 보려 하신즉',14083),
('ps-14-3','ps','시편',14,3,'다 치우쳐 함께 더러운 자가 되고 선을 행하는 자가 없으니 하나도 없도다',14084),
('ps-14-4','ps','시편',14,4,'죄악을 행하는 자는 다 무지하냐 그들이 떡 먹듯이 내 백성을 먹으면서 여호와를 부르지 아니하는도다',14085),
('ps-14-5','ps','시편',14,5,'그러나 거기서 그들은 두려워하고 두려워하였으니 하나님이 의인의 세대에 계심이로다',14086),
