('sng-1-3','sng','아가',1,3,'네 기름이 향기로워 아름답고 네 이름이 쏟은 향기름 같으므로 처녀들이 너를 사랑하는구나',17541),
('sng-1-4','sng','아가',1,4,'왕이 나를 그의 방으로 이끌어 들이시니 너는 나를 인도하라 우리가 너를 따라 달려가리라 우리가 너로 말미암아 기뻐하며 즐거워하니 네 사랑이 포도주보다 더 진함이라 처녀들이 너를 사랑함이 마땅하니라',17542),
('sng-1-5','sng','아가',1,5,'예루살렘 딸들아 내가 비록 검으나 아름다우니 게달의 장막 같을지라도 솔로몬의 휘장과도 같구나',17543),
