('sng-2-16','sng','아가',2,16,'내 사랑하는 자는 내게 속하였고 나는 그에게 속하였도다 그가 백합화 가운데에서 양 떼를 먹이는구나',17571),
('sng-2-17','sng','아가',2,17,'내 사랑하는 자야 날이 저물고 그림자가 사라지기 전에 돌아와서 베데르 산의 노루와 어린 사슴 같을지라',17572),
('sng-3-1','sng','아가',3,1,'내가 밤에 침상에서 마음으로 사랑하는 자를 찾았노라 찾아도 찾아내지 못하였노라',17573),
('sng-3-2','sng','아가',3,2,'이에 내가 일어나서 성 안을 돌아다니며 마음에 사랑하는 자를 거리에서나 큰 길에서나 찾으리라 하고 찾으나 만나지 못하였노라',17574),
('sng-3-3','sng','아가',3,3,'성 안을 순찰하는 자들을 만나서 묻기를 내 마음으로 사랑하는 자를 너희가 보았느냐 하고',17575),
