('sng-4-14','sng','아가',4,14,'나도와 번홍화와 창포와 계수와 각종 유향목과 몰약과 침향과 모든 귀한 향품이요',17597),
('sng-4-15','sng','아가',4,15,'너는 동산의 샘이요 생수의 우물이요 레바논에서부터 흐르는 시내로구나',17598),
('sng-4-16','sng','아가',4,16,'북풍아 일어나라 남풍아 오라 나의 동산에 불어서 향기를 날리라 나의 사랑하는 자가 그 동산에 들어가서 그 아름다운 열매 먹기를 원하노라',17599),
('sng-5-1','sng','아가',5,1,'내 누이, 내 신부야 내가 내 동산에 들어와서 나의 몰약과 향 재료를 거두고 나의 꿀송이와 꿀을 먹고 내 포도주와 내 우유를 마셨으니 나의 친구들아 먹으라 나의 사랑하는 사람들아 많이 마시라',17600),
('sng-5-2','sng','아가',5,2,'내가 잘지라도 마음은 깨었는데 나의 사랑하는 자의 소리가 들리는구나 문을 두드려 이르기를 나의 누이, 나의 사랑, 나의 비둘기, 나의 완전한 자야 문을 열어 다오 내 머리에는 이슬이, 내 머리털에는 밤이슬이 가득하였다 하는구나',17601),
('sng-5-3','sng','아가',5,3,'내가 옷을 벗었으니 어찌 다시 입겠으며 내가 발을 씻었으니 어찌 다시 더럽히랴마는',17602),
('sng-5-4','sng','아가',5,4,'내 사랑하는 자가 문틈으로 손을 들이밀매 내 마음이 움직여서',17603),
('sng-5-5','sng','아가',5,5,'일어나 내 사랑하는 자를 위하여 문을 열 때 몰약이 내 손에서, 몰약의 즙이 내 손가락에서 문빗장에 떨어지는구나',17604),
('sng-5-6','sng','아가',5,6,'내가 내 사랑하는 자를 위하여 문을 열었으나 그는 벌써 물러갔네 그가 말할 때에 내 혼이 나갔구나 내가 그를 찾아도 못 만났고 불러도 응답이 없었노라',17605),
('sng-5-7','sng','아가',5,7,'성 안을 순찰하는 자들이 나를 만나매 나를 쳐서 상하게 하였고 성벽을 파수하는 자들이 나의 겉옷을 벗겨 가졌도다',17606),
('sng-5-8','sng','아가',5,8,'예루살렘 딸들아 너희에게 내가 부탁한다 너희가 내 사랑하는 자를 만나거든 내가 사랑하므로 병이 났다고 하려무나',17607),
('sng-5-9','sng','아가',5,9,'여자들 가운데에 어여쁜 자야 너의 사랑하는 자가 남의 사랑하는 자보다 나은 것이 무엇인가 너의 사랑하는 자가 남의 사랑하는 자보다 나은 것이 무엇이기에 이같이 우리에게 부탁하는가',17608),
('sng-5-10','sng','아가',5,10,'내 사랑하는 자는 희고도 붉어 많은 사람 가운데에 뛰어나구나',17609),
('sng-5-11','sng','아가',5,11,'머리는 순금 같고 머리털은 고불고불하고 까마귀 같이 검구나',17610),
('sng-5-12','sng','아가',5,12,'눈은 시냇가의 비둘기 같은데 우유로 씻은 듯하고 아름답게도 박혔구나',17611),
('sng-5-13','sng','아가',5,13,'뺨은 향기로운 꽃밭 같고 향기로운 풀언덕과도 같고 입술은 백합화 같고 몰약의 즙이 뚝뚝 떨어지는구나',17612),
('sng-5-14','sng','아가',5,14,'손은 황옥을 물린 황금 노리개 같고 몸은 아로새긴 상아에 청옥을 입힌 듯하구나',17613),
('sng-5-15','sng','아가',5,15,'다리는 순금 받침에 세운 화반석 기둥 같고 생김새는 레바논 같으며 백향목처럼 보기 좋고',17614),
('sng-5-16','sng','아가',5,16,'입은 심히 달콤하니 그 전체가 사랑스럽구나 예루살렘 딸들아 이는 내 사랑하는 자요 나의 친구로다',17615),
('sng-6-1','sng','아가',6,1,'여자들 가운데에서 어여쁜 자야 네 사랑하는 자가 어디로 갔는가 네 사랑하는 자가 어디로 돌아갔는가 우리가 너와 함께 찾으리라',17616),
('sng-6-2','sng','아가',6,2,'내 사랑하는 자가 자기 동산으로 내려가 향기로운 꽃밭에 이르러서 동산 가운데에서 양 떼를 먹이며 백합화를 꺾는구나',17617),
('sng-6-3','sng','아가',6,3,'나는 내 사랑하는 자에게 속하였고 내 사랑하는 자는 내게 속하였으며 그가 백합화 가운데에서 그 양 떼를 먹이는도다',17618),
('sng-6-4','sng','아가',6,4,'내 사랑아 너는 디르사 같이 어여쁘고, 예루살렘 같이 곱고, 깃발을 세운 군대 같이 당당하구나',17619),
('sng-6-5','sng','아가',6,5,'네 눈이 나를 놀라게 하니 돌이켜 나를 보지 말라 네 머리털은 길르앗 산 기슭에 누운 염소 떼 같고',17620),
('sng-6-6','sng','아가',6,6,'네 이는 목욕하고 나오는 암양 떼 같으니 쌍태를 가졌으며 새끼 없는 것은 하나도 없구나',17621),
('sng-6-7','sng','아가',6,7,'너울 속의 네 뺨은 석류 한 쪽 같구나',17622),
('sng-6-8','sng','아가',6,8,'왕비가 육십 명이요 후궁이 팔십 명이요 시녀가 무수하되',17623),
('sng-6-9','sng','아가',6,9,'내 비둘기, 내 완전한 자는 하나뿐이로구나 그는 그의 어머니의 외딸이요 그 낳은 자가 귀중하게 여기는 자로구나 여자들이 그를 보고 복된 자라 하고 왕비와 후궁들도 그를 칭찬하는구나',17624),
('sng-6-10','sng','아가',6,10,'아침 빛 같이 뚜렷하고 달 같이 아름답고 해 같이 맑고 깃발을 세운 군대 같이 당당한 여자가 누구인가',17625),
('sng-6-11','sng','아가',6,11,'골짜기의 푸른 초목을 보려고 포도나무가 순이 났는가 석류나무가 꽃이 피었는가 알려고 내가 호도 동산으로 내려갔을 때에',17626),
('sng-6-12','sng','아가',6,12,'부지중에 내 마음이 나를 내 귀한 백성의 수레 가운데에 이르게 하였구나',17627),
('sng-6-13','sng','아가',6,13,'돌아오고 돌아오라 술람미 여자야 돌아오고 돌아오라 우리가 너를 보게 하라 너희가 어찌하여 마하나임에서 춤추는 것을 보는 것처럼 술람미 여자를 보려느냐',17628),
('sng-7-1','sng','아가',7,1,'귀한 자의 딸아 신을 신은 네 발이 어찌 그리 아름다운가 네 넓적다리는 둥글어서 숙련공의 손이 만든 구슬 꿰미 같구나',17629),
('sng-7-2','sng','아가',7,2,'배꼽은 섞은 포도주를 가득히 부은 둥근 잔 같고 허리는 백합화로 두른 밀단 같구나',17630),
('sng-7-3','sng','아가',7,3,'두 유방은 암사슴의 쌍태 새끼 같고',17631),
('sng-7-4','sng','아가',7,4,'목은 상아 망대 같구나 눈은 헤스본 바드랍빔 문 곁에 있는 연못 같고 코는 다메섹을 향한 레바논 망대 같구나',17632),
('sng-7-5','sng','아가',7,5,'머리는 갈멜 산 같고 드리운 머리털은 자주 빛이 있으니 왕이 그 머리카락에 매이었구나',17633),
('sng-7-6','sng','아가',7,6,'사랑아 네가 어찌 그리 아름다운지, 어찌 그리 화창한지 즐겁게 하는구나',17634),
('sng-7-7','sng','아가',7,7,'네 키는 종려나무 같고 네 유방은 그 열매송이 같구나',17635),
('sng-7-8','sng','아가',7,8,'내가 말하기를 종려나무에 올라가서 그 가지를 잡으리라 하였나니 네 유방은 포도송이 같고 네 콧김은 사과 냄새 같고',17636),
('sng-7-9','sng','아가',7,9,'네 입은 좋은 포도주 같을 것이니라. 이 포도주는 내 사랑하는 자를 위하여 미끄럽게 흘러내려서 자는 자의 입을 움직이게 하느니라',17637),
('sng-7-10','sng','아가',7,10,'나는 내 사랑하는 자에게 속하였도다 그가 나를 사모하는구나',17638),
('sng-7-11','sng','아가',7,11,'내 사랑하는 자야 우리가 함께 들로 가서 동네에서 유숙하자',17639),
('sng-7-12','sng','아가',7,12,'우리가 일찍이 일어나서 포도원으로 가서 포도 움이 돋았는지, 꽃술이 퍼졌는지, 석류 꽃이 피었는지 보자 거기에서 내가 내 사랑을 네게 주리라',17640),
('sng-7-13','sng','아가',7,13,'합환채가 향기를 뿜어내고 우리의 문 앞에는 여러 가지 귀한 열매가 새 것, 묵은 것으로 마련되었구나 내가 내 사랑하는 자 너를 위하여 쌓아 둔 것이로다',17641),
('sng-8-1','sng','아가',8,1,'네가 내 어머니의 젖을 먹은 오라비 같았더라면 내가 밖에서 너를 만날 때에 입을 맞추어도 나를 업신여길 자가 없었을 것이라',17642),
('sng-8-2','sng','아가',8,2,'내가 너를 이끌어 내 어머니 집에 들이고 네게서 교훈을 받았으리라 나는 향기로운 술 곧 석류즙으로 네게 마시게 하겠고',17643),
('sng-8-3','sng','아가',8,3,'너는 왼팔로는 내 머리를 고이고 오른손으로는 나를 안았으리라',17644),
('sng-8-4','sng','아가',8,4,'예루살렘 딸들아 내가 너희에게 부탁한다 내 사랑하는 자가 원하기 전에는 흔들지 말며 깨우지 말지니라',17645),
('sng-8-5','sng','아가',8,5,'그의 사랑하는 자를 의지하고 거친 들에서 올라오는 여자가 누구인가. 너로 말미암아 네 어머니가 고생한 곳 너를 낳은 자가 애쓴 그 곳 사과나무 아래에서 내가 너를 깨웠노라',17646),
('sng-8-6','sng','아가',8,6,'너는 나를 도장 같이 마음에 품고 도장 같이 팔에 두라 사랑은 죽음 같이 강하고 질투는 스올 같이 잔인하며 불길 같이 일어나니 그 기세가 여호와의 불과 같으니라',17647),
('sng-8-7','sng','아가',8,7,'많은 물도 이 사랑을 끄지 못하겠고 홍수라도 삼키지 못하나니 사람이 그의 온 가산을 다 주고 사랑과 바꾸려 할지라도 오히려 멸시를 받으리라',17648),
('sng-8-8','sng','아가',8,8,'우리에게 있는 작은 누이는 아직도 유방이 없구나 그가 청혼을 받는 날에는 우리가 그를 위하여 무엇을 할까',17649),
('sng-8-9','sng','아가',8,9,'그가 성벽이라면 우리는 은 망대를 그 위에 세울 것이요 그가 문이라면 우리는 백향목 판자로 두르리라',17650),
('sng-8-10','sng','아가',8,10,'나는 성벽이요 내 유방은 망대 같으니 그러므로 나는 그가 보기에 화평을 얻은 자 같구나',17651),
('sng-8-11','sng','아가',8,11,'솔로몬이 바알하몬에 포도원이 있어 지키는 자들에게 맡겨 두고 그들로 각기 그 열매로 말미암아 은 천을 바치게 하였구나',17652),
('sng-8-12','sng','아가',8,12,'솔로몬 너는 천을 얻겠고 열매를 지키는 자도 이백을 얻으려니와 내게 속한 내 포도원은 내 앞에 있구나',17653),
('sng-8-13','sng','아가',8,13,'너 동산에 거주하는 자야 친구들이 네 소리에 귀를 기울이니 내가 듣게 하려무나',17654),
('sng-8-14','sng','아가',8,14,'내 사랑하는 자야 너는 빨리 달리라 향기로운 산 위에 있는 노루와도 같고 어린 사슴과도 같아라',17655),
('isa-1-1','isa','이사야',1,1,'유다 왕 웃시야와 요담과 아하스와 히스기야 시대에 아모스의 아들 이사야가 유다와 예루살렘에 관하여 본 계시라',17656),
('isa-1-2','isa','이사야',1,2,'하늘이여 들으라 땅이여 귀를 기울이라 여호와께서 말씀하시기를 내가 자식을 양육하였거늘 그들이 나를 거역하였도다',17657),
('isa-1-3','isa','이사야',1,3,'소는 그 임자를 알고 나귀는 그 주인의 구유를 알건마는 이스라엘은 알지 못하고 나의 백성은 깨닫지 못하는도다 하셨도다',17658),
('isa-1-4','isa','이사야',1,4,'슬프다 범죄한 나라요 허물 진 백성이요 행악의 종자요 행위가 부패한 자식이로다 그들이 여호와를 버리며 이스라엘의 거룩하신 이를 만홀히 여겨 멀리하고 물러갔도다',17659),
('isa-1-5','isa','이사야',1,5,'너희가 어찌하여 매를 더 맞으려고 패역을 거듭하느냐 온 머리는 병들었고 온 마음은 피곤하였으며',17660),
('isa-1-6','isa','이사야',1,6,'발바닥에서 머리까지 성한 곳이 없이 상한 것과 터진 것과 새로 맞은 흔적뿐이거늘 그것을 짜며 싸매며 기름으로 부드럽게 함을 받지 못하였도다',17661),
('isa-1-7','isa','이사야',1,7,'너희의 땅은 황폐하였고 너희의 성읍들은 불에 탔고 너희의 토지는 너희 목전에서 이방인에게 삼켜졌으며 이방인에게 파괴됨 같이 황폐하였고',17662),
('isa-1-8','isa','이사야',1,8,'딸 시온은 포도원의 망대 같이, 참외밭의 원두막 같이, 에워 싸인 성읍 같이 겨우 남았도다',17663),
('isa-1-9','isa','이사야',1,9,'만군의 여호와께서 우리를 위하여 생존자를 조금 남겨 두지 아니하셨더면 우리가 소돔 같고 고모라 같았으리로다',17664),
('isa-1-10','isa','이사야',1,10,'너희 소돔의 관원들아 여호와의 말씀을 들을지어다 너희 고모라의 백성아 우리 하나님의 법에 귀를 기울일지어다',17665),
