('isa-4-5','isa','이사야',4,5,'여호와께서 거하시는 온 시온 산과 모든 집회 위에 낮이면 구름과 연기, 밤이면 화염의 빛을 만드시고 그 모든 영광 위에 덮개를 두시며',17739),
('isa-4-6','isa','이사야',4,6,'또 초막이 있어서 낮에는 더위를 피하는 그늘을 지으며 또 풍우를 피하여 숨는 곳이 되리라',17740),
('isa-5-1','isa','이사야',5,1,'나는 내가 사랑하는 자를 위하여 노래하되 내가 사랑하는 자의 포도원을 노래하리라 내가 사랑하는 자에게 포도원이 있음이여 심히 기름진 산에로다',17741),
('isa-5-2','isa','이사야',5,2,'땅을 파서 돌을 제하고 극상품 포도나무를 심었도다 그 중에 망대를 세웠고 또 그 안에 술틀을 팠도다 좋은 포도 맺기를 바랐더니 들포도를 맺었도다',17742),
('isa-5-3','isa','이사야',5,3,'예루살렘 주민과 유다 사람들아 구하노니 이제 나와 내 포도원 사이에서 사리를 판단하라',17743),
('isa-5-4','isa','이사야',5,4,'내가 내 포도원을 위하여 행한 것 외에 무엇을 더할 것이 있으랴 내가 좋은 포도 맺기를 기다렸거늘 들포도를 맺음은 어찌 됨인고',17744),
('isa-5-5','isa','이사야',5,5,'이제 내가 내 포도원에 어떻게 행할지를 너희에게 이르리라 내가 그 울타리를 걷어 먹힘을 당하게 하며 그 담을 헐어 짓밟히게 할 것이요',17745),
('isa-5-6','isa','이사야',5,6,'내가 그것을 황폐하게 하리니 다시는 가지를 자름이나 북을 돋우지 못하여 찔레와 가시가 날 것이며 내가 또 구름에게 명하여 그 위에 비를 내리지 못하게 하리라 하셨으니',17746),
('isa-5-7','isa','이사야',5,7,'무릇 만군의 여호와의 포도원은 이스라엘 족속이요 그가 기뻐하시는 나무는 유다 사람이라 그들에게 정의를 바라셨더니 도리어 포학이요 그들에게 공의를 바라셨더니 도리어 부르짖음이었도다',17747),
('isa-5-8','isa','이사야',5,8,'가옥에 가옥을 이으며 전토에 전토를 더하여 빈 틈이 없도록 하고 이 땅 가운데에서 홀로 거주하려 하는 자들은 화 있을진저',17748),
('isa-5-9','isa','이사야',5,9,'만군의 여호와께서 내 귀에 말씀하시되 정녕히 허다한 가옥이 황폐하리니 크고 아름다울지라도 거주할 자가 없을 것이며',17749),
('isa-5-10','isa','이사야',5,10,'열흘 갈이 포도원에 겨우 포도주 한 바트가 나겠고 한 호멜의 종자를 뿌려도 간신히 한 에바가 나리라 하시도다',17750),
('isa-5-11','isa','이사야',5,11,'아침에 일찍이 일어나 독주를 마시며 밤이 깊도록 포도주에 취하는 자들은 화 있을진저',17751),
('isa-5-12','isa','이사야',5,12,'그들이 연회에는 수금과 비파와 소고와 피리와 포도주를 갖추었어도 여호와께서 행하시는 일에 관심을 두지 아니하며 그의 손으로 하신 일을 보지 아니하는도다',17752),
('isa-5-13','isa','이사야',5,13,'그러므로 내 백성이 무지함으로 말미암아 사로잡힐 것이요 그들의 귀한 자는 굶주릴 것이요 무리는 목마를 것이라',17753),
('isa-5-14','isa','이사야',5,14,'그러므로 스올이 욕심을 크게 내어 한량 없이 그 입을 벌린즉 그들의 호화로움과 그들의 많은 무리와 그들의 떠드는 것과 그 중에서 즐거워하는 자가 거기에 빠질 것이라',17754),
('isa-5-15','isa','이사야',5,15,'여느 사람은 구푸리고 존귀한 자는 낮아지고 오만한 자의 눈도 낮아질 것이로되',17755),
('isa-5-16','isa','이사야',5,16,'오직 만군의 여호와는 정의로우시므로 높임을 받으시며 거룩하신 하나님은 공의로우시므로 거룩하다 일컬음을 받으시리니',17756),
('isa-5-17','isa','이사야',5,17,'그 때에는 어린 양들이 자기 초장에 있는 것 같이 풀을 먹을 것이요 유리하는 자들이 부자의 버려진 밭에서 먹으리라',17757),
('isa-5-18','isa','이사야',5,18,'거짓으로 끈을 삼아 죄악을 끌며 수레 줄로 함 같이 죄악을 끄는 자는 화 있을진저',17758),
('isa-5-19','isa','이사야',5,19,'그들이 이르기를 그는 자기의 일을 속속히 이루어 우리에게 보게 할 것이며 이스라엘의 거룩한 이는 자기의 계획을 속히 이루어 우리가 알게 할 것이라 하는도다',17759),
('isa-5-20','isa','이사야',5,20,'악을 선하다 하며 선을 악하다 하며 흑암으로 광명을 삼으며 광명으로 흑암을 삼으며 쓴 것으로 단 것을 삼으며 단 것으로 쓴 것을 삼는 자들은 화 있을진저',17760),
('isa-5-21','isa','이사야',5,21,'스스로 지혜롭다 하며 스스로 명철하다 하는 자들은 화 있을진저',17761),
('isa-5-22','isa','이사야',5,22,'포도주를 마시기에 용감하며 독주를 잘 빚는 자들은 화 있을진저',17762),
('isa-5-23','isa','이사야',5,23,'그들은 뇌물로 말미암아 악인을 의롭다 하고 의인에게서 그 공의를 빼앗는도다',17763),
('isa-5-24','isa','이사야',5,24,'이로 말미암아 불꽃이 그루터기를 삼킴 같이, 마른 풀이 불 속에 떨어짐 같이 그들의 뿌리가 썩겠고 꽃이 티끌처럼 날리리니 그들이 만군의 여호와의 율법을 버리며 이스라엘의 거룩하신 이의 말씀을 멸시하였음이라',17764),
('isa-5-25','isa','이사야',5,25,'그러므로 여호와께서 자기 백성에게 노를 발하시고 그들 위에 손을 들어 그들을 치신지라 산들은 진동하며 그들의 시체는 거리 가운데에 분토 같이 되었도다 그럴지라도 그의 노가 돌아서지 아니하였고 그의 손이 여전히 펼쳐져 있느니라',17765),
('isa-5-26','isa','이사야',5,26,'또 그가 기치를 세우시고 먼 나라들을 불러 땅 끝에서부터 자기에게로 오게 하실 것이라 보라 그들이 빨리 달려올 것이로되',17766),
('isa-5-27','isa','이사야',5,27,'그 중에 곤핍하여 넘어지는 자도 없을 것이며 조는 자나 자는 자도 없을 것이며 그들의 허리띠는 풀리지 아니하며 그들의 들메끈은 끊어지지 아니하며',17767),
('isa-5-28','isa','이사야',5,28,'그들의 화살은 날카롭고 모든 활은 당겨졌으며 그들의 말굽은 부싯돌 같고 병거 바퀴는 회오리바람 같을 것이며',17768),
('isa-5-29','isa','이사야',5,29,'그들의 부르짖음은 암사자 같을 것이요 그들의 소리지름은 어린 사자들과 같을 것이라 그들이 부르짖으며 먹이를 움켜 가져가 버려도 건질 자가 없으리로다',17769),
('isa-5-30','isa','이사야',5,30,'그 날에 그들이 바다 물결 소리 같이 백성을 향하여 부르짖으리니 사람이 그 땅을 바라보면 흑암과 고난이 있고 빛은 구름에 가려서 어두우리라',17770),
('isa-6-1','isa','이사야',6,1,'웃시야 왕이 죽던 해에 내가 본즉 주께서 높이 들린 보좌에 앉으셨는데 그의 옷자락은 성전에 가득하였고',17771),
