('isa-6-3','isa','이사야',6,3,'서로 불러 이르되 거룩하다 거룩하다 거룩하다 만군의 여호와여 그의 영광이 온 땅에 충만하도다 하더라',17773),
('isa-6-4','isa','이사야',6,4,'이같이 화답하는 자의 소리로 말미암아 문지방의 터가 요동하며 성전에 연기가 충만한지라',17774),
('isa-6-5','isa','이사야',6,5,'그 때에 내가 말하되 화로다 나여 망하게 되었도다 나는 입술이 부정한 사람이요 나는 입술이 부정한 백성 중에 거주하면서 만군의 여호와이신 왕을 뵈었음이로다 하였더라',17775),
('isa-6-6','isa','이사야',6,6,'그 때에 그 스랍 중의 하나가 부젓가락으로 제단에서 집은 바 핀 숯을 손에 가지고 내게로 날아와서',17776),
('isa-6-7','isa','이사야',6,7,'그것을 내 입술에 대며 이르되 보라 이것이 네 입에 닿았으니 네 악이 제하여졌고 네 죄가 사하여졌느니라 하더라',17777),
('isa-6-8','isa','이사야',6,8,'내가 또 주의 목소리를 들으니 주께서 이르시되 내가 누구를 보내며 누가 우리를 위하여 갈꼬 하시니 그 때에 내가 이르되 내가 여기 있나이다 나를 보내소서 하였더니',17778),
