('isa-6-12','isa','이사야',6,12,'여호와께서 사람들을 멀리 옮기셔서 이 땅 가운데에 황폐한 곳이 많을 때까지니라',17782),
('isa-6-13','isa','이사야',6,13,'그 중에 십분의 일이 아직 남아 있을지라도 이것도 황폐하게 될 것이나 밤나무와 상수리나무가 베임을 당하여도 그 그루터기는 남아 있는 것 같이 거룩한 씨가 이 땅의 그루터기니라 하시더라',17783),
('isa-7-1','isa','이사야',7,1,'웃시야의 손자요 요담의 아들인 유다의 아하스 왕 때에 아람의 르신 왕과 르말리야의 아들 이스라엘의 베가 왕이 올라와서 예루살렘을 쳤으나 능히 이기지 못하니라',17784),
