('isa-31-2','isa','이사야',31,2,'여호와께서도 지혜로우신즉 재앙을 내리실 것이라 그의 말씀들을 변하게 하지 아니하시고 일어나사 악행하는 자들의 집을 치시며 행악을 돕는 자들을 치시리니',18253),
('isa-31-3','isa','이사야',31,3,'애굽은 사람이요 신이 아니며 그들의 말들은 육체요 영이 아니라 여호와께서 그의 손을 펴시면 돕는 자도 넘어지며 도움을 받는 자도 엎드러져서 다 함께 멸망하리라',18254),
