('isa-48-12','isa','이사야',48,12,'야곱아 내가 부른 이스라엘아 내게 들으라 나는 그니 나는 처음이요 또 나는 마지막이라',18627),
('isa-48-13','isa','이사야',48,13,'과연 내 손이 땅의 기초를 정하였고 내 오른손이 하늘을 폈나니 내가 그들을 부르면 그것들이 일제히 서느니라',18628),
