('isa-48-18','isa','이사야',48,18,'네가 나의 명령에 주의하였더라면 네 평강이 강과 같았겠고 네 공의가 바다 물결 같았을 것이며',18633),
('isa-48-19','isa','이사야',48,19,'네 자손이 모래 같았겠고 네 몸의 소생이 모래 알 같아서 그의 이름이 내 앞에서 끊어지지 아니하였겠고 없어지지 아니하였으리라 하셨느니라',18634),
('isa-48-20','isa','이사야',48,20,'너희는 바벨론에서 나와서 갈대아인을 피하고 즐거운 소리로 이를 알게 하여 들려 주며 땅 끝까지 반포하여 이르기를 여호와께서 그의 종 야곱을 구속하셨다 하라',18635),
('isa-48-21','isa','이사야',48,21,'여호와께서 그들을 사막으로 통과하게 하시던 때에 그들이 목마르지 아니하게 하시되 그들을 위하여 바위에서 물이 흘러나게 하시며 바위를 쪼개사 물이 솟아나게 하셨느니라',18636),
