('isa-49-4','isa','이사야',49,4,'그러나 나는 말하기를 내가 헛되이 수고하였으며 무익하게 공연히 내 힘을 다하였다 하였도다 참으로 나에 대한 판단이 여호와께 있고 나의 보응이 나의 하나님께 있느니라',18641),
