('isa-49-8','isa','이사야',49,8,'여호와께서 이같이 이르시되 은혜의 때에 내가 네게 응답하였고 구원의 날에 내가 너를 도왔도다 내가 장차 너를 보호하여 너를 백성의 언약으로 삼으며 나라를 일으켜 그들에게 그 황무하였던 땅을 기업으로 상속하게 하리라',18645),
