('isa-50-5','isa','이사야',50,5,'주 여호와께서 나의 귀를 여셨으므로 내가 거역하지도 아니하며 뒤로 물러가지도 아니하며',18668),
('isa-50-6','isa','이사야',50,6,'나를 때리는 자들에게 내 등을 맡기며 나의 수염을 뽑는 자들에게 나의 뺨을 맡기며 모욕과 침 뱉음을 당하여도 내 얼굴을 가리지 아니하였느니라',18669),
('isa-50-7','isa','이사야',50,7,'주 여호와께서 나를 도우시므로 내가 부끄러워하지 아니하고 내 얼굴을 부싯돌 같이 굳게 하였으므로 내가 수치를 당하지 아니할 줄 아노라',18670),
