('isa-50-9','isa','이사야',50,9,'보라 주 여호와께서 나를 도우시리니 나를 정죄할 자 누구냐 보라 그들은 다 옷과 같이 해어지며 좀이 그들을 먹으리라',18672),
('isa-50-10','isa','이사야',50,10,'너희 중에 여호와를 경외하며 그의 종의 목소리를 청종하는 자가 누구냐 흑암 중에 행하여 빛이 없는 자라도 여호와의 이름을 의뢰하며 자기 하나님께 의지할지어다',18673),
('isa-50-11','isa','이사야',50,11,'보라 불을 피우고 횃불을 둘러 띤 자여 너희가 다 너희의 불꽃 가운데로 걸어가며 너희가 피운 횃불 가운데로 걸어갈지어다 너희가 내 손에서 얻을 것이 이것이라 너희가 고통이 있는 곳에 누우리라',18674),
('isa-51-1','isa','이사야',51,1,'의를 따르며 여호와를 찾아 구하는 너희는 내게 들을지어다 너희를 떠낸 반석과 너희를 파낸 우묵한 구덩이를 생각하여 보라',18675),
('isa-51-2','isa','이사야',51,2,'너희의 조상 아브라함과 너희를 낳은 사라를 생각하여 보라 아브라함이 혼자 있을 때에 내가 그를 부르고 그에게 복을 주어 창성하게 하였느니라',18676),
('isa-51-3','isa','이사야',51,3,'나 여호와가 시온의 모든 황폐한 곳들을 위로하여 그 사막을 에덴 같게, 그 광야를 여호와의 동산 같게 하였나니 그 가운데에 기뻐함과 즐거워함과 감사함과 창화하는 소리가 있으리라',18677),
('isa-51-4','isa','이사야',51,4,'내 백성이여 내게 주의하라 내 나라여 내게 귀를 기울이라 이는 율법이 내게서부터 나갈 것임이라 내가 내 공의를 만민의 빛으로 세우리라',18678),
('isa-51-5','isa','이사야',51,5,'내 공의가 가깝고 내 구원이 나갔은즉 내 팔이 만민을 심판하리니 섬들이 나를 앙망하여 내 팔에 의지하리라',18679),
('isa-51-6','isa','이사야',51,6,'너희는 하늘로 눈을 들며 그 아래의 땅을 살피라 하늘이 연기 같이 사라지고 땅이 옷 같이 해어지며 거기에 사는 자들이 하루살이 같이 죽으려니와 나의 구원은 영원히 있고 나의 공의는 폐하여지지 아니하리라',18680),
('isa-51-7','isa','이사야',51,7,'의를 아는 자들아, 마음에 내 율법이 있는 백성들아, 너희는 내게 듣고 그들의 비방을 두려워하지 말라 그들의 비방에 놀라지 말라',18681),
('isa-51-8','isa','이사야',51,8,'옷 같이 좀이 그들을 먹을 것이며 양털 같이 좀벌레가 그들을 먹을 것이나 나의 공의는 영원히 있겠고 나의 구원은 세세에 미치리라',18682),
('isa-51-9','isa','이사야',51,9,'여호와의 팔이여 깨소서 깨소서 능력을 베푸소서 옛날 옛시대에 깨신 것 같이 하소서 라합을 저미시고 용을 찌르신 이가 어찌 주가 아니시며',18683),
('isa-51-10','isa','이사야',51,10,'바다를, 넓고 깊은 물을 말리시고 바다 깊은 곳에 길을 내어 구속 받은 자들을 건너게 하신 이가 어찌 주가 아니시니이까',18684),
('isa-51-11','isa','이사야',51,11,'여호와께 구속 받은 자들이 돌아와 노래하며 시온으로 돌아오니 영원한 기쁨이 그들의 머리 위에 있고 슬픔과 탄식이 달아나리이다',18685),
('isa-51-12','isa','이사야',51,12,'이르시되 너희를 위로하는 자는 나 곧 나이니라 너는 어떠한 자이기에 죽을 사람을 두려워하며 풀 같이 될 사람의 아들을 두려워하느냐',18686),
('isa-51-13','isa','이사야',51,13,'하늘을 펴고 땅의 기초를 정하고 너를 지은 자 여호와를 어찌하여 잊어버렸느냐 너를 멸하려고 준비하는 저 학대자의 분노를 어찌하여 항상 종일 두려워하느냐 학대자의 분노가 어디 있느냐',18687),
('isa-51-14','isa','이사야',51,14,'결박된 포로가 속히 놓일 것이니 죽지도 아니할 것이요 구덩이로 내려가지도 아니할 것이며 그의 양식이 부족하지도 아니하리라',18688),
('isa-51-15','isa','이사야',51,15,'나는 네 하나님 여호와라 바다를 휘저어서 그 물결을 뒤흔들게 하는 자이니 그의 이름은 만군의 여호와니라',18689),
('isa-51-16','isa','이사야',51,16,'내가 내 말을 네 입에 두고 내 손 그늘로 너를 덮었나니 이는 내가 하늘을 펴며 땅의 기초를 정하며 시온에게 이르기를 너는 내 백성이라 말하기 위함이니라',18690),
('isa-51-17','isa','이사야',51,17,'여호와의 손에서 그의 분노의 잔을 마신 예루살렘이여 깰지어다 깰지어다 일어설지어다 네가 이미 비틀걸음 치게 하는 큰 잔을 마셔 다 비웠도다',18691),
