('isa-51-19','isa','이사야',51,19,'이 두 가지 일이 네게 닥쳤으니 누가 너를 위하여 슬퍼하랴 곧 황폐와 멸망이요 기근과 칼이라 누가 너를 위로하랴',18693),
('isa-51-20','isa','이사야',51,20,'네 아들들이 곤비하여 그물에 걸린 영양 같이 온 거리 모퉁이에 누웠으니 그들에게 여호와의 분노와 네 하나님의 견책이 가득하도다',18694),
