('isa-52-12','isa','이사야',52,12,'여호와께서 너희 앞에서 행하시며 이스라엘의 하나님이 너희 뒤에서 호위하시리니 너희가 황급히 나오지 아니하며 도망하듯 다니지 아니하리라',18709),
