('isa-53-11','isa','이사야',53,11,'그가 자기 영혼의 수고한 것을 보고 만족하게 여길 것이라 나의 의로운 종이 자기 지식으로 많은 사람을 의롭게 하며 또 그들의 죄악을 친히 담당하리로다',18723),
('isa-53-12','isa','이사야',53,12,'그러므로 내가 그에게 존귀한 자와 함께 몫을 받게 하며 강한 자와 함께 탈취한 것을 나누게 하리니 이는 그가 자기 영혼을 버려 사망에 이르게 하며 범죄자 중 하나로 헤아림을 받았음이니라 그러나 그가 많은 사람의 죄를 담당하며 범죄자를 위하여 기도하였느니라',18724),
('isa-54-1','isa','이사야',54,1,'잉태하지 못하며 출산하지 못한 너는 노래할지어다 산고를 겪지 못한 너는 외쳐 노래할지어다 이는 홀로 된 여인의 자식이 남편 있는 자의 자식보다 많음이라 여호와께서 말씀하셨느니라',18725),
('isa-54-2','isa','이사야',54,2,'네 장막터를 넓히며 네 처소의 휘장을 아끼지 말고 널리 펴되 너의 줄을 길게 하며 너의 말뚝을 견고히 할지어다',18726),
('isa-54-3','isa','이사야',54,3,'이는 네가 좌우로 퍼지며 네 자손은 열방을 얻으며 황폐한 성읍들을 사람 살 곳이 되게 할 것임이라',18727),
