('isa-58-2','isa','이사야',58,2,'그들이 날마다 나를 찾아 나의 길 알기를 즐거워함이 마치 공의를 행하여 그의 하나님의 규례를 저버리지 아니하는 나라 같아서 의로운 판단을 내게 구하며 하나님과 가까이 하기를 즐거워하는도다',18789),
