('isa-58-7','isa','이사야',58,7,'또 주린 자에게 네 양식을 나누어 주며 유리하는 빈민을 집에 들이며 헐벗은 자를 보면 입히며 또 네 골육을 피하여 스스로 숨지 아니하는 것이 아니겠느냐',18794),
('isa-58-8','isa','이사야',58,8,'그리하면 네 빛이 새벽 같이 비칠 것이며 네 치유가 급속할 것이며 네 공의가 네 앞에 행하고 여호와의 영광이 네 뒤에 호위하리니',18795),
('isa-58-9','isa','이사야',58,9,'네가 부를 때에는 나 여호와가 응답하겠고 네가 부르짖을 때에는 내가 여기 있다 하리라',18796),
