('isa-65-5','isa','이사야',65,5,'사람에게 이르기를 너는 네 자리에 서 있고 내게 가까이 하지 말라 나는 너보다 거룩함이라 하나니 이런 자들은 내 코의 연기요 종일 타는 불이로다',18903),
('isa-65-6','isa','이사야',65,6,'보라 이것이 내 앞에 기록되었으니 내가 잠잠하지 아니하고 반드시 보응하되 그들의 품에 보응하리라',18904),
('isa-65-7','isa','이사야',65,7,'너희의 죄악과 너희 조상들의 죄악은 한 가지니 그들이 산 위에서 분향하며 작은 산 위에서 나를 능욕하였음이라 그러므로 내가 먼저 그들의 행위를 헤아리고 그들의 품에 보응하리라 여호와가 말하였느니라',18905),
('isa-65-8','isa','이사야',65,8,'여호와께서 이와 같이 말씀하시되 포도송이에는 즙이 있으므로 사람들이 말하기를 그것을 상하지 말라 거기 복이 있느니라 하나니 나도 내 종들을 위하여 그와 같이 행하여 다 멸하지 아니하고',18906),
('isa-65-9','isa','이사야',65,9,'내가 야곱에게서 씨를 내며 유다에게서 나의 산들을 기업으로 얻을 자를 내리니 내가 택한 자가 이를 기업으로 얻을 것이요 나의 종들이 거기에 살 것이라',18907),
('isa-65-10','isa','이사야',65,10,'사론은 양 떼의 우리가 되겠고 아골 골짜기는 소 떼가 눕는 곳이 되어 나를 찾은 내 백성의 소유가 되려니와',18908),
('isa-65-11','isa','이사야',65,11,'오직 나 여호와를 버리며 나의 성산을 잊고 갓에게 상을 베풀며 므니에게 섞은 술을 가득히 붓는 너희여',18909),
('isa-65-12','isa','이사야',65,12,'내가 너희를 칼에 붙일 것인즉 다 구푸리고 죽임을 당하리니 이는 내가 불러도 너희가 대답하지 아니하며 내가 말하여도 듣지 아니하고 나의 눈에 악을 행하였으며 내가 즐겨하지 아니하는 일을 택하였음이니라',18910),
('isa-65-13','isa','이사야',65,13,'이러므로 주 여호와께서 이와 같이 말씀하시니라 보라 나의 종들은 먹을 것이로되 너희는 주릴 것이니라 보라 나의 종들은 마실 것이로되 너희는 갈할 것이니라 보라 나의 종들은 기뻐할 것이로되 너희는 수치를 당할 것이니라',18911),
('isa-65-14','isa','이사야',65,14,'보라 나의 종들은 마음이 즐거우므로 노래할 것이로되 너희는 마음이 슬프므로 울며 심령이 상하므로 통곡할 것이며',18912),
('isa-65-15','isa','이사야',65,15,'또 너희가 남겨 놓은 이름은 내가 택한 자의 저줏거리가 될 것이니라 주 여호와 내가 너를 죽이고 내 종들은 다른 이름으로 부르리라',18913),
('isa-65-16','isa','이사야',65,16,'이러므로 땅에서 자기를 위하여 복을 구하는 자는 진리의 하나님을 향하여 복을 구할 것이요 땅에서 맹세하는 자는 진리의 하나님으로 맹세하리니 이는 이전 환난이 잊어졌고 내 눈 앞에 숨겨졌음이라',18914),
('isa-65-17','isa','이사야',65,17,'보라 내가 새 하늘과 새 땅을 창조하나니 이전 것은 기억되거나 마음에 생각나지 아니할 것이라',18915),
('isa-65-18','isa','이사야',65,18,'너희는 내가 창조하는 것으로 말미암아 영원히 기뻐하며 즐거워할지니라 보라 내가 예루살렘을 즐거운 성으로 창조하며 그 백성을 기쁨으로 삼고',18916),
('isa-65-19','isa','이사야',65,19,'내가 예루살렘을 즐거워하며 나의 백성을 기뻐하리니 우는 소리와 부르짖는 소리가 그 가운데에서 다시는 들리지 아니할 것이며',18917),
('isa-65-20','isa','이사야',65,20,'거기는 날 수가 많지 못하여 죽는 어린이와 수한이 차지 못한 노인이 다시는 없을 것이라 곧 백 세에 죽는 자를 젊은이라 하겠고 백 세가 못되어 죽는 자는 저주 받은 자이리라',18918),
('isa-65-21','isa','이사야',65,21,'그들이 가옥을 건축하고 그 안에 살겠고 포도나무를 심고 열매를 먹을 것이며',18919),
('isa-65-22','isa','이사야',65,22,'그들이 건축한 데에 타인이 살지 아니할 것이며 그들이 심은 것을 타인이 먹지 아니하리니 이는 내 백성의 수한이 나무의 수한과 같겠고 내가 택한 자가 그 손으로 일한 것을 길이 누릴 것이며',18920),
('isa-65-23','isa','이사야',65,23,'그들의 수고가 헛되지 않겠고 그들이 생산한 것이 재난을 당하지 아니하리니 그들은 여호와의 복된 자의 자손이요 그들의 후손도 그들과 같을 것임이라',18921),
('isa-65-24','isa','이사야',65,24,'그들이 부르기 전에 내가 응답하겠고 그들이 말을 마치기 전에 내가 들을 것이며',18922),
