('isa-66-1','isa','이사야',66,1,'여호와께서 이와 같이 말씀하시되 하늘은 나의 보좌요 땅은 나의 발판이니 너희가 나를 위하여 무슨 집을 지으랴 내가 안식할 처소가 어디랴',18924),
('isa-66-2','isa','이사야',66,2,'나 여호와가 말하노라 내 손이 이 모든 것을 지었으므로 그들이 생겼느니라 무릇 마음이 가난하고 심령에 통회하며 내 말을 듣고 떠는 자 그 사람은 내가 돌보려니와',18925),
('isa-66-3','isa','이사야',66,3,'소를 잡아 드리는 것은 살인함과 다름이 없이 하고 어린 양으로 제사드리는 것은 개의 목을 꺾음과 다름이 없이 하며 드리는 예물은 돼지의 피와 다름이 없이 하고 분향하는 것은 우상을 찬송함과 다름이 없이 행하는 그들은 자기의 길을 택하며 그들의 마음은 가증한 것을 기뻐한즉',18926),
('isa-66-4','isa','이사야',66,4,'나 또한 유혹을 그들에게 택하여 주며 그들이 무서워하는 것을 그들에게 임하게 하리니 이는 내가 불러도 대답하는 자가 없으며 내가 말하여도 그들이 듣지 않고 오직 나의 목전에서 악을 행하며 내가 기뻐하지 아니하는 것을 택하였음이라 하시니라',18927),
