('isa-66-6','isa','이사야',66,6,'떠드는 소리가 성읍에서부터 들려 오며 목소리가 성전에서부터 들리니 이는 여호와께서 그의 원수에게 보응하시는 목소리로다',18929),
('isa-66-7','isa','이사야',66,7,'시온은 진통을 하기 전에 해산하며 고통을 당하기 전에 남아를 낳았으니',18930),
