('jer-6-17','jer','예레미야',6,17,'내가 또 너희 위에 파수꾼을 세웠으니 나팔 소리를 들으라 하나 그들의 대답이 우리는 듣지 않겠노라 하였도다',19107),
('jer-6-18','jer','예레미야',6,18,'그러므로 너희 나라들아 들으라 무리들아 그들이 당할 일을 알라',19108),
('jer-6-19','jer','예레미야',6,19,'땅이여 들으라 내가 이 백성에게 재앙을 내리리니 이것이 그들의 생각의 결과라 그들이 내 말을 듣지 아니하며 내 율법을 거절하였음이니라',19109),
