('jer-7-9','jer','예레미야',7,9,'너희가 도둑질하며 살인하며 간음하며 거짓 맹세하며 바알에게 분향하며 너희가 알지 못하는 다른 신들을 따르면서',19129),
('jer-7-10','jer','예레미야',7,10,'내 이름으로 일컬음을 받는 이 집에 들어와서 내 앞에 서서 말하기를 우리가 구원을 얻었나이다 하느냐 이는 이 모든 가증한 일을 행하려 함이로다',19130),
('jer-7-11','jer','예레미야',7,11,'내 이름으로 일컬음을 받는 이 집이 너희 눈에는 도둑의 소굴로 보이느냐 보라 나 곧 내가 그것을 보았노라 여호와의 말씀이니라',19131),
('jer-7-12','jer','예레미야',7,12,'너희는 내가 처음으로 내 이름을 둔 처소 실로에 가서 내 백성 이스라엘의 악에 대하여 내가 어떻게 행하였는지를 보라',19132),
('jer-7-13','jer','예레미야',7,13,'여호와의 말씀이니라 이제 너희가 그 모든 일을 행하였으며 내가 너희에게 말하되 새벽부터 부지런히 말하여도 듣지 아니하였고 너희를 불러도 대답하지 아니하였느니라',19133),
('jer-7-14','jer','예레미야',7,14,'그러므로 내가 실로에 행함 같이 너희가 신뢰하는 바 내 이름으로 일컬음을 받는 이 집 곧 너희와 너희 조상들에게 준 이 곳에 행하겠고',19134),
('jer-7-15','jer','예레미야',7,15,'내가 너희 모든 형제 곧 에브라임 온 자손을 쫓아낸 것 같이 내 앞에서 너희를 쫓아내리라 하셨다 할지니라',19135),
('jer-7-16','jer','예레미야',7,16,'그런즉 너는 이 백성을 위하여 기도하지 말라 그들을 위하여 부르짖어 구하지 말라 내게 간구하지 말라 내가 네게서 듣지 아니하리라',19136),
('jer-7-17','jer','예레미야',7,17,'너는 그들이 유다 성읍들과 예루살렘 거리에서 행하는 일을 보지 못하느냐',19137),
('jer-7-18','jer','예레미야',7,18,'자식들은 나무를 줍고 아버지들은 불을 피우며 부녀들은 가루를 반죽하여 하늘의 여왕을 위하여 과자를 만들며 그들이 또 다른 신들에게 전제를 부음으로 나의 노를 일으키느니라',19138),
('jer-7-19','jer','예레미야',7,19,'여호와의 말씀이니라 그들이 나를 격노하게 함이냐 자기 얼굴에 부끄러움을 자취함이 아니냐',19139),
('jer-7-20','jer','예레미야',7,20,'그러므로 주 여호와께서 이와 같이 말씀하시니라 보라 나의 진노와 분노를 이 곳과 사람과 짐승과 들나무와 땅의 소산에 부으리니 불 같이 살라지고 꺼지지 아니하리라 하시니라',19140),
('jer-7-21','jer','예레미야',7,21,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희 희생제물과 번제물의 고기를 아울러 먹으라',19141),
('jer-7-22','jer','예레미야',7,22,'사실은 내가 너희 조상들을 애굽 땅에서 인도하여 낸 날에 번제나 희생에 대하여 말하지 아니하며 명령하지 아니하고',19142),
('jer-7-23','jer','예레미야',7,23,'오직 내가 이것을 그들에게 명령하여 이르기를 너희는 내 목소리를 들으라 그리하면 나는 너희 하나님이 되겠고 너희는 내 백성이 되리라 너희는 내가 명령한 모든 길로 걸어가라 그리하면 복을 받으리라 하였으나',19143),
('jer-7-24','jer','예레미야',7,24,'그들이 순종하지 아니하며 귀를 기울이지도 아니하고 자신들의 악한 마음의 꾀와 완악한 대로 행하여 그 등을 내게로 돌리고 그 얼굴을 향하지 아니하였으며',19144),
('jer-7-25','jer','예레미야',7,25,'너희 조상들이 애굽 땅에서 나온 날부터 오늘까지 내가 내 종 선지자들을 너희에게 보내되 끊임없이 보내었으나',19145),
('jer-7-26','jer','예레미야',7,26,'너희가 나에게 순종하지 아니하며 귀를 기울이지 아니하고 목을 굳게 하여 너희 조상들보다 악을 더 행하였느니라',19146),
('jer-7-27','jer','예레미야',7,27,'네가 그들에게 이 모든 말을 할지라도 그들이 너에게 순종하지 아니할 것이요 네가 그들을 불러도 그들이 네게 대답하지 아니하리니',19147),
('jer-7-28','jer','예레미야',7,28,'너는 그들에게 말하기를 너희는 너희 하나님 여호와의 목소리를 순종하지 아니하며 교훈을 받지 아니하는 민족이라 진실이 없어져 너희 입에서 끊어졌다 할지니라',19148),
('jer-7-29','jer','예레미야',7,29,'너의 머리털을 베어 버리고 벗은 산 위에서 통곡할지어다 여호와께서 그 노하신 바 이 세대를 끊어 버리셨음이라',19149),
('jer-7-30','jer','예레미야',7,30,'여호와께서 말씀하시되 유다 자손이 나의 눈 앞에 악을 행하여 내 이름으로 일컬음을 받는 집에 그들의 가증한 것을 두어 집을 더럽혔으며',19150),
('jer-7-31','jer','예레미야',7,31,'힌놈의 아들 골짜기에 도벳 사당을 건축하고 그들의 자녀들을 불에 살랐나니 내가 명령하지 아니하였고 내 마음에 생각하지도 아니한 일이니라',19151),
('jer-7-32','jer','예레미야',7,32,'그러므로 여호와께서 말씀하시니라 날이 이르면 이 곳을 도벳이라 하거나 힌놈의 아들의 골짜기라 말하지 아니하고 죽임의 골짜기라 말하리니 이는 도벳에 자리가 없을 만큼 매장했기 때문이니라',19152),
('jer-7-33','jer','예레미야',7,33,'이 백성의 시체가 공중의 새와 땅의 짐승의 밥이 될 것이나 그것을 쫓을 자가 없을 것이라',19153),
('jer-7-34','jer','예레미야',7,34,'그 때에 내가 유다 성읍들과 예루살렘 거리에 기뻐하는 소리, 즐거워하는 소리, 신랑의 소리, 신부의 소리가 끊어지게 하리니 땅이 황폐하리라',19154),
('jer-8-1','jer','예레미야',8,1,'여호와의 말씀이니라 그 때에 사람들이 유다 왕들의 뼈와 그의 지도자들의 뼈와 제사장들의 뼈와 선지자들의 뼈와 예루살렘 주민의 뼈를 그 무덤에서 끌어내어',19155),
('jer-8-2','jer','예레미야',8,2,'그들이 사랑하며 섬기며 뒤따르며 구하며 경배하던 해와 달과 하늘의 뭇 별 아래에서 펼쳐지게 하리니 그 뼈가 거두이거나 묻히지 못하여 지면에서 분토 같을 것이며',19156),
('jer-8-3','jer','예레미야',8,3,'이 악한 민족의 남아 있는 자, 무릇 내게 쫓겨나서 각처에 남아 있는 자들이 사는 것보다 죽는 것을 원하리라 만군의 여호와의 말씀이니라',19157),
('jer-8-4','jer','예레미야',8,4,'너는 또 그들에게 말하기를 여호와의 말씀에 사람이 엎드러지면 어찌 일어나지 아니하겠으며 사람이 떠나갔으면 어찌 돌아오지 아니하겠느냐',19158),
('jer-8-5','jer','예레미야',8,5,'이 예루살렘 백성이 항상 나를 떠나 물러감은 어찌함이냐 그들이 거짓을 고집하고 돌아오기를 거절하도다',19159),
('jer-8-6','jer','예레미야',8,6,'내가 귀를 기울여 들은즉 그들이 정직을 말하지 아니하며 그들의 악을 뉘우쳐서 내가 행한 것이 무엇인고 말하는 자가 없고 전쟁터로 향하여 달리는 말 같이 각각 그 길로 행하도다',19160),
('jer-8-7','jer','예레미야',8,7,'공중의 학은 그 정한 시기를 알고 산비둘기와 제비와 두루미는 그들이 올 때를 지키거늘 내 백성은 여호와의 규례를 알지 못하도다',19161),
('jer-8-8','jer','예레미야',8,8,'너희가 어찌 우리는 지혜가 있고 우리에게는 여호와의 율법이 있다 말하겠느냐 참으로 서기관의 거짓의 붓이 거짓되게 하였나니',19162),
('jer-8-9','jer','예레미야',8,9,'지혜롭다 하는 자들은 부끄러움을 당하며 두려워 떨다가 잡히리라 보라 그들이 여호와의 말을 버렸으니 그들에게 무슨 지혜가 있으랴',19163),
('jer-8-10','jer','예레미야',8,10,'그러므로 내가 그들의 아내를 타인에게 주겠고 그들의 밭을 그 차지할 자들에게 주리니 그들은 가장 작은 자로부터 큰 자까지 다 욕심내며 선지자로부터 제사장까지 다 거짓을 행함이라',19164),
('jer-8-11','jer','예레미야',8,11,'그들이 딸 내 백성의 상처를 가볍게 여기면서 말하기를 평강하다, 평강하다 하나 평강이 없도다',19165),
('jer-8-12','jer','예레미야',8,12,'그들이 가증한 일을 행할 때에 부끄러워하였느냐 아니라 조금도 부끄러워 하지 않을 뿐 아니라 얼굴도 붉어지지 아니하였느니라 그러므로 그들이 엎드러질 자와 함께 엎드러질 것이라 내가 그들을 벌할 때에 그들이 거꾸러지리라 여호와의 말씀이니라',19166),
('jer-8-13','jer','예레미야',8,13,'여호와의 말씀이니라 내가 그들을 진멸하리니 포도나무에 포도가 없을 것이며 무화과나무에 무화과가 없을 것이며 그 잎사귀가 마를 것이라 내가 그들에게 준 것이 없어지리라 하셨나니',19167),
('jer-8-14','jer','예레미야',8,14,'우리가 어찌 가만히 앉았으랴 모일지어다 우리가 견고한 성읍들로 들어가서 거기에서 멸망하자 우리가 여호와께 범죄하였으므로 우리 하나님 여호와께서 우리를 멸하시며 우리에게 독한 물을 마시게 하심이니라',19168),
('jer-8-15','jer','예레미야',8,15,'우리가 평강을 바라나 좋은 것이 없으며 고침을 입을 때를 바라나 놀라움뿐이로다',19169),
('jer-8-16','jer','예레미야',8,16,'그 말의 부르짖음이 단에서부터 들리고 그 준마들이 우는 소리에 온 땅이 진동하며 그들이 이르러 이 땅과 그 소유와 성읍과 그 중의 주민을 삼켰도다',19170),
('jer-8-17','jer','예레미야',8,17,'여호와의 말씀이니라 내가 술법으로도 제어할 수 없는 뱀과 독사를 너희 가운데 보내리니 그것들이 너희를 물리라 하시도다',19171),
('jer-8-18','jer','예레미야',8,18,'슬프다 나의 근심이여 어떻게 위로를 받을 수 있을까 내 마음이 병들었도다',19172),
('jer-8-19','jer','예레미야',8,19,'딸 내 백성의 심히 먼 땅에서 부르짖는 소리로다 여호와께서 시온에 계시지 아니한가, 그의 왕이 그 가운데 계시지 아니한가 그들이 어찌하여 그 조각한 신상과 이방의 헛된 것들로 나를 격노하게 하였는고 하시니',19173),
('jer-8-20','jer','예레미야',8,20,'추수할 때가 지나고 여름이 다하였으나 우리는 구원을 얻지 못한다 하는도다',19174),
('jer-8-21','jer','예레미야',8,21,'딸 내 백성이 상하였으므로 나도 상하여 슬퍼하며 놀라움에 잡혔도다',19175),
('jer-8-22','jer','예레미야',8,22,'길르앗에는 유향이 있지 아니한가 그 곳에는 의사가 있지 아니한가 딸 내 백성이 치료를 받지 못함은 어찌 됨인고',19176),
('jer-9-1','jer','예레미야',9,1,'어찌하면 내 머리는 물이 되고 내 눈은 눈물 근원이 될꼬 죽임을 당한 딸 내 백성을 위하여 주야로 울리로다',19177),
('jer-9-2','jer','예레미야',9,2,'내가 광야에서 나그네가 머무를 곳을 얻는다면 내 백성을 떠나 가리니 그들은 다 간음하는 자요 반역한 자의 무리가 됨이로다',19178),
('jer-9-3','jer','예레미야',9,3,'여호와의 말씀이니라 그들이 활을 당김 같이 그들의 혀를 놀려 거짓을 말하며 그들이 이 땅에서 강성하나 진실하지 아니하고 악에서 악으로 진행하며 또 나를 알지 못하느니라',19179),
('jer-9-4','jer','예레미야',9,4,'너희는 각기 이웃을 조심하며 어떤 형제든지 믿지 말라 형제마다 완전히 속이며 이웃마다 다니며 비방함이라',19180),
('jer-9-5','jer','예레미야',9,5,'그들은 각기 이웃을 속이며 진실을 말하지 아니하며 그들의 혀로 거짓말하기를 가르치며 악을 행하기에 지치거늘',19181),
('jer-9-6','jer','예레미야',9,6,'네가 사는 곳이 속이는 일 가운데 있도다 그들은 속이는 일로 말미암아 나를 알기를 싫어하느니라 여호와의 말씀이니라',19182),
('jer-9-7','jer','예레미야',9,7,'그러므로 만군의 여호와께서 이와 같이 말씀하시되 보라 내가 내 딸 백성을 어떻게 처치할꼬 그들을 녹이고 연단하리라',19183),
('jer-9-8','jer','예레미야',9,8,'그들의 혀는 죽이는 화살이라 거짓을 말하며 입으로는 그 이웃에게 평화를 말하나 마음으로는 해를 꾸미는도다',19184),
('jer-9-9','jer','예레미야',9,9,'내가 이 일들로 말미암아 그들에게 벌하지 아니하겠으며 내 마음이 이런 나라에 보복하지 않겠느냐 여호와의 말씀이니라',19185),
('jer-9-10','jer','예레미야',9,10,'내가 산들을 위하여 울며 부르짖으며 광야 목장을 위하여 슬퍼하나니 이는 그것들이 불에 탔으므로 지나는 자가 없으며 거기서 가축의 소리가 들리지 아니하며 공중의 새도 짐승도 다 도망하여 없어졌음이라',19186),
('jer-9-11','jer','예레미야',9,11,'내가 예루살렘을 무더기로 만들며 승냥이 굴이 되게 하겠고 유다의 성읍들을 황폐하게 하여 주민이 없게 하리라',19187),
('jer-9-12','jer','예레미야',9,12,'지혜가 있어서 이 일을 깨달을 만한 자가 누구며 여호와의 입의 말씀을 받아서 선포할 자가 누구인고 이 땅이 어찌하여 멸망하여 광야 같이 불타서 지나가는 자가 없게 되었느냐',19188),
('jer-9-13','jer','예레미야',9,13,'여호와께서 말씀하시되 이는 그들이 내가 그들의 앞에 세운 나의 율법을 버리고 내 목소리를 순종하지 아니하며 그대로 행하지 아니하고',19189),
('jer-9-14','jer','예레미야',9,14,'그 마음의 완악함을 따라 그 조상들이 자기에게 가르친 바알들을 따랐음이라',19190),
('jer-9-15','jer','예레미야',9,15,'그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 그들 곧 이 백성에게 쑥을 먹이며 독한 물을 마시게 하고',19191),
('jer-9-16','jer','예레미야',9,16,'그들과 그들의 조상이 알지 못하던 여러 나라 가운데에 그들을 흩어 버리고 진멸되기까지 그 뒤로 칼을 보내리라 하셨느니라',19192),
('jer-9-17','jer','예레미야',9,17,'만군의 여호와께서 이와 같이 말씀하시되 너희는 잘 생각해 보고 곡하는 부녀를 불러오며 또 사람을 보내 지혜로운 부녀를 불러오되',19193),
('jer-9-18','jer','예레미야',9,18,'그들로 빨리 와서 우리를 위하여 애곡하여 우리의 눈에서 눈물이 떨어지게 하며 우리 눈꺼풀에서 물이 쏟아지게 하라',19194),
('jer-9-19','jer','예레미야',9,19,'이는 시온에서 통곡하는 소리가 들리기를 우리가 아주 망하였구나 우리가 크게 부끄러움을 당하였구나 우리가 그 땅을 떠난 것은 그들이 우리 거처를 헐었음이로다 함이로다',19195),
('jer-9-20','jer','예레미야',9,20,'부녀들이여 여호와의 말씀을 들으라 너희 귀에 그 입의 말씀을 받으라 너희 딸들에게 애곡하게 하고 각기 이웃에게 슬픈 노래를 가르치라',19196),
('jer-9-21','jer','예레미야',9,21,'무릇 사망이 우리 창문을 통하여 넘어 들어오며 우리 궁실에 들어오며 밖에서는 자녀들을 거리에서는 청년들을 멸절하려 하느니라',19197),
('jer-9-22','jer','예레미야',9,22,'너는 이같이 말하라 여호와의 말씀에 사람의 시체가 분토 같이 들에 떨어질 것이며 추수하는 자의 뒤에 버려져 거두지 못한 곡식단 같이 되리라 하셨느니라',19198),
('jer-9-23','jer','예레미야',9,23,'여호와께서 이와 같이 말씀하시되 지혜로운 자는 그의 지혜를 자랑하지 말라 용사는 그의 용맹을 자랑하지 말라 부자는 그의 부함을 자랑하지 말라',19199),
('jer-9-24','jer','예레미야',9,24,'자랑하는 자는 이것으로 자랑할지니 곧 명철하여 나를 아는 것과 나 여호와는 사랑과 정의와 공의를 땅에 행하는 자인 줄 깨닫는 것이라 나는 이 일을 기뻐하노라 여호와의 말씀이니라',19200),
('jer-9-25','jer','예레미야',9,25,'여호와의 말씀이니라 보라 날이 이르면 할례 받은 자와 할례 받지 못한 자를 내가 다 벌하리니',19201),
('jer-9-26','jer','예레미야',9,26,'곧 애굽과 유다와 에돔과 암몬 자손과 모압과 및 광야에 살면서 살쩍을 깎은 자들에게라 무릇 모든 민족은 할례를 받지 못하였고 이스라엘은 마음에 할례를 받지 못하였느니라 하셨느니라',19202),
('jer-10-1','jer','예레미야',10,1,'이스라엘 집이여 여호와께서 너희에게 이르시는 말씀을 들을지어다',19203),
('jer-10-2','jer','예레미야',10,2,'여호와께서 이와 같이 말씀하시되 여러 나라의 길을 배우지 말라 이방 사람들은 하늘의 징조를 두려워하거니와 너희는 그것을 두려워하지 말라',19204),
('jer-10-3','jer','예레미야',10,3,'여러 나라의 풍습은 헛된 것이니 삼림에서 벤 나무요 기술공의 두 손이 도끼로 만든 것이라',19205),
('jer-10-4','jer','예레미야',10,4,'그들이 은과 금으로 그것에 꾸미고 못과 장도리로 그것을 든든히 하여 흔들리지 않게 하나니',19206),
('jer-10-5','jer','예레미야',10,5,'그것이 둥근 기둥 같아서 말도 못하며 걸어다니지도 못하므로 사람이 메어야 하느니라 그것이 그들에게 화를 주거나 복을 주지 못하나니 너희는 두려워하지 말라 하셨느니라',19207),
('jer-10-6','jer','예레미야',10,6,'여호와여 주와 같은 이 없나이다 주는 크시니 주의 이름이 그 권능으로 말미암아 크시니이다',19208),
('jer-10-7','jer','예레미야',10,7,'이방 사람들의 왕이시여 주를 경외하지 아니할 자가 누구리이까 이는 주께 당연한 일이라 여러 나라와 여러 왕국들의 지혜로운 자들 가운데 주와 같은 이가 없음이니이다',19209),
('jer-10-8','jer','예레미야',10,8,'그들은 다 무지하고 어리석은 것이니 우상의 가르침은 나무뿐이라',19210),
('jer-10-9','jer','예레미야',10,9,'다시스에서 가져온 은박과 우바스에서 가져온 금으로 꾸미되 기술공과 은장색의 손으로 만들었고 청색 자색 옷을 입었나니 이는 정교한 솜씨로 만든 것이거니와',19211),
('jer-10-10','jer','예레미야',10,10,'오직 여호와는 참 하나님이시요 살아 계신 하나님이시요 영원한 왕이시라 그 진노하심에 땅이 진동하며 그 분노하심을 이방이 능히 당하지 못하느니라',19212),
('jer-10-11','jer','예레미야',10,11,'너희는 이같이 그들에게 이르기를 천지를 짓지 아니한 신들은 땅 위에서, 이 하늘 아래에서 망하리라 하라',19213),
('jer-10-12','jer','예레미야',10,12,'여호와께서 그의 권능으로 땅을 지으셨고 그의 지혜로 세계를 세우셨고 그의 명철로 하늘을 펴셨으며',19214),
('jer-10-13','jer','예레미야',10,13,'그가 목소리를 내신즉 하늘에 많은 물이 생기나니 그는 땅 끝에서 구름이 오르게 하시며 비를 위하여 번개치게 하시며 그 곳간에서 바람을 내시거늘',19215),
('jer-10-14','jer','예레미야',10,14,'사람마다 어리석고 무식하도다 은장이마다 자기의 조각한 신상으로 말미암아 수치를 당하나니 이는 그가 부어 만든 우상은 거짓 것이요 그 속에 생기가 없음이라',19216),
('jer-10-15','jer','예레미야',10,15,'그것들은 헛 것이요 망령되이 만든 것인즉 징벌하실 때에 멸망할 것이나',19217),
('jer-10-16','jer','예레미야',10,16,'야곱의 분깃은 이같지 아니하시니 그는 만물의 조성자요 이스라엘은 그의 기업의 지파라 그 이름은 만군의 여호와시니라',19218),
('jer-10-17','jer','예레미야',10,17,'에워싸인 가운데에 앉은 자여 네 짐 꾸러미를 이 땅에서 꾸리라',19219),
('jer-10-18','jer','예레미야',10,18,'여호와께서 이와 같이 말씀하시되 보라 내가 이 땅에 사는 자를 이번에는 내던질 것이라 그들을 괴롭게 하여 깨닫게 하리라 하셨느니라',19220),
('jer-10-19','jer','예레미야',10,19,'슬프다 내 상처여 내가 중상을 당하였도다 그러나 내가 말하노라 이는 참으로 고난이라 내가 참아야 하리로다',19221),
('jer-10-20','jer','예레미야',10,20,'내 장막이 무너지고 나의 모든 줄이 끊어졌으며 내 자녀가 나를 떠나가고 있지 아니하니 내 장막을 세울 자와 내 휘장을 칠 자가 다시 없도다',19222),
('jer-10-21','jer','예레미야',10,21,'목자들은 어리석어 여호와를 찾지 아니하므로 형통하지 못하며 그 모든 양 떼는 흩어졌도다',19223),
('jer-10-22','jer','예레미야',10,22,'들을지어다 북방에서부터 크게 떠드는 소리가 들리니 유다 성읍들을 황폐하게 하여 승냥이의 거처가 되게 하리로다',19224),
('jer-10-23','jer','예레미야',10,23,'여호와여 내가 알거니와 사람의 길이 자신에게 있지 아니하니 걸음을 지도함이 걷는 자에게 있지 아니하니이다',19225),
('jer-10-24','jer','예레미야',10,24,'여호와여 나를 징계하옵시되 너그러이 하시고 진노로 하지 마옵소서 주께서 내가 없어지게 하실까 두려워하나이다',19226),
('jer-10-25','jer','예레미야',10,25,'주를 알지 못하는 이방 사람들과 주의 이름으로 기도하지 아니하는 족속들에게 주의 분노를 부으소서 그들은 야곱을 씹어 삼켜 멸하고 그의 거처를 황폐하게 하였나이다 하니라',19227),
('jer-11-1','jer','예레미야',11,1,'여호와께로부터 예레미야에게 임한 말씀이라 이르시되',19228),
('jer-11-2','jer','예레미야',11,2,'너희는 이 언약의 말을 듣고 유다인과 예루살렘 주민에게 말하라',19229),
('jer-11-3','jer','예레미야',11,3,'그들에게 이르기를 이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 이 언약의 말을 따르지 않는 자는 저주를 받을 것이니라',19230),
('jer-11-4','jer','예레미야',11,4,'이 언약은 내가 너희 조상들을 쇠풀무 애굽 땅에서 이끌어내던 날에 그들에게 명령한 것이라 곧 내가 이르기를 너희는 내 목소리를 순종하고 나의 모든 명령을 따라 행하라 그리하면 너희는 내 백성이 되겠고 나는 너희의 하나님이 되리라',19231),
('jer-11-5','jer','예레미야',11,5,'내가 또 너희 조상들에게 한 맹세는 그들에게 젖과 꿀이 흐르는 땅을 주리라 한 언약을 이루리라 한 것인데 오늘이 그것을 증언하느니라 하라 하시기로 내가 대답하여 이르되 아멘 여호와여 하였노라',19232),
('jer-11-6','jer','예레미야',11,6,'여호와께서 내게 이르시되 너는 이 모든 말로 유다 성읍들과 예루살렘 거리에서 선포하여 이르기를 너희는 이 언약의 말을 듣고 지키라',19233),
('jer-11-7','jer','예레미야',11,7,'내가 너희 조상들을 애굽 땅에서 인도하여 낸 날부터 오늘까지 간절히 경계하며 끊임없이 경계하기를 너희는 내 목소리를 순종하라 하였으나',19234),
('jer-11-8','jer','예레미야',11,8,'그들이 순종하지 아니하며 귀를 기울이지도 아니하고 각각 그 악한 마음의 완악한 대로 행하였으므로 내가 그들에게 행하라 명령하였어도 그들이 행하지 아니한 이 언약의 모든 규정대로 그들에게 이루게 하였느니라 하라',19235),
('jer-11-9','jer','예레미야',11,9,'여호와께서 또 내게 이르시되 유다인과 예루살렘 주민 중에 반역이 있도다',19236),
('jer-11-10','jer','예레미야',11,10,'그들이 내 말 듣기를 거절한 자기들의 선조의 죄악으로 돌아가서 다른 신들을 따라 섬겼은즉 이스라엘 집과 유다 집이 내가 그들의 조상들과 맺은 언약을 깨뜨렸도다',19237),
('jer-11-11','jer','예레미야',11,11,'그러므로 나 여호와가 이와 같이 말하노라 보라 내가 재앙을 그들에게 내리리니 그들이 피할 수 없을 것이라 그들이 내게 부르짖을지라도 내가 듣지 아니할 것인즉',19238),
('jer-11-12','jer','예레미야',11,12,'유다 성읍들과 예루살렘 주민이 그 분향하는 신들에게 가서 부르짖을지라도 그 신들이 그 고난 가운데에서 절대로 그들을 구원하지 못하리라',19239),
('jer-11-13','jer','예레미야',11,13,'유다야 네 신들이 네 성읍의 수와 같도다 너희가 예루살렘 거리의 수대로 그 수치스러운 물건의 제단 곧 바알에게 분향하는 제단을 쌓았도다',19240),
('jer-11-14','jer','예레미야',11,14,'그러므로 너는 이 백성을 위하여 기도하지 말라 그들을 위하여 부르짖거나 구하지 말라 그들이 그 고난으로 말미암아 내게 부르짖을 때에 내가 그들에게서 듣지 아니하리라',19241),
('jer-11-15','jer','예레미야',11,15,'나의 사랑하는 자가 많은 악한 음모를 꾸미더니 나의 집에서 무엇을 하려느냐 거룩한 제물 고기로 네 재난을 피할 수 있겠느냐 그 때에 네가 기뻐하겠느냐',19242),
('jer-11-16','jer','예레미야',11,16,'여호와께서는 그의 이름을 일컬어 좋은 열매 맺는 아름다운 푸른 감람나무라 하였었으나 큰 소동 중에 그 위에 불을 피웠고 그 가지는 꺾였도다',19243),
('jer-11-17','jer','예레미야',11,17,'바알에게 분향함으로 나의 노여움을 일으킨 이스라엘 집과 유다 집의 악으로 말미암아 그를 심은 만군의 여호와께서 그에게 재앙을 선언하셨느니라',19244),
('jer-11-18','jer','예레미야',11,18,'여호와께서 내게 알게 하셨으므로 내가 그것을 알았나이다 그 때에 주께서 그들의 행위를 내게 보이셨나이다',19245),
('jer-11-19','jer','예레미야',11,19,'나는 끌려서 도살 당하러 가는 순한 어린 양과 같으므로 그들이 나를 해하려고 꾀하기를 우리가 그 나무와 열매를 함께 박멸하자 그를 살아 있는 자의 땅에서 끊어서 그의 이름이 다시 기억되지 못하게 하자 함을 내가 알지 못하였나이다',19246),
('jer-11-20','jer','예레미야',11,20,'공의로 판단하시며 사람의 마음을 감찰하시는 만군의 여호와여 나의 원통함을 주께 아뢰었사오니 그들에게 대한 주의 보복을 내가 보리이다 하였더니',19247),
('jer-11-21','jer','예레미야',11,21,'여호와께서 아나돗 사람들에 대하여 이와 같이 말씀하시되 그들이 네 생명을 빼앗으려고 찾아 이르기를 너는 여호와의 이름으로 예언하지 말라 두렵건대 우리 손에 죽을까 하노라 하도다',19248),
('jer-11-22','jer','예레미야',11,22,'그러므로 만군의 여호와께서 이와 같이 말씀하시니라 보라 내가 그들을 벌하리니 청년들은 칼에 죽으며 자녀들은 기근에 죽고',19249),
('jer-11-23','jer','예레미야',11,23,'남는 자가 없으리라 내가 아나돗 사람에게 재앙을 내리리니 곧 그들을 벌할 해에니라',19250),
('jer-12-1','jer','예레미야',12,1,'여호와여 내가 주와 변론할 때에는 주께서 의로우시니이다 그러나 내가 주께 질문하옵나니 악한 자의 길이 형통하며 반역한 자가 다 평안함은 무슨 까닭이니이까',19251),
('jer-12-2','jer','예레미야',12,2,'주께서 그들을 심으시므로 그들이 뿌리가 박히고 장성하여 열매를 맺었거늘 그들의 입은 주께 가까우나 그들의 마음은 머니이다',19252),
('jer-12-3','jer','예레미야',12,3,'여호와여 주께서 나를 아시고 나를 보시며 내 마음이 주를 향하여 어떠함을 감찰하시오니 양을 잡으려고 끌어냄과 같이 그들을 끌어내시되 죽일 날을 위하여 그들을 구별하옵소서',19253),
('jer-12-4','jer','예레미야',12,4,'언제까지 이 땅이 슬퍼하며 온 지방의 채소가 마르리이까 짐승과 새들도 멸절하게 되었사오니 이는 이 땅 주민이 악하여 스스로 말하기를 그가 우리의 나중 일을 보지 못하리라 함이니이다',19254),
('jer-12-5','jer','예레미야',12,5,'만일 네가 보행자와 함께 달려도 피곤하면 어찌 능히 말과 경주하겠느냐 네가 평안한 땅에서는 무사하려니와 요단 강 물이 넘칠 때에는 어찌하겠느냐',19255),
('jer-12-6','jer','예레미야',12,6,'네 형제와 아버지의 집이라도 너를 속이며 네 뒤에서 크게 외치나니 그들이 네게 좋은 말을 할지라도 너는 믿지 말지니라',19256),
('jer-12-7','jer','예레미야',12,7,'내가 내 집을 버리며 내 소유를 내던져 내 마음으로 사랑하는 것을 그 원수의 손에 넘겼나니',19257),
('jer-12-8','jer','예레미야',12,8,'내 소유가 숲속의 사자 같이 되어서 나를 향하여 그 소리를 내므로 내가 그를 미워하였음이로라',19258),
('jer-12-9','jer','예레미야',12,9,'내 소유가 내게 대하여는 무늬 있는 매가 아니냐 매들이 그것을 에워싸지 아니하느냐 너희는 가서 들짐승들을 모아다가 그것을 삼키게 하라',19259),
('jer-12-10','jer','예레미야',12,10,'많은 목자가 내 포도원을 헐며 내 몫을 짓밟아서 내가 기뻐하는 땅을 황무지로 만들었도다',19260),
('jer-12-11','jer','예레미야',12,11,'그들이 이를 황폐하게 하였으므로 그 황무지가 나를 향하여 슬퍼하는도다 온 땅이 황폐함은 이를 마음에 두는 자가 없음이로다',19261),
('jer-12-12','jer','예레미야',12,12,'파괴하는 자들이 광야의 모든 벗은 산 위에 이르렀고 여호와의 칼이 땅 이 끝에서 저 끝까지 삼키니 모든 육체가 평안하지 못하도다',19262),
('jer-12-13','jer','예레미야',12,13,'무리가 밀을 심어도 가시를 거두며 수고하여도 소득이 없은즉 그 소산으로 말미암아 스스로 수치를 당하리니 이는 여호와의 분노로 말미암음이니라',19263),
('jer-12-14','jer','예레미야',12,14,'내가 내 백성 이스라엘에게 기업으로 준 소유에 손을 대는 나의 모든 악한 이웃에 대하여 여호와께서 이와 같이 말씀하시니라 보라 내가 그들을 그 땅에서 뽑아 버리겠고 유다 집을 그들 가운데서 뽑아 내리라',19264),
('jer-12-15','jer','예레미야',12,15,'내가 그들을 뽑아 낸 후에 내가 돌이켜 그들을 불쌍히 여겨서 각 사람을 그들의 기업으로, 각 사람을 그 땅으로 다시 인도하리니',19265),
('jer-12-16','jer','예레미야',12,16,'그들이 내 백성의 도를 부지런히 배우며 살아 있는 여호와라는 내 이름으로 맹세하기를 자기들이 내 백성을 가리켜 바알로 맹세하게 한 것 같이 하면 그들이 내 백성 가운데에 세움을 입으려니와',19266),
('jer-12-17','jer','예레미야',12,17,'그들이 순종하지 아니하면 내가 반드시 그 나라를 뽑으리라 뽑아 멸하리라 여호와의 말씀이니라',19267),
('jer-13-1','jer','예레미야',13,1,'여호와께서 이와 같이 내게 이르시되 너는 가서 베 띠를 사서 네 허리에 띠고 물에 적시지 말라 하시기로',19268),
('jer-13-2','jer','예레미야',13,2,'내가 여호와의 말씀대로 띠를 사서 내 허리에 띠니라',19269),
('jer-13-3','jer','예레미야',13,3,'여호와의 말씀이 다시 내게 임하여 이르시되',19270),
('jer-13-4','jer','예레미야',13,4,'너는 사서 네 허리에 띤 띠를 가지고 일어나 유브라데로 가서 거기서 그것을 바위 틈에 감추라 하시기로',19271),
('jer-13-5','jer','예레미야',13,5,'내가 여호와께서 내게 명령하신 대로 가서 그것을 유브라데 물 가에 감추니라',19272),
('jer-13-6','jer','예레미야',13,6,'여러 날 후에 여호와께서 내게 이르시되 일어나 유브라데로 가서 내가 네게 명령하여 거기 감추게 한 띠를 가져오라 하시기로',19273),
('jer-13-7','jer','예레미야',13,7,'내가 유브라데로 가서 그 감추었던 곳을 파고 띠를 가져오니 띠가 썩어서 쓸 수 없게 되었더라',19274),
('jer-13-8','jer','예레미야',13,8,'여호와의 말씀이 내게 임하니라 이르시되',19275),
('jer-13-9','jer','예레미야',13,9,'여호와께서 이와 같이 말씀하시니라 내가 유다의 교만과 예루살렘의 큰 교만을 이같이 썩게 하리라',19276),
('jer-13-10','jer','예레미야',13,10,'이 악한 백성이 내 말 듣기를 거절하고 그 마음의 완악한 대로 행하며 다른 신들을 따라 그를 섬기며 그에게 절하니 그들이 이 띠가 쓸 수 없음 같이 되리라',19277),
('jer-13-11','jer','예레미야',13,11,'여호와의 말씀이니라 띠가 사람의 허리에 속함 같이 내가 이스라엘 온 집과 유다 온 집으로 내게 속하게 하여 그들로 내 백성이 되게 하며 내 이름과 명예와 영광이 되게 하려 하였으나 그들이 듣지 아니하였느니라',19278),
('jer-13-12','jer','예레미야',13,12,'그러므로 너는 이 말로 그들에게 이르기를 이스라엘의 하나님 여호와의 말씀에 모든 가죽부대가 포도주로 차리라 하셨다 하라 그리하면 그들이 네게 이르기를 모든 가죽부대가 포도주로 찰 줄을 우리가 어찌 알지 못하리요 하리니',19279),
('jer-13-13','jer','예레미야',13,13,'너는 다시 그들에게 이르기를 여호와의 말씀에 보라 내가 이 땅의 모든 주민과 다윗의 왕위에 앉은 왕들과 제사장들과 선지자들과 예루살렘 모든 주민으로 잔뜩 취하게 하고',19280),
('jer-13-14','jer','예레미야',13,14,'또 그들에게 각 사람이 충돌하여 상하게 하되 부자 사이에도 그러하게 할 것이라 내가 그들을 불쌍히 여기지 아니하며 사랑하지 아니하며 아끼지 아니하고 멸하리라 하셨다 하라 여호와의 말씀이니라',19281),
('jer-13-15','jer','예레미야',13,15,'너희는 들을지어다, 귀를 기울일지어다, 교만하지 말지어다, 여호와께서 말씀하셨음이라',19282),
('jer-13-16','jer','예레미야',13,16,'그가 어둠을 일으키시기 전, 너희 발이 어두운 산에 거치기 전, 너희 바라는 빛이 사망의 그늘로 변하여 침침한 어둠이 되게 하시기 전에 너희 하나님 여호와께 영광을 돌리라',19283),
('jer-13-17','jer','예레미야',13,17,'너희가 이를 듣지 아니하면 나의 심령이 너희 교만으로 말미암아 은밀한 곳에서 울 것이며 여호와의 양 떼가 사로잡힘으로 말미암아 눈물을 흘려 통곡하리라',19284),
('jer-13-18','jer','예레미야',13,18,'너는 왕과 왕후에게 전하기를 스스로 낮추어 앉으라 관 곧 영광의 면류관이 내려졌다 하라',19285),
('jer-13-19','jer','예레미야',13,19,'네겝의 성읍들이 봉쇄되어 열 자가 없고 유다가 다 잡혀가되 온전히 잡혀가도다',19286),
('jer-13-20','jer','예레미야',13,20,'너는 눈을 들어 북방에서 오는 자들을 보라 네게 맡겼던 양 떼, 네 아름다운 양 떼는 어디 있느냐',19287),
('jer-13-21','jer','예레미야',13,21,'너의 친구 삼았던 자를 그가 네 위에 우두머리로 세우실 때에 네가 무슨 말을 하겠느냐 네가 고통에 사로잡힘이 산고를 겪는 여인 같지 않겠느냐',19288),
('jer-13-22','jer','예레미야',13,22,'네가 마음으로 이르기를 어찌하여 이런 일이 내게 닥쳤는고 하겠으나 네 죄악이 크므로 네 치마가 들리고 네 발뒤꿈치가 상함이니라',19289),
('jer-13-23','jer','예레미야',13,23,'구스인이 그의 피부를, 표범이 그의 반점을 변하게 할 수 있느냐 할 수 있을진대 악에 익숙한 너희도 선을 행할 수 있으리라',19290),
('jer-13-24','jer','예레미야',13,24,'그러므로 내가 그들을 사막 바람에 불려가는 검불 같이 흩으리로다',19291),
('jer-13-25','jer','예레미야',13,25,'여호와의 말씀이니라 이는 네 몫이요 내가 헤아려 정하여 네게 준 분깃이니 네가 나를 잊어버리고 거짓을 신뢰하는 까닭이라',19292),
('jer-13-26','jer','예레미야',13,26,'그러므로 내가 네 치마를 네 얼굴에까지 들춰서 네 수치를 드러내리라',19293),
('jer-13-27','jer','예레미야',13,27,'내가 너의 간음과 사악한 소리와 들의 작은 산 위에서 네가 행한 음란과 음행과 가증한 것을 보았노라 화 있을진저 예루살렘이여 네가 얼마나 오랜 후에야 정결하게 되겠느냐 하시니라',19294),
('jer-14-1','jer','예레미야',14,1,'가뭄에 대하여 예레미야에게 임한 여호와의 말씀이라',19295),
('jer-14-2','jer','예레미야',14,2,'유다가 슬퍼하며 성문의 무리가 피곤하여 땅 위에서 애통하니 예루살렘의 부르짖음이 위로 오르도다',19296),
('jer-14-3','jer','예레미야',14,3,'귀인들은 자기 사환들을 보내어 물을 얻으려 하였으나 그들이 우물에 갔어도 물을 얻지 못하여 빈 그릇으로 돌아오니 부끄럽고 근심하여 그들의 머리를 가리며',19297),
('jer-14-4','jer','예레미야',14,4,'땅에 비가 없어 지면이 갈라지니 밭 가는 자가 부끄러워서 그의 머리를 가리는도다',19298),
('jer-14-5','jer','예레미야',14,5,'들의 암사슴은 새끼를 낳아도 풀이 없으므로 내버리며',19299),
('jer-14-6','jer','예레미야',14,6,'들 나귀들은 벗은 산 위에 서서 승냥이 같이 헐떡이며 풀이 없으므로 눈이 흐려지는도다',19300),
('jer-14-7','jer','예레미야',14,7,'여호와여 우리의 죄악이 우리에게 대하여 증언할지라도 주는 주의 이름을 위하여 일하소서 우리의 타락함이 많으니이다 우리가 주께 범죄하였나이다',19301),
('jer-14-8','jer','예레미야',14,8,'이스라엘의 소망이시요 고난 당한 때의 구원자시여 어찌하여 이 땅에서 거류하는 자 같이, 하룻밤을 유숙하는 나그네 같이 하시나이까',19302),
('jer-14-9','jer','예레미야',14,9,'어찌하여 놀란 자 같으시며 구원하지 못하는 용사 같으시니이까 여호와여 주는 그래도 우리 가운데 계시고 우리는 주의 이름으로 일컬음을 받는 자이오니 우리를 버리지 마옵소서',19303),
('jer-14-10','jer','예레미야',14,10,'여호와께서 이 백성에 대하여 이와 같이 말씀하시되 그들이 어그러진 길을 사랑하여 그들의 발을 멈추지 아니하므로 여호와께서 그들을 받지 아니하고 이제 그들의 죄를 기억하시고 그 죄를 벌하시리라 하시고',19304),
('jer-14-11','jer','예레미야',14,11,'여호와께서 또 내게 이르시되 너는 이 백성을 위하여 복을 구하지 말라',19305),
('jer-14-12','jer','예레미야',14,12,'그들이 금식할지라도 내가 그 부르짖음을 듣지 아니하겠고 번제와 소제를 드릴지라도 내가 그것을 받지 아니할 뿐 아니라 칼과 기근과 전염병으로 내가 그들을 멸하리라',19306),
('jer-14-13','jer','예레미야',14,13,'이에 내가 말하되 슬프도소이다 주 여호와여 보시옵소서 선지자들이 그들에게 이르기를 너희가 칼을 보지 아니하겠고 기근은 너희에게 이르지 아니할 것이라 내가 이 곳에서 너희에게 확실한 평강을 주리라 하나이다',19307),
('jer-14-14','jer','예레미야',14,14,'여호와께서 내게 이르시되 선지자들이 내 이름으로 거짓 예언을 하도다 나는 그들을 보내지 아니하였고 그들에게 명령하거나 이르지 아니하였거늘 그들이 거짓 계시와 점술과 헛된 것과 자기 마음의 거짓으로 너희에게 예언하는도다',19308),
('jer-14-15','jer','예레미야',14,15,'그러므로 내가 보내지 아니하였어도 내 이름으로 예언하여 이르기를 칼과 기근이 이 땅에 이르지 아니하리라 하는 선지자들에 대하여 여호와께서 이와 같이 말씀하셨노라 그 선지자들은 칼과 기근에 멸망할 것이요',19309),
('jer-14-16','jer','예레미야',14,16,'그들의 예언을 받은 백성은 기근과 칼로 말미암아 예루살렘 거리에 던짐을 당할 것인즉 그들을 장사할 자가 없을 것이요 그들의 아내와 아들과 딸이 그렇게 되리니 이는 내가 그들의 악을 그 위에 부음이니라',19310),
('jer-14-17','jer','예레미야',14,17,'너는 이 말로 그들에게 이르라 내 눈이 밤낮으로 그치지 아니하고 눈물을 흘리리니 이는 처녀 딸 내 백성이 큰 파멸, 중한 상처로 말미암아 망함이라',19311),
('jer-14-18','jer','예레미야',14,18,'내가 들에 나간즉 칼에 죽은 자요 내가 성읍에 들어간즉 기근으로 병든 자며 선지자나 제사장이나 알지 못하는 땅으로 두루 다니도다',19312),
('jer-14-19','jer','예레미야',14,19,'주께서 유다를 온전히 버리시나이까 주의 심령이 시온을 싫어하시나이까 어찌하여 우리를 치시고 치료하지 아니하시나이까 우리가 평강을 바라도 좋은 것이 없고 치료 받기를 기다리나 두려움만 보나이다',19313),
('jer-14-20','jer','예레미야',14,20,'여호와여 우리의 악과 우리 조상의 죄악을 인정하나이다 우리가 주께 범죄하였나이다',19314),
('jer-14-21','jer','예레미야',14,21,'주의 이름을 위하여 우리를 미워하지 마옵소서 주의 영광의 보좌를 욕되게 마옵소서 주께서 우리와 세우신 언약을 기억하시고 폐하지 마옵소서',19315),
('jer-14-22','jer','예레미야',14,22,'이방인의 우상 가운데 능히 비를 내리게 할 자가 있나이까 하늘이 능히 소나기를 내릴 수 있으리이까 우리 하나님 여호와여 그리하는 자는 주가 아니시니이까 그러므로 우리가 주를 앙망하옵는 것은 주께서 이 모든 것을 만드셨음이니이다 하니라',19316),
('jer-15-1','jer','예레미야',15,1,'여호와께서 내게 이르시되 모세와 사무엘이 내 앞에 섰다 할지라도 내 마음은 이 백성을 향할 수 없나니 그들을 내 앞에서 쫓아 내보내라',19317),
('jer-15-2','jer','예레미야',15,2,'그들이 만일 네게 말하기를 우리가 어디로 나아가리요 하거든 너는 그들에게 이르기를 여호와께서 이와 같이 말씀하시니라 죽을 자는 죽음으로 나아가고 칼을 받을 자는 칼로 나아가고 기근을 당할 자는 기근으로 나아가고 포로 될 자는 포로 됨으로 나아갈지니라 하셨다 하라',19318),
('jer-15-3','jer','예레미야',15,3,'여호와의 말씀이니라 내가 그들을 네 가지로 벌하리니 곧 죽이는 칼과 찢는 개와 삼켜 멸하는 공중의 새와 땅의 짐승으로 할 것이며',19319),
('jer-15-4','jer','예레미야',15,4,'유다 왕 히스기야의 아들 므낫세가 예루살렘에 행한 것으로 말미암아 내가 그들을 세계 여러 민족 가운데에 흩으리라',19320),
('jer-15-5','jer','예레미야',15,5,'예루살렘아 너를 불쌍히 여길 자 누구며 너를 위해 울 자 누구며 돌이켜 네 평안을 물을 자 누구냐',19321),
('jer-15-6','jer','예레미야',15,6,'여호와께서 이르시되 네가 나를 버렸고 내게서 물러갔으므로 네게로 내 손을 펴서 너를 멸하였노니 이는 내가 뜻을 돌이키기에 지쳤음이로다',19322),
('jer-15-7','jer','예레미야',15,7,'내가 그들을 그 땅의 여러 성문에서 키로 까불러 그 자식을 끊어서 내 백성을 멸하였나니 이는 그들이 자기들의 길에서 돌이키지 아니하였음이라',19323),
('jer-15-8','jer','예레미야',15,8,'그들의 과부가 내 앞에 바다 모래보다 더 많아졌느니라 내가 대낮에 파멸시킬 자를 그들에게로 데려다가 그들과 청년들의 어미를 쳐서 놀람과 두려움을 그들에게 갑자기 닥치게 하였으며',19324),
('jer-15-9','jer','예레미야',15,9,'일곱을 낳은 여인에게는 쇠약하여 기절하게 하며 아직도 대낮에 그의 해가 떨어져서 그에게 수치와 근심을 당하게 하였느니라 그 남은 자는 그들의 대적의 칼에 붙이리라 여호와의 말씀이니라',19325),
('jer-15-10','jer','예레미야',15,10,'내게 재앙이로다 나의 어머니여 어머니께서 나를 온 세계에 다투는 자와 싸우는 자를 만날 자로 낳으셨도다 내가 꾸어 주지도 아니하였고 사람이 내게 꾸이지도 아니하였건마는 다 나를 저주하는도다',19326),
('jer-15-11','jer','예레미야',15,11,'여호와께서 이르시되 내가 진실로 너를 강하게 할 것이요 너에게 복을 받게 할 것이며 내가 진실로 네 원수로 재앙과 환난의 때에 네게 간구하게 하리라',19327),
('jer-15-12','jer','예레미야',15,12,'누가 능히 철 곧 북방의 철과 놋을 꺾으리요',19328),
('jer-15-13','jer','예레미야',15,13,'그러나 네 모든 죄로 말미암아 네 국경 안의 모든 재산과 보물로 값 없이 탈취를 당하게 할 것이며',19329),
('jer-15-14','jer','예레미야',15,14,'네 원수와 함께 네가 알지 못하는 땅에 이르게 하리니 이는 나의 진노의 맹렬한 불이 너희를 사르려 함이라',19330),
('jer-15-15','jer','예레미야',15,15,'여호와여 주께서 아시오니 원하건대 주는 나를 기억하시며 돌보시사 나를 박해하는 자에게 보복하시고 주의 오래 참으심으로 말미암아 나로 멸망하지 아니하게 하옵시며 주를 위하여 내가 부끄러움 당하는 줄을 아시옵소서',19331),
('jer-15-16','jer','예레미야',15,16,'만군의 하나님 여호와시여 나는 주의 이름으로 일컬음을 받는 자라 내가 주의 말씀을 얻어 먹었사오니 주의 말씀은 내게 기쁨과 내 마음의 즐거움이오나',19332),
('jer-15-17','jer','예레미야',15,17,'내가 기뻐하는 자의 모임 가운데 앉지 아니하며 즐거워하지도 아니하고 주의 손에 붙들려 홀로 앉았사오니 이는 주께서 분노로 내게 채우셨음이니이다',19333),
('jer-15-18','jer','예레미야',15,18,'나의 고통이 계속하며 상처가 중하여 낫지 아니함은 어찌 됨이니이까 주께서는 내게 대하여 물이 말라서 속이는 시내 같으시리이까',19334),
('jer-15-19','jer','예레미야',15,19,'여호와께서 이와 같이 말씀하시되 네가 만일 돌아오면 내가 너를 다시 이끌어 내 앞에 세울 것이며 네가 만일 헛된 것을 버리고 귀한 것을 말한다면 너는 나의 입이 될 것이라 그들은 네게로 돌아오려니와 너는 그들에게로 돌아가지 말지니라',19335),
('jer-15-20','jer','예레미야',15,20,'내가 너로 이 백성 앞에 견고한 놋 성벽이 되게 하리니 그들이 너를 칠지라도 이기지 못할 것은 내가 너와 함께 하여 너를 구하여 건짐이라 여호와의 말씀이니라',19336),
('jer-15-21','jer','예레미야',15,21,'내가 너를 악한 자의 손에서 건지며 무서운 자의 손에서 구원하리라',19337),
('jer-16-1','jer','예레미야',16,1,'여호와의 말씀이 또 내게 임하여 이르시되',19338),
('jer-16-2','jer','예레미야',16,2,'너는 이 땅에서 아내를 맞이하지 말며 자녀를 두지 말지니라',19339),
('jer-16-3','jer','예레미야',16,3,'이 곳에서 낳은 자녀와 이 땅에서 그들을 해산한 어머니와 그들을 낳은 아버지에 대하여 여호와께서 이와 같이 말씀하시오니',19340),
('jer-16-4','jer','예레미야',16,4,'그들은 독한 병으로 죽어도 아무도 슬퍼하지 않을 것이며 묻어 주지 않아 지면의 분토와 같을 것이며 칼과 기근에 망하고 그 시체는 공중의 새와 땅의 짐승의 밥이 되리라',19341),
('jer-16-5','jer','예레미야',16,5,'여호와께서 이와 같이 말씀하시되 초상집에 들어가지 말라 가서 통곡하지 말며 그들을 위하여 애곡하지 말라 내가 이 백성에게서 나의 평강을 빼앗으며 인자와 사랑을 제함이라 여호와의 말씀이니라',19342),
('jer-16-6','jer','예레미야',16,6,'큰 자든지 작은 자든지 이 땅에서 죽으리니 그들이 매장되지 못할 것이며 그들을 위하여 애곡하는 자도 없겠고 자기 몸을 베거나 머리털을 미는 자도 없을 것이며',19343),
('jer-16-7','jer','예레미야',16,7,'그 죽은 자로 말미암아 슬퍼하는 자와 떡을 떼며 위로하는 자가 없을 것이며 그들의 아버지나 어머니의 상사를 위하여 위로의 잔을 그들에게 마시게 할 자가 없으리라',19344),
('jer-16-8','jer','예레미야',16,8,'너는 잔칫집에 들어가서 그들과 함께 앉아 먹거나 마시지 말라',19345),
('jer-16-9','jer','예레미야',16,9,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 기뻐하는 소리와 즐거워하는 소리와 신랑의 소리와 신부의 소리를 내가 네 목전, 네 시대에 이 곳에서 끊어지게 하리라',19346),
('jer-16-10','jer','예레미야',16,10,'네가 이 모든 말로 백성에게 말할 때에 그들이 네게 묻기를 여호와께서 우리에게 이 모든 큰 재앙을 선포하심은 어찌 됨이며 우리의 죄악은 무엇이며 우리가 우리 하나님 여호와께 범한 죄는 무엇이냐 하거든',19347),
('jer-16-11','jer','예레미야',16,11,'너는 그들에게 대답하기를 여호와께서 말씀하시되 너희 조상들이 나를 버리고 다른 신들을 따라서 그들을 섬기며 그들에게 절하고 나를 버려 내 율법을 지키지 아니하였음이라',19348),
('jer-16-12','jer','예레미야',16,12,'너희가 너희 조상들보다 더욱 악을 행하였도다 보라 너희가 각기 악한 마음의 완악함을 따라 행하고 나에게 순종하지 아니하였으므로',19349),
('jer-16-13','jer','예레미야',16,13,'내가 너희를 이 땅에서 쫓아내어 너희와 너희 조상들이 알지 못하던 땅에 이르게 할 것이라 너희가 거기서 주야로 다른 신들을 섬기리니 이는 내가 너희에게 은혜를 베풀지 아니함이라 하셨다 하라',19350),
('jer-16-14','jer','예레미야',16,14,'여호와의 말씀이니라 그러나 보라 날이 이르리니 다시는 이스라엘 자손을 애굽 땅에서 인도하여 내신 여호와께서 살아 계심을 두고 맹세하지 아니하고',19351),
('jer-16-15','jer','예레미야',16,15,'이스라엘 자손을 북방 땅과 그 쫓겨 났던 모든 나라에서 인도하여 내신 여호와께서 살아 계심을 두고 맹세하리라 내가 그들을 그들의 조상들에게 준 그들의 땅으로 인도하여 들이리라',19352),
('jer-16-16','jer','예레미야',16,16,'여호와의 말씀이니라 보라 내가 많은 어부를 불러다가 그들을 낚게 하며 그 후에 많은 포수를 불러다가 그들을 모든 산과 모든 언덕과 바위 틈에서 사냥하게 하리니',19353),
('jer-16-17','jer','예레미야',16,17,'이는 내 눈이 그들의 행위를 살펴보므로 그들이 내 얼굴 앞에서 숨기지 못하며 그들의 죄악이 내 목전에서 숨겨지지 못함이라',19354),
('jer-16-18','jer','예레미야',16,18,'내가 우선 그들의 악과 죄를 배나 갚을 것은 그들이 그 미운 물건의 시체로 내 땅을 더럽히며 그들의 가증한 것으로 내 기업에 가득하게 하였음이라',19355),
('jer-16-19','jer','예레미야',16,19,'여호와 나의 힘, 나의 요새, 환난날의 피난처시여 민족들이 땅 끝에서 주께 이르러 말하기를 우리 조상들의 계승한 바는 허망하고 거짓되고 무익한 것뿐이라',19356),
('jer-16-20','jer','예레미야',16,20,'사람이 어찌 신 아닌 것을 자기의 신으로 삼겠나이까 하리이다',19357),
('jer-16-21','jer','예레미야',16,21,'여호와께서 이르시되 보라 이번에 그들에게 내 손과 내 능력을 알려서 그들로 내 이름이 여호와인 줄 알게 하리라',19358),
('jer-17-1','jer','예레미야',17,1,'유다의 죄는 금강석 끝 철필로 기록되되 그들의 마음 판과 그들의 제단 뿔에 새겨졌거늘',19359),
('jer-17-2','jer','예레미야',17,2,'그들의 자녀가 높은 언덕 위 푸른 나무 곁에 있는 그 제단들과 아세라들을 생각하도다',19360),
('jer-17-3','jer','예레미야',17,3,'들에 있는 나의 산아 네 온 영토의 죄로 말미암아 내가 네 재산과 네 모든 보물과 산당들로 노략을 당하게 하리니',19361),
('jer-17-4','jer','예레미야',17,4,'내가 네게 준 네 기업에서 네 손을 뗄 것이며 또 내가 너로 하여금 너의 알지 못하는 땅에서 네 원수를 섬기게 하리니 이는 너희가 내 노를 맹렬하게 하여 영원히 타는 불을 일으켰음이라',19362),
('jer-17-5','jer','예레미야',17,5,'여호와께서 이와 같이 말씀하시니라 무릇 사람을 믿으며 육신으로 그의 힘을 삼고 마음이 여호와에게서 떠난 그 사람은 저주를 받을 것이라',19363),
('jer-17-6','jer','예레미야',17,6,'그는 사막의 떨기나무 같아서 좋은 일이 오는 것을 보지 못하고 광야 간조한 곳, 건건한 땅, 사람이 살지 않는 땅에 살리라',19364),
('jer-17-7','jer','예레미야',17,7,'그러나 무릇 여호와를 의지하며 여호와를 의뢰하는 그 사람은 복을 받을 것이라',19365),
('jer-17-8','jer','예레미야',17,8,'그는 물 가에 심어진 나무가 그 뿌리를 강변에 뻗치고 더위가 올지라도 두려워하지 아니하며 그 잎이 청청하며 가무는 해에도 걱정이 없고 결실이 그치지 아니함 같으리라',19366),
('jer-17-9','jer','예레미야',17,9,'만물보다 거짓되고 심히 부패한 것은 마음이라 누가 능히 이를 알리요마는',19367),
('jer-17-10','jer','예레미야',17,10,'나 여호와는 심장을 살피며 폐부를 시험하고 각각 그의 행위와 그의 행실대로 보응하나니',19368),
('jer-17-11','jer','예레미야',17,11,'불의로 치부하는 자는 자고새가 낳지 아니한 알을 품음 같아서 그의 중년에 그것이 떠나겠고 마침내 어리석은 자가 되리라',19369),
('jer-17-12','jer','예레미야',17,12,'영화로우신 보좌여 시작부터 높이 계시며 우리의 성소이시며',19370),
('jer-17-13','jer','예레미야',17,13,'이스라엘의 소망이신 여호와여 무릇 주를 버리는 자는 다 수치를 당할 것이라 무릇 여호와를 떠나는 자는 흙에 기록이 되오리니 이는 생수의 근원이신 여호와를 버림이니이다',19371),
('jer-17-14','jer','예레미야',17,14,'여호와여 주는 나의 찬송이시오니 나를 고치소서 그리하시면 내가 낫겠나이다 나를 구원하소서 그리하시면 내가 구원을 얻으리이다',19372),
('jer-17-15','jer','예레미야',17,15,'보라 그들이 내게 이르기를 여호와의 말씀이 어디 있느냐 이제 임하게 할지어다 하나이다',19373),
('jer-17-16','jer','예레미야',17,16,'나는 목자의 직분에서 물러가지 아니하고 주를 따랐사오며 재앙의 날도 내가 원하지 아니하였음을 주께서 아시는 바라 내 입술에서 나온 것이 주의 목전에 있나이다',19374),
('jer-17-17','jer','예레미야',17,17,'주는 내게 두려움이 되지 마옵소서 재앙의 날에 주는 나의 피난처시니이다',19375),
('jer-17-18','jer','예레미야',17,18,'나를 박해하는 자로 치욕을 당하게 하시고 나로 치욕을 당하게 마옵소서 그들은 놀라게 하시고 나는 놀라게 하지 마시옵소서 재앙의 날을 그들에게 임하게 하시며 배나 되는 멸망으로 그들을 멸하소서',19376),
('jer-17-19','jer','예레미야',17,19,'여호와께서 내게 이와 같이 말씀하시되 너는 가서 유다 왕들이 출입하는 평민의 문과 예루살렘 모든 문에 서서',19377),
('jer-17-20','jer','예레미야',17,20,'무리에게 이르기를 이 문으로 들어오는 유다 왕들과 유다 모든 백성과 예루살렘 모든 주민인 너희는 여호와의 말씀을 들을지어다',19378),
('jer-17-21','jer','예레미야',17,21,'여호와께서 이와 같이 말씀하시되 너희는 스스로 삼가서 안식일에 짐을 지고 예루살렘 문으로 들어오지 말며',19379),
('jer-17-22','jer','예레미야',17,22,'안식일에 너희 집에서 짐을 내지 말며 어떤 일이라도 하지 말고 내가 너희 조상들에게 명령함 같이 안식일을 거룩히 할지어다',19380),
('jer-17-23','jer','예레미야',17,23,'그들은 순종하지 아니하며 귀를 기울이지 아니하며 그 목을 곧게 하여 듣지 아니하며 교훈을 받지 아니하였느니라',19381),
('jer-17-24','jer','예레미야',17,24,'여호와의 말씀이니라 너희가 만일 삼가 나를 순종하여 안식일에 짐을 지고 이 성문으로 들어오지 아니하며 안식일을 거룩히 하여 어떤 일이라도 하지 아니하면',19382),
('jer-17-25','jer','예레미야',17,25,'다윗의 왕위에 앉아 있는 왕들과 고관들이 병거와 말을 타고 이 성문으로 들어오되 그들과 유다 모든 백성과 예루살렘 주민들이 함께 그리할 것이요 이 성은 영원히 있을 것이며',19383),
('jer-17-26','jer','예레미야',17,26,'사람들이 유다 성읍들과 예루살렘에 둘린 곳들과 베냐민 땅과 평지와 산지와 네겝으로부터 와서 번제와 희생과 소제와 유향과 감사제물을 여호와의 성전에 가져오려니와',19384),
('jer-17-27','jer','예레미야',17,27,'그러나 만일 너희가 나를 순종하지 아니하고 안식일을 거룩되게 아니하여 안식일에 짐을 지고 예루살렘 문으로 들어오면 내가 성문에 불을 놓아 예루살렘 궁전을 삼키게 하리니 그 불이 꺼지지 아니하리라 하셨다 할지니라 하시니라',19385),
('jer-18-1','jer','예레미야',18,1,'여호와께로부터 예레미야에게 임한 말씀에 이르시되',19386),
('jer-18-2','jer','예레미야',18,2,'너는 일어나 토기장이의 집으로 내려가라 내가 거기에서 내 말을 네게 들려 주리라 하시기로',19387),
('jer-18-3','jer','예레미야',18,3,'내가 토기장이의 집으로 내려가서 본즉 그가 녹로로 일을 하는데',19388),
('jer-18-4','jer','예레미야',18,4,'진흙으로 만든 그릇이 토기장이의 손에서 터지매 그가 그것으로 자기 의견에 좋은 대로 다른 그릇을 만들더라',19389),
('jer-18-5','jer','예레미야',18,5,'그 때에 여호와의 말씀이 내게 임하니라 이르시되',19390),
('jer-18-6','jer','예레미야',18,6,'여호와의 말씀이니라 이스라엘 족속아 이 토기장이가 하는 것 같이 내가 능히 너희에게 행하지 못하겠느냐 이스라엘 족속아 진흙이 토기장이의 손에 있음 같이 너희가 내 손에 있느니라',19391),
('jer-18-7','jer','예레미야',18,7,'내가 어느 민족이나 국가를 뽑거나 부수거나 멸하려 할 때에',19392),
('jer-18-8','jer','예레미야',18,8,'만일 내가 말한 그 민족이 그의 악에서 돌이키면 내가 그에게 내리기로 생각하였던 재앙에 대하여 뜻을 돌이키겠고',19393),
('jer-18-9','jer','예레미야',18,9,'내가 어느 민족이나 국가를 건설하거나 심으려 할 때에',19394),
('jer-18-10','jer','예레미야',18,10,'만일 그들이 나 보기에 악한 것을 행하여 내 목소리를 청종하지 아니하면 내가 그에게 유익하게 하리라고 한 복에 대하여 뜻을 돌이키리라',19395),
('jer-18-11','jer','예레미야',18,11,'그러므로 이제 너는 유다 사람들과 예루살렘 주민들에게 말하여 이르기를 여호와의 말씀에 보라 내가 너희에게 재앙을 내리며 계책을 세워 너희를 치려 하노니 너희는 각기 악한 길에서 돌이키며 너희의 길과 행위를 아름답게 하라 하셨다 하라',19396),
('jer-18-12','jer','예레미야',18,12,'그러나 그들이 말하기를 이는 헛되니 우리는 우리의 계획대로 행하며 우리는 각기 악한 마음이 완악한 대로 행하리라 하느니라',19397),
('jer-18-13','jer','예레미야',18,13,'그러므로 여호와께서 이와 같이 말씀하시니라 너희는 누가 이러한 일을 들었는지 여러 나라 가운데 물어보라 처녀 이스라엘이 심히 가증한 일을 행하였도다',19398),
('jer-18-14','jer','예레미야',18,14,'레바논의 눈이 어찌 들의 바위를 떠나겠으며 먼 곳에서 흘러내리는 찬물이 어찌 마르겠느냐',19399),
('jer-18-15','jer','예레미야',18,15,'무릇 내 백성은 나를 잊고 허무한 것에게 분향하거니와 이러한 것들은 그들로 그들의 길 곧 그 옛길에서 넘어지게 하며 곁길 곧 닦지 아니한 길로 행하게 하여',19400),
('jer-18-16','jer','예레미야',18,16,'그들의 땅으로 두려움과 영원한 웃음 거리가 되게 하리니 그리로 지나는 자마다 놀라서 그의 머리를 흔들리라',19401),
('jer-18-17','jer','예레미야',18,17,'내가 그들을 그들의 원수 앞에서 흩어 버리기를 동풍으로 함 같이 할 것이며 그들의 재난의 날에는 내가 그들에게 등을 보이고 얼굴을 보이지 아니하리라',19402),
('jer-18-18','jer','예레미야',18,18,'그들이 말하기를 오라 우리가 꾀를 내어 예레미야를 치자 제사장에게서 율법이, 지혜로운 자에게서 책략이, 선지자에게서 말씀이 끊어지지 아니할 것이니 오라 우리가 혀로 그를 치고 그의 어떤 말에도 주의하지 말자 하나이다',19403),
('jer-18-19','jer','예레미야',18,19,'여호와여 나를 돌아보사 나와 더불어 다투는 그들의 목소리를 들어 보옵소서',19404),
('jer-18-20','jer','예레미야',18,20,'어찌 악으로 선을 갚으리이까마는 그들이 나의 생명을 해하려고 구덩이를 팠나이다 내가 주의 분노를 그들에게서 돌이키려 하고 주의 앞에 서서 그들을 위하여 유익한 말을 한 것을 기억하옵소서',19405),
('jer-18-21','jer','예레미야',18,21,'그러하온즉 그들의 자녀를 기근에 내어 주시며 그들을 칼의 세력에 넘기시며 그들의 아내들은 자녀를 잃고 과부가 되며 그 장정은 죽음을 당하며 그 청년은 전장에서 칼을 맞게 하시며',19406),
('jer-18-22','jer','예레미야',18,22,'주께서 군대로 갑자기 그들에게 이르게 하사 그들의 집에서 부르짖음이 들리게 하옵소서 이는 그들이 나를 잡으려고 구덩이를 팠고 내 발을 빠뜨리려고 올무를 놓았음이니이다',19407),
('jer-18-23','jer','예레미야',18,23,'여호와여 그들이 나를 죽이려 하는 계략을 주께서 다 아시오니 그 악을 사하지 마옵시며 그들의 죄를 주의 목전에서 지우지 마시고 그들을 주 앞에 넘어지게 하시되 주께서 노하시는 때에 이같이 그들에게 행하옵소서 하니라',19408),
('jer-19-1','jer','예레미야',19,1,'여호와께서 이와 같이 말씀하시되 가서 토기장이의 옹기를 사고 백성의 어른들과 제사장의 어른 몇 사람과',19409),
('jer-19-2','jer','예레미야',19,2,'하시드 문 어귀 곁에 있는 힌놈의 아들의 골짜기로 가서 거기에서 내가 네게 이른 말을 선포하여',19410),
('jer-19-3','jer','예레미야',19,3,'말하기를 너희 유다 왕들과 예루살렘 주민아 여호와의 말씀을 들으라 만군의 여호와 이스라엘의 하나님이 이같이 말씀하시되 보라 내가 이 곳에 재앙을 내릴 것이라 그것을 듣는 모든 자의 귀가 떨리니',19411),
('jer-19-4','jer','예레미야',19,4,'이는 그들이 나를 버리고 이 곳을 불결하게 하며 이 곳에서 자기와 자기 조상들과 유다 왕들이 알지 못하던 다른 신들에게 분향하며 무죄한 자의 피로 이 곳에 채웠음이며',19412),
('jer-19-5','jer','예레미야',19,5,'또 그들이 바알을 위하여 산당을 건축하고 자기 아들들을 바알에게 번제로 불살라 드렸나니 이는 내가 명령하거나 말하거나 뜻한 바가 아니니라',19413),
('jer-19-6','jer','예레미야',19,6,'그러므로 보라 다시는 이 곳을 도벳이나 힌놈의 아들의 골짜기라 부르지 아니하고 오직 죽임의 골짜기라 부르는 날이 이를 것이라 여호와의 말이니라',19414),
('jer-19-7','jer','예레미야',19,7,'내가 이 곳에서 유다와 예루살렘의 계획을 무너뜨려 그들로 그 대적 앞과 생명을 찾는 자의 손의 칼에 엎드러지게 하고 그 시체를 공중의 새와 땅의 짐승의 밥이 되게 하며',19415),
('jer-19-8','jer','예레미야',19,8,'이 성읍으로 놀람과 조롱 거리가 되게 하리니 그 모든 재앙으로 말미암아 지나는 자마다 놀라며 조롱할 것이며',19416),
('jer-19-9','jer','예레미야',19,9,'그들이 그들의 원수와 그들의 생명을 찾는 자에게 둘러싸여 곤경에 빠질 때에 내가 그들이 그들의 아들의 살, 딸의 살을 먹게 하고 또 각기 친구의 살을 먹게 하리라 하셨다 하고',19417),
('jer-19-10','jer','예레미야',19,10,'너는 함께 가는 자의 목전에서 그 옹기를 깨뜨리고',19418),
('jer-19-11','jer','예레미야',19,11,'그들에게 이르기를 만군의 여호와께서 이와 같이 말씀하시되 사람이 토기장이의 그릇을 한 번 깨뜨리면 다시 완전하게 할 수 없나니 이와 같이 내가 이 백성과 이 성읍을 무너뜨리리니 도벳에 매장할 자리가 없을 만큼 매장하리라',19419),
('jer-19-12','jer','예레미야',19,12,'여호와의 말씀이니라 내가 이 곳과 그 가운데 주민에게 이같이 행하여 이 성읍으로 도벳 같게 할 것이라',19420),
('jer-19-13','jer','예레미야',19,13,'예루살렘 집들과 유다 왕들의 집들이 그 집 위에서 하늘의 만상에 분향하고 다른 신들에게 전제를 부음으로 더러워졌은즉 도벳 땅처럼 되리라 하셨다 하라 하시니',19421),
('jer-19-14','jer','예레미야',19,14,'예레미야가 여호와께서 자기를 보내사 예언하게 하신 도벳에서 돌아와 여호와의 집 뜰에 서서 모든 백성에게 말하되',19422),
('jer-19-15','jer','예레미야',19,15,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 보라 내가 이 성읍에 대하여 선언한 모든 재앙을 이 성읍과 그 모든 촌락에 내리리니 이는 그들의 목을 곧게 하여 내 말을 듣지 아니함이라 하시니라',19423),
('jer-20-1','jer','예레미야',20,1,'임멜의 아들 제사장 바스훌은 여호와의 성전의 총감독이라 그가 예레미야의 이 일 예언함을 들은지라',19424),
('jer-20-2','jer','예레미야',20,2,'이에 바스훌이 선지자 예레미야를 때리고 여호와의 성전에 있는 베냐민 문 위층에 목에 씌우는 나무 고랑으로 채워 두었더니',19425),
('jer-20-3','jer','예레미야',20,3,'다음날 바스훌이 예레미야를 목에 씌우는 나무 고랑에서 풀어 주매 예레미야가 그에게 이르되 여호와께서 네 이름을 바스훌이라 아니하시고 마골밋사빕이라 하시느니라',19426),
('jer-20-4','jer','예레미야',20,4,'여호와께서 이와 같이 말씀하시되 보라 내가 너로 너와 네 모든 친구에게 두려움이 되게 하리니 그들이 그들의 원수들의 칼에 엎드러질 것이요 네 눈은 그것을 볼 것이며 내가 온 유다를 바벨론 왕의 손에 넘기리니 그가 그들을 사로잡아 바벨론으로 옮겨 칼로 죽이리라',19427),
('jer-20-5','jer','예레미야',20,5,'내가 또 이 성읍의 모든 부와 그 모든 소득과 그 모든 귀중품과 유다 왕들의 모든 보물을 그 원수의 손에 넘기리니 그들이 그것을 탈취하여 바벨론으로 가져가리라',19428),
('jer-20-6','jer','예레미야',20,6,'바스훌아 너와 네 집에 사는 모든 사람이 포로 되어 옮겨지리니 네가 바벨론에 이르러 거기서 죽어 거기 묻힐 것이라 너와 너의 거짓 예언을 들은 네 모든 친구도 그와 같으리라 하셨느니라',19429),
('jer-20-7','jer','예레미야',20,7,'여호와여 주께서 나를 권유하시므로 내가 그 권유를 받았사오며 주께서 나보다 강하사 이기셨으므로 내가 조롱 거리가 되니 사람마다 종일토록 나를 조롱하나이다',19430),
('jer-20-8','jer','예레미야',20,8,'내가 말할 때마다 외치며 파멸과 멸망을 선포하므로 여호와의 말씀으로 말미암아 내가 종일토록 치욕과 모욕 거리가 됨이니이다',19431),
('jer-20-9','jer','예레미야',20,9,'내가 다시는 여호와를 선포하지 아니하며 그의 이름으로 말하지 아니하리라 하면 나의 마음이 불붙는 것 같아서 골수에 사무치니 답답하여 견딜 수 없나이다',19432),
('jer-20-10','jer','예레미야',20,10,'나는 무리의 비방과 사방이 두려워함을 들었나이다 그들이 이르기를 고소하라 우리도 고소하리라 하오며 내 친한 벗도 다 내가 실족하기를 기다리며 그가 혹시 유혹을 받게 되면 우리가 그를 이기어 우리 원수를 갚자 하나이다',19433),
('jer-20-11','jer','예레미야',20,11,'그러하오나 여호와는 두려운 용사 같으시며 나와 함께 하시므로 나를 박해하는 자들이 넘어지고 이기지 못할 것이오며 그들은 지혜롭게 행하지 못하므로 큰 치욕을 당하오리니 그 치욕은 길이 잊지 못할 것이니이다',19434),
('jer-20-12','jer','예레미야',20,12,'의인을 시험하사 그 폐부와 심장을 보시는 만군의 여호와여 나의 사정을 주께 아뢰었사온즉 주께서 그들에게 보복하심을 나에게 보게 하옵소서',19435),
('jer-20-13','jer','예레미야',20,13,'여호와께 노래하라 너희는 여호와를 찬양하라 가난한 자의 생명을 행악자의 손에서 구원하셨음이니라',19436),
('jer-20-14','jer','예레미야',20,14,'내 생일이 저주를 받았더면, 나의 어머니가 나를 낳던 날이 복이 없었더면,',19437),
('jer-20-15','jer','예레미야',20,15,'나의 아버지에게 소식을 전하여 이르기를 당신이 득남하였다 하여 아버지를 즐겁게 하던 자가 저주를 받았더면,',19438),
('jer-20-16','jer','예레미야',20,16,'그 사람은 여호와께서 무너뜨리시고 후회하지 아니하신 성읍 같이 되었더면, 그가 아침에는 부르짖는 소리, 낮에는 떠드는 소리를 듣게 하였더면, 좋을 뻔하였나니',19439),
('jer-20-17','jer','예레미야',20,17,'이는 그가 나를 태에서 죽이지 아니하셨으며 나의 어머니를 내 무덤이 되지 않게 하셨으며 그의 배가 부른 채로 항상 있지 않게 하신 까닭이로다',19440),
('jer-20-18','jer','예레미야',20,18,'어찌하여 내가 태에서 나와서 고생과 슬픔을 보며 나의 날을 부끄러움으로 보내는고 하니라',19441),
('jer-21-1','jer','예레미야',21,1,'여호와께로부터 예레미야에게 말씀이 임하니라 시드기야 왕이 말기야의 아들 바스훌과 제사장 마아세야의 아들 스바냐를 예레미야에게 보내니라',19442),
('jer-21-2','jer','예레미야',21,2,'바벨론의 느부갓네살 왕이 우리를 치니 청컨대 너는 우리를 위하여 여호와께 간구하라 여호와께서 혹시 그의 모든 기적으로 우리를 도와 행하시면 그가 우리를 떠나리라 하니',19443),
('jer-21-3','jer','예레미야',21,3,'예레미야가 그들에게 대답하되 너희는 시드기야에게 이같이 말하라',19444),
('jer-21-4','jer','예레미야',21,4,'이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 보라 너희가 성 밖에서 바벨론의 왕과 또 너희를 에워싼 갈대아인과 싸우는 데 쓰는 너희 손의 무기를 내가 뒤로 돌릴 것이요 그것들을 이 성 가운데 모아들이리라',19445),
('jer-21-5','jer','예레미야',21,5,'내가 든 손과 강한 팔 곧 진노와 분노와 대노로 친히 너희를 칠 것이며',19446),
('jer-21-6','jer','예레미야',21,6,'내가 또 사람이나 짐승이나 이 성에 있는 것을 다 치리니 그들이 큰 전염병에 죽으리라 하셨다 하라',19447),
('jer-21-7','jer','예레미야',21,7,'여호와의 말씀이니라 그 후에 내가 유다의 왕 시드기야와 그의 신하들과 백성과 및 이 성읍에서 전염병과 칼과 기근에서 남은 자를 바벨론의 느부갓네살 왕의 손과 그들의 원수의 손과 그들의 생명을 찾는 자들의 손에 넘기리니 그가 칼날로 그들을 치되 측은히 여기지 아니하며 긍휼히 여기지 아니하며 불쌍히 여기지 아니하리라 하셨느니라',19448),
('jer-21-8','jer','예레미야',21,8,'여호와께서 말씀하시기를 보라 내가 너희 앞에 생명의 길과 사망의 길을 두었노라 너는 이 백성에게 전하라 하셨느니라',19449),
('jer-21-9','jer','예레미야',21,9,'이 성읍에 사는 자는 칼과 기근과 전염병에 죽으려니와 너희를 에워싼 갈대아인에게 나가서 항복하는 자는 살 것이나 그의 목숨은 전리품 같이 되리라',19450),
('jer-21-10','jer','예레미야',21,10,'여호와의 말씀이니라 내가 나의 얼굴을 이 성읍으로 향함은 복을 내리기 위함이 아니요 화를 내리기 위함이라 이 성읍이 바벨론 왕의 손에 넘김이 될 것이요 그는 그것을 불사르리라',19451),
('jer-21-11','jer','예레미야',21,11,'유다 왕의 집에 대한 여호와의 말을 들으라',19452),
('jer-21-12','jer','예레미야',21,12,'여호와께서 이와 같이 말씀하시니라 다윗의 집이여 너는 아침마다 정의롭게 판결하여 탈취 당한 자를 압박자의 손에서 건지라 그리하지 아니하면 너희의 악행 때문에 내 분노가 불 같이 일어나서 사르리니 능히 끌 자가 없으리라',19453),
('jer-21-13','jer','예레미야',21,13,'여호와의 말씀이니라 골짜기와 평원 바위의 주민아 보라 너희가 말하기를 누가 내려와서 우리를 치리요 누가 우리의 거처에 들어오리요 하거니와 나는 네 대적이라',19454),
('jer-21-14','jer','예레미야',21,14,'내가 너희 행위대로 너희를 벌할 것이요 내가 또 수풀에 불을 놓아 그 모든 주위를 사르리라 여호와의 말씀이니라',19455),
('jer-22-1','jer','예레미야',22,1,'여호와께서 이와 같이 말씀하시되 너는 유다 왕의 집에 내려가서 거기에서 이 말을 선언하여',19456),
('jer-22-2','jer','예레미야',22,2,'이르기를 다윗의 왕위에 앉은 유다 왕이여 너와 네 신하와 이 문들로 들어오는 네 백성은 여호와의 말씀을 들을지니라',19457),
('jer-22-3','jer','예레미야',22,3,'여호와께서 이와 같이 말씀하시되 너희가 정의와 공의를 행하여 탈취 당한 자를 압박하는 자의 손에서 건지고 이방인과 고아와 과부를 압제하거나 학대하지 말며 이 곳에서 무죄한 피를 흘리지 말라',19458),
('jer-22-4','jer','예레미야',22,4,'너희가 참으로 이 말을 준행하면 다윗의 왕위에 앉을 왕들과 신하들과 백성이 병거와 말을 타고 이 집 문으로 들어오게 되리라',19459),
('jer-22-5','jer','예레미야',22,5,'그러나 너희가 이 말을 듣지 아니하면 내가 나를 두고 맹세하노니 이 집이 황폐하리라 여호와의 말씀이니라',19460),
('jer-22-6','jer','예레미야',22,6,'여호와께서 유다 왕의 집에 대하여 이와 같이 말씀하시니라 네가 내게 길르앗 같고 레바논의 머리이나 내가 반드시 너로 광야와 주민이 없는 성읍을 만들 것이라',19461),
('jer-22-7','jer','예레미야',22,7,'내가 너를 파멸할 자를 준비하리니 그들이 각기 손에 무기를 가지고 네 아름다운 백향목을 찍어 불에 던지리라',19462),
('jer-22-8','jer','예레미야',22,8,'여러 민족들이 이 성읍으로 지나가며 서로 말하기를 여호와가 이 큰 성읍에 이같이 행함은 어찌 됨인고 하겠고',19463),
('jer-22-9','jer','예레미야',22,9,'그들이 대답하기는 이는 그들이 자기 하나님 여호와의 언약을 버리고 다른 신들에게 절하고 그를 섬긴 까닭이라 하셨다 할지니라',19464),
('jer-22-10','jer','예레미야',22,10,'너희는 죽은 자를 위하여 울지 말며 그를 위하여 애통하지 말고 잡혀 간 자를 위하여 슬피 울라 그는 다시 돌아와 그 고국을 보지 못할 것임이라',19465),
('jer-22-11','jer','예레미야',22,11,'여호와께서 유다 왕 요시야의 아들 곧 그의 아버지 요시야를 이어 왕이 되었다가 이 곳에서 나간 살룸에 대하여 이와 같이 말씀하시니라 그가 이 곳으로 다시 돌아오지 못하고',19466),
('jer-22-12','jer','예레미야',22,12,'잡혀 간 곳에서 그가 거기서 죽으리니 이 땅을 다시 보지 못하리라',19467),
('jer-22-13','jer','예레미야',22,13,'불의로 그 집을 세우며 부정하게 그 다락방을 지으며 자기의 이웃을 고용하고 그의 품삯을 주지 아니하는 자에게 화 있을진저',19468),
('jer-22-14','jer','예레미야',22,14,'그가 이르기를 내가 나를 위하여 큰 집과 넓은 다락방을 지으리라 하고 자기를 위하여 창문을 만들고 그것에 백향목으로 입히고 붉은 빛으로 칠하도다',19469),
('jer-22-15','jer','예레미야',22,15,'네가 백향목을 많이 사용하여 왕이 될 수 있겠느냐 네 아버지가 먹거나 마시지 아니하였으며 정의와 공의를 행하지 아니하였느냐 그 때에 그가 형통하였었느니라',19470),
('jer-22-16','jer','예레미야',22,16,'그는 가난한 자와 궁핍한 자를 변호하고 형통하였나니 이것이 나를 앎이 아니냐 여호와의 말씀이니라',19471),
('jer-22-17','jer','예레미야',22,17,'그러나 네 두 눈과 마음은 탐욕과 무죄한 피를 흘림과 압박과 포악을 행하려 할 뿐이니라',19472),
('jer-22-18','jer','예레미야',22,18,'그러므로 여호와께서 유다의 왕 요시야의 아들 여호야김에게 대하여 이와 같이 말씀하시니라 무리가 그를 위하여 슬프다 내 형제여, 슬프다 내 자매여 하며 통곡하지 아니할 것이며 그를 위하여 슬프다 주여 슬프다 그 영광이여 하며 통곡하지도 아니할 것이라',19473),
('jer-22-19','jer','예레미야',22,19,'그가 끌려 예루살렘 문 밖에 던져지고 나귀 같이 매장함을 당하리라',19474),
('jer-22-20','jer','예레미야',22,20,'너는 레바논에 올라 외치며 바산에서 네 소리를 높이며 아바림에서 외치라 이는 너를 사랑하는 자가 다 멸망하였음이라',19475),
('jer-22-21','jer','예레미야',22,21,'네가 평안할 때에 내가 네게 말하였으나 네 말이 나는 듣지 아니하리라 하였나니 네가 어려서부터 내 목소리를 청종하지 아니함이 네 습관이라',19476),
('jer-22-22','jer','예레미야',22,22,'네 목자들은 다 바람에 삼켜질 것이요 너를 사랑하는 자들은 사로잡혀 가리니 그 때에 네가 반드시 네 모든 악 때문에 수치와 욕을 당하리라',19477),
('jer-22-23','jer','예레미야',22,23,'레바논에 살면서 백향목에 깃들이는 자여 여인이 해산하는 고통 같은 고통이 네게 임할 때에 너의 가련함이 얼마나 심하랴',19478),
('jer-22-24','jer','예레미야',22,24,'여호와의 말씀이니라 나의 삶으로 맹세하노니 유다 왕 여호야김의 아들 고니야가 나의 오른손의 인장반지라 할지라도 내가 빼어',19479),
('jer-22-25','jer','예레미야',22,25,'네 생명을 찾는 자의 손과 네가 두려워하는 자의 손 곧 바벨론의 왕 느부갓네살의 손과 갈대아인의 손에 줄 것이라',19480),
('jer-22-26','jer','예레미야',22,26,'내가 너와 너를 낳은 어머니를 너희가 나지 아니한 다른 지방으로 쫓아내리니 너희가 거기에서 죽으리라',19481),
('jer-22-27','jer','예레미야',22,27,'그들이 그들의 마음에 돌아오기를 사모하는 땅에 돌아오지 못하리라',19482),
('jer-22-28','jer','예레미야',22,28,'이 사람 고니야는 천하고 깨진 그릇이냐 좋아하지 아니하는 그릇이냐 어찌하여 그와 그의 자손이 쫓겨나서 알지 못하는 땅에 들어갔는고',19483),
('jer-22-29','jer','예레미야',22,29,'땅이여, 땅이여, 땅이여, 여호와의 말을 들을지니라',19484),
('jer-22-30','jer','예레미야',22,30,'여호와께서 이와 같이 말씀하시니라 너희는 이 사람이 자식이 없겠고 그의 평생 동안 형통하지 못할 자라 기록하라 이는 그의 자손 중 형통하여 다윗의 왕위에 앉아 유다를 다스릴 사람이 다시는 없을 것임이라 하시니라',19485),
('jer-23-1','jer','예레미야',23,1,'여호와의 말씀이니라 내 목장의 양 떼를 멸하며 흩어지게 하는 목자에게 화 있으리라',19486),
('jer-23-2','jer','예레미야',23,2,'그러므로 이스라엘의 하나님 여호와께서 내 백성을 기르는 목자에게 이와 같이 말씀하시니라 너희가 내 양 떼를 흩으며 그것을 몰아내고 돌보지 아니하였도다 보라 내가 너희의 악행 때문에 너희에게 보응하리라 여호와의 말씀이니라',19487),
('jer-23-3','jer','예레미야',23,3,'내가 내 양 떼의 남은 것을 그 몰려 갔던 모든 지방에서 모아 다시 그 우리로 돌아오게 하리니 그들의 생육이 번성할 것이며',19488),
('jer-23-4','jer','예레미야',23,4,'내가 그들을 기르는 목자들을 그들 위에 세우리니 그들이 다시는 두려워하거나 놀라거나 잃어 버리지 아니하리라 여호와의 말씀이니라',19489),
('jer-23-5','jer','예레미야',23,5,'여호와의 말씀이니라 보라 때가 이르리니 내가 다윗에게 한 의로운 가지를 일으킬 것이라 그가 왕이 되어 지혜롭게 다스리며 세상에서 정의와 공의를 행할 것이며',19490),
('jer-23-6','jer','예레미야',23,6,'그의 날에 유다는 구원을 받겠고 이스라엘은 평안히 살 것이며 그의 이름은 여호와 우리의 공의라 일컬음을 받으리라',19491),
('jer-23-7','jer','예레미야',23,7,'그러므로 여호와의 말씀이니라 보라 날이 이르리니 그들이 다시는 이스라엘 자손을 애굽 땅에서 인도하여 내신 여호와의 사심으로 맹세하지 아니하고',19492),
('jer-23-8','jer','예레미야',23,8,'이스라엘 집 자손을 북쪽 땅, 그 모든 쫓겨났던 나라에서 인도하여 내신 여호와의 사심으로 맹세할 것이며 그들이 자기 땅에 살리라 하시니라',19493),
('jer-23-9','jer','예레미야',23,9,'선지자들에 대한 말씀이라. 내 마음이 상하며 내 모든 뼈가 떨리며 내가 취한 사람 같으며 포도주에 잡힌 사람 같으니 이는 여호와와 그 거룩한 말씀 때문이라',19494),
('jer-23-10','jer','예레미야',23,10,'이 땅에 간음하는 자가 가득하도다 저주로 말미암아 땅이 슬퍼하며 광야의 초장들이 마르나니 그들의 행위가 악하고 힘쓰는 것이 정직하지 못함이로다',19495),
('jer-23-11','jer','예레미야',23,11,'여호와의 말씀이니라 선지자와 제사장이 다 사악한지라 내가 내 집에서도 그들의 악을 발견하였노라',19496),
('jer-23-12','jer','예레미야',23,12,'그러므로 그들의 길이 그들에게 어두운 가운데 미끄러운 곳과 같이 되고 그들이 밀어냄을 당하여 그 길에 엎드러질 것이라 그들을 벌하는 해에 내가 그들에게 재앙을 내리리라 여호와의 말씀이니라',19497),
('jer-23-13','jer','예레미야',23,13,'내가 사마리아 선지자들 가운데 우매함을 보았나니 그들은 바알을 의지하고 예언하여 내 백성 이스라엘을 그릇되게 하였고',19498),
('jer-23-14','jer','예레미야',23,14,'내가 예루살렘 선지자들 가운데도 가증한 일을 보았나니 그들은 간음을 행하며 거짓을 말하며 악을 행하는 자의 손을 강하게 하여 사람으로 그 악에서 돌이킴이 없게 하였은즉 그들은 다 내 앞에서 소돔과 다름이 없고 그 주민은 고모라와 다름이 없느니라',19499),
('jer-23-15','jer','예레미야',23,15,'그러므로 만군의 여호와께서 선지자에 대하여 이와 같이 말씀하시니라 보라 내가 그들에게 쑥을 먹이며 독한 물을 마시게 하리니 이는 사악이 예루살렘 선지자들로부터 나와서 온 땅에 퍼짐이라 하시니라',19500),
('jer-23-16','jer','예레미야',23,16,'만군의 여호와께서 이와 같이 말씀하시되 너희에게 예언하는 선지자들의 말을 듣지 말라 그들은 너희에게 헛된 것을 가르치나니 그들이 말한 묵시는 자기 마음으로 말미암은 것이요 여호와의 입에서 나온 것이 아니니라',19501),
('jer-23-17','jer','예레미야',23,17,'항상 그들이 나를 멸시하는 자에게 이르기를 너희가 평안하리라 여호와의 말씀이니라 하며 또 자기 마음이 완악한 대로 행하는 모든 사람에게 이르기를 재앙이 너희에게 임하지 아니하리라 하였느니라',19502),
('jer-23-18','jer','예레미야',23,18,'누가 여호와의 회의에 참여하여 그 말을 알아들었으며 누가 귀를 기울여 그 말을 들었느냐',19503),
('jer-23-19','jer','예레미야',23,19,'보라 여호와의 노여움이 일어나 폭풍과 회오리바람처럼 악인의 머리를 칠 것이라',19504),
('jer-23-20','jer','예레미야',23,20,'여호와의 진노가 내 마음의 뜻하는 바를 행하여 이루기까지는 그치지 아니하나니 너희가 끝날에 그것을 완전히 깨달으리라',19505),
('jer-23-21','jer','예레미야',23,21,'이 선지자들은 내가 보내지 아니하였어도 달음질하며 내가 그들에게 이르지 아니하였어도 예언하였은즉',19506),
('jer-23-22','jer','예레미야',23,22,'그들이 만일 나의 회의에 참여하였더라면 내 백성에게 내 말을 들려서 그들을 악한 길과 악한 행위에서 돌이키게 하였으리라',19507),
('jer-23-23','jer','예레미야',23,23,'여호와의 말씀이니라 나는 가까운 데에 있는 하나님이요 먼 데에 있는 하나님은 아니냐',19508),
('jer-23-24','jer','예레미야',23,24,'여호와의 말씀이니라 사람이 내게 보이지 아니하려고 누가 자신을 은밀한 곳에 숨길 수 있겠느냐 여호와가 말하노라 나는 천지에 충만하지 아니하냐',19509),
('jer-23-25','jer','예레미야',23,25,'내 이름으로 거짓을 예언하는 선지자들의 말에 내가 꿈을 꾸었다 꿈을 꾸었다고 말하는 것을 내가 들었노라',19510),
('jer-23-26','jer','예레미야',23,26,'거짓을 예언하는 선지자들이 언제까지 이 마음을 품겠느냐 그들은 그 마음의 간교한 것을 예언하느니라',19511),
('jer-23-27','jer','예레미야',23,27,'그들이 서로 꿈 꾼 것을 말하니 그 생각인즉 그들의 조상들이 바알로 말미암아 내 이름을 잊어버린 것 같이 내 백성으로 내 이름을 잊게 하려 함이로다',19512),
('jer-23-28','jer','예레미야',23,28,'여호와의 말씀이니라 꿈을 꾼 선지자는 꿈을 말할 것이요 내 말을 받은 자는 성실함으로 내 말을 말할 것이라 겨가 어찌 알곡과 같겠느냐',19513),
('jer-23-29','jer','예레미야',23,29,'여호와의 말씀이니라 내 말이 불 같지 아니하냐 바위를 쳐서 부스러뜨리는 방망이 같지 아니하냐',19514),
('jer-23-30','jer','예레미야',23,30,'여호와의 말씀이라 그러므로 보라 서로 내 말을 도둑질하는 선지자들을 내가 치리라',19515),
('jer-23-31','jer','예레미야',23,31,'여호와의 말씀이니라 보라 그들이 혀를 놀려 여호와가 말씀하셨다 하는 선지자들을 내가 치리라',19516),
('jer-23-32','jer','예레미야',23,32,'여호와의 말씀이니라 보라 거짓 꿈을 예언하여 이르며 거짓과 헛된 자만으로 내 백성을 미혹하게 하는 자를 내가 치리라 내가 그들을 보내지 아니하였으며 명령하지 아니하였나니 그들은 이 백성에게 아무 유익이 없느니라 여호와의 말씀이니라',19517),
('jer-23-33','jer','예레미야',23,33,'이 백성이나 선지자나 제사장이 네게 물어 이르기를 여호와의 엄중한 말씀이 무엇인가 묻거든 너는 그들에게 대답하기를 엄중한 말씀이 무엇이냐 묻느냐 여호와의 말씀에 내가 너희를 버리리라 하셨고',19518),
('jer-23-34','jer','예레미야',23,34,'또 여호와의 엄중한 말씀이라 하는 선지자에게나 제사장에게나 백성에게는 내가 그 사람과 그 집안을 벌하리라 하셨다 하고',19519),
('jer-23-35','jer','예레미야',23,35,'너희는 서로 이웃과 형제에게 묻기를 여호와께서 무엇이라 응답하셨으며 여호와께서 무엇이라 말씀하셨느냐 하고',19520),
('jer-23-36','jer','예레미야',23,36,'다시는 여호와의 엄중한 말씀이라 말하지 말라 각 사람의 말이 자기에게 중벌이 되리니 이는 너희가 살아 계신 하나님, 만군의 여호와 우리 하나님의 말씀을 망령되이 사용함이니라 하고',19521),
('jer-23-37','jer','예레미야',23,37,'너는 또 선지자에게 말하기를 여호와께서 네게 무엇이라 대답하셨으며 여호와께서 무엇이라 말씀하셨느냐',19522),
('jer-23-38','jer','예레미야',23,38,'너희는 여호와의 엄중한 말씀이라 말하도다 그러므로 여호와께서 이와 같이 말씀하시되 내가 너희에게 사람을 보내어 이 말씀은 여호와의 엄중한 말씀이니 너희는 말하지 말라 하였으나 너희가 여호와의 엄중한 말씀이라 하였은즉',19523),
('jer-23-39','jer','예레미야',23,39,'내가 너희를 온전히 잊어버리며 내가 너희와 너희 조상들에게 준 이 성읍을 내 앞에서 내버려',19524),
('jer-23-40','jer','예레미야',23,40,'너희는 영원한 치욕과 잊지 못할 영구한 수치를 당하게 하리라 하셨느니라',19525),
('jer-24-1','jer','예레미야',24,1,'바벨론의 느부갓네살 왕이 유다 왕 여호야김의 아들 여고냐와 유다 고관들과 목공들과 철공들을 예루살렘에서 바벨론으로 옮긴 후에 여호와께서 여호와의 성전 앞에 놓인 무화과 두 광주리를 내게 보이셨는데',19526),
('jer-24-2','jer','예레미야',24,2,'한 광주리에는 처음 익은 듯한 극히 좋은 무화과가 있고 한 광주리에는 나빠서 먹을 수 없는 극히 나쁜 무화과가 있더라',19527),
('jer-24-3','jer','예레미야',24,3,'여호와께서 내게 이르시되 예레미야야 네가 무엇을 보느냐 하시매 내가 대답하되 무화과이온데 그 좋은 무화과는 극히 좋고 그 나쁜 것은 아주 나빠서 먹을 수 없게 나쁘니이다 하니',19528),
('jer-24-4','jer','예레미야',24,4,'여호와의 말씀이 또 내게 임하니라 이르시되',19529),
('jer-24-5','jer','예레미야',24,5,'이스라엘의 하나님 여호와께서 이와 같이 말씀하시니라 내가 이 곳에서 옮겨 갈대아인의 땅에 이르게 한 유다 포로를 이 좋은 무화과 같이 잘 돌볼 것이라',19530),
('jer-24-6','jer','예레미야',24,6,'내가 그들을 돌아보아 좋게 하여 다시 이 땅으로 인도하여 세우고 헐지 아니하며 심고 뽑지 아니하겠고',19531),
('jer-24-7','jer','예레미야',24,7,'내가 여호와인 줄 아는 마음을 그들에게 주어서 그들이 전심으로 내게 돌아오게 하리니 그들은 내 백성이 되겠고 나는 그들의 하나님이 되리라',19532),
('jer-24-8','jer','예레미야',24,8,'여호와께서 이와 같이 말씀하시니라 내가 유다의 왕 시드기야와 그 고관들과 예루살렘의 남은 자로서 이 땅에 남아 있는 자와 애굽 땅에 사는 자들을 나빠서 먹을 수 없는 이 나쁜 무화과 같이 버리되',19533),
('jer-24-9','jer','예레미야',24,9,'세상 모든 나라 가운데 흩어서 그들에게 환난을 당하게 할 것이며 또 그들에게 내가 쫓아 보낼 모든 곳에서 부끄러움을 당하게 하며 말 거리가 되게 하며 조롱과 저주를 받게 할 것이며',19534),
('jer-24-10','jer','예레미야',24,10,'내가 칼과 기근과 전염병을 그들 가운데 보내 그들이 내가 그들과 그들의 조상들에게 준 땅에서 멸절하기까지 이르게 하리라 하시니라',19535),
('jer-25-1','jer','예레미야',25,1,'유다의 왕 요시야의 아들 여호야김 넷째 해 곧 바벨론의 왕 느부갓네살 원년에 유다의 모든 백성에 관한 말씀이 예레미야에게 임하니라',19536),
('jer-25-2','jer','예레미야',25,2,'선지자 예레미야가 유다의 모든 백성과 예루살렘의 모든 주민에게 말하여 이르되',19537),
('jer-25-3','jer','예레미야',25,3,'유다의 왕 아몬의 아들 요시야 왕 열셋째 해부터 오늘까지 이십삼 년 동안 여호와의 말씀이 내게 임하기로 내가 너희에게 꾸준히 일렀으나 너희가 순종하지 아니하였느니라',19538),
('jer-25-4','jer','예레미야',25,4,'그러므로 여호와께서 그의 모든 종 선지자를 너희에게 끊임없이 보내셨으나 너희가 순종하지 아니하였으며 귀를 기울여 듣지도 아니하였도다',19539),
('jer-25-5','jer','예레미야',25,5,'그가 이르시기를 너희는 각자의 악한 길과 악행을 버리고 돌아오라 그리하면 나 여호와가 너희와 너희 조상들에게 영원부터 영원까지 준 그 땅에 살리라',19540),
('jer-25-6','jer','예레미야',25,6,'너희는 다른 신을 따라다니며 섬기거나 경배하지 말며 너희 손으로 만든 것으로써 나의 노여움을 일으키지 말라 그리하면 내가 너희를 해하지 아니하리라 하였으나',19541),
('jer-25-7','jer','예레미야',25,7,'너희가 내 말을 순종하지 아니하고 너희 손으로 만든 것으로써 나의 노여움을 일으켜 스스로 해하였느니라 여호와의 말씀이니라',19542),
