('jer-25-25','jer','예레미야',25,25,'시므리의 모든 왕과 엘람의 모든 왕과 메대의 모든 왕과',19560),
('jer-25-26','jer','예레미야',25,26,'북쪽 원근의 모든 왕과 지면에 있는 세상의 모든 나라로 마시게 하니라 세삭 왕은 그 후에 마시리라',19561),
('jer-25-27','jer','예레미야',25,27,'너는 그들에게 이르기를 만군의 여호와 이스라엘의 하나님의 말씀에 너희는 내가 너희 가운데 보내는 칼 앞에서 마시며 취하여 토하고 엎드러져 다시는 일어나지 말아라 하셨느니라',19562),
('jer-25-28','jer','예레미야',25,28,'그들이 만일 네 손에서 잔을 받아 마시기를 거절하거든 너는 그들에게 이르기를 만군의 여호와께서 말씀하시기를 너희가 반드시 마셔야 하리라',19563),
('jer-25-29','jer','예레미야',25,29,'보라 내가 내 이름으로 일컬음을 받는 성에서부터 재앙 내리기를 시작하였은즉 너희가 어찌 능히 형벌을 면할 수 있느냐 면하지 못하리니 이는 내가 칼을 불러 세상의 모든 주민을 칠 것임이라 하셨다 하라 만군의 여호와의 말씀이니라',19564),
('jer-25-30','jer','예레미야',25,30,'그러므로 너는 그들에게 이 모든 말로 예언하여 이르기를 여호와께서 높은 데서 포효하시고 그의 거룩한 처소에서 소리를 내시며 그의 초장을 향하여 크게 부르시고 세상 모든 주민에 대하여 포도 밟는 자 같이 흥겹게 노래하시리라',19565),
('jer-25-31','jer','예레미야',25,31,'요란한 소리가 땅 끝까지 이름은 여호와께서 뭇 민족과 다투시며 모든 육체를 심판하시며 악인을 칼에 내어 주셨음이라 여호와의 말씀이니라',19566),
('jer-25-32','jer','예레미야',25,32,'만군의 여호와께서 이와 같이 말씀하시니라 보라 재앙이 나서 나라에서 나라에 미칠 것이며 큰 바람이 땅 끝에서 일어날 것이라',19567),
('jer-25-33','jer','예레미야',25,33,'그 날에 여호와에게 죽임을 당한 자가 땅 이 끝에서 땅 저 끝에 미칠 것이나 그들을 위하여 애곡하는 자도 없고 시신을 거두어 주는 자도 없고 매장하여 주는 자도 없으리니 그들은 지면에서 분토가 되리로다',19568),
('jer-25-34','jer','예레미야',25,34,'너희 목자들아 외쳐 애곡하라 너희 양 떼의 인도자들아 잿더미에서 뒹굴라 이는 너희가 도살 당할 날과 흩음을 당할 기한이 찼음인즉 너희가 귀한 그릇이 떨어짐 같이 될 것이라',19569),
('jer-25-35','jer','예레미야',25,35,'목자들은 도망할 수 없겠고 양 떼의 인도자들은 도주할 수 없으리로다',19570),
