('jer-25-37','jer','예레미야',25,37,'평화로운 목장들이 여호와의 진노하시는 열기 앞에서 적막하게 되리라',19572),
('jer-25-38','jer','예레미야',25,38,'그가 젊은 사자 같이 그 굴에서 나오셨으니 그 호통치시는 분의 분노와 그의 극렬한 진노로 말미암아 그들의 땅이 폐허가 되리로다 하시니라',19573),
('jer-26-1','jer','예레미야',26,1,'유다의 왕 요시야의 아들 여호야김이 다스리기 시작한 때에 여호와께로부터 이 말씀이 임하여 이르시되',19574),
('jer-26-2','jer','예레미야',26,2,'여호와께서 이와 같이 말씀하시니라 너는 여호와의 성전 뜰에 서서 유다 모든 성읍에서 여호와의 성전에 와서 예배하는 자에게 내가 네게 명령하여 이르게 한 모든 말을 전하되 한 마디도 감하지 말라',19575),
('jer-26-3','jer','예레미야',26,3,'그들이 듣고 혹시 각각 그 악한 길에서 돌아오리라 그리하면 내가 그들의 악행으로 말미암아 그들에게 재앙을 내리려 하던 뜻을 돌이키리라',19576),
('jer-26-4','jer','예레미야',26,4,'너는 그들에게 이와 같이 이르라 여호와의 말씀에 너희가 나를 순종하지 아니하며 내가 너희 앞에 둔 내 율법을 행하지 아니하며',19577),
('jer-26-5','jer','예레미야',26,5,'내가 너희에게 나의 종 선지자들을 꾸준히 보내 그들의 말을 순종하라고 하였으나 너희는 순종하지 아니하였느니라',19578),
('jer-26-6','jer','예레미야',26,6,'내가 이 성전을 실로 같이 되게 하고 이 성을 세계 모든 민족의 저줏거리가 되게 하리라 하셨느니라',19579),
('jer-26-7','jer','예레미야',26,7,'예레미야가 여호와의 성전에서 이 말을 하매 제사장들과 선지자들과 모든 백성이 듣더라',19580),
('jer-26-8','jer','예레미야',26,8,'예레미야가 여호와께서 명령하신 말씀을 모든 백성에게 전하기를 마치매 제사장들과 선지자들과 모든 백성이 그를 붙잡고 이르되 네가 반드시 죽어야 하리라',19581),
('jer-26-9','jer','예레미야',26,9,'어찌하여 네가 여호와의 이름을 의지하고 예언하여 이르기를 이 성전이 실로 같이 되겠고 이 성이 황폐하여 주민이 없으리라 하느냐 하며 그 모든 백성이 여호와의 성전에서 예레미야를 향하여 모여드니라',19582),
('jer-26-10','jer','예레미야',26,10,'유다의 고관들이 이 말을 듣고 왕궁에서 여호와의 성전으로 올라가 여호와의 성전 새 대문의 입구에 앉으매',19583),
('jer-26-11','jer','예레미야',26,11,'제사장들과 선지자들이 고관들과 모든 백성에게 말하여 이르되 이 사람은 죽는 것이 합당하니 너희 귀로 들음 같이 이 성에 관하여 예언하였음이라',19584),
('jer-26-12','jer','예레미야',26,12,'예레미야가 모든 고관과 백성에게 말하여 이르되 여호와께서 나를 보내사 너희가 들은 바 모든 말로 이 성전과 이 성을 향하여 예언하게 하셨느니라',19585),
('jer-26-13','jer','예레미야',26,13,'그런즉 너희는 너희 길과 행위를 고치고 너희 하나님 여호와의 목소리를 청종하라 그리하면 여호와께서 너희에게 선언하신 재앙에 대하여 뜻을 돌이키시리라',19586),
('jer-26-14','jer','예레미야',26,14,'보라 나는 너희 손에 있으니 너희 의견에 좋은 대로, 옳은 대로 하려니와',19587),
('jer-26-15','jer','예레미야',26,15,'너희는 분명히 알아라 너희가 나를 죽이면 반드시 무죄한 피를 너희 몸과 이 성과 이 성 주민에게 돌리는 것이니라 이는 여호와께서 진실로 나를 보내사 이 모든 말을 너희 귀에 말하게 하셨음이라',19588),
('jer-26-16','jer','예레미야',26,16,'고관들과 모든 백성이 제사장들과 선지자들에게 이르되 이 사람이 우리 하나님 여호와의 이름으로 우리에게 말하였으니 죽일 만한 이유가 없느니라',19589),
('jer-26-17','jer','예레미야',26,17,'그러자 그 지방의 장로 중 몇 사람이 일어나 백성의 온 회중에게 말하여 이르기를',19590),
('jer-26-18','jer','예레미야',26,18,'유다의 왕 히스기야 시대에 모레셋 사람 미가가 유다의 모든 백성에게 예언하여 이르되 만군의 여호와께서 이와 같이 말씀하셨느니라 시온은 밭 같이 경작지가 될 것이며 예루살렘은 돌 무더기가 되며 이 성전의 산은 산당의 숲과 같이 되리라 하였으나',19591),
('jer-26-19','jer','예레미야',26,19,'유다의 왕 히스기야와 모든 유다가 그를 죽였느냐 히스기야가 여호와를 두려워하여 여호와께 간구하매 여호와께서 그들에게 선언한 재앙에 대하여 뜻을 돌이키지 아니하셨느냐 우리가 이같이 하면 우리의 생명을 스스로 심히 해롭게 하는 것이니라',19592),
('jer-26-20','jer','예레미야',26,20,'또 여호와의 이름으로 예언한 사람이 있었는데 곧 기럇여아림 스마야의 아들 우리야라 그가 예레미야의 모든 말과 같이 이 성과 이 땅에 경고하여 예언하매',19593),
('jer-26-21','jer','예레미야',26,21,'여호야김 왕과 그의 모든 용사와 모든 고관이 그의 말을 듣고서 왕이 그를 죽이려 하매 우리야가 그 말을 듣고 두려워 애굽으로 도망하여 간지라',19594),
('jer-26-22','jer','예레미야',26,22,'여호야김 왕이 사람을 애굽으로 보내되 곧 악볼의 아들 엘라단과 몇 사람을 함께 애굽으로 보냈더니',19595),
('jer-26-23','jer','예레미야',26,23,'그들이 우리야를 애굽에서 연행하여 여호야김 왕에게로 그를 데려오매 왕이 칼로 그를 죽이고 그의 시체를 평민의 묘지에 던지게 하니라',19596),
('jer-26-24','jer','예레미야',26,24,'사반의 아들 아히감의 손이 예레미야를 도와 주어 그를 백성의 손에 내어 주지 아니하여 죽이지 못하게 하니라',19597),
('jer-27-1','jer','예레미야',27,1,'유다의 왕 요시야의 아들 여호야김이 다스리기 시작할 때에 여호와께서 말씀으로 예레미야에게 임하시니라',19598),
('jer-27-2','jer','예레미야',27,2,'여호와께서 이와 같이 내게 말씀하시되 너는 줄과 멍에를 만들어 네 목에 걸고',19599),
('jer-27-3','jer','예레미야',27,3,'유다의 왕 시드기야를 보러 예루살렘에 온 사신들의 손에도 그것을 주어 에돔의 왕과 모압의 왕과 암몬 자손의 왕과 두로의 왕과 시돈의 왕에게 보내며',19600),
('jer-27-4','jer','예레미야',27,4,'그들에게 명령하여 그들의 주께 말하게 하기를 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희는 너희의 주께 이같이 전하라',19601),
('jer-27-5','jer','예레미야',27,5,'나는 내 큰 능력과 나의 쳐든 팔로 땅과 지상에 있는 사람과 짐승들을 만들고 내가 보기에 옳은 사람에게 그것을 주었노라',19602),
('jer-27-6','jer','예레미야',27,6,'이제 내가 이 모든 땅을 내 종 바벨론의 왕 느부갓네살의 손에 주고 또 들짐승들을 그에게 주어서 섬기게 하였나니',19603),
('jer-27-7','jer','예레미야',27,7,'모든 나라가 그와 그의 아들과 손자를 그 땅의 기한이 이르기까지 섬기리라 또한 많은 나라들과 큰 왕들이 그 자신을 섬기리라',19604),
('jer-27-8','jer','예레미야',27,8,'여호와의 말씀이니라 바벨론의 왕 느부갓네살을 섬기지 아니하며 그 목으로 바벨론의 왕의 멍에를 메지 아니하는 백성과 나라는 내가 그들이 멸망하기까지 칼과 기근과 전염병으로 그 민족을 벌하리라',19605),
('jer-27-9','jer','예레미야',27,9,'너희는 너희 선지자나 복술가나 꿈꾸는 자나 술사나 요술자가 이르기를 너희가 바벨론의 왕을 섬기게 되지 아니하리라 하여도 너희는 듣지 말라',19606),
('jer-27-10','jer','예레미야',27,10,'그들은 너희에게 거짓을 예언하여 너희가 너희 땅에서 멀리 떠나게 하며 또 내가 너희를 몰아내게 하며 너희를 멸망하게 하느니라',19607),
('jer-27-11','jer','예레미야',27,11,'그러나 그 목으로 바벨론의 왕의 멍에를 메고 그를 섬기는 나라는 내가 그들을 그 땅에 머물러 밭을 갈며 거기서 살게 하리라 하셨다 하라 여호와의 말씀이니라 하시니라',19608),
('jer-27-12','jer','예레미야',27,12,'내가 이 모든 말씀대로 유다의 왕 시드기야에게 전하여 이르되 왕과 백성은 바벨론 왕의 멍에를 목에 메고 그와 그의 백성을 섬기소서 그리하면 사시리라',19609),
('jer-27-13','jer','예레미야',27,13,'어찌하여 당신과 당신의 백성이 여호와께서 바벨론의 왕을 섬기지 아니하는 나라에 대하여 하신 말씀과 같이 칼과 기근과 전염병에 죽으려 하나이까',19610),
('jer-27-14','jer','예레미야',27,14,'그러므로 당신들은 바벨론의 왕을 섬기게 되지 아니하리라 하는 선지자의 말을 듣지 마소서 그들은 거짓을 예언함이니이다',19611),
('jer-27-15','jer','예레미야',27,15,'이는 여호와의 말씀이니라 내가 그들을 보내지 아니하였거늘 그들이 내 이름으로 거짓을 예언하니 내가 너희를 몰아내리니 너희와 너희에게 예언하는 선지자들이 멸망하리라',19612),
('jer-27-16','jer','예레미야',27,16,'내가 또 제사장들과 그 모든 백성에게 전하여 이르되 여호와께서 이와 같이 말씀하시기를 보라 여호와의 성전의 기구를 이제 바벨론에서 속히 돌려오리라고 너희에게 예언하는 선지자들의 말을 듣지 말라 이는 그들이 거짓을 예언함이니라 하셨나니',19613),
('jer-27-17','jer','예레미야',27,17,'너희는 그들의 말을 듣지 말고 바벨론의 왕을 섬기라 그리하면 살리라 어찌하여 이 성을 황무지가 되게 하려느냐',19614),
('jer-27-18','jer','예레미야',27,18,'만일 그들이 선지자이고 여호와의 말씀을 가지고 있다면 그들이 여호와의 성전에와 유다의 왕의 궁전에와 예루살렘에 남아 있는 기구를 바벨론으로 옮겨가지 못하도록 만군의 여호와께 구하여야 할 것이니라',19615),
('jer-27-19','jer','예레미야',27,19,'만군의 여호와께서 기둥들과 큰 대야와 받침들과 이 성에 남아 있는 기구에 대하여 이같이 말씀하시나니',19616),
('jer-27-20','jer','예레미야',27,20,'이것은 바벨론의 왕 느부갓네살이 유다의 왕 여호야김의 아들 여고니야와 유다와 예루살렘 모든 귀인을 예루살렘에서 바벨론으로 사로잡아 옮길 때에 가져가지 아니하였던 것이라',19617),
('jer-27-21','jer','예레미야',27,21,'만군의 여호와 이스라엘의 하나님께서 여호와의 성전과 유다의 왕의 궁전과 예루살렘에 남아 있는 그 기구에 대하여 이와 같이 말씀하셨느니라',19618),
('jer-27-22','jer','예레미야',27,22,'그것들이 바벨론으로 옮겨지고 내가 이것을 돌보는 날까지 거기에 있을 것이니라 그 후에 내가 그것을 올려 와 이 곳에 그것들을 되돌려 두리라 여호와의 말씀이니라',19619),
('jer-28-1','jer','예레미야',28,1,'그 해 곧 유다 왕 시드기야가 다스리기 시작한 지 사 년 다섯째 달 기브온 앗술의 아들 선지자 하나냐가 여호와의 성전에서 제사장들과 모든 백성이 보는 앞에서 내게 말하여 이르되',19620),
('jer-28-2','jer','예레미야',28,2,'만군의 여호와 이스라엘의 하나님이 이같이 일러 말씀하시기를 내가 바벨론의 왕의 멍에를 꺾었느니라',19621),
('jer-28-3','jer','예레미야',28,3,'내가 바벨론의 왕 느부갓네살이 이 곳에서 빼앗아 바벨론으로 옮겨 간 여호와의 성전 모든 기구를 이 년 안에 다시 이 곳으로 되돌려 오리라',19622),
('jer-28-4','jer','예레미야',28,4,'내가 또 유다의 왕 여호야김의 아들 여고니야와 바벨론으로 간 유다 모든 포로를 다시 이 곳으로 돌아오게 하리니 이는 내가 바벨론의 왕의 멍에를 꺾을 것임이라 여호와의 말씀이니라 하시니라',19623),
('jer-28-5','jer','예레미야',28,5,'선지자 예레미야가 여호와의 성전에 서 있는 제사장들과 모든 백성들이 보는 앞에서 선지자 하나냐에게 말하니라',19624),
('jer-28-6','jer','예레미야',28,6,'선지자 예레미야가 말하니라 아멘, 여호와는 이같이 하옵소서 여호와께서 네가 예언한 말대로 이루사 여호와의 성전 기구와 모든 포로를 바벨론에서 이 곳으로 되돌려 오시기를 원하노라',19625),
('jer-28-7','jer','예레미야',28,7,'그러나 너는 내가 네 귀와 모든 백성의 귀에 이르는 이 말을 잘 들으라',19626),
('jer-28-8','jer','예레미야',28,8,'나와 너 이전의 선지자들이 예로부터 많은 땅들과 큰 나라들에 대하여 전쟁과 재앙과 전염병을 예언하였느니라',19627),
('jer-28-9','jer','예레미야',28,9,'평화를 예언하는 선지자는 그 예언자의 말이 응한 후에야 그가 진실로 여호와께서 보내신 선지자로 인정 받게 되리라',19628),
('jer-28-10','jer','예레미야',28,10,'선지자 하나냐가 선지자 예레미야의 목에서 멍에를 빼앗아 꺾고',19629),
