('jer-28-12','jer','예레미야',28,12,'선지자 하나냐가 선지자 예레미야의 목에서 멍에를 꺾어 버린 후에 여호와의 말씀이 예레미야에게 임하니라 이르시기를',19631),
('jer-28-13','jer','예레미야',28,13,'너는 가서 하나냐에게 말하여 이르기를 여호와의 말씀에 네가 나무 멍에들을 꺾었으나 그 대신 쇠 멍에들을 만들었느니라',19632),
('jer-28-14','jer','예레미야',28,14,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 내가 쇠 멍에로 이 모든 나라의 목에 메워 바벨론의 왕 느부갓네살을 섬기게 하였으니 그들이 그를 섬기리라 내가 들짐승도 그에게 주었느니라 하라',19633),
('jer-28-15','jer','예레미야',28,15,'선지자 예레미야가 선지자 하나냐에게 이르되 하나냐여 들으라 여호와께서 너를 보내지 아니하셨거늘 네가 이 백성에게 거짓을 믿게 하는도다',19634),
('jer-28-16','jer','예레미야',28,16,'그러므로 여호와께서 이와 같이 말씀하시되 내가 너를 지면에서 제하리니 네가 여호와께 패역한 말을 하였음이라 네가 금년에 죽으리라 하였더니',19635),
('jer-28-17','jer','예레미야',28,17,'선지자 하나냐가 그 해 일곱째 달에 죽었더라',19636),
('jer-29-1','jer','예레미야',29,1,'선지자 예레미야가 예루살렘에서 이같은 편지를 느부갓네살이 예루살렘에서 바벨론으로 끌고 간 포로 중 남아 있는 장로들과 제사장들과 선지자들과 모든 백성에게 보냈는데',19637),
('jer-29-2','jer','예레미야',29,2,'그 때는 여고니야 왕과 왕후와 궁중 내시들과 유다와 예루살렘의 고관들과 기능공과 토공들이 예루살렘에서 떠난 후라',19638),
('jer-29-3','jer','예레미야',29,3,'유다의 왕 시드기야가 바벨론으로 보내어 바벨론의 왕 느부갓네살에게로 가게 한 사반의 아들 엘라사와 힐기야의 아들 그마랴 편으로 말하되',19639),
('jer-29-4','jer','예레미야',29,4,'만군의 여호와 이스라엘의 하나님께서 예루살렘에서 바벨론으로 사로잡혀 가게 한 모든 포로에게 이와 같이 말씀하시니라',19640),
