('jer-29-7','jer','예레미야',29,7,'너희는 내가 사로잡혀 가게 한 그 성읍의 평안을 구하고 그를 위하여 여호와께 기도하라 이는 그 성읍이 평안함으로 너희도 평안할 것임이라',19643),
('jer-29-8','jer','예레미야',29,8,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말하노라 너희 중에 있는 선지자들에게와 점쟁이에게 미혹되지 말며 너희가 꾼 꿈도 곧이 듣고 믿지 말라',19644),
('jer-29-9','jer','예레미야',29,9,'내가 그들을 보내지 아니하였어도 그들이 내 이름으로 거짓을 예언함이라 여호와의 말씀이니라',19645),
('jer-29-10','jer','예레미야',29,10,'여호와께서 이와 같이 말씀하시니라 바벨론에서 칠십 년이 차면 내가 너희를 돌보고 나의 선한 말을 너희에게 성취하여 너희를 이 곳으로 돌아오게 하리라',19646),
('jer-29-11','jer','예레미야',29,11,'여호와의 말씀이니라 너희를 향한 나의 생각을 내가 아나니 평안이요 재앙이 아니니라 너희에게 미래와 희망을 주는 것이니라',19647),
('jer-29-12','jer','예레미야',29,12,'너희가 내게 부르짖으며 내게 와서 기도하면 내가 너희들의 기도를 들을 것이요',19648),
('jer-29-13','jer','예레미야',29,13,'너희가 온 마음으로 나를 구하면 나를 찾을 것이요 나를 만나리라',19649),
('jer-29-14','jer','예레미야',29,14,'이것은 여호와의 말씀이니라 나는 너희들을 만날 것이며 너희를 포로된 중에서 다시 돌아오게 하되 내가 쫓아 보내었던 나라들과 모든 곳에서 모아 사로잡혀 떠났던 그 곳으로 돌아오게 하리라 이것은 여호와의 말씀이니라',19650),
('jer-29-15','jer','예레미야',29,15,'너희가 말하기를 여호와께서 우리를 위하여 바벨론에서 선지자를 일으키셨느니라',19651),
('jer-29-16','jer','예레미야',29,16,'다윗의 왕좌에 앉은 왕과 이 성에 사는 모든 백성 곧 너희와 함께 포로 되어 가지 아니한 너희 형제에게 여호와께서 이와 같이 말씀하셨느니라',19652),
('jer-29-17','jer','예레미야',29,17,'만군의 여호와께서 이와 같이 말씀하시되 보라 내가 칼과 기근과 전염병을 그들에게 보내어 그들에게 상하여 먹을 수 없는 몹쓸 무화과 같게 하겠고',19653),
('jer-29-18','jer','예레미야',29,18,'내가 칼과 기근과 전염병으로 그들을 뒤따르게 하며 그들을 세계 여러 나라 가운데에 흩어 학대를 당하게 할 것이며 내가 그들을 쫓아낸 나라들 가운데에서 저주와 경악과 조소와 수모의 대상이 되게 하리라',19654),
