('jer-29-22','jer','예레미야',29,22,'바벨론에 있는 유다의 모든 포로가 그들을 저줏거리로 삼아서 이르기를 여호와께서 너를 바벨론 왕이 불살라 죽인 시드기야와 아합 같게 하시기를 원하노라 하리니',19658),
