('jer-29-26','jer','예레미야',29,26,'여호와께서 너를 제사장 여호야다를 대신하여 제사장을 삼아 여호와의 성전 감독자로 세우심은 모든 미친 자와 선지자 노릇을 하는 자들을 목에 씌우는 나무 고랑과 목에 씌우는 쇠 고랑을 채우게 하심이어늘',19662),
('jer-29-27','jer','예레미야',29,27,'이제 네가 어찌하여 너희 중에 선지자 노릇을 하는 아나돗 사람 예레미야를 책망하지 아니하느냐',19663),
('jer-29-28','jer','예레미야',29,28,'그가 바벨론에 있는 우리에게 편지하기를 오래 지내야 하리니 너희는 집을 짓고 살며 밭을 일구고 그 열매를 먹으라 하셨다 하니라',19664),
('jer-29-29','jer','예레미야',29,29,'제사장 스바냐가 스마야의 글을 선지자 예레미야에게 읽어서 들려 줄 때에',19665),
('jer-29-30','jer','예레미야',29,30,'여호와의 말씀이 예레미야에게 임하여 이르시되',19666),
