('jer-30-6','jer','예레미야',30,6,'너희는 자식을 해산하는 남자가 있는가 물어보라 어찌하여 모든 남자가 해산하는 여자 같이 손을 자기 허리에 대고 모든 얼굴이 겁에 질려 새파래졌는가',19674),
