('jer-30-8','jer','예레미야',30,8,'만군의 여호와의 말씀이라 그 날에 내가 네 목에서 그 멍에를 꺾어 버리며 네 포박을 끊으리니 다시는 이방인을 섬기지 않으리라',19676),
('jer-30-9','jer','예레미야',30,9,'그들은 그들의 하나님 여호와를 섬기며 내가 그들을 위하여 세울 그들의 왕 다윗을 섬기리라',19677),
