('jer-30-11','jer','예레미야',30,11,'이는 여호와의 말씀이라 내가 너와 함께 있어 너를 구원할 것이라 너를 흩었던 그 모든 이방을 내가 멸망시키리라 그럴지라도 너만은 멸망시키지 아니하리라 그러나 내가 법에 따라 너를 징계할 것이요 결코 무죄한 자로만 여기지는 아니하리라',19679),
('jer-30-12','jer','예레미야',30,12,'여호와께서 이와 같이 말씀하시니라 네 상처는 고칠 수 없고 네 부상은 중하도다',19680),
('jer-30-13','jer','예레미야',30,13,'네 송사를 처리할 재판관이 없고 네 상처에는 약도 없고 처방도 없도다',19681),
('jer-30-14','jer','예레미야',30,14,'너를 사랑하던 자가 다 너를 잊고 찾지 아니하니 이는 네 악행이 많고 네 죄가 많기 때문에 나는 네 원수가 당할 고난을 네가 받게 하며 잔인한 징계를 내렸도다',19682),
('jer-30-15','jer','예레미야',30,15,'너는 어찌하여 네 상처 때문에 부르짖느냐 네 고통이 심하도다 네 악행이 많고 네 죄가 허다하므로 내가 이 일을 너에게 행하였느니라',19683),
('jer-30-16','jer','예레미야',30,16,'그러므로 너를 먹는 모든 자는 잡아먹힐 것이며 네 모든 대적은 사로잡혀 갈 것이고 너에게서 탈취해 간 자는 탈취를 당할 것이며 너에게서 노략질한 모든 자는 노략물이 되리라',19684),
('jer-30-17','jer','예레미야',30,17,'여호와의 말씀이니라 그들이 쫓겨난 자라 하매 시온을 찾는 자가 없은즉 내가 너의 상처로부터 새 살이 돋아나게 하여 너를 고쳐 주리라',19685),
('jer-30-18','jer','예레미야',30,18,'여호와께서 말씀하시니라 보라 내가 야곱 장막의 포로들을 돌아오게 할 것이고 그 거처들에 사랑을 베풀 것이라 성읍은 그 폐허가 된 언덕 위에 건축될 것이요 그 보루는 규정에 따라 사람이 살게 되리라',19686),
('jer-30-19','jer','예레미야',30,19,'그들에게서 감사하는 소리가 나오고 즐거워하는 자들의 소리가 나오리라 내가 그들을 번성하게 하리니 그들의 수가 줄어들지 아니하겠고 내가 그들을 존귀하게 하리니 그들은 비천하여지지 아니하리라',19687),
('jer-30-20','jer','예레미야',30,20,'그의 자손은 예전과 같겠고 그 회중은 내 앞에 굳게 설 것이며 그를 압박하는 모든 사람은 내가 다 벌하리라',19688),
('jer-30-21','jer','예레미야',30,21,'그 영도자는 그들 중에서 나올 것이요 그 통치자도 그들 중에서 나오리라 내가 그를 가까이 오게 하리니 그가 내게 가까이 오리라 참으로 담대한 마음으로 내게 가까이 올 자가 누구냐 여호와의 말씀이니라',19689),
('jer-30-22','jer','예레미야',30,22,'너희는 내 백성이 되겠고 나는 너희들의 하나님이 되리라',19690),
('jer-30-23','jer','예레미야',30,23,'보라 여호와의 노여움이 일어나 폭풍과 회오리바람처럼 악인의 머리 위에서 회오리칠 것이라',19691),
('jer-30-24','jer','예레미야',30,24,'여호와의 진노는 그의 마음의 뜻한 바를 행하여 이루기까지는 돌이키지 아니하나니 너희가 끝날에 그것을 깨달으리라',19692),
('jer-31-1','jer','예레미야',31,1,'여호와의 말씀이니라 그 때에 내가 이스라엘 모든 종족의 하나님이 되고 그들은 내 백성이 되리라',19693),
('jer-31-2','jer','예레미야',31,2,'여호와께서 이같이 말씀하시니라 칼에서 벗어난 백성이 광야에서 은혜를 입었나니 곧 내가 이스라엘로 안식을 얻게 하러 갈 때에라',19694),
('jer-31-3','jer','예레미야',31,3,'옛적에 여호와께서 나에게 나타나사 내가 영원한 사랑으로 너를 사랑하기에 인자함으로 너를 이끌었다 하였노라',19695),
('jer-31-4','jer','예레미야',31,4,'처녀 이스라엘아 내가 다시 너를 세우리니 네가 세움을 입을 것이요 네가 다시 소고를 들고 즐거워하는 자들과 함께 춤추며 나오리라',19696),
('jer-31-5','jer','예레미야',31,5,'네가 다시 사마리아 산들에 포도나무들을 심되 심는 자가 그 열매를 따기 시작하리라',19697),
('jer-31-6','jer','예레미야',31,6,'에브라임 산 위에서 파수꾼이 외치는 날이 있을 것이라 이르기를 너희는 일어나라 우리가 시온에 올라가서 우리 하나님 여호와께로 나아가자 하리라',19698),
('jer-31-7','jer','예레미야',31,7,'여호와께서 이와 같이 말씀하시니라 너희는 여러 민족의 앞에 서서 야곱을 위하여 기뻐 외치라 너희는 전파하며 찬양하며 말하라 여호와여 주의 백성 이스라엘의 남은 자를 구원하소서 하라',19699),
('jer-31-8','jer','예레미야',31,8,'보라 나는 그들을 북쪽 땅에서 인도하며 땅 끝에서부터 모으리라 그들 중에는 맹인과 다리 저는 사람과 잉태한 여인과 해산하는 여인이 함께 있으며 큰 무리를 이루어 이 곳으로 돌아오리라',19700),
('jer-31-9','jer','예레미야',31,9,'그들이 울며 돌아오리니 나의 인도함을 받고 간구할 때에 내가 그들을 넘어지지 아니하고 물 있는 계곡의 곧은 길로 가게 하리라 나는 이스라엘의 아버지요 에브라임은 나의 장자니라',19701),
('jer-31-10','jer','예레미야',31,10,'이방들이여 너희는 여호와의 말씀을 듣고 먼 섬에 전파하여 이르기를 이스라엘을 흩으신 자가 그를 모으시고 목자가 그 양 떼에게 행함 같이 그를 지키시리로다',19702),
('jer-31-11','jer','예레미야',31,11,'여호와께서 야곱을 구원하시되 그들보다 강한 자의 손에서 속량하셨으니',19703),
('jer-31-12','jer','예레미야',31,12,'그들이 와서 시온의 높은 곳에서 찬송하며 여호와의 복 곧 곡식과 새 포도주와 기름과 어린 양의 떼와 소의 떼를 얻고 크게 기뻐하리라 그 심령은 물 댄 동산 같겠고 다시는 근심이 없으리로다 할지어다',19704),
('jer-31-13','jer','예레미야',31,13,'그 때에 처녀는 춤추며 즐거워하겠고 청년과 노인은 함께 즐거워하리니 내가 그들의 슬픔을 돌려서 즐겁게 하며 그들을 위로하여 그들의 근심으로부터 기쁨을 얻게 할 것임이라',19705),
('jer-31-14','jer','예레미야',31,14,'내가 기름으로 제사장들의 마음을 흡족하게 하며 내 복으로 내 백성을 만족하게 하리라 여호와의 말씀이니라',19706),
('jer-31-15','jer','예레미야',31,15,'여호와께서 이와 같이 말씀하시니라 라마에서 슬퍼하며 통곡하는 소리가 들리니 라헬이 그 자식 때문에 애곡하는 것이라 그가 자식이 없어져서 위로 받기를 거절하는도다',19707),
('jer-31-16','jer','예레미야',31,16,'여호와께서 이와 같이 말씀하시니라 네 울음 소리와 네 눈물을 멈추어라 네 일에 삯을 받을 것인즉 그들이 그의 대적의 땅에서 돌아오리라 여호와의 말씀이니라',19708),
('jer-31-17','jer','예레미야',31,17,'너의 장래에 소망이 있을 것이라 너의 자녀가 자기들의 지경으로 돌아오리라 여호와의 말씀이니라',19709),
('jer-31-18','jer','예레미야',31,18,'에브라임이 스스로 탄식함을 내가 분명히 들었노니 주께서 나를 징벌하시매 멍에에 익숙하지 못한 송아지 같은 내가 징벌을 받았나이다 주는 나의 하나님 여호와이시니 나를 이끌어 돌이키소서 그리하시면 내가 돌아오겠나이다',19710),
('jer-31-19','jer','예레미야',31,19,'내가 돌이킨 후에 뉘우쳤고 내가 교훈을 받은 후에 내 볼기를 쳤사오니 이는 어렸을 때의 치욕을 지므로 부끄럽고 욕됨이니이다 하도다',19711),
('jer-31-20','jer','예레미야',31,20,'에브라임은 나의 사랑하는 아들 기뻐하는 자식이 아니냐 내가 그를 책망하여 말할 때마다 깊이 생각하노라 그러므로 그를 위하여 내 창자가 들끓으니 내가 반드시 그를 불쌍히 여기리라 여호와의 말씀이니라',19712),
('jer-31-21','jer','예레미야',31,21,'처녀 이스라엘아 너의 이정표를 세우며 너의 푯말을 만들고 큰 길 곧 네가 전에 가던 길을 마음에 두라 돌아오라 네 성읍들로 돌아오라',19713),
('jer-31-22','jer','예레미야',31,22,'반역한 딸아 네가 어느 때까지 방황하겠느냐 여호와가 새 일을 세상에 창조하였나니 곧 여자가 남자를 둘러 싸리라',19714),
('jer-31-23','jer','예레미야',31,23,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 내가 그 사로잡힌 자를 돌아오게 할 때에 그들이 유다 땅과 그 성읍들에서 다시 이 말을 쓰리니 곧 의로운 처소여, 거룩한 산이여, 여호와께서 네게 복 주시기를 원하노라 할 것이며',19715),
('jer-31-24','jer','예레미야',31,24,'유다와 그 모든 성읍의 농부와 양 떼를 인도하는 자가 거기에 함께 살리니',19716),
('jer-31-25','jer','예레미야',31,25,'이는 내가 그 피곤한 심령을 상쾌하게 하며 모든 연약한 심령을 만족하게 하였음이라 하시기로',19717),
('jer-31-26','jer','예레미야',31,26,'내가 깨어 보니 내 잠이 달았더라',19718),
('jer-31-27','jer','예레미야',31,27,'여호와의 말씀이니라 보라 내가 사람의 씨와 짐승의 씨를 이스라엘 집과 유다 집에 뿌릴 날이 이르리니',19719),
('jer-31-28','jer','예레미야',31,28,'깨어서 그들을 뿌리 뽑으며 무너뜨리며 전복하며 멸망시키며 괴롭게 하던 것과 같이 내가 깨어서 그들을 세우며 심으리라 여호와의 말씀이니라',19720),
('jer-31-29','jer','예레미야',31,29,'그 때에 그들이 말하기를 다시는 아버지가 신 포도를 먹었으므로 아들들의 이가 시다 하지 아니하겠고',19721),
('jer-31-30','jer','예레미야',31,30,'신 포도를 먹는 자마다 그의 이가 신 것 같이 누구나 자기의 죄악으로 말미암아 죽으리라',19722),
('jer-31-31','jer','예레미야',31,31,'여호와의 말씀이니라 보라 날이 이르리니 내가 이스라엘 집과 유다 집에 새 언약을 맺으리라',19723),
('jer-31-32','jer','예레미야',31,32,'이 언약은 내가 그들의 조상들의 손을 잡고 애굽 땅에서 인도하여 내던 날에 맺은 것과 같지 아니할 것은 내가 그들의 남편이 되었어도 그들이 내 언약을 깨뜨렸음이라 여호와의 말씀이니라',19724),
('jer-31-33','jer','예레미야',31,33,'그러나 그 날 후에 내가 이스라엘 집과 맺을 언약은 이러하니 곧 내가 나의 법을 그들의 속에 두며 그들의 마음에 기록하여 나는 그들의 하나님이 되고 그들은 내 백성이 될 것이라 여호와의 말씀이니라',19725),
('jer-31-34','jer','예레미야',31,34,'그들이 다시는 각기 이웃과 형제를 가리켜 이르기를 너는 여호와를 알라 하지 아니하리니 이는 작은 자로부터 큰 자까지 다 나를 알기 때문이라 내가 그들의 악행을 사하고 다시는 그 죄를 기억하지 아니하리라 여호와의 말씀이니라',19726),
('jer-31-35','jer','예레미야',31,35,'여호와께서 이와 같이 말씀하셨느니라 그는 해를 낮의 빛으로 주셨고 달과 별들을 밤의 빛으로 정하였고 바다를 뒤흔들어 그 파도로 소리치게 하나니 그의 이름은 만군의 여호와니라',19727),
('jer-31-36','jer','예레미야',31,36,'이 법도가 내 앞에서 폐할진대 이스라엘 자손도 내 앞에서 끊어져 영원히 나라가 되지 못하리라 여호와의 말씀이니라',19728),
('jer-31-37','jer','예레미야',31,37,'여호와께서 이와 같이 말씀하시니라 위에 있는 하늘을 측량할 수 있으며 밑에 있는 땅의 기초를 탐지할 수 있다면 내가 이스라엘 자손이 행한 모든 일로 말미암아 그들을 다 버리리라 여호와의 말씀이니라',19729),
('jer-31-38','jer','예레미야',31,38,'보라, 날이 이르리니 이 성은 하나넬 망대로부터 모퉁이에 이르기까지 여호와를 위하여 건축될 것이라 여호와의 말씀이니라',19730),
('jer-31-39','jer','예레미야',31,39,'측량줄이 곧게 가렙 언덕 밑에 이르고 고아로 돌아',19731),
('jer-31-40','jer','예레미야',31,40,'시체와 재의 모든 골짜기와 기드론 시내에 이르는 모든 고지 곧 동쪽 마문의 모퉁이에 이르기까지 여호와의 거룩한 곳이니라 영원히 다시는 뽑거나 전복하지 못할 것이니라',19732),
('jer-32-1','jer','예레미야',32,1,'유다의 시드기야 왕 열째 해 곧 느부갓네살 열여덟째 해에 여호와의 말씀이 예레미야에게 임하니라',19733),
('jer-32-2','jer','예레미야',32,2,'그 때에 바벨론 군대는 예루살렘을 에워싸고 선지자 예레미야는 유다의 왕의 궁중에 있는 시위대 뜰에 갇혔으니',19734),
('jer-32-3','jer','예레미야',32,3,'이는 그가 예언하기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 차지할 것이며 유다 왕 시드기야는 갈대아인의 손에서 벗어나지 못하고 반드시 바벨론 왕의 손에 넘겨진 바 되리니 입이 입을 대하여 말하고 눈이 서로 볼 것이며 그가 시드기야를 바벨론으로 끌어 가리니 시드기야는 내가 돌볼 때까지 거기에 있으리라 여호와께서 이와 같이 말씀하시니라 너희가 갈대아인과 싸울지라도 승리하지 못하리라 하셨다 하였더니 유다 왕 시드기야가 이르되 네가 어찌하여 이같이 예언하였느냐 하고 그를 가두었음이었더라',19735),
('jer-32-4','jer','예레미야',32,4,'이는 그가 예언하기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 차지할 것이며 유다 왕 시드기야는 갈대아인의 손에서 벗어나지 못하고 반드시 바벨론 왕의 손에 넘겨진 바 되리니 입이 입을 대하여 말하고 눈이 서로 볼 것이며 그가 시드기야를 바벨론으로 끌어 가리니 시드기야는 내가 돌볼 때까지 거기에 있으리라 여호와께서 이와 같이 말씀하시니라 너희가 갈대아인과 싸울지라도 승리하지 못하리라 하셨다 하였더니 유다 왕 시드기야가 이르되 네가 어찌하여 이같이 예언하였느냐 하고 그를 가두었음이었더라',19736),
('jer-32-5','jer','예레미야',32,5,'이는 그가 예언하기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 차지할 것이며 유다 왕 시드기야는 갈대아인의 손에서 벗어나지 못하고 반드시 바벨론 왕의 손에 넘겨진 바 되리니 입이 입을 대하여 말하고 눈이 서로 볼 것이며 그가 시드기야를 바벨론으로 끌어 가리니 시드기야는 내가 돌볼 때까지 거기에 있으리라 여호와께서 이와 같이 말씀하시니라 너희가 갈대아인과 싸울지라도 승리하지 못하리라 하셨다 하였더니 유다 왕 시드기야가 이르되 네가 어찌하여 이같이 예언하였느냐 하고 그를 가두었음이었더라',19737),
('jer-32-6','jer','예레미야',32,6,'예레미야가 이르되 여호와의 말씀이 내게 임하였느니라 이르시기를',19738),
('jer-32-7','jer','예레미야',32,7,'보라 네 숙부 살룸의 아들 하나멜이 네게 와서 말하기를 너는 아나돗에 있는 내 밭을 사라 이 기업을 무를 권리가 네게 있느니라 하리라 하시더니',19739),
('jer-32-8','jer','예레미야',32,8,'여호와의 말씀과 같이 나의 숙부의 아들 하나멜이 시위대 뜰 안 나에게 와서 이르되 청하노니 너는 베냐민 땅 아나돗에 있는 나의 밭을 사라 기업의 상속권이 네게 있고 무를 권리가 네게 있으니 너를 위하여 사라 하는지라 내가 이것이 여호와의 말씀인 줄 알았으므로',19740),
('jer-32-9','jer','예레미야',32,9,'내 숙부의 아들 하나멜의 아나돗에 있는 밭을 사는데 은 십칠 세겔을 달아 주되',19741),
('jer-32-10','jer','예레미야',32,10,'증서를 써서 봉인하고 증인을 세우고 은을 저울에 달아 주고',19742),
('jer-32-11','jer','예레미야',32,11,'법과 규례대로 봉인하고 봉인하지 아니한 매매 증서를 내가 가지고',19743),
('jer-32-12','jer','예레미야',32,12,'나의 숙부의 아들 하나멜과 매매 증서에 인 친 증인 앞과 시위대 뜰에 앉아 있는 유다 모든 사람 앞에서 그 매매 증서를 마세야의 손자 네리야의 아들 바룩에게 부치며',19744),
('jer-32-13','jer','예레미야',32,13,'그들의 앞에서 바룩에게 명령하여 이르되',19745),
('jer-32-14','jer','예레미야',32,14,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시기를 너는 이 증서 곧 봉인하고 봉인하지 않은 매매 증서를 가지고 토기에 담아 오랫동안 보존하게 하라',19746),
('jer-32-15','jer','예레미야',32,15,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 사람이 이 땅에서 집과 밭과 포도원을 다시 사게 되리라 하셨다 하니라',19747),
('jer-32-16','jer','예레미야',32,16,'내가 매매 증서를 네리야의 아들 바룩에게 넘겨 준 뒤에 여호와께 기도하여 이르되',19748),
('jer-32-17','jer','예레미야',32,17,'슬프도소이다 주 여호와여 주께서 큰 능력과 펴신 팔로 천지를 지으셨사오니 주에게는 할 수 없는 일이 없으시니이다',19749),
('jer-32-18','jer','예레미야',32,18,'주는 은혜를 천만인에게 베푸시며 아버지의 죄악을 그 후손의 품에 갚으시오니 크고 능력 있으신 하나님이시요 이름은 만군의 여호와시니이다',19750),
('jer-32-19','jer','예레미야',32,19,'주는 책략에 크시며 하시는 일에 능하시며 인류의 모든 길을 주목하시며 그의 길과 그의 행위의 열매대로 보응하시나이다',19751),
('jer-32-20','jer','예레미야',32,20,'주께서 애굽 땅에서 표적과 기사를 행하셨고 오늘까지도 이스라엘과 인류 가운데 그와 같이 행하사 주의 이름을 오늘과 같이 되게 하셨나이다',19752),
('jer-32-21','jer','예레미야',32,21,'주께서 표적과 기사와 강한 손과 펴신 팔과 큰 두려움으로 주의 백성 이스라엘을 애굽 땅에서 인도하여 내시고',19753),
('jer-32-22','jer','예레미야',32,22,'그들에게 주시기로 그 조상들에게 맹세하신 바 젖과 꿀이 흐르는 땅을 그들에게 주셨으므로',19754),
('jer-32-23','jer','예레미야',32,23,'그들이 들어가서 이를 차지하였거늘 주의 목소리를 순종하지 아니하며 주의 율법에서 행하지 아니하며 무릇 주께서 행하라 명령하신 일을 행하지 아니하였으므로 주께서 이 모든 재앙을 그들에게 내리셨나이다',19755),
('jer-32-24','jer','예레미야',32,24,'보옵소서 이 성을 빼앗으려고 만든 참호가 이 성에 이르렀고 칼과 기근과 전염병으로 말미암아 이 성이 이를 치는 갈대아인의 손에 넘긴 바 되었으니 주의 말씀대로 되었음을 주께서 보시나이다',19756),
('jer-32-25','jer','예레미야',32,25,'주 여호와여 주께서 내게 은으로 밭을 사며 증인을 세우라 하셨으나 이 성은 갈대아인의 손에 넘기신 바 되었나이다',19757),
('jer-32-26','jer','예레미야',32,26,'그 때에 여호와의 말씀이 예레미야에게 임하여 이르시되',19758),
('jer-32-27','jer','예레미야',32,27,'나는 여호와요 모든 육체의 하나님이라 내게 할 수 없는 일이 있겠느냐',19759),
('jer-32-28','jer','예레미야',32,28,'그러므로 여호와께서 이와 같이 말씀하시니라 보라 내가 이 성을 갈대아인의 손과 바벨론의 느부갓네살 왕의 손에 넘길 것인즉 그가 차지할 것이라',19760),
('jer-32-29','jer','예레미야',32,29,'이 성을 치는 갈대아인이 와서 이 성읍에 불을 놓아 성과 집 곧 그 지붕에서 바알에게 분향하며 다른 신들에게 전제를 드려 나를 격노하게 한 집들을 사르리니',19761),
('jer-32-30','jer','예레미야',32,30,'이는 이스라엘 자손과 유다 자손이 예로부터 내 눈 앞에 악을 행하였을 뿐이라 이스라엘 자손은 그의 손으로 만든 것을 가지고 나를 격노하게 한 것뿐이니라 여호와의 말씀이니라',19762),
('jer-32-31','jer','예레미야',32,31,'이 성이 건설된 날부터 오늘까지 나의 노여움과 분을 일으키므로 내가 내 앞에서 그것을 옮기려 하노니',19763),
('jer-32-32','jer','예레미야',32,32,'이는 이스라엘 자손과 유다 자손이 모든 악을 행하여 내 노여움을 일으켰음이라 그들과 그들의 왕들과 그의 고관들과 그의 제사장들과 그의 선지자들과 유다 사람들과 예루살렘 주민들이 다 그러하였느니라',19764),
('jer-32-33','jer','예레미야',32,33,'그들이 등을 내게로 돌리고 얼굴을 내게로 향하지 아니하며 내가 그들을 가르치되 끊임없이 가르쳤는데도 그들이 교훈을 듣지 아니하며 받지 아니하고',19765),
('jer-32-34','jer','예레미야',32,34,'내 이름으로 일컫는 집에 자기들의 가증한 물건들을 세워서 그 집을 더럽게 하며',19766),
('jer-32-35','jer','예레미야',32,35,'힌놈의 아들의 골짜기에 바알의 산당을 건축하였으며 자기들의 아들들과 딸들을 몰렉 앞으로 지나가게 하였느니라 그들이 이런 가증한 일을 행하여 유다로 범죄하게 한 것은 내가 명령한 것도 아니요 내 마음에 둔 것도 아니니라',19767),
('jer-32-36','jer','예레미야',32,36,'그러나 이스라엘의 하나님 여호와께서 너희가 말하는 바 칼과 기근과 전염병으로 말미암아 바벨론 왕의 손에 넘긴 바 되었다 하는 이 성에 대하여 이와 같이 말씀하시니라',19768),
('jer-32-37','jer','예레미야',32,37,'보라 내가 노여움과 분함과 큰 분노로 그들을 쫓아 보내었던 모든 지방에서 그들을 모아들여 이 곳으로 돌아오게 하여 안전히 살게 할 것이라',19769),
('jer-32-38','jer','예레미야',32,38,'그들은 내 백성이 되겠고 나는 그들의 하나님이 될 것이며',19770),
('jer-32-39','jer','예레미야',32,39,'내가 그들에게 한 마음과 한 길을 주어 자기들과 자기 후손의 복을 위하여 항상 나를 경외하게 하고',19771),
('jer-32-40','jer','예레미야',32,40,'내가 그들에게 복을 주기 위하여 그들을 떠나지 아니하리라 하는 영원한 언약을 그들에게 세우고 나를 경외함을 그들의 마음에 두어 나를 떠나지 않게 하고',19772),
('jer-32-41','jer','예레미야',32,41,'내가 기쁨으로 그들에게 복을 주되 분명히 나의 마음과 정성을 다하여 그들을 이 땅에 심으리라',19773),
('jer-32-42','jer','예레미야',32,42,'여호와께서 이와 같이 말씀하시니라 내가 이 백성에게 이 큰 재앙을 내린 것 같이 허락한 모든 복을 그들에게 내리리라',19774),
('jer-32-43','jer','예레미야',32,43,'너희가 말하기를 황폐하여 사람이나 짐승이 없으며 갈대아인의 손에 넘긴 바 되었다 하는 이 땅에서 사람들이 밭을 사되',19775),
('jer-32-44','jer','예레미야',32,44,'베냐민 땅과 예루살렘 사방과 유다 성읍들과 산지의 성읍들과 저지대의 성읍들과 네겝의 성읍들에 있는 밭을 은으로 사고 증서를 기록하여 봉인하고 증인을 세우리니 이는 내가 그들의 포로를 돌아오게 함이니라 여호와의 말씀이니라',19776),
('jer-33-1','jer','예레미야',33,1,'예레미야가 아직 시위대 뜰에 갇혀 있을 때에 여호와의 말씀이 그에게 두 번째로 임하니라 이르시되',19777),
('jer-33-2','jer','예레미야',33,2,'일을 행하시는 여호와, 그것을 만들며 성취하시는 여호와, 그의 이름을 여호와라 하는 이가 이와 같이 이르시도다',19778),
('jer-33-3','jer','예레미야',33,3,'너는 내게 부르짖으라 내가 네게 응답하겠고 네가 알지 못하는 크고 은밀한 일을 네게 보이리라',19779),
('jer-33-4','jer','예레미야',33,4,'이스라엘의 하나님 여호와께서 말씀하시니라 무리가 이 성읍의 가옥과 유다 왕궁을 헐어서 갈대아인의 참호와 칼을 대항하여',19780),
('jer-33-5','jer','예레미야',33,5,'싸우려 하였으나 내가 나의 노여움과 분함으로 그들을 죽이고 그들의 시체로 이 성을 채우게 하였나니 이는 그들의 모든 악행으로 말미암아 나의 얼굴을 가리어 이 성을 돌아보지 아니하였음이라',19781),
('jer-33-6','jer','예레미야',33,6,'그러나 보라 내가 이 성읍을 치료하며 고쳐 낫게 하고 평안과 진실이 풍성함을 그들에게 나타낼 것이며',19782),
('jer-33-7','jer','예레미야',33,7,'내가 유다의 포로와 이스라엘의 포로를 돌아오게 하여 그들을 처음과 같이 세울 것이며',19783),
('jer-33-8','jer','예레미야',33,8,'내가 그들을 내게 범한 그 모든 죄악에서 정하게 하며 그들이 내게 범하며 행한 모든 죄악을 사할 것이라',19784),
('jer-33-9','jer','예레미야',33,9,'이 성읍이 세계 열방 앞에서 나의 기쁜 이름이 될 것이며 찬송과 영광이 될 것이요 그들은 내가 이 백성에게 베푼 모든 복을 들을 것이요 내가 이 성읍에 베푼 모든 복과 모든 평안으로 말미암아 두려워하며 떨리라',19785),
('jer-33-10','jer','예레미야',33,10,'여호와께서 이와 같이 말씀하시니라 너희가 가리켜 말하기를 황폐하여 사람도 없고 짐승도 없다 하던 여기 곧 황폐하여 사람도 없고 주민도 없고 짐승도 없던 유다 성읍들과 예루살렘 거리에서 즐거워하는 소리, 기뻐하는 소리, 신랑의 소리, 신부의 소리와 및 만군의 여호와께 감사하라, 여호와는 선하시니 그 인자하심이 영원하다 하는 소리와 여호와의 성전에 감사제를 드리는 자들의 소리가 다시 들리리니 이는 내가 이 땅의 포로를 돌려보내어 지난 날처럼 되게 할 것임이라 여호와의 말씀이니라',19786),
('jer-33-11','jer','예레미야',33,11,'여호와께서 이와 같이 말씀하시니라 너희가 가리켜 말하기를 황폐하여 사람도 없고 짐승도 없다 하던 여기 곧 황폐하여 사람도 없고 주민도 없고 짐승도 없던 유다 성읍들과 예루살렘 거리에서 즐거워하는 소리, 기뻐하는 소리, 신랑의 소리, 신부의 소리와 및 만군의 여호와께 감사하라, 여호와는 선하시니 그 인자하심이 영원하다 하는 소리와 여호와의 성전에 감사제를 드리는 자들의 소리가 다시 들리리니 이는 내가 이 땅의 포로를 돌려보내어 지난 날처럼 되게 할 것임이라 여호와의 말씀이니라',19787),
('jer-33-12','jer','예레미야',33,12,'만군의 여호와께서 이와 같이 말씀하시니라 황폐하여 사람도 없고 짐승도 없던 이 곳과 그 모든 성읍에 다시 목자가 살 곳이 있으리니 그의 양 떼를 눕게 할 것이라',19788),
('jer-33-13','jer','예레미야',33,13,'산지 성읍들과 평지 성읍들과 네겝의 성읍들과 베냐민 땅과 예루살렘 사면과 유다 성읍들에서 양 떼가 다시 계수하는 자의 손 아래로 지나리라 여호와께서 말씀하시니라',19789),
('jer-33-14','jer','예레미야',33,14,'여호와의 말씀이니라 보라 내가 이스라엘 집과 유다 집에 대하여 일러 준 선한 말을 성취할 날이 이르리라',19790),
('jer-33-15','jer','예레미야',33,15,'그 날 그 때에 내가 다윗에게서 한 공의로운 가지가 나게 하리니 그가 이 땅에 정의와 공의를 실행할 것이라',19791),
('jer-33-16','jer','예레미야',33,16,'그 날에 유다가 구원을 받겠고 예루살렘이 안전히 살 것이며 이 성은 여호와는 우리의 의라는 이름을 얻으리라',19792),
('jer-33-17','jer','예레미야',33,17,'여호와께서 이와 같이 말씀하시니라 이스라엘 집의 왕위에 앉을 사람이 다윗에게 영원히 끊어지지 아니할 것이며',19793),
('jer-33-18','jer','예레미야',33,18,'내 앞에서 번제를 드리며 소제를 사르며 다른 제사를 항상 드릴 레위 사람 제사장들도 끊어지지 아니하리라 하시니라',19794),
('jer-33-19','jer','예레미야',33,19,'여호와의 말씀이 예레미야에게 임하니라 이르시되',19795),
('jer-33-20','jer','예레미야',33,20,'여호와께서 이와 같이 말씀하시니라 너희가 능히 낮에 대한 나의 언약과 밤에 대한 나의 언약을 깨뜨려 주야로 그 때를 잃게 할 수 있을진대',19796),
('jer-33-21','jer','예레미야',33,21,'내 종 다윗에게 세운 나의 언약도 깨뜨려 그에게 그의 자리에 앉아 다스릴 아들이 없게 할 수 있겠으며 내가 나를 섬기는 레위인 제사장에게 세운 언약도 파할 수 있으리라',19797),
('jer-33-22','jer','예레미야',33,22,'하늘의 만상은 셀 수 없으며 바다의 모래는 측량할 수 없나니 내가 그와 같이 내 종 다윗의 자손과 나를 섬기는 레위인을 번성하게 하리라 하시니라',19798),
('jer-33-23','jer','예레미야',33,23,'여호와의 말씀이 예레미야에게 임하니라 이르시되',19799),
('jer-33-24','jer','예레미야',33,24,'이 백성이 말하기를 여호와께서 자기가 택하신 그들 중에 두 가계를 버리셨다 한 것을 네가 생각하지 아니하느냐 그들이 내 백성을 멸시하여 자기들 앞에서 나라로 인정하지 아니하도다',19800),
('jer-33-25','jer','예레미야',33,25,'여호와께서 이와 같이 말씀하시니라 내가 주야와 맺은 언약이 없다든지 천지의 법칙을 내가 정하지 아니하였다면',19801),
('jer-33-26','jer','예레미야',33,26,'야곱과 내 종 다윗의 자손을 버리고 다시는 다윗의 자손 중에서 아브라함과 이삭과 야곱의 자손을 다스릴 자를 택하지 아니하리라 내가 그 포로된 자를 돌아오게 하고 그를 불쌍히 여기리라',19802),
('jer-34-1','jer','예레미야',34,1,'바벨론의 느부갓네살 왕과 그의 모든 군대와 그의 통치하에 있는 땅의 모든 나라와 모든 백성이 예루살렘과 그 모든 성읍을 칠 때에 말씀이 여호와께로부터 예레미야에게 임하여 이르시되',19803),
('jer-34-2','jer','예레미야',34,2,'이스라엘의 하나님 여호와께서 이와 같이 말씀하시니라 너는 가서 유다의 시드기야 왕에게 아뢰어 이르기를 여호와의 말씀에 보라 내가 이 성을 바벨론 왕의 손에 넘기리니 그가 이 성을 불사를 것이라',19804),
('jer-34-3','jer','예레미야',34,3,'네가 그의 손에서 벗어나지 못하고 반드시 사로잡혀 그의 손에 넘겨져서 네 눈은 바벨론 왕의 눈을 볼 것이며 그의 입은 네 입을 마주 대하여 말할 것이요 너는 바벨론으로 가리라',19805),
('jer-34-4','jer','예레미야',34,4,'그러나 유다의 시드기야 왕이여 여호와의 말씀을 들으라 여호와께서 네게 대하여 이와 같이 말씀하시니라 네가 칼에 죽지 아니하고',19806),
('jer-34-5','jer','예레미야',34,5,'평안히 죽을 것이며 사람이 너보다 먼저 있은 네 조상들 곧 선왕들에게 분향하던 것 같이 네게 분향하며 너를 위하여 애통하기를 슬프다 주여 하리니 이는 내가 말하였음이라 여호와의 말씀이니라 하시니라',19807),
('jer-34-6','jer','예레미야',34,6,'선지자 예레미야가 이 모든 말씀을 예루살렘에서 유다의 시드기야 왕에게 아뢰니라',19808),
('jer-34-7','jer','예레미야',34,7,'그 때에 바벨론의 왕의 군대가 예루살렘과 유다의 남은 모든 성읍들을 쳤으니 곧 라기스와 아세가라 유다의 견고한 성읍 중에 이것들만 남았음이더라',19809),
('jer-34-8','jer','예레미야',34,8,'시드기야 왕이 예루살렘에 있는 모든 백성과 한 가지로 하나님 앞에서 계약을 맺고 자유를 선포한 후에 여호와께로부터 말씀이 예레미야에게 임하니라',19810),
('jer-34-9','jer','예레미야',34,9,'그 계약은 사람마다 각기 히브리 남녀 노비를 놓아 자유롭게 하고 그의 동족 유다인을 종으로 삼지 못하게 한 것이라',19811),
('jer-34-10','jer','예레미야',34,10,'이 계약에 가담한 고관들과 모든 백성이 각기 노비를 자유롭게 하고 다시는 종을 삼지 말라 함을 듣고 순복하여 놓았더니',19812),
('jer-34-11','jer','예레미야',34,11,'후에 그들의 뜻이 변하여 자유를 주었던 노비를 끌어다가 복종시켜 다시 노비로 삼았더라',19813),
('jer-34-12','jer','예레미야',34,12,'그러므로 여호와의 말씀이 여호와께로부터 예레미야에게 임하니라 이르시되',19814),
('jer-34-13','jer','예레미야',34,13,'이스라엘 하나님 여호와께서 이와 같이 말씀하시니라 내가 너희 선조를 애굽 땅 종의 집에서 인도하여 낼 때에 그들과 언약을 맺으며 이르기를',19815),
('jer-34-14','jer','예레미야',34,14,'너희 형제 히브리 사람이 네게 팔려 왔거든 너희는 칠 년 되는 해에 그를 놓아 줄 것이니라 그가 육 년 동안 너를 섬겼은즉 그를 놓아 자유롭게 할지니라 하였으나 너희 선조가 내게 순종하지 아니하며 귀를 기울이지도 아니하였느니라',19816),
('jer-34-15','jer','예레미야',34,15,'그러나 너희는 이제 돌이켜 내 눈 앞에 바른 일을 행하여 각기 이웃에게 자유를 선포하되 내 이름으로 일컬음을 받는 집에서 내 앞에서 계약을 맺었거늘',19817),
('jer-34-16','jer','예레미야',34,16,'너희가 돌이켜 내 이름을 더럽히고 각기 놓아 그들의 마음대로 자유롭게 하였던 노비를 끌어다가 다시 너희에게 복종시켜 너희의 노비로 삼았도다',19818),
('jer-34-17','jer','예레미야',34,17,'그러므로 여호와께서 이와 같이 말씀하시니라 너희가 나에게 순종하지 아니하고 각기 형제와 이웃에게 자유를 선포한 것을 실행하지 아니하였은즉 내가 너희를 대적하여 칼과 전염병과 기근에게 자유를 주리라 여호와의 말씀이니라 내가 너희를 세계 여러 나라 가운데에 흩어지게 할 것이며',19819),
('jer-34-18','jer','예레미야',34,18,'송아지를 둘로 쪼개고 그 두 조각 사이로 지나매 내 앞에 언약을 맺었으나 그 말을 실행하지 아니하여 내 계약을 어긴 그들을',19820),
('jer-34-19','jer','예레미야',34,19,'곧 송아지 두 조각 사이로 지난 유다 고관들과 예루살렘 고관들과 내시들과 제사장들과 이 땅 모든 백성을',19821),
('jer-34-20','jer','예레미야',34,20,'내가 그들의 원수의 손과 그들의 생명을 찾는 자의 손에 넘기리니 그들의 시체가 공중의 새와 땅의 짐승의 먹이가 될 것이며',19822),
('jer-34-21','jer','예레미야',34,21,'또 내가 유다의 시드기야 왕과 그의 고관들을 그의 원수의 손과 그의 생명을 찾는 자의 손과 너희에게서 떠나간 바벨론 왕의 군대의 손에 넘기리라',19823),
('jer-34-22','jer','예레미야',34,22,'여호와의 말씀이니라 보라 내가 그들에게 명령하여 이 성읍에 다시 오게 하리니 그들이 이 성을 쳐서 빼앗아 불사를 것이라 내가 유다의 성읍들을 주민이 없어 처참한 황무지가 되게 하리라',19824),
('jer-35-1','jer','예레미야',35,1,'유다의 요시야 왕의 아들 여호야김 때에 여호와께로부터 말씀이 예레미야에게 임하여 이르시되',19825),
('jer-35-2','jer','예레미야',35,2,'너는 레갑 사람들의 집에 가서 그들에게 말하고 그들을 여호와의 집 한 방으로 데려다가 포도주를 마시게 하라 하시니라',19826),
('jer-35-3','jer','예레미야',35,3,'이에 내가 하바시냐의 손자요 예레미야의 아들인 야아사냐와 그의 형제와 그의 모든 아들과 모든 레갑 사람들을 데리고',19827),
('jer-35-4','jer','예레미야',35,4,'여호와의 집에 이르러 익다랴의 아들 하나님의 사람 하난의 아들들의 방에 들였는데 그 방은 고관들의 방 곁이요 문을 지키는 살룸의 아들 마아세야의 방 위더라',19828),
('jer-35-5','jer','예레미야',35,5,'내가 레갑 사람들의 후손들 앞에 포도주가 가득한 종지와 술잔을 놓고 마시라 권하매',19829),
('jer-35-6','jer','예레미야',35,6,'그들이 이르되 우리는 포도주를 마시지 아니하겠노라 레갑의 아들 우리 선조 요나답이 우리에게 명령하여 이르기를 너희와 너희 자손은 영원히 포도주를 마시지 말며',19830),
('jer-35-7','jer','예레미야',35,7,'너희가 집도 짓지 말며 파종도 하지 말며 포도원을 소유하지도 말고 너희는 평생 동안 장막에 살아라 그리하면 너희가 머물러 사는 땅에서 너희 생명이 길리라 하였으므로',19831),
('jer-35-8','jer','예레미야',35,8,'우리가 레갑의 아들 우리 선조 요나답이 우리에게 명령한 모든 말을 순종하여 우리와 우리 아내와 자녀가 평생 동안 포도주를 마시지 아니하며',19832),
('jer-35-9','jer','예레미야',35,9,'살 집도 짓지 아니하며 포도원이나 밭이나 종자도 가지지 아니하고',19833),
('jer-35-10','jer','예레미야',35,10,'장막에 살면서 우리 선조 요나답이 우리에게 명령한 대로 다 지켜 행하였노라',19834),
('jer-35-11','jer','예레미야',35,11,'그러나 바벨론의 느부갓네살 왕이 이 땅에 올라왔을 때에 우리가 말하기를 갈대아인의 군대와 수리아인의 군대를 피하여 예루살렘으로 가자 하고 우리가 예루살렘에 살았노라',19835),
('jer-35-12','jer','예레미야',35,12,'그 때에 여호와의 말씀이 예레미야에게 임하여 이르시되',19836),
('jer-35-13','jer','예레미야',35,13,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 너는 가서 유다 사람들과 예루살렘 주민에게 이르기를 너희가 내 말을 들으며 교훈을 받지 아니하겠느냐 여호와의 말씀이니라',19837),
('jer-35-14','jer','예레미야',35,14,'레갑의 아들 요나답이 그의 자손에게 포도주를 마시지 말라 한 그 명령은 실행되도다 그들은 그 선조의 명령을 순종하여 오늘까지 마시지 아니하거늘 내가 너희에게 말하고 끊임없이 말하여도 너희는 내게 순종하지 아니하도다',19838),
('jer-35-15','jer','예레미야',35,15,'내가 내 종 모든 선지자를 너희에게 보내고 끊임없이 보내며 이르기를 너희는 이제 각기 악한 길에서 돌이켜 행위를 고치고 다른 신을 따라 그를 섬기지 말라 그리하면 너희는 내가 너희와 너희 선조에게 준 이 땅에 살리라 하여도 너희가 귀를 기울이지 아니하며 내게 순종하지 아니하였느니라',19839),
('jer-35-16','jer','예레미야',35,16,'레갑의 아들 요나답의 자손은 그의 선조가 그들에게 명령한 그 명령을 지켜 행하나 이 백성은 내게 순종하지 아니하도다',19840),
('jer-35-17','jer','예레미야',35,17,'그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 유다와 예루살렘의 모든 주민에게 내가 그들에게 대하여 선포한 모든 재앙을 내리리니 이는 내가 그들에게 말하여도 듣지 아니하며 불러도 대답하지 아니함이니라 하셨다 하라',19841),
('jer-35-18','jer','예레미야',35,18,'예레미야가 레갑 사람의 가문에게 이르되 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시기를 너희가 너희 선조 요나답의 명령을 순종하여 그의 모든 규율을 지키며 그가 너희에게 명령한 것을 행하였도다',19842),
('jer-35-19','jer','예레미야',35,19,'그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 레갑의 아들 요나답에게서 내 앞에 설 사람이 영원히 끊어지지 아니하리라 하시니라',19843),
('jer-36-1','jer','예레미야',36,1,'유다의 요시야 왕의 아들 여호야김 제사년에 여호와께로부터 예레미야에게 말씀이 임하니라 이르시되',19844),
('jer-36-2','jer','예레미야',36,2,'너는 두루마리 책을 가져다가 내가 네게 말하던 날 곧 요시야의 날부터 오늘까지 이스라엘과 유다와 모든 나라에 대하여 내가 네게 일러 준 모든 말을 거기에 기록하라',19845),
('jer-36-3','jer','예레미야',36,3,'유다 가문이 내가 그들에게 내리려 한 모든 재난을 듣고 각기 악한 길에서 돌이키리니 그리하면 내가 그 악과 죄를 용서하리라 하시니라',19846),
('jer-36-4','jer','예레미야',36,4,'이에 예레미야가 네리야의 아들 바룩을 부르매 바룩이 예레미야가 불러 주는 대로 여호와께서 그에게 이르신 모든 말씀을 두루마리 책에 기록하니라',19847),
('jer-36-5','jer','예레미야',36,5,'예레미야가 바룩에게 명령하여 이르되 나는 붙잡혔으므로 여호와의 집에 들어갈 수 없으니',19848),
('jer-36-6','jer','예레미야',36,6,'너는 들어가서 내가 말한 대로 두루마리에 기록한 여호와의 말씀을 금식일에 여호와의 성전에 있는 백성의 귀에 낭독하고 유다 모든 성읍에서 온 자들의 귀에도 낭독하라',19849),
('jer-36-7','jer','예레미야',36,7,'그들이 여호와 앞에 기도를 드리며 각기 악한 길을 떠나리라 여호와께서 이 백성에 대하여 선포하신 노여움과 분이 크니라',19850),
('jer-36-8','jer','예레미야',36,8,'네리야의 아들 바룩이 선지자 예레미야가 자기에게 명령한 대로 하여 여호와의 성전에서 책에 있는 여호와의 모든 말씀을 낭독하니라',19851),
('jer-36-9','jer','예레미야',36,9,'유다의 요시야 왕의 아들 여호야김의 제오년 구월에 예루살렘 모든 백성과 유다 성읍들에서 예루살렘에 이른 모든 백성이 여호와 앞에서 금식을 선포한지라',19852),
('jer-36-10','jer','예레미야',36,10,'바룩이 여호와의 성전 위뜰 곧 여호와의 성전에 있는 새 문 어귀 곁에 있는 사반의 아들 서기관 그마랴의 방에서 그 책에 기록된 예레미야의 말을 모든 백성에게 낭독하니라',19853),
('jer-36-11','jer','예레미야',36,11,'사반의 손자요 그마랴의 아들인 미가야가 그 책에 기록된 여호와의 말씀을 다 듣고',19854),
('jer-36-12','jer','예레미야',36,12,'왕궁에 내려가서 서기관의 방에 들어가니 모든 고관 곧 서기관 엘리사마와 스마야의 아들 들라야와 악볼의 아들 엘라단과 사반의 아들 그마랴와 하나냐의 아들 시드기야와 모든 고관이 거기에 앉아 있는지라',19855),
('jer-36-13','jer','예레미야',36,13,'미가야가 바룩이 백성의 귀에 책을 낭독할 때에 들은 모든 말을 그들에게 전하매',19856),
('jer-36-14','jer','예레미야',36,14,'이에 모든 고관이 구시의 증손 셀레먀의 손자 느다냐의 아들 여후디를 바룩에게 보내 이르되 너는 백성의 귀에 낭독한 두루마리를 손에 가지고 오라 네리야의 아들 바룩이 두루마리를 손에 가지고 그들에게로 오니',19857),
('jer-36-15','jer','예레미야',36,15,'그들이 바룩에게 이르되 앉아서 이를 우리 귀에 낭독하라 바룩이 그들의 귀에 낭독하매',19858),
('jer-36-16','jer','예레미야',36,16,'그들이 그 모든 말씀을 듣고 놀라 서로 보며 바룩에게 이르되 우리가 이 모든 말을 왕에게 아뢰리라',19859),
('jer-36-17','jer','예레미야',36,17,'그들이 또 바룩에게 물어 이르되 너는 그가 불러 주는 이 모든 말을 어떻게 기록하였느냐 청하노니 우리에게 알리라',19860),
('jer-36-18','jer','예레미야',36,18,'바룩이 대답하되 그가 그의 입으로 이 모든 말을 내게 불러 주기로 내가 먹으로 책에 기록하였노라',19861),
('jer-36-19','jer','예레미야',36,19,'이에 고관들이 바룩에게 이르되 너는 가서 예레미야와 함께 숨고 너희가 있는 곳을 사람에게 알리지 말라 하니라',19862),
('jer-36-20','jer','예레미야',36,20,'그들이 두루마리를 서기관 엘리사마의 방에 두고 뜰에 들어가 왕께 나아가서 이 모든 말을 왕의 귀에 아뢰니',19863),
('jer-36-21','jer','예레미야',36,21,'왕이 여후디를 보내어 두루마리를 가져오게 하매 여후디가 서기관 엘리사마의 방에서 가져다가 왕과 왕의 곁에 선 모든 고관의 귀에 낭독하니',19864),
('jer-36-22','jer','예레미야',36,22,'그 때는 아홉째 달이라 왕이 겨울 궁전에 앉았고 그 앞에는 불 피운 화로가 있더라',19865),
('jer-36-23','jer','예레미야',36,23,'여후디가 서너 쪽을 낭독하면 왕이 면도칼로 그것을 연하여 베어 화로 불에 던져서 두루마리를 모두 태웠더라',19866),
('jer-36-24','jer','예레미야',36,24,'왕과 그의 신하들이 이 모든 말을 듣고도 두려워하거나 자기들의 옷을 찢지 아니하였고',19867),
('jer-36-25','jer','예레미야',36,25,'엘라단과 들라야와 그마랴가 왕께 두루마리를 불사르지 말도록 아뢰어도 왕이 듣지 아니하였으며',19868),
('jer-36-26','jer','예레미야',36,26,'왕이 왕의 아들 여라므엘과 아스리엘의 아들 스라야와 압디엘의 아들 셀레먀에게 명령하여 서기관 바룩과 선지자 예레미야를 잡으라 하였으나 여호와께서 그들을 숨기셨더라',19869),
