('jer-36-28','jer','예레미야',36,28,'너는 다시 다른 두루마리를 가지고 유다의 여호야김 왕이 불사른 첫 두루마리의 모든 말을 기록하고',19871),
('jer-36-29','jer','예레미야',36,29,'또 유다의 여호야김 왕에 대하여 이와 같이 말하기를 여호와의 말씀에 네가 이 두루마리를 불사르며 말하기를 네가 어찌하여 바벨론의 왕이 반드시 와서 이 땅을 멸하고 사람과 짐승을 이 땅에서 없어지게 하리라 하는 말을 이 두루마리에 기록하였느냐 하도다',19872),
('jer-36-30','jer','예레미야',36,30,'그러므로 여호와께서 유다의 왕 여호야김에 대하여 이와 같이 말씀하시니라 그에게 다윗의 왕위에 앉을 자가 없게 될 것이요 그의 시체는 버림을 당하여 낮에는 더위, 밤에는 추위를 당하리라',19873),
('jer-36-31','jer','예레미야',36,31,'또 내가 그와 그의 자손과 신하들을 그들의 죄악으로 말미암아 벌할 것이라 내가 일찍이 그들과 예루살렘 주민과 유다 사람에게 그 모든 재난을 내리리라 선포하였으나 그들이 듣지 아니하였느니라',19874),
('jer-36-32','jer','예레미야',36,32,'이에 예레미야가 다른 두루마리를 가져다가 네리야의 아들 서기관 바룩에게 주매 그가 유다의 여호야김 왕이 불사른 책의 모든 말을 예레미야가 전하는 대로 기록하고 그 외에도 그 같은 말을 많이 더 하였더라',19875),
('jer-37-1','jer','예레미야',37,1,'요시야의 아들 시드기야가 여호야김의 아들 고니야의 뒤를 이어 왕이 되었으니 이는 바벨론의 느부갓네살 왕이 그를 유다 땅의 왕으로 삼음이었더라',19876),
('jer-37-2','jer','예레미야',37,2,'그와 그의 신하와 그의 땅 백성이 여호와께서 선지자 예레미야에게 하신 말씀을 듣지 아니하니라',19877),
('jer-37-3','jer','예레미야',37,3,'시드기야 왕이 셀레먀의 아들 여후갈과 마아세야의 아들 제사장 스바냐를 선지자 예레미야에게 보내 청하되 너는 우리를 위하여 우리 하나님 여호와께 기도하라 하였으니',19878),
('jer-37-4','jer','예레미야',37,4,'그 때에 예레미야가 갇히지 아니하였으므로 백성 가운데 출입하는 중이었더라',19879),
('jer-37-5','jer','예레미야',37,5,'바로의 군대가 애굽에서 나오매 예루살렘을 에워쌌던 갈대아인이 그 소문을 듣고 예루살렘에서 떠났더라',19880),
('jer-37-6','jer','예레미야',37,6,'여호와의 말씀이 선지자 예레미야에게 임하여 이르시되',19881),
('jer-37-7','jer','예레미야',37,7,'이스라엘의 하나님 여호와께서 이와 같이 말씀하시니라 너희를 보내어 내게 구하게 한 유다의 왕에게 아뢰라 너희를 도우려고 나왔던 바로의 군대는 자기 땅 애굽으로 돌아가겠고',19882),
('jer-37-8','jer','예레미야',37,8,'갈대아인이 다시 와서 이 성을 쳐서 빼앗아 불사르리라',19883),
('jer-37-9','jer','예레미야',37,9,'여호와께서 이와 같이 말씀하시니라 너희는 스스로 속여 말하기를 갈대아인이 반드시 우리를 떠나리라 하지 말라 그들이 떠나지 아니하리라',19884),
('jer-37-10','jer','예레미야',37,10,'가령 너희가 너희를 치는 갈대아인의 온 군대를 쳐서 그 중에 부상자만 남긴다 할지라도 그들이 각기 장막에서 일어나 이 성을 불사르리라',19885),
('jer-37-11','jer','예레미야',37,11,'갈대아인의 군대가 바로의 군대를 두려워하여 예루살렘에서 떠나매',19886),
('jer-37-12','jer','예레미야',37,12,'예레미야가 베냐민 땅에서 백성 가운데 분깃을 받으려고 예루살렘을 떠나 그리로 가려 하여',19887),
('jer-37-13','jer','예레미야',37,13,'베냐민 문에 이른즉 하나냐의 손자요 셀레먀의 아들인 이리야라 이름하는 문지기의 우두머리가 선지자 예레미야를 붙잡아 이르되 네가 갈대아인에게 항복하려 하는도다',19888),
