('jer-37-15','jer','예레미야',37,15,'고관들이 노여워하여 예레미야를 때려서 서기관 요나단의 집에 가두었으니 이는 그들이 이 집을 옥으로 삼았음이더라',19890),
('jer-37-16','jer','예레미야',37,16,'예레미야가 뚜껑 씌운 웅덩이에 들어간 지 여러 날 만에',19891),
('jer-37-17','jer','예레미야',37,17,'시드기야 왕이 사람을 보내어 그를 이끌어내고 왕궁에서 그에게 비밀히 물어 이르되 여호와께로부터 받은 말씀이 있느냐 예레미야가 대답하되 있나이다 또 이르되 왕이 바벨론의 왕의 손에 넘겨지리이다',19892),
('jer-37-18','jer','예레미야',37,18,'예레미야가 다시 시드기야 왕에게 이르되 내가 왕에게나 왕의 신하에게나 이 백성에게 무슨 죄를 범하였기에 나를 옥에 가두었나이까',19893),
('jer-37-19','jer','예레미야',37,19,'바벨론의 왕이 와서 왕과 이 땅을 치지 아니하리라고 예언한 왕의 선지자들이 이제 어디 있나이까',19894),
('jer-37-20','jer','예레미야',37,20,'내 주 왕이여 이제 청하건대 내게 들으시며 나의 탄원을 받으사 나를 서기관 요나단의 집으로 돌려보내지 마옵소서 내가 거기에서 죽을까 두려워하나이다',19895),
('jer-37-21','jer','예레미야',37,21,'이에 시드기야 왕이 명령하여 예레미야를 감옥 뜰에 두고 떡 만드는 자의 거리에서 매일 떡 한 개씩 그에게 주게 하매 성중에 떡이 떨어질 때까지 이르니라 예레미야가 감옥 뜰에 머무니라',19896),
('jer-38-1','jer','예레미야',38,1,'맛단의 아들 스바댜와 바스훌의 아들 그다랴와 셀레먀의 아들 유갈과 말기야의 아들 바스훌이 예레미야가 모든 백성에게 이르는 말을 들은즉 이르기를',19897),
('jer-38-2','jer','예레미야',38,2,'여호와께서 이와 같이 말씀하시되 이 성에 머무는 자는 칼과 기근과 전염병에 죽으리라 그러나 갈대아인에게 항복하는 자는 살리니 그는 노략물을 얻음 같이 자기의 목숨을 건지리라',19898),
('jer-38-3','jer','예레미야',38,3,'여호와께서 이와 같이 말씀하시니라 이 성이 반드시 바벨론의 왕의 군대의 손에 넘어가리니 그가 차지하리라 하셨다 하는지라',19899),
('jer-38-4','jer','예레미야',38,4,'이에 그 고관들이 왕께 아뢰되 이 사람이 백성의 평안을 구하지 아니하고 재난을 구하오니 청하건대 이 사람을 죽이소서 그가 이같이 말하여 이 성에 남은 군사의 손과 모든 백성의 손을 약하게 하나이다',19900),
('jer-38-5','jer','예레미야',38,5,'시드기야 왕이 이르되 보라 그가 너희 손 안에 있느니라 왕은 조금도 너희를 거스를 수 없느니라 하는지라',19901),
('jer-38-6','jer','예레미야',38,6,'그들이 예레미야를 끌어다가 감옥 뜰에 있는 왕의 아들 말기야의 구덩이에 던져 넣을 때에 예레미야를 줄로 달아내렸는데 그 구덩이에는 물이 없고 진창뿐이므로 예레미야가 진창 속에 빠졌더라',19902),
('jer-38-7','jer','예레미야',38,7,'왕궁 내시 구스인 에벳멜렉이 그들이 예레미야를 구덩이에 던져 넣었음을 들으니라 그 때에 왕이 베냐민 문에 앉았더니',19903),
('jer-38-8','jer','예레미야',38,8,'에벳멜렉이 왕궁에서 나와 왕께 아뢰어 이르되',19904),
