('jer-38-10','jer','예레미야',38,10,'왕이 구스 사람 에벳멜렉에게 명령하여 이르되 너는 여기서 삼십 명을 데리고 가서 선지자 예레미야가 죽기 전에 그를 구덩이에서 끌어내라',19906),
('jer-38-11','jer','예레미야',38,11,'에벳멜렉이 사람들을 데리고 왕궁 곳간 밑 방에 들어가서 거기에서 헝겊과 낡은 옷을 가져다가 그것을 구덩이에 있는 예레미야에게 밧줄로 내리며',19907),
('jer-38-12','jer','예레미야',38,12,'구스인 에벳멜렉이 예레미야에게 이르되 당신은 이 헝겊과 낡은 옷을 당신의 겨드랑이에 대고 줄을 그 아래에 대시오 예레미야가 그대로 하매',19908),
('jer-38-13','jer','예레미야',38,13,'그들이 줄로 예레미야를 구덩이에서 끌어낸지라 예레미야가 시위대 뜰에 머무니라',19909),
('jer-38-14','jer','예레미야',38,14,'시드기야 왕이 사람을 보내어 선지자 예레미야를 여호와의 성전 셋째 문으로 데려오게 하고 왕이 예레미야에게 이르되 내가 네게 한 가지 일을 물으리니 한 마디도 내게 숨기지 말라',19910),
('jer-38-15','jer','예레미야',38,15,'예레미야가 시드기야에게 이르되 내가 이 일을 왕에게 아시게 하여도 왕이 결코 나를 죽이지 아니하시리이까 가령 내가 왕을 권한다 할지라도 왕이 듣지 아니하시리이다',19911),
('jer-38-16','jer','예레미야',38,16,'시드기야 왕이 비밀히 예레미야에게 맹세하여 이르되 우리에게 이 영혼을 지으신 여호와께서 살아 계심을 두고 맹세하노니 내가 너를 죽이지도 아니하겠으며 네 생명을 찾는 그 사람들의 손에 넘기지도 아니하리라 하는지라',19912),
('jer-38-17','jer','예레미야',38,17,'예레미야가 시드기야에게 이르되 만군의 하나님이신 이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 네가 만일 바벨론의 왕의 고관들에게 항복하면 네 생명이 살겠고 이 성이 불사름을 당하지 아니하겠고 너와 네 가족이 살려니와',19913),
('jer-38-18','jer','예레미야',38,18,'네가 만일 나가서 바벨론의 왕의 고관들에게 항복하지 아니하면 이 성이 갈대아인의 손에 넘어가리니 그들이 이 성을 불사를 것이며 너는 그들의 손을 벗어나지 못하리라 하셨나이다',19914),
