('jer-38-26','jer','예레미야',38,26,'그들에게 대답하되 내가 왕 앞에 간구하기를 나를 요나단의 집으로 되돌려 보내지 마소서 그리하여 거기서 죽지 않게 하옵소서 하였다 하라 하니라',19922),
