('jer-40-2','jer','예레미야',40,2,'사령관이 예레미야를 불러다가 이르되 네 하나님 여호와께서 이 곳에 이 재난을 선포하시더니',19944),
('jer-40-3','jer','예레미야',40,3,'여호와께서 그가 말씀하신 대로 행하셨으니 이는 너희가 여호와께 범죄하고 그의 목소리에 순종하지 아니하였으므로 이제 이루어졌도다 이 일이 너희에게 임한 것이니라',19945),
('jer-40-4','jer','예레미야',40,4,'보라 내가 오늘 네 손의 사슬을 풀어 너를 풀어 주노니 만일 네가 나와 함께 바벨론으로 가는 것을 좋게 여기거든 가자 내가 너를 선대하리라 만일 나와 함께 바벨론으로 가는 것을 좋지 않게 여기거든 그만 두라 보라 온 땅이 네 앞에 있나니 네가 좋게 여기는 대로 옳게 여기는 곳으로 갈지니라 하니라',19946),
('jer-40-5','jer','예레미야',40,5,'예레미야가 아직 돌이키기 전에 그가 다시 이르되 너는 바벨론의 왕이 유다 성읍들을 맡도록 세운 사반의 손자 아히감의 아들 그다랴에게로 돌아가서 그와 함께 백성 가운데 살거나 네가 옳게 여기는 곳으로 가거나 할지니라 하고 그 사령관이 그에게 양식과 선물을 주어 보내매',19947),
('jer-40-6','jer','예레미야',40,6,'예레미야가 미스바로 가서 아히감의 아들 그다랴에게로 나아가서 그 땅에 남아 있는 백성 가운데 그와 함께 사니라',19948),
('jer-40-7','jer','예레미야',40,7,'들에 있는 모든 지휘관과 그 부하들이 바벨론의 왕이 아히감의 아들 그다랴에게 그 땅을 맡기고 남녀와 유아1)와 바벨론으로 잡혀가지 아니한 빈민을 그에게 위임하였다 함을 듣고',19949),
('jer-40-8','jer','예레미야',40,8,'그들 곧 느다냐의 아들 이스마엘과 가레아의 두 아들 요하난과 요나단과 단후멧의 아들 스라야와 느도바 사람 에배의 아들들과 마아가 사람의 아들 여사냐와 그들의 사람들이 미스바로 가서 그다랴에게 이르니',19950),
('jer-40-9','jer','예레미야',40,9,'사반의 손자 아히감의 아들 그다랴가 그들과 그들의 사람들에게 맹세하며 이르되 너희는 갈대아 사람을 섬기기를 두려워하지 말고 이 땅에 살면서 바벨론의 왕을 섬기라 그리하면 너희에게 유익하리라',19951),
('jer-40-10','jer','예레미야',40,10,'보라 나는 미스바에 살면서 우리에게로 오는 갈대아 사람을 섬기리니 너희는 포도주와 여름 과일과 기름을 모아 그릇에 저장하고 너희가 얻은 성읍들에 살라 하니라',19952),
('jer-40-11','jer','예레미야',40,11,'모압과 암몬 자손 중과 에돔과 모든 지방에 있는 유다 사람도 바벨론의 왕이 유다에 사람을 남겨 둔 것과 사반의 손자 아히감의 아들 그다랴를 그들을 위하여 세웠다 함을 듣고',19953),
('jer-40-12','jer','예레미야',40,12,'그 모든 유다 사람이 쫓겨났던 각처에서 돌아와 유다 땅 미스바에 사는 그다랴에게 이르러 포도주와 여름 과일을 심히 많이 모으니라',19954),
('jer-40-13','jer','예레미야',40,13,'가레아의 아들 요하난과 들에 있던 모든 군 지휘관들이 미스바에 사는 그다랴에게 이르러',19955),
('jer-40-14','jer','예레미야',40,14,'그에게 이르되 암몬 자손의 왕 바알리스가 네 생명을 빼앗으려 하여 느다냐의 아들 이스마엘을 보낸 줄 네가 아느냐 하되 아히감의 아들 그다랴가 믿지 아니한지라',19956),
('jer-40-15','jer','예레미야',40,15,'가레아의 아들 요하난이 미스바에서 그다랴에게 비밀히 말하여 이르되 청하노니 내가 가서 사람이 모르게 느다냐의 아들 이스마엘을 죽이게 하라 어찌하여 그가 네 생명을 빼앗게 하여 네게 모인 모든 유다 사람을 흩어지게 하며 유다의 남은 자로 멸망을 당하게 하랴 하니라',19957),
('jer-40-16','jer','예레미야',40,16,'그러나 아히감의 아들 그다랴가 가레아의 아들 요하난에게 이르되 네가 이 일을 행하지 말 것이니라 네가 이스마엘에 대하여 한 말은 진정이 아니니라 하니라',19958),
('jer-41-1','jer','예레미야',41,1,'일곱째 달에 왕의 종친 엘리사마의 손자요 느다냐의 아들로서 왕의 장관인 이스마엘이 열 사람과 함께 미스바로 가서 아히감의 아들 그다랴에게 이르러 미스바에서 함께 떡을 먹다가',19959),
('jer-41-2','jer','예레미야',41,2,'느다냐의 아들 이스마엘과 그와 함께 있던 열 사람이 일어나서 바벨론의 왕의 그 땅을 위임했던 사반의 손자 아히감의 아들 그다랴를 칼로 쳐죽였고',19960),
('jer-41-3','jer','예레미야',41,3,'이스마엘이 또 미스바에서 그다랴와 함께 있던 모든 유다 사람과 거기에 있는 갈대아 군사를 죽였더라',19961),
('jer-41-4','jer','예레미야',41,4,'그가 그다랴를 죽인 지 이틀이 되었어도 이를 아는 사람이 없었더라',19962),
('jer-41-5','jer','예레미야',41,5,'그 때에 사람 팔십 명이 자기들의 수염을 깎고 옷을 찢고 몸에 상처를 내고 손에 소제물과 유향을 가지고 세겜과 실로와 사마리아로부터 와서 여호와의 성전으로 나아가려 한지라',19963),
('jer-41-6','jer','예레미야',41,6,'느다냐의 아들 이스마엘이 그들을 영접하러 미스바에서 나와 울면서 가다가 그들을 만나 아히감의 아들 그다랴에게로 가자 하더라',19964),
('jer-41-7','jer','예레미야',41,7,'그들이 성읍 중앙에 이를 때에 느다냐의 아들 이스마엘이 자기와 함께 있던 사람들과 더불어 그들을 죽여 구덩이 가운데에 던지니라',19965),
('jer-41-8','jer','예레미야',41,8,'그 중의 열 사람은 이스마엘에게 이르기를 우리가 밀과 보리와 기름과 꿀을 밭에 감추었으니 우리를 죽이지 말라 하니 그가 그치고 그들을 그의 형제와 마찬가지로 죽이지 아니하였더라',19966),
('jer-41-9','jer','예레미야',41,9,'이스마엘이 그다랴에게 속한 사람들을 죽이고 그 시체를 던진 구덩이는 아사 왕이 이스라엘의 바아사 왕을 두려워하여 팠던 것이라 느다냐의 아들 이스마엘이 그가 쳐죽인 사람들의 시체를 거기에 채우고',19967),
('jer-41-10','jer','예레미야',41,10,'미스바에 남아 있는 왕의 딸들과 모든 백성 곧 사령관 느부사라단이 아히감의 아들 그다랴에게 위임하였던 바 미스바에 남아 있는 모든 백성을 이스마엘이 사로잡되 곧 느다냐의 아들 이스마엘이 그들을 사로잡고 암몬 자손에게로 가려고 떠나니라',19968),
('jer-41-11','jer','예레미야',41,11,'가레아의 아들 요하난과 그와 함께 있는 모든 군 지휘관이 느다냐의 아들 이스마엘이 행한 모든 악을 듣고',19969),
('jer-41-12','jer','예레미야',41,12,'모든 사람을 데리고 느다냐의 아들 이스마엘과 싸우러 가다가 기브온 큰 물 가에서 그를 만나매',19970),
('jer-41-13','jer','예레미야',41,13,'이스마엘과 함께 있던 모든 백성이 가레아의 아들 요하난과 그와 함께 있던 모든 군 지휘관을 보고 기뻐한지라',19971),
('jer-41-14','jer','예레미야',41,14,'이에 미스바에서 이스마엘이 사로잡은 그 모든 백성이 돌이켜 가레아의 아들 요하난에게로 돌아가니',19972),
('jer-41-15','jer','예레미야',41,15,'느다냐의 아들 이스마엘이 여덟 사람과 함께 요하난을 피하여 암몬 자손에게로 가니라',19973),
('jer-41-16','jer','예레미야',41,16,'가레아의 아들 요하난과 그와 함께 있던 모든 군 지휘관이 느다냐의 아들 이스마엘이 아히감의 아들 그다랴를 죽이고 미스바에서 잡아간 모든 남은 백성 곧 군사와 여자와 유아와 내시를 기브온에서 빼앗아 가지고 돌아와서',19974),
('jer-41-17','jer','예레미야',41,17,'애굽으로 가려고 떠나 베들레헴 근처에 있는 게롯김함에 머물렀으니',19975),
('jer-41-18','jer','예레미야',41,18,'이는 느다냐의 아들 이스마엘이 바벨론의 왕이 그 땅을 위임한 아히감의 아들 그다랴를 죽였으므로 그들이 갈대아 사람을 두려워함이었더라',19976),
('jer-42-1','jer','예레미야',42,1,'이에 모든 군대의 지휘관과 가레아의 아들 요하난과 호사야의 아들 여사냐와 백성의 낮은 자로부터 높은 자까지 다 나아와',19977),
('jer-42-2','jer','예레미야',42,2,'선지자 예레미야에게 이르되 당신은 우리의 탄원을 듣고 이 남아 있는 모든 자를 위하여 당신의 하나님 여호와께 기도해 주소서 당신이 보는 바와 같이 우리는 많은 사람 중에서 남은 적은 무리이니',19978),
('jer-42-3','jer','예레미야',42,3,'당신의 하나님 여호와께서 우리가 마땅히 갈 길과 할 일을 보이시기를 원하나이다',19979),
('jer-42-4','jer','예레미야',42,4,'선지자 예레미야가 그들에게 이르되 내가 너희 말을 들었은즉 너희 말대로 너희 하나님 여호와께 기도하고 무릇 여호와께서 너희에게 응답하시는 것을 숨김이 없이 너희에게 말하리라',19980),
('jer-42-5','jer','예레미야',42,5,'그들이 예레미야에게 이르되 우리가 당신의 하나님 여호와께서 당신을 보내사 우리에게 이르시는 모든 말씀대로 행하리이다 여호와께서는 우리 가운데에 진실하고 성실한 증인이 되시옵소서',19981),
('jer-42-6','jer','예레미야',42,6,'우리가 당신을 우리 하나님 여호와께 보냄은 그의 목소리가 우리에게 좋든지 좋지 않든지를 막론하고 순종하려 함이라 우리가 우리 하나님 여호와의 목소리를 순종하면 우리에게 복이 있으리이다 하니라',19982),
('jer-42-7','jer','예레미야',42,7,'십일 후에 여호와의 말씀이 예레미야에게 임하니',19983),
('jer-42-8','jer','예레미야',42,8,'그가 가레아의 아들 요하난과 그와 함께 있는 모든 군 지휘관과 백성의 낮은 자로부터 높은 자까지 다 부르고',19984),
('jer-42-9','jer','예레미야',42,9,'그들에게 이르되 너희가 나를 보내어 너희의 간구를 이스라엘의 하나님 여호와께 드리게 하지 아니하였느냐 그가 이렇게 이르니라',19985),
('jer-42-10','jer','예레미야',42,10,'너희가 이 땅에 눌러 앉아 산다면 내가 너희를 세우고 헐지 아니하며 너희를 심고 뽑지 아니하리니 이는 내가 너희에게 내린 재난에 대하여 뜻을 돌이킴이라',19986),
('jer-42-11','jer','예레미야',42,11,'여호와의 말씀이니라 너희는 너희가 두려워하는 바벨론의 왕을 겁내지 말라 내가 너희와 함께 있어 너희를 구원하며 그의 손에서 너희를 건지리니 두려워하지 말라',19987),
('jer-42-12','jer','예레미야',42,12,'내가 너희를 불쌍히 여기리니 그도 너희를 불쌍히 여겨 너희를 너희 본향으로 돌려보내리라 하셨느니라',19988),
('jer-42-13','jer','예레미야',42,13,'그러나 만일 너희가 너희 하나님 여호와의 말씀을 복종하지 아니하고 말하기를 우리는 이 땅에 살지 아니하리라 하며',19989),
('jer-42-14','jer','예레미야',42,14,'또 너희가 말하기를 아니라 우리는 전쟁도 보이지 아니하며 나팔 소리도 들리지 아니하며 양식의 궁핍도 당하지 아니하는 애굽 땅으로 들어가 살리라 하는도다',19990),
('jer-42-15','jer','예레미야',42,15,'그러므로 너희 유다의 남은 자여 이제 여호와의 말씀을 들으라 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희가 만일 애굽에 들어가서 거기에 살기로 고집하면',19991),
('jer-42-16','jer','예레미야',42,16,'너희가 두려워하는 칼이 애굽 땅으로 따라가서 너희에게 미칠 것이요 너희가 두려워하는 기근이 애굽으로 급히 따라가서 너희에게 임하리니 너희가 거기에서 죽을 것이라',19992),
('jer-42-17','jer','예레미야',42,17,'무릇 애굽으로 들어가서 거기에 머물러 살기로 고집하는 모든 사람은 이와 같이 되리니 곧 칼과 기근과 전염병에 죽을 것인즉 내가 그들에게 내리는 재난을 벗어나서 남을 자 없으리라',19993),
('jer-42-18','jer','예레미야',42,18,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 나의 노여움과 분을 예루살렘 주민에게 부은 것 같이 너희가 애굽에 이를 때에 나의 분을 너희에게 부으리니 너희가 가증함과 놀램과 저주와 치욕 거리가 될 것이라 너희가 다시는 이 땅을 보지 못하리라 하시도다',19994),
('jer-42-19','jer','예레미야',42,19,'유다의 남은 자들아 여호와께서 너희를 두고 하신 말씀에 너희는 애굽으로 가지 말라 하셨고 나도 오늘 너희에게 경고한 것을 너희는 분명히 알라',19995),
('jer-42-20','jer','예레미야',42,20,'너희가 나를 너희 하나님 여호와께 보내며 이르기를 우리를 위하여 우리 하나님 여호와께 기도하고 우리 하나님 여호와께서 말씀하신 대로 우리에게 전하라 우리가 그대로 행하리라 하여 너희 마음을 속였느니라',19996),
('jer-42-21','jer','예레미야',42,21,'너희 하나님 여호와께서 나를 보내사 너희에게 명하신 말씀을 내가 오늘 너희에게 전하였어도 너희가 너희 하나님 여호와의 목소리를 도무지 순종하지 아니하였은즉',19997),
('jer-42-22','jer','예레미야',42,22,'너희가 가서 머물려고 하는 곳에서 칼과 기근과 전염병에 죽을 줄 분명히 알지니라',19998),
('jer-43-1','jer','예레미야',43,1,'예레미야가 모든 백성에게 그들의 하나님 여호와의 말씀 곧 그들의 하나님 여호와께서 자기를 보내사 그들에게 이르신 이 모든 말씀을 말하기를 마치니',19999),
('jer-43-2','jer','예레미야',43,2,'호사야의 아들 아사랴와 가레아의 아들 요하난과 모든 오만한 자가 예레미야에게 말하기를 네가 거짓을 말하는도다 우리 하나님 여호와께서 너희는 애굽에 살려고 그리로 가지 말라고 너를 보내어 말하게 하지 아니하셨느니라',20000),
('jer-43-3','jer','예레미야',43,3,'이는 네리야의 아들 바룩이 너를 부추겨서 우리를 대적하여 갈대아 사람의 손에 넘겨 죽이며 바벨론으로 붙잡아가게 하려 함이라',20001),
('jer-43-4','jer','예레미야',43,4,'이에 가레아의 아들 요하난과 모든 군 지휘관과 모든 백성이 유다 땅에 살라 하시는 여호와의 목소리를 순종하지 아니하고',20002),
('jer-43-5','jer','예레미야',43,5,'가레아의 아들 요하난과 모든 군 지휘관이 유다의 남은 자 곧 쫓겨났던 여러 나라 가운데에서 유다 땅에 살려 하여 돌아온 자',20003),
('jer-43-6','jer','예레미야',43,6,'곧 남자와 여자와 유아와 왕의 딸들과 사령관 느부사라단이 사반의 손자 아히감의 아들 그다랴에게 맡겨 둔 모든 사람과 선지자 예레미야와 네리야의 아들 바룩을 거느리고',20004),
('jer-43-7','jer','예레미야',43,7,'애굽 땅에 들어가 다바네스에 이르렀으니 그들이 여호와의 목소리를 순종하지 아니함이러라',20005),
('jer-43-8','jer','예레미야',43,8,'다바네스에서 여호와의 말씀이 예레미야에게 임하여 이르시되',20006),
('jer-43-9','jer','예레미야',43,9,'너는 유다 사람의 눈 앞에서 네 손으로 큰 돌 여러 개를 가져다가 다바네스에 있는 바로의 궁전 대문의 벽돌로 쌓은 축대에 진흙으로 감추라',20007),
('jer-43-10','jer','예레미야',43,10,'그리고 너는 그들에게 말하기를 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 보라 내가 내 종 바벨론의 느부갓네살 왕을 불러오리니 그가 그의 왕좌를 내가 감추게 한 이 돌들 위에 놓고 또 그 화려한 큰 장막을 그 위에 치리라',20008),
('jer-43-11','jer','예레미야',43,11,'그가 와서 애굽 땅을 치고 죽일 자는 죽이고 사로잡을 자는 사로잡고 칼로 칠 자는 칼로 칠 것이라',20009),
('jer-43-12','jer','예레미야',43,12,'내가 애굽 신들의 신당들을 불지르리라 느부갓네살이 그들을 불사르며 그들을 사로잡을 것이요 목자가 그의 몸에 옷을 두름 같이 애굽 땅을 자기 몸에 두르고 평안히 그 곳을 떠날 것이며',20010),
('jer-43-13','jer','예레미야',43,13,'그가 또 애굽 땅 벧세메스의 석상들을 깨뜨리고 애굽 신들의 신당들을 불사르리라 하셨다 할지니라 하니라',20011),
('jer-44-1','jer','예레미야',44,1,'애굽 땅에 사는 모든 유다 사람 곧 믹돌과 다바네스와 놉과 바드로스 지방에 사는 자에 대하여 말씀이 예레미야에게 임하니라 이르시되',20012),
('jer-44-2','jer','예레미야',44,2,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 너희가 예루살렘과 유다 모든 성읍에 내린 나의 모든 재난을 보았느니라 보라 오늘 그것들이 황무지가 되었고 사는 사람이 없나니',20013),
('jer-44-3','jer','예레미야',44,3,'이는 그들이 자기나 너희나 너희 조상들이 알지 못하는 다른 신들에게 나아가 분향하여 섬겨서 나의 노여움을 일으킨 악행으로 말미암음이라',20014),
('jer-44-4','jer','예레미야',44,4,'내가 나의 모든 종 선지자들을 너희에게 보내되 끊임없이 보내어 이르기를 너희는 내가 미워하는 이 가증한 일을 행하지 말라 하였으나',20015),
('jer-44-5','jer','예레미야',44,5,'그들이 듣지 아니하며 귀를 기울이지 아니하고 다른 신들에게 여전히 분향하여 그들의 악에서 돌이키지 아니하였으므로',20016),
('jer-44-6','jer','예레미야',44,6,'나의 분과 나의 노여움을 쏟아서 유다 성읍들과 예루살렘 거리를 불살랐더니 그것들이 오늘과 같이 폐허와 황무지가 되었느니라',20017),
('jer-44-7','jer','예레미야',44,7,'만군의 하나님 이스라엘의 하나님 여호와께서 이와 같이 말씀하셨느니라 너희가 어찌하여 큰 악을 행하여 자기 영혼을 해하며 유다 가운데에서 너희의 남자와 여자와 아이와 젖 먹는 자를 멸절하여 남은 자가 없게 하려느냐',20018),
('jer-44-8','jer','예레미야',44,8,'어찌하여 너희가 너희 손이 만든 것으로 나의 노여움을 일으켜 너희가 가서 머물러 사는 애굽 땅에서 다른 신들에게 분향함으로 끊어 버림을 당하여 세계 여러 나라 가운데에서 저주와 수치 거리가 되고자 하느냐',20019),
('jer-44-9','jer','예레미야',44,9,'너희가 유다 땅과 예루살렘 거리에서 행한 너희 조상들의 악행과 유다 왕들의 악행과 왕비들의 악행과 너희의 악행과 너희 아내들의 악행을 잊었느냐',20020),
('jer-44-10','jer','예레미야',44,10,'그들이 오늘까지 겸손하지 아니하며 두려워하지도 아니하고 내가 너희와 너희 조상들 앞에 세운 나의 율법과 나의 법규를 지켜 행하지 아니하느니라',20021),
('jer-44-11','jer','예레미야',44,11,'그러므로 만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 내가 얼굴을 너희에게로 향하여 환난을 내리고 온 유다를 끊어 버릴 것이며',20022),
('jer-44-12','jer','예레미야',44,12,'내가 또 애굽 땅에 머물러 살기로 고집하고 그리로 들어간 유다의 남은 자들을 처단하리니 그들이 다 멸망하여 애굽 땅에서 엎드러질 것이라 그들이 칼과 기근에 망하되 낮은 자로부터 높은 자까지 칼과 기근에 죽어서 저주와 놀램과 조롱과 수치의 대상이 되리라',20023),
('jer-44-13','jer','예레미야',44,13,'내가 예루살렘을 벌한 것 같이 애굽 땅에 사는 자들을 칼과 기근과 전염병으로 벌하리니',20024),
('jer-44-14','jer','예레미야',44,14,'애굽 땅에 들어가서 거기에 머물러 살려는 유다의 남은 자 중에 피하거나 살아 남아 소원대로 돌아와서 살고자 하여 유다 땅에 돌아올 자가 없을 것이라 도망치는 자들 외에는 돌아올 자가 없으리라 하셨느니라',20025),
('jer-44-15','jer','예레미야',44,15,'그리하여 자기 아내들이 다른 신들에게 분향하는 줄을 아는 모든 남자와 곁에 섰던 모든 여인 곧 애굽 땅 바드로스에 사는 모든 백성의 큰 무리가 예레미야에게 대답하여 이르되',20026),
('jer-44-16','jer','예레미야',44,16,'네가 여호와의 이름으로 우리에게 하는 말을 우리가 듣지 아니하고',20027),
('jer-44-17','jer','예레미야',44,17,'우리 입에서 낸 모든 말을 반드시 실행하여 우리가 본래 하던 것 곧 우리와 우리 선조와 우리 왕들과 우리 고관들이 유다 성읍들과 예루살렘 거리에서 하던 대로 하늘의 여왕에게 분향하고 그 앞에 전제를 드리리라 그 때에는 우리가 먹을 것이 풍부하며 복을 받고 재난을 당하지 아니하였더니',20028),
('jer-44-18','jer','예레미야',44,18,'우리가 하늘의 여왕에게 분향하고 그 앞에 전제 드리던 것을 폐한 후부터는 모든 것이 궁핍하고 칼과 기근에 멸망을 당하였느니라 하며',20029),
('jer-44-19','jer','예레미야',44,19,'여인들은 이르되 우리가 하늘의 여왕에게 분향하고 그 앞에 전제를 드릴 때에 어찌 우리 남편의 허락이 없이 그의 형상과 같은 과자를 만들어 놓고 전제를 드렸느냐 하는지라',20030),
('jer-44-20','jer','예레미야',44,20,'예레미야가 남녀 모든 무리 곧 이 말로 대답하는 모든 백성에게 일러 이르되',20031),
('jer-44-21','jer','예레미야',44,21,'너희가 너희 선조와 너희 왕들과 고관들과 유다 땅 백성이 유다 성읍들과 예루살렘 거리에서 분향한 일을 여호와께서 기억하셨고 그의 마음에 떠오른 것이 아닌가',20032),
('jer-44-22','jer','예레미야',44,22,'여호와께서 너희 악행과 가증한 행위를 더 참을 수 없으셨으므로 너희 땅이 오늘과 같이 황폐하며 놀램과 저줏거리가 되어 주민이 없게 되었나니',20033),
('jer-44-23','jer','예레미야',44,23,'너희가 분향하여 여호와께 범죄하였으며 여호와의 목소리를 순종하지 아니하고 여호와의 율법과 법규와 여러 증거대로 행하지 아니하였으므로 이 재난이 오늘과 같이 너희에게 일어났느니라',20034),
('jer-44-24','jer','예레미야',44,24,'예레미야가 다시 모든 백성과 모든 여인에게 말하되 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라',20035),
('jer-44-25','jer','예레미야',44,25,'만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시되 너희와 너희 아내들이 입으로 말하고 손으로 이루려 하여 이르기를 우리가 서원한 대로 반드시 이행하여 하늘의 여왕에게 분향하고 전제를 드리리라 하였은즉 너희 서원을 성취하며 너희 서원을 이행하라 하시느니라',20036),
('jer-44-26','jer','예레미야',44,26,'그러므로 애굽 땅에서 사는 모든 유다 사람이여 여호와의 말씀을 들으라 여호와께서 말씀하시되 보라 내가 나의 큰 이름으로 맹세하였은즉 애굽 온 땅에 사는 유다 사람들의 입에서 다시는 내 이름을 부르며 주 여호와의 살아 계심을 두고 맹세하노라 하는 자가 없으리라',20037),
('jer-44-27','jer','예레미야',44,27,'보라 내가 깨어 있어 그들에게 재난을 내리고 복을 내리지 아니하리니 애굽 땅에 있는 유다 모든 사람이 칼과 기근에 망하여 멸절되리라',20038),
('jer-44-28','jer','예레미야',44,28,'그런즉 칼을 피한 소수의 사람이 애굽 땅에서 나와 유다 땅으로 돌아오리니 애굽 땅에 들어가서 거기에 머물러 사는 유다의 모든 남은 자가 내 말과 그들의 말 가운데서 누구의 말이 진리인지 알리라',20039),
('jer-44-29','jer','예레미야',44,29,'여호와의 말씀이니라 내가 이 곳에서 너희를 벌할 표징이 이것이라 내가 너희에게 재난을 내리리라 한 말이 반드시 이루어질 것을 그것으로 알게 하리라',20040),
('jer-44-30','jer','예레미야',44,30,'보라 내가 유다의 시드기야 왕을 그의 원수 곧 그의 생명을 찾는 바벨론의 느부갓네살 왕의 손에 넘긴 것 같이 애굽의 바로 호브라 왕을 그의 원수들 곧 그의 생명을 찾는 자들의 손에 넘겨 주리라 여호와께서 이와 같이 말씀하셨느니라',20041),
('jer-45-1','jer','예레미야',45,1,'유다의 요시야 왕의 아들 여호야김 넷째 해에 네리야의 아들 바룩이 예레미야가 불러 주는 대로 이 모든 말을 책에 기록하니라 그 때에 선지자 예레미야가 그에게 말하여 이르되',20042),
