('jer-49-1','jer','예레미야',49,1,'암몬 자손에 대한 말씀이라 여호와께서 이와 같이 말씀하시되 이스라엘이 자식이 없느냐 상속자가 없느냐 말감이 갓을 점령하며 그 백성이 그 성읍들에 사는 것은 어찌 됨이냐',20129),
