('jer-49-31','jer','예레미야',49,31,'여호와의 말씀이니라 너는 일어나 고요하고도 평안히 사는 백성 곧 성문이나 문빗장이 없이 홀로 사는 국민을 치라',20159),
('jer-49-32','jer','예레미야',49,32,'그들의 낙타들은 노략물이 되겠고 그들의 많은 가축은 탈취를 당할 것이라 내가 그 살쩍을 깎는 자들을 사면에 흩고 그 재난을 여러 곳에서 오게 하리라 여호와의 말씀이니라',20160),
('jer-49-33','jer','예레미야',49,33,'하솔은 큰 뱀의 거처가 되어 영원히 황폐하리니 거기 사는 사람이나 그 가운데에 머물러 사는 사람이 아무도 없게 되리라 하시니라',20161),
('jer-49-34','jer','예레미야',49,34,'유다 왕 시드기야가 즉위한 지 오래지 아니하여서 엘람에 대한 여호와의 말씀이 선지자 예레미야에게 임하여 이르시되',20162),
('jer-49-35','jer','예레미야',49,35,'만군의 여호와가 이같이 말하노라 보라 내가 엘람의 힘의 으뜸가는 활을 꺾을 것이요',20163),
('jer-49-36','jer','예레미야',49,36,'하늘의 사방에서부터 사방 바람을 엘람에 오게 하여 그들을 사방으로 흩으리니 엘람에서 쫓겨난 자가 가지 않는 나라가 없으리라',20164),
('jer-49-37','jer','예레미야',49,37,'여호와의 말씀이니라 내가 엘람으로 그의 원수의 앞, 그의 생명을 노리는 자의 앞에서 놀라게 할 것이며 내가 재앙 곧 나의 진노를 그들 위에 내릴 것이며 내가 또 그 뒤로 칼을 보내어 그들을 멸망시키리라',20165),
('jer-49-38','jer','예레미야',49,38,'내가 나의 보좌를 엘람에 주고 왕과 고관들을 그 곳에서 멸하리라 여호와의 말씀이니라',20166),
('jer-49-39','jer','예레미야',49,39,'그러나 말일에 이르러 내가 엘람의 포로를 돌아가게 하리라 여호와의 말씀이니라',20167),
('jer-50-1','jer','예레미야',50,1,'여호와께서 선지자 예레미야에게 바벨론과 갈대아 사람의 땅에 대하여 하신 말씀이라',20168),
('jer-50-2','jer','예레미야',50,2,'너희는 나라들 가운데에 전파하라 공포하라 깃발을 세우라 숨김이 없이 공포하여 이르라 바벨론이 함락되고 벨이 수치를 당하며 므로닥이 부스러지며 그 신상들은 수치를 당하며 우상들은 부스러진다 하라',20169),
('jer-50-3','jer','예레미야',50,3,'이는 한 나라가 북쪽에서 나와서 그를 쳐서 그 땅으로 황폐하게 하여 그 가운데에 사는 자가 없게 할 것임이라 사람이나 짐승이 다 도망할 것임이니라',20170),
('jer-50-4','jer','예레미야',50,4,'여호와의 말씀이니라 그 날 그 때에 이스라엘 자손이 돌아오며 유다 자손도 함께 돌아오되 그들이 울면서 그 길을 가며 그의 하나님 여호와께 구할 것이며',20171),
('jer-50-5','jer','예레미야',50,5,'그들이 그 얼굴을 시온으로 향하여 그 길을 물으며 말하기를 너희는 오라 잊을 수 없는 영원한 언약으로 여호와와 연합하라 하리라',20172),
('jer-50-6','jer','예레미야',50,6,'내 백성은 잃어 버린 양 떼로다 그 목자들이 그들을 곁길로 가게 하여 산으로 돌이키게 하였으므로 그들이 산에서 언덕으로 돌아다니며 쉴 곳을 잊었도다',20173),
('jer-50-7','jer','예레미야',50,7,'그들을 만나는 자들은 그들을 삼키며 그의 대적은 말하기를 그들이 여호와 곧 의로운 처소시며 그의 조상들의 소망이신 여호와께 범죄하였음인즉 우리는 무죄하다 하였느니라',20174),
('jer-50-8','jer','예레미야',50,8,'너희는 바벨론 가운데에서 도망하라 갈대아 사람의 땅에서 나오라 양 떼에 앞서가는 숫염소 같이 하라',20175),
('jer-50-9','jer','예레미야',50,9,'보라 내가 큰 민족의 무리를 북쪽에서 올라오게 하여 바벨론을 대항하게 하리니 그들이 대열을 벌이고 쳐서 정복할 것이라 그들의 화살은 노련한 용사의 화살 같아서 허공을 치지 아니하리라',20176),
('jer-50-10','jer','예레미야',50,10,'갈대아가 약탈을 당할 것이라 그를 약탈하는 자마다 만족하리라 여호와의 말씀이니라',20177),
('jer-50-11','jer','예레미야',50,11,'나의 소유를 노략하는 자여 너희가 즐거워하며 기뻐하고 타작하는 송아지 같이 발굽을 구르며 군마 같이 우는도다',20178),
