('jer-50-33','jer','예레미야',50,33,'만군의 여호와께서 이와 같이 말씀하시니라 이스라엘 자손과 유다 자손이 함께 학대를 받는도다 그들을 사로잡은 자는 다 그들을 붙들고 놓아 주지 아니하리라',20200),
