('jer-50-46','jer','예레미야',50,46,'바벨론이 약탈 당하는 소리에 땅이 진동하며 그 부르짖음이 나라들 가운데에 들리리라 하시도다',20213),
('jer-51-1','jer','예레미야',51,1,'여호와께서 이와 같이 말씀하시되 보라 내가 멸망시키는 자의 심령을 부추겨 바벨론을 치고 또 나를 대적하는 자 중에 있는 자를 치되',20214),
