('jer-51-63','jer','예레미야',51,63,'너는 이 책 읽기를 다한 후에 책에 돌을 매어 유브라데 강 속에 던지며',20276),
('jer-51-64','jer','예레미야',51,64,'말하기를 바벨론이 나의 재난 때문에 이같이 몰락하여 다시 일어서지 못하리니 그들이 피폐하리라 하라 하니라 예레미야의 말이 이에 끝나니라',20277),
('jer-52-1','jer','예레미야',52,1,'시드기야가 왕위에 오를 때에 나이가 이십일 세라 예루살렘에서 십일 년 동안 다스리니라 그의 어머니의 이름은 하무달이라 립나인 예레미야의 딸이더라',20278),
('jer-52-2','jer','예레미야',52,2,'그가 여호야김의 모든 행위를 본받아 여호와 보시기에 악을 행한지라',20279),
('jer-52-3','jer','예레미야',52,3,'여호와께서 예루살렘과 유다에게 진노하심이 그들을 자기 앞에서 쫓아내시기까지 이르렀더라. 시드기야가 바벨론 왕을 배반하니라',20280),
('jer-52-4','jer','예레미야',52,4,'시드기야 제구년 열째 달 열째 날에 바벨론 왕 느부갓네살이 그의 모든 군대를 거느리고 예루살렘을 치러 올라와서 그 성에 대하여 진을 치고 주위에 토성을 쌓으매',20281),
('jer-52-5','jer','예레미야',52,5,'그 성이 시드기야 왕 제십일년까지 포위되었더라',20282),
('jer-52-6','jer','예레미야',52,6,'그 해 넷째 달 구일에 성중에 기근이 심하여 그 땅 백성의 양식이 떨어졌더라',20283),
('jer-52-7','jer','예레미야',52,7,'그 성벽이 파괴되매 모든 군사가 밤중에 그 성에서 나가 두 성벽 사이 왕의 동산 곁문 길로 도망하여 갈대아인들이 그 성읍을 에워쌌으므로 그들이 아라바 길로 가더니',20284),
('jer-52-8','jer','예레미야',52,8,'갈대아 군대가 그 왕을 뒤쫓아 가서 여리고 평지에서 시드기야를 따라 잡으매 왕의 모든 군대가 그를 떠나 흩어진지라',20285),
('jer-52-9','jer','예레미야',52,9,'그들이 왕을 사로잡아 그를 하맛 땅 리블라에 있는 바벨론 왕에게로 끌고 가매 그가 시드기야를 심문하니라',20286),
('jer-52-10','jer','예레미야',52,10,'바벨론 왕이 시드기야의 아들들을 그의 눈 앞에서 죽이고 또 리블라에서 유다의 모든 고관을 죽이며',20287),
('jer-52-11','jer','예레미야',52,11,'시드기야의 두 눈을 빼고 놋사슬로 그를 결박하여 바벨론 왕이 그를 바벨론으로 끌고 가서 그가 죽는 날까지 옥에 가두었더라',20288),
('jer-52-12','jer','예레미야',52,12,'바벨론의 느부갓네살 왕의 열아홉째 해 다섯째 달 열째 날에 바벨론 왕의 어전 사령관 느부사라단이 예루살렘에 이르러',20289),
('jer-52-13','jer','예레미야',52,13,'여호와의 성전과 왕궁을 불사르고 예루살렘의 모든 집과 고관들의 집까지 불살랐으며',20290),
('jer-52-14','jer','예레미야',52,14,'사령관을 따르는 갈대아 사람의 모든 군대가 예루살렘 사면 성벽을 헐었더라',20291),
('jer-52-15','jer','예레미야',52,15,'사령관 느부사라단이 백성 중 가난한 자와 성중에 남아 있는 백성과 바벨론 왕에게 항복한 자와 무리의 남은 자를 사로잡아 갔고',20292),
('jer-52-16','jer','예레미야',52,16,'가난한 백성은 남겨 두어 포도원을 관리하는 자와 농부가 되게 하였더라',20293),
('jer-52-17','jer','예레미야',52,17,'갈대아 사람은 또 여호와의 성전의 두 놋기둥과 받침들과 여호와의 성전의 놋대야를 깨뜨려 그 놋을 바벨론으로 가져갔고',20294),
('jer-52-18','jer','예레미야',52,18,'가마들과 부삽들과 부집게들과 주발들과 숟가락들과 섬길 때에 쓰는 모든 놋그릇을 다 가져갔고',20295),
('jer-52-19','jer','예레미야',52,19,'사령관은 잔들과 화로들과 주발들과 솥들과 촛대들과 숟가락들과 바리들 곧 금으로 만든 물건의 금과 은으로 만든 물건의 은을 가져갔더라',20296),
('jer-52-20','jer','예레미야',52,20,'솔로몬 왕이 여호와의 성전을 위하여 만든 두 기둥과 한 바다와 그 받침 아래에 있는 열두 놋 소 곧 이 모든 기구의 놋 무게는 헤아릴 수 없었더라',20297),
('jer-52-21','jer','예레미야',52,21,'그 기둥은 한 기둥의 높이가 십팔 규빗이요 그 둘레는 십이 규빗이며 그 속이 비었고 그 두께는 네 손가락 두께이며',20298),
('jer-52-22','jer','예레미야',52,22,'기둥 위에 놋머리가 있어 그 높이가 다섯 규빗이요 머리 사면으로 돌아가며 꾸민 망사와 석류가 다 놋이며 또 다른 기둥에도 이런 모든 것과 석류가 있었더라',20299),
('jer-52-23','jer','예레미야',52,23,'그 사면에 있는 석류는 아흔여섯 개요 그 기둥에 둘린 그물 위에 있는 석류는 도합이 백 개이었더라',20300),
('jer-52-24','jer','예레미야',52,24,'사령관이 대제사장 스라야와 부제사장 스바냐와 성전 문지기 세 사람을 사로잡고',20301),
('jer-52-25','jer','예레미야',52,25,'또 성 안에서 사람을 사로잡았으니 곧 군사를 거느린 지휘관 한 사람과 또 성중에서 만난 왕의 내시 칠 명과 군인을 감독하는 군 지휘관의 서기관 하나와 성 안에서 만난 평민 육십 명이라',20302),
('jer-52-26','jer','예레미야',52,26,'사령관 느부사라단은 그들을 사로잡아 립나에 있는 바벨론의 왕에게 나아가매',20303),
('jer-52-27','jer','예레미야',52,27,'바벨론의 왕이 하맛 땅 립나에서 다 쳐 죽였더라 이와 같이 유다가 사로잡혀 본국에서 떠났더라',20304),
('jer-52-28','jer','예레미야',52,28,'느부갓네살이 사로잡아 간 백성은 이러하니라 제칠년에 유다인이 삼천이십삼 명이요',20305),
('jer-52-29','jer','예레미야',52,29,'느부갓네살의 열여덟째 해에 예루살렘에서 사로잡아 간 자가 팔백삼십이 명이요',20306),
('jer-52-30','jer','예레미야',52,30,'느부갓네살의 제이십삼년에 사령관 느부사라단이 사로잡아 간 유다 사람이 칠백사십오 명이니 그 총수가 사천육백 명이더라',20307),
('jer-52-31','jer','예레미야',52,31,'유다 왕 여호야긴이 사로잡혀 간 지 삼십칠 년 곧 바벨론의 에윌므로닥 왕의 즉위 원년 열두째 달 스물다섯째 날 그가 유다의 여호야긴 왕의 머리를 들어 주었고 감옥에서 풀어 주었더라',20308),
('jer-52-32','jer','예레미야',52,32,'그에게 친절하게 말하고 그의 자리를 그와 함께 바벨론에 있는 왕들의 자리보다 높이고',20309),
('jer-52-33','jer','예레미야',52,33,'그 죄수의 의복을 갈아 입혔고 그의 평생 동안 항상 왕의 앞에서 먹게 하였으며',20310),
('jer-52-34','jer','예레미야',52,34,'그가 날마다 쓸 것을 바벨론의 왕에게서 받는 정량이 있었고 죽는 날까지 곧 종신토록 받았더라',20311),
('lam-1-1','lam','예레미야애가',1,1,'슬프다 이 성이여 전에는 사람들이 많더니 이제는 어찌 그리 적막하게 앉았는고 전에는 열국 중에 크던 자가 이제는 과부 같이 되었고 전에는 열방 중에 공주였던 자가 이제는 강제 노동을 하는 자가 되었도다',20312),
('lam-1-2','lam','예레미야애가',1,2,'밤에는 슬피 우니 눈물이 뺨에 흐름이여 사랑하던 자들 중에 그에게 위로하는 자가 없고 친구들도 다 배반하여 원수들이 되었도다',20313),
('lam-1-3','lam','예레미야애가',1,3,'유다는 환난과 많은 고난 가운데에 사로잡혀 갔도다 그가 열국 가운데에 거주하면서 쉴 곳을 얻지 못함이여 그를 핍박하는 모든 자들이 궁지에서 그를 뒤따라 잡았도다',20314),
('lam-1-4','lam','예레미야애가',1,4,'시온의 도로들이 슬퍼함이여 절기를 지키려 나아가는 사람이 없음이로다 모든 성문들이 적막하며 제사장들이 탄식하며 처녀들이 근심하며 시온도 곤고를 받았도다',20315),
('lam-1-5','lam','예레미야애가',1,5,'그의 대적들이 머리가 되고 그의 원수들이 형통함은 그의 죄가 많으므로 여호와께서 그를 곤고하게 하셨음이라 어린 자녀들이 대적에게 사로잡혔도다',20316),
('lam-1-6','lam','예레미야애가',1,6,'딸 시온의 모든 영광이 떠나감이여 그의 모든 지도자들은 꼴을 찾지 못한 사슴들처럼 뒤쫓는 자 앞에서 힘없이 달아났도다',20317),
('lam-1-7','lam','예레미야애가',1,7,'예루살렘이 환난과 유리하는 고통을 당하는 날에 옛날의 모든 즐거움을 기억하였음이여 그의 백성이 대적의 손에 넘어졌으나 그를 돕는 자가 없었고 대적들은 그의 멸망을 비웃는도다',20318),
('lam-1-8','lam','예레미야애가',1,8,'예루살렘이 크게 범죄함으로 조소거리가 되었으니 전에 그에게 영광을 돌리던 모든 사람이 그의 벗었음을 보고 업신여김이여 그는 탄식하며 물러가는도다',20319),
('lam-1-9','lam','예레미야애가',1,9,'그의 더러운 것이 그의 옷깃에 묻어 있으나 그의 나중을 생각하지 아니함이여 그러므로 놀랍도록 낮아져도 그를 위로할 자가 없도다 여호와여 원수가 스스로 큰 체하오니 나의 환난을 감찰하소서',20320),
('lam-1-10','lam','예레미야애가',1,10,'대적이 손을 펴서 그의 모든 보물들을 빼앗았나이다 주께서 이미 이방인들을 막아 주의 성회에 들어오지 못하도록 명령하신 그 성소에 그들이 들어간 것을 예루살렘이 보았나이다',20321),
('lam-1-11','lam','예레미야애가',1,11,'그 모든 백성이 생명을 이으려고 보물로 먹을 것들을 바꾸었더니 지금도 탄식하며 양식을 구하나이다 나는 비천하오니 여호와여 나를 돌보시옵소서',20322),
('lam-1-12','lam','예레미야애가',1,12,'지나가는 모든 사람들이여 너희에게는 관계가 없는가 나의 고통과 같은 고통이 있는가 볼지어다 여호와께서 그의 진노하신 날에 나를 괴롭게 하신 것이로다',20323),
('lam-1-13','lam','예레미야애가',1,13,'높은 곳에서 나의 골수에 불을 보내어 이기게 하시고 내 발 앞에 그물을 치사 나로 물러가게 하셨음이여 종일토록 나를 피곤하게 하여 황폐하게 하셨도다',20324),
('lam-1-14','lam','예레미야애가',1,14,'내 죄악의 멍에를 그의 손으로 묶고 얽어 내 목에 올리사 내 힘을 피곤하게 하셨음이여 내가 감당할 수 없는 자의 손에 주께서 나를 넘기셨도다',20325),
('lam-1-15','lam','예레미야애가',1,15,'주께서 내 영토 안 나의 모든 용사들을 없는 것 같이 여기시고 성회를 모아 내 청년들을 부수심이여 처녀 딸 유다를 내 주께서 술틀에 밟으셨도다',20326),
('lam-1-16','lam','예레미야애가',1,16,'이로 말미암아 내가 우니 내 눈에 눈물이 물 같이 흘러내림이여 나를 위로하여 내 생명을 회복시켜 줄 자가 멀리 떠났음이로다 원수들이 이기매 내 자녀들이 외롭도다',20327),
('lam-1-17','lam','예레미야애가',1,17,'시온이 두 손을 폈으나 그를 위로할 자가 없도다 여호와께서 야곱의 사방에 있는 자들에게 명령하여 야곱의 대적들이 되게 하셨으니 예루살렘은 그들 가운데에 있는 불결한 자가 되었도다',20328),
('lam-1-18','lam','예레미야애가',1,18,'여호와는 의로우시도다 그러나 내가 그의 명령을 거역하였도다 너희 모든 백성들아 내 말을 듣고 내 고통을 볼지어다 나의 처녀들과 나의 청년들이 사로잡혀 갔도다',20329),
('lam-1-19','lam','예레미야애가',1,19,'내가 내 사랑하는 자들을 불렀으나 그들은 나를 속였으며 나의 제사장들과 장로들은 그들의 목숨을 회복시킬 그들의 양식을 구하다가 성 가운데에서 기절하였도다',20330),
('lam-1-20','lam','예레미야애가',1,20,'여호와여 보시옵소서 내가 환난을 당하여 나의 애를 다 태우고 나의 마음이 상하오니 나의 반역이 심히 큼이니이다 밖에서는 칼이 내 아들을 빼앗아 가고 집 안에서는 죽음 같은 것이 있나이다',20331),
('lam-1-21','lam','예레미야애가',1,21,'그들이 내가 탄식하는 것을 들었으나 나를 위로하는 자가 없으며 나의 모든 원수들은 내가 재난 당하는 것을 듣고 주께서 이렇게 행하신 것을 기뻐하나이다 그러나 주께서 그 선포하신 날을 이르게 하셔서 그들이 나와 같이 되게 하소서',20332),
('lam-1-22','lam','예레미야애가',1,22,'그들의 모든 악을 주 앞에 가지고 오게 하시고 나의 모든 죄악들로 말미암아 내게 행하신 것 같이 그들에게 행하옵소서 나의 탄식이 많고 나의 마음이 병들었나이다',20333),
('lam-2-1','lam','예레미야애가',2,1,'슬프다 주께서 어찌 그리 진노하사 딸 시온을 구름으로 덮으셨는가 이스라엘의 아름다움을 하늘에서 땅에 던지셨음이여 그의 진노의 날에 그의 발판을 기억하지 아니하셨도다',20334),
('lam-2-2','lam','예레미야애가',2,2,'주께서 야곱의 모든 거처들을 삼키시고 긍휼히 여기지 아니하셨음이여 노하사 딸 유다의 견고한 성채들을 허물어 땅에 엎으시고 나라와 그 지도자들을 욕되게 하셨도다',20335),
('lam-2-3','lam','예레미야애가',2,3,'맹렬한 진노로 이스라엘의 모든 뿔을 자르셨음이여 원수 앞에서 그의 오른손을 뒤로 거두어 들이시고 맹렬한 불이 사방으로 불사름 같이 야곱을 불사르셨도다',20336),
('lam-2-4','lam','예레미야애가',2,4,'원수 같이 그의 활을 당기고 대적처럼 그의 오른손을 들고 서서 눈에 드는 아름다운 모든 사람을 죽이셨음이여 딸 시온의 장막에 그의 노를 불처럼 쏟으셨도다',20337),
('lam-2-5','lam','예레미야애가',2,5,'주께서 원수 같이 되어 이스라엘을 삼키셨음이여 그 모든 궁궐들을 삼키셨고 견고한 성들을 무너뜨리사 딸 유다에 근심과 애통을 더하셨도다',20338),
('lam-2-6','lam','예레미야애가',2,6,'주께서 그의 초막을 동산처럼 헐어 버리시며 그의 절기를 폐하셨도다 여호와께서 시온에서 절기와 안식일을 잊어버리게 하시며 그가 진노하사 왕과 제사장을 멸시하셨도다',20339),
('lam-2-7','lam','예레미야애가',2,7,'여호와께서 또 자기 제단을 버리시며 자기 성소를 미워하시며 궁전의 성벽들을 원수의 손에 넘기셨으매 그들이 여호와의 전에서 떠들기를 절기의 날과 같이 하였도다',20340),
('lam-2-8','lam','예레미야애가',2,8,'여호와께서 딸 시온의 성벽을 헐기로 결심하시고 줄을 띠고 무너뜨리는 일에서 손을 거두지 아니하사 성벽과 성곽으로 통곡하게 하셨으매 그들이 함께 쇠하였도다',20341),
('lam-2-9','lam','예레미야애가',2,9,'성문이 땅에 묻히며 빗장이 부서져 파괴되고 왕과 지도자들이 율법 없는 이방인들 가운데에 있으며 그 성의 선지자들은 여호와의 묵시를 받지 못하는도다',20342),
('lam-2-10','lam','예레미야애가',2,10,'딸 시온의 장로들이 땅에 앉아 잠잠하고 티끌을 머리에 덮어쓰고 굵은 베를 허리에 둘렀음이여 예루살렘 처녀들은 머리를 땅에 숙였도다',20343),
('lam-2-11','lam','예레미야애가',2,11,'내 눈이 눈물에 상하며 내 창자가 끊어지며 내 간이 땅에 쏟아졌으니 이는 딸 내 백성이 패망하여 어린 자녀와 젖 먹는 아이들이 성읍 길거리에 기절함이로다',20344),
('lam-2-12','lam','예레미야애가',2,12,'그들이 성읍 길거리에서 상한 자처럼 기절하여 그의 어머니들의 품에서 혼이 떠날 때에 어머니들에게 이르기를 곡식과 포도주가 어디 있느냐 하도다',20345),
('lam-2-13','lam','예레미야애가',2,13,'딸 예루살렘이여 내가 무엇으로 네게 증거하며 무엇으로 네게 비유할까 처녀 딸 시온이여 내가 무엇으로 네게 비교하여 너를 위로할까 너의 파괴됨이 바다 같이 크니 누가 너를 고쳐 줄소냐',20346),
('lam-2-14','lam','예레미야애가',2,14,'네 선지자들이 네게 대하여 헛되고 어리석은 묵시를 보았으므로 네 죄악을 드러내어서 네가 사로잡힌 것을 돌이키지 못하였도다 그들이 거짓 경고와 미혹하게 할 것만 보았도다',20347),
('lam-2-15','lam','예레미야애가',2,15,'모든 지나가는 자들이 다 너를 향하여 박수치며 딸 예루살렘을 향하여 비웃고 머리를 흔들며 말하기를 온전한 영광이라, 모든 세상 사람들의 기쁨이라 일컫던 성이 이 성이냐 하며',20348),
('lam-2-16','lam','예레미야애가',2,16,'네 모든 원수들은 너를 향하여 그들의 입을 벌리며 비웃고 이를 갈며 말하기를 우리가 그를 삼켰도다 우리가 바라던 날이 과연 이 날이라 우리가 얻기도 하고 보기도 하였다 하도다',20349),
('lam-2-17','lam','예레미야애가',2,17,'여호와께서 이미 정하신 일을 행하시고 옛날에 명령하신 말씀을 다 이루셨음이여 긍휼히 여기지 아니하시고 무너뜨리사 원수가 너로 말미암아 즐거워하게 하며 네 대적자들의 뿔로 높이 들리게 하셨도다',20350),
('lam-2-18','lam','예레미야애가',2,18,'그들의 마음이 주를 향하여 부르짖기를 딸 시온의 성벽아 너는 밤낮으로 눈물을 강처럼 흘릴지어다 스스로 쉬지 말고 네 눈동자를 쉬게 하지 말지어다',20351),
('lam-2-19','lam','예레미야애가',2,19,'초저녁에 일어나 부르짖을지어다 네 마음을 주의 얼굴 앞에 물 쏟듯 할지어다 각 길 어귀에서 주려 기진한 네 어린 자녀들의 생명을 위하여 주를 향하여 손을 들지어다 하였도다',20352),
('lam-2-20','lam','예레미야애가',2,20,'여호와여 보시옵소서 주께서 누구에게 이같이 행하셨는지요 여인들이 어찌 자기 열매 곧 그들이 낳은 아이들을 먹으오며 제사장들과 선지자들이 어찌 주의 성소에서 죽임을 당하오리이까',20353),
('lam-2-21','lam','예레미야애가',2,21,'늙은이와 젊은이가 다 길바닥에 엎드러졌사오며 내 처녀들과 내 청년들이 칼에 쓰러졌나이다 주께서 주의 진노의 날에 죽이시되 긍휼히 여기지 아니하시고 도륙하셨나이다',20354),
('lam-2-22','lam','예레미야애가',2,22,'주께서 내 두려운 일들을 사방에서 부르시기를 절기 때 무리를 부름 같이 하셨나이다 여호와께서 진노하시는 날에는 피하거나 남은 자가 없나이다 내가 낳아 기르는 아이들을 내 원수가 다 멸하였나이다',20355),
('lam-3-1','lam','예레미야애가',3,1,'여호와의 분노의 매로 말미암아 고난 당한 자는 나로다',20356),
('lam-3-2','lam','예레미야애가',3,2,'나를 이끌어 어둠 안에서 걸어가게 하시고 빛 안에서 걸어가지 못하게 하셨으며',20357),
