('ezk-1-13','ezk','에스겔',1,13,'또 생물들의 모양은 타는 숯불과 횃불 모양 같은데 그 불이 그 생물 사이에서 오르락내리락 하며 그 불은 광채가 있고 그 가운데에서는 번개가 나며',20478),
('ezk-1-14','ezk','에스겔',1,14,'그 생물들은 번개 모양 같이 왕래하더라',20479),
('ezk-1-15','ezk','에스겔',1,15,'내가 그 생물들을 보니 그 생물들 곁에 있는 땅 위에는 바퀴가 있는데 그 네 얼굴을 따라 하나씩 있고',20480),
('ezk-1-16','ezk','에스겔',1,16,'그 바퀴의 모양과 그 구조는 황옥 같이 보이는데 그 넷은 똑같은 모양을 가지고 있으며 그들의 모양과 구조는 바퀴 안에 바퀴가 있는 것 같으며',20481),
('ezk-1-17','ezk','에스겔',1,17,'그들이 갈 때에는 사방으로 향한 대로 돌이키지 아니하고 가며',20482),
('ezk-1-18','ezk','에스겔',1,18,'그 둘레는 높고 무서우며 그 네 둘레로 돌아가면서 눈이 가득하며',20483),
('ezk-1-19','ezk','에스겔',1,19,'그 생물들이 갈 때에 바퀴들도 그 곁에서 가고 그 생물들이 땅에서 들릴 때에 바퀴들도 들려서',20484),
('ezk-1-20','ezk','에스겔',1,20,'영이 어떤 쪽으로 가면 생물들도 영이 가려 하는 곳으로 가고 바퀴들도 그 곁에서 들리니 이는 생물의 영이 그 바퀴들 가운데에 있음이니라',20485),
('ezk-1-21','ezk','에스겔',1,21,'그들이 가면 이들도 가고 그들이 서면 이들도 서고 그들이 땅에서 들릴 때에는 이들도 그 곁에서 들리니 이는 생물의 영이 그 바퀴들 가운데에 있음이더라',20486),
('ezk-1-22','ezk','에스겔',1,22,'그 생물의 머리 위에는 수정 같은 궁창의 형상이 있어 보기에 두려운데 그들의 머리 위에 펼쳐져 있고',20487),
('ezk-1-23','ezk','에스겔',1,23,'그 궁창 밑에 생물들의 날개가 서로 향하여 펴 있는데 이 생물은 두 날개로 몸을 가렸고 저 생물도 두 날개로 몸을 가렸더라',20488),
('ezk-1-24','ezk','에스겔',1,24,'생물들이 갈 때에 내가 그 날개 소리를 들으니 많은 물 소리와도 같으며 전능자의 음성과도 같으며 떠드는 소리 곧 군대의 소리와도 같더니 그 생물이 설 때에 그 날개를 내렸더라',20489),
('ezk-1-25','ezk','에스겔',1,25,'그 머리 위에 있는 궁창 위에서부터 음성이 나더라 그 생물이 설 때에 그 날개를 내렸더라',20490),
('ezk-1-26','ezk','에스겔',1,26,'그 머리 위에 있는 궁창 위에 보좌의 형상이 있는데 그 모양이 남보석 같고 그 보좌의 형상 위에 한 형상이 있어 사람의 모양 같더라',20491),
('ezk-1-27','ezk','에스겔',1,27,'내가 보니 그 허리 위의 모양은 단 쇠 같아서 그 속과 주위가 불 같고 내가 보니 그 허리 아래의 모양도 불 같아서 사방으로 광채가 나며',20492),
('ezk-1-28','ezk','에스겔',1,28,'그 사방 광채의 모양은 비 오는 날 구름에 있는 무지개 같으니 이는 여호와의 영광의 형상의 모양이라 내가 보고 엎드려 말씀하시는 이의 음성을 들으니라',20493),
('ezk-2-1','ezk','에스겔',2,1,'그가 내게 이르시되 인자야 네 발로 일어서라 내가 네게 말하리라 하시며',20494),
('ezk-2-2','ezk','에스겔',2,2,'그가 내게 말씀하실 때에 그 영이 내게 임하사 나를 일으켜 내 발로 세우시기로 내가 그 말씀하시는 자의 소리를 들으니',20495),
('ezk-2-3','ezk','에스겔',2,3,'내게 이르시되 인자야 내가 너를 이스라엘 자손 곧 패역한 백성, 나를 배반하는 자에게 보내노라 그들과 그 조상들이 내게 범죄하여 오늘까지 이르렀나니',20496),
('ezk-2-4','ezk','에스겔',2,4,'이 자손은 얼굴이 뻔뻔하고 마음이 굳은 자니라 내가 너를 그들에게 보내노니 너는 그들에게 이르기를 주 여호와의 말씀이 이러하시다 하라',20497),
('ezk-2-5','ezk','에스겔',2,5,'그들은 패역한 족속이라 그들이 듣든지 아니 듣든지 그들 가운데에 선지자가 있음을 알지니라',20498),
('ezk-2-6','ezk','에스겔',2,6,'인자야 너는 비록 가시와 찔레와 함께 있으며 전갈 가운데에 거주할지라도 그들을 두려워하지 말고 그들의 말을 두려워하지 말지어다 그들은 패역한 족속이라도 그 말을 두려워하지 말며 그 얼굴을 무서워하지 말지어다',20499),
('ezk-2-7','ezk','에스겔',2,7,'그들은 심히 패역한 자라 그들이 듣든지 아니 듣든지 너는 내 말로 고할지어다',20500),
('ezk-2-8','ezk','에스겔',2,8,'너 인자야 내가 네게 이르는 말을 듣고 그 패역한 족속 같이 패역하지 말고 네 입을 벌리고 내가 네게 주는 것을 먹으라 하시기로',20501),
('ezk-2-9','ezk','에스겔',2,9,'내가 보니 보라 한 손이 나를 향하여 펴지고 보라 그 안에 두루마리 책이 있더라',20502),
('ezk-2-10','ezk','에스겔',2,10,'그가 그것을 내 앞에 펴시니 그 안팎에 글이 있는데 그 위에 애가와 애곡과 재앙의 말이 기록되었더라',20503),
('ezk-3-1','ezk','에스겔',3,1,'또 그가 내게 이르시되 인자야 너는 발견한 것을 먹으라 너는 이 두루마리를 먹고 가서 이스라엘 족속에게 말하라 하시기로',20504),
('ezk-3-2','ezk','에스겔',3,2,'내가 입을 벌리니 그가 그 두루마리를 내게 먹이시며',20505),
('ezk-3-3','ezk','에스겔',3,3,'내게 이르시되 인자야 내가 네게 주는 이 두루마리를 네 배에 넣으며 네 창자에 채우라 하시기에 내가 먹으니 그것이 내 입에서 달기가 꿀 같더라',20506),
('ezk-3-4','ezk','에스겔',3,4,'그가 또 내게 이르시되 인자야 이스라엘 족속에게 가서 내 말로 그들에게 고하라',20507),
('ezk-3-5','ezk','에스겔',3,5,'너를 언어가 다르거나 말이 어려운 백성에게 보내는 것이 아니요 이스라엘 족속에게 보내는 것이라',20508),
('ezk-3-6','ezk','에스겔',3,6,'너를 언어가 다르거나 말이 어려워 네가 그들의 말을 알아 듣지 못할 나라들에게 보내는 것이 아니니라 내가 너를 그들에게 보냈다면 그들은 정녕 네 말을 들었으리라',20509),
('ezk-3-7','ezk','에스겔',3,7,'그러나 이스라엘 족속은 이마가 굳고 마음이 굳어 네 말을 듣고자 아니하리니 이는 내 말을 듣고자 아니함이니라',20510),
('ezk-3-8','ezk','에스겔',3,8,'보라 내가 그들의 얼굴을 마주보도록 네 얼굴을 굳게 하였고 그들의 이마를 마주보도록 네 이마를 굳게 하였으되',20511),
('ezk-3-9','ezk','에스겔',3,9,'네 이마를 화석보다 굳은 금강석 같이 하였으니 그들이 비록 반역하는 족속이라도 두려워하지 말며 그들의 얼굴을 무서워하지 말라 하시니라',20512),
('ezk-3-10','ezk','에스겔',3,10,'또 내게 이르시되 인자야 내가 네게 이를 모든 말을 너는 마음으로 받으며 귀로 듣고',20513),
('ezk-3-11','ezk','에스겔',3,11,'사로잡힌 네 민족에게로 가서 그들이 듣든지 아니 듣든지 그들에게 고하여 이르기를 주 여호와의 말씀이 이러하시다 하라',20514),
('ezk-3-12','ezk','에스겔',3,12,'때에 주의 영이 나를 들어올리시는데 내가 내 뒤에서 크게 울리는 소리를 들으니 찬송할지어다 여호와의 영광이 그의 처소로부터 나오는도다 하니',20515),
('ezk-3-13','ezk','에스겔',3,13,'이는 생물들의 날개가 서로 부딪치는 소리와 생물 곁의 바퀴 소리라 크게 울리는 소리더라',20516),
('ezk-3-14','ezk','에스겔',3,14,'주의 영이 나를 들어올려 데리고 가시는데 내가 근심하고 분한 마음으로 가니 여호와의 권능이 힘 있게 나를 감동시키시더라',20517),
('ezk-3-15','ezk','에스겔',3,15,'이에 내가 델아빕에 이르러 그 사로잡힌 백성 곧 그발 강 가에 거주하는 자들에게 나아가 그 중에서 두려워 떨며 칠 일을 지내니라',20518),
('ezk-3-16','ezk','에스겔',3,16,'칠 일 후에 여호와의 말씀이 내게 임하여 이르시되',20519),
('ezk-3-17','ezk','에스겔',3,17,'인자야 내가 너를 이스라엘 족속의 파수꾼으로 세웠으니 너는 내 입의 말을 듣고 나를 대신하여 그들을 깨우치라',20520),
('ezk-3-18','ezk','에스겔',3,18,'가령 내가 악인에게 말하기를 너는 꼭 죽으리라 할 때에 네가 깨우치지 아니하거나 말로 악인에게 일러서 그의 악한 길을 떠나 생명을 구원하게 하지 아니하면 그 악인은 그의 죄악 중에서 죽으려니와 내가 그의 피 값을 네 손에서 찾을 것이고',20521),
('ezk-3-19','ezk','에스겔',3,19,'네가 악인을 깨우치되 그가 그의 악한 마음과 악한 행위에서 돌이키지 아니하면 그는 그의 죄악 중에서 죽으려니와 너는 네 생명을 보존하리라',20522),
('ezk-3-20','ezk','에스겔',3,20,'또 의인이 그의 공의에서 돌이켜 악을 행할 때에는 이미 행한 그의 공의는 기억할 바 아니라 내가 그 앞에 거치는 것을 두면 그가 죽을지니 이는 네가 그를 깨우치지 않음이니라 그는 그의 죄 중에서 죽으려니와 그의 피 값은 내가 네 손에서 찾으리라',20523),
('ezk-3-21','ezk','에스겔',3,21,'그러나 네가 그 의인을 깨우쳐 범죄하지 아니하게 함으로 그가 범죄하지 아니하면 정녕 살리니 이는 깨우침을 받음이며 너도 네 영혼을 보존하리라',20524),
('ezk-3-22','ezk','에스겔',3,22,'여호와께서 권능으로 거기서 내게 임하시고 또 내게 이르시되 일어나 들로 나아가라 내가 거기서 너와 말하리라 하시기로',20525),
('ezk-3-23','ezk','에스겔',3,23,'내가 일어나 들로 나아가니 여호와의 영광이 거기에 머물렀는데 내가 전에 그발 강 가에서 보던 영광과 같은지라 내가 곧 엎드리니',20526),
('ezk-3-24','ezk','에스겔',3,24,'주의 영이 내게 임하사 나를 일으켜 내 발로 세우시고 내게 말씀하여 이르시되 너는 가서 네 집에 들어가 문을 닫으라',20527),
('ezk-3-25','ezk','에스겔',3,25,'너 인자야 보라 무리가 네 위에 줄을 놓아 너를 동여매리니 네가 그들 가운데에서 나오지 못할 것이라',20528),
('ezk-3-26','ezk','에스겔',3,26,'내가 네 혀를 네 입천장에 붙게 하여 네가 말 못하는 자가 되어 그들을 꾸짖는 자가 되지 못하게 하리니 그들은 패역한 족속임이니라',20529),
('ezk-3-27','ezk','에스겔',3,27,'그러나 내가 너와 말할 때에 네 입을 열리니 너는 그들에게 이르기를 주 여호와의 말씀이 이러하시다 하라 들을 자는 들을 것이요 듣기 싫은 자는 듣지 아니하리니 그들은 반역하는 족속임이니라',20530),
('ezk-4-1','ezk','에스겔',4,1,'너 인자야 토판을 가져다가 그것을 네 앞에 놓고 한 성읍 곧 예루살렘을 그 위에 그리고',20531),
('ezk-4-2','ezk','에스겔',4,2,'그 성읍을 에워싸되 그것을 향하여 사다리를 세우고 그것을 향하여 흙으로 언덕을 쌓고 그것을 향하여 진을 치고 그것을 향하여 공성퇴를 둘러 세우고',20532),
('ezk-4-3','ezk','에스겔',4,3,'또 철판을 가져다가 너와 성읍 사이에 두어 철벽을 삼고 성을 포위하는 것처럼 에워싸라 이것이 이스라엘 족속에게 징조가 되리라',20533),
('ezk-4-4','ezk','에스겔',4,4,'너는 또 왼쪽으로 누워 이스라엘 족속의 죄악을 짊어지되 네가 눕는 날수대로 그 죄악을 담당할지니라',20534),
('ezk-4-5','ezk','에스겔',4,5,'내가 그들의 범죄한 햇수대로 네게 날수를 정하였나니 곧 삼백구십 일이니라 너는 이렇게 이스라엘 족속의 죄악을 담당하고',20535),
('ezk-4-6','ezk','에스겔',4,6,'그 수가 차거든 너는 오른쪽으로 누워 유다 족속의 죄악을 담당하라 내가 네게 사십 일로 정하였나니 하루가 일 년이니라',20536),
('ezk-4-7','ezk','에스겔',4,7,'너는 또 네 얼굴을 에워싸인 예루살렘 쪽으로 향하고 팔을 걷어 올리고 예언하라',20537),
('ezk-4-8','ezk','에스겔',4,8,'내가 줄로 너를 동이리니 네가 에워싸는 날이 끝나기까지 몸을 이리 저리 돌리지 못하리라',20538),
('ezk-4-9','ezk','에스겔',4,9,'너는 밀과 보리와 콩과 팥과 조와 귀리를 가져다가 한 그릇에 담고 너를 위하여 떡을 만들어 네가 옆으로 눕는 날수 곧 삼백구십 일 동안 먹되',20539),
('ezk-4-10','ezk','에스겔',4,10,'너는 음식물을 달아서 하루 이십 세겔씩 때를 따라 먹고',20540),
('ezk-4-11','ezk','에스겔',4,11,'물도 육분의 일 힌씩 되어서 때를 따라 마시라',20541),
('ezk-4-12','ezk','에스겔',4,12,'너는 그것을 보리떡처럼 만들어 먹되 그들의 목전에서 인분 불을 피워 구울지니라',20542),
('ezk-4-13','ezk','에스겔',4,13,'또 여호와께서 이르시되 내가 여러 나라들로 쫓아내어 흩어 버릴 이스라엘 자손이 거기서 이같이 부정한 떡을 먹으리라 하시기로',20543),
('ezk-4-14','ezk','에스겔',4,14,'내가 말하되 아하 주 여호와여 나는 영혼을 더럽힌 일이 없었나이다 어려서부터 지금까지 스스로 죽은 것이나 짐승에게 찢긴 것을 먹지 아니하였고 가증한 고기를 입에 넣지 아니하였나이다',20544),
('ezk-4-15','ezk','에스겔',4,15,'여호와께서 내게 이르시되 보라 쇠똥으로 인분을 대신하기를 허락하노니 너는 그것으로 떡을 구울지니라',20545),
('ezk-4-16','ezk','에스겔',4,16,'또 내게 이르시되 인자야 내가 예루살렘에서 의뢰하는 양식을 끊으리니 백성이 근심 중에 떡을 달아 먹고 두려워 떨며 물을 되어 마시다가',20546),
('ezk-4-17','ezk','에스겔',4,17,'떡과 물이 부족하여 피차에 두려워 하여 떨며 그 죄악 중에서 쇠패하리라',20547),
('ezk-5-1','ezk','에스겔',5,1,'너 인자야 너는 날카로운 칼을 가져다가 삭도로 삼아 네 머리털과 수염을 깎아서 저울로 달아 나누어 두라',20548),
('ezk-5-2','ezk','에스겔',5,2,'그 성읍을 에워싸는 날이 차거든 너는 터럭 삼분의 일은 성읍 안에서 불사르고 삼분의 일은 성읍 사방에서 칼로 치고 또 삼분의 일은 바람에 흩으라 내가 그 뒤를 따라 칼을 빼리라',20549),
('ezk-5-3','ezk','에스겔',5,3,'너는 터럭 중에서 조금을 네 옷자락에 싸고',20550),
('ezk-5-4','ezk','에스겔',5,4,'또 그 가운데에서 얼마를 불에 던져 사르라 그 속에서 불이 이스라엘 온 족속에게로 나오리라',20551),
('ezk-5-5','ezk','에스겔',5,5,'주 여호와께서 이와 같이 이르시되 이것이 곧 예루살렘이라 내가 그를 이방인 가운데에 두어 나라들이 둘러 있게 하였거늘',20552),
('ezk-5-6','ezk','에스겔',5,6,'그가 내 규례를 거슬러서 이방인보다 악을 더 행하며 내 율례도 그리함이 그를 둘러 있는 나라들보다 더하니 이는 그들이 내 규례를 버리고 내 율례를 행하지 아니하였음이니라',20553),
('ezk-5-7','ezk','에스겔',5,7,'그러므로 나 주 여호와가 말하노라 너희 요란함이 너희를 둘러싸고 있는 이방인들보다 더하여 내 율례를 행하지 아니하며 내 규례를 지키지 아니하고 너희를 둘러 있는 이방인들의 규례대로도 행하지 아니하였느니라',20554),
('ezk-5-8','ezk','에스겔',5,8,'그러므로 나 주 여호와가 말하노라 나 곧 내가 너를 치며 이방인의 목전에서 너에게 벌을 내리되',20555),
('ezk-5-9','ezk','에스겔',5,9,'네 모든 가증한 일로 말미암아 내가 전무후무하게 네게 내릴지라',20556),
('ezk-5-10','ezk','에스겔',5,10,'그리한즉 네 가운데에서 아버지가 아들을 잡아먹고 아들이 그 아버지를 잡아먹으리라 내가 벌을 네게 내리고 너희 중에 남은 자를 다 사방에 흩으리라',20557),
('ezk-5-11','ezk','에스겔',5,11,'그러므로 나 주 여호와가 말하노라 내가 나의 삶을 두고 맹세하노니 네가 모든 미운 물건과 모든 가증한 일로 내 성소를 더럽혔은즉 나도 너를 아끼지 아니하며 긍휼을 베풀지 아니하고 미약하게 하리니',20558),
('ezk-5-12','ezk','에스겔',5,12,'너희 가운데에서 삼분의 일은 전염병으로 죽으며 기근으로 멸망할 것이요 삼분의 일은 너의 사방에서 칼에 엎드러질 것이며 삼분의 일은 내가 사방에 흩어 버리고 또 그 뒤를 따라 가며 칼을 빼리라',20559),
('ezk-5-13','ezk','에스겔',5,13,'이와 같이 내 노가 다한즉 그들을 향한 분이 풀려서 내 마음이 가라앉으리라 내 분이 그들에게 다한즉 나 여호와가 열심으로 말한 줄을 그들이 알리라',20560),
('ezk-5-14','ezk','에스겔',5,14,'내가 이르되 또 너를 황무하게 하고 너를 둘러싸고 있는 이방인들 중에서 모든 지나가는 자의 목전에 모욕 거리가 되게 하리니',20561),
('ezk-5-15','ezk','에스겔',5,15,'내 노와 분과 중한 책망으로 네게 벌을 내린즉 너를 둘러싸고 있는 이방인들에게 네가 수치와 조롱 거리가 되고 두려움과 경고가 되리라 나 여호와의 말이니라',20562),
('ezk-5-16','ezk','에스겔',5,16,'내가 멸망하게 하는 기근의 독한 화살을 너희에게 보내되 기근을 더하여 너희가 의뢰하는 양식을 끊을 것이라',20563),
('ezk-5-17','ezk','에스겔',5,17,'내가 기근과 사나운 짐승을 너희에게 보내 외롭게 하고 너희 가운데에 전염병과 살륙이 일어나게 하고 또 칼이 너희에게 임하게 하리라 나 여호와의 말이니라',20564),
('ezk-6-1','ezk','에스겔',6,1,'여호와의 말씀이 내게 임하여 이르시되',20565),
('ezk-6-2','ezk','에스겔',6,2,'인자야 너는 이스라엘 산을 향하여 그들에게 예언하여',20566),
('ezk-6-3','ezk','에스겔',6,3,'이르기를 이스라엘 산들아 주 여호와의 말씀을 들으라 주 여호와께서 산과 언덕과 시내와 골짜기를 향하여 이같이 말씀하시기를 나 곧 내가 칼이 너희에게 임하게 하여 너희 산당을 멸하리니',20567),
('ezk-6-4','ezk','에스겔',6,4,'너희 제단들이 황폐하고 분향제단들이 깨뜨려질 것이며 너희가 죽임을 당하여 너희 우상 앞에 엎드러지게 할 것이라',20568),
('ezk-6-5','ezk','에스겔',6,5,'이스라엘 자손의 시체를 그 우상 앞에 두며 너희 해골을 너희 제단 사방에 흩으리라',20569),
('ezk-6-6','ezk','에스겔',6,6,'내가 너희가 거주하는 모든 성읍이 사막이 되게 하며 산당을 황폐하게 하리니 이는 너희 제단이 깨어지고 황폐하며 너희 우상들이 깨어져 없어지며 너희 분향제단들이 찍히며 너희가 만든 것이 폐하여지며',20570),
('ezk-6-7','ezk','에스겔',6,7,'또 너희가 죽임을 당하여 엎드러지게 하여 내가 여호와인 줄을 너희가 알게 하려 함이라',20571),
('ezk-6-8','ezk','에스겔',6,8,'그러나 너희가 여러 나라에 흩어질 때에 내가 너희 중에서 칼을 피하여 이방인들 중에 살아 남은 자가 있게 할지라',20572),
('ezk-6-9','ezk','에스겔',6,9,'너희 중에서 살아 남은 자가 사로잡혀 이방인들 중에 있어서 나를 기억하되 그들이 음란한 마음으로 나를 떠나고 음란한 눈으로 우상을 섬겨 나를 근심하게 한 것을 기억하고 스스로 한탄하리니 이는 그 모든 가증한 일로 악을 행하였음이라',20573),
('ezk-6-10','ezk','에스겔',6,10,'그 때에야 그들이 나를 여호와인 줄 알리라 내가 이런 재앙을 그들에게 내리겠다 한 말이 헛되지 아니하니라',20574),
('ezk-6-11','ezk','에스겔',6,11,'주 여호와께서 이같이 이르시되 너는 손뼉을 치고 발을 구르며 말할지어다 오호라 이스라엘 족속이 모든 가증한 악을 행하므로 마침내 칼과 기근과 전염병에 망하되',20575),
('ezk-6-12','ezk','에스겔',6,12,'먼 데 있는 자는 전염병에 죽고 가까운 데 있는 자는 칼에 엎드러지고 남아 있어 에워싸인 자는 기근에 죽으리라 이같이 내 진노를 그들에게 이룬즉',20576),
('ezk-6-13','ezk','에스겔',6,13,'그 죽임 당한 시체들이 그 우상들 사이에, 제단 사방에, 각 높은 고개 위에, 모든 산 꼭대기에, 모든 푸른 나무 아래에, 무성한 상수리나무 아래 곧 그 우상에게 분향하던 곳에 있으리니 내가 여호와인 줄을 너희가 알리라',20577),
('ezk-6-14','ezk','에스겔',6,14,'내가 내 손을 그들의 위에 펴서 그가 사는 온 땅 곧 광야에서부터 디블라까지 황량하고 황폐하게 하리니 내가 여호와인 줄을 그들이 알리라',20578),
('ezk-7-1','ezk','에스겔',7,1,'또 여호와의 말씀이 내게 임하여 이르시되',20579),
('ezk-7-2','ezk','에스겔',7,2,'너 인자야 주 여호와께서 이스라엘 땅에 관하여 이같이 말씀하셨느니라 끝났도다 이 땅 사방의 일이 끝났도다',20580),
('ezk-7-3','ezk','에스겔',7,3,'이제는 네게 끝이 이르렀나니 내가 내 진노를 네게 나타내어 네 행위를 심판하고 네 모든 가증한 일을 보응하리라',20581),
('ezk-7-4','ezk','에스겔',7,4,'내가 너를 불쌍히 여기지 아니하며 긍휼히 여기지도 아니하고 네 행위대로 너를 벌하여 네 가증한 일이 너희 중에 나타나게 하리니 내가 여호와인 줄을 너희가 알리라',20582),
('ezk-7-5','ezk','에스겔',7,5,'주 여호와께서 이같이 이르시되 재앙이로다, 비상한 재앙이로다 볼지어다 그것이 왔도다',20583),
('ezk-7-6','ezk','에스겔',7,6,'끝이 왔도다, 끝이 왔도다 끝이 너에게 왔도다 볼지어다 그것이 왔도다',20584),
('ezk-7-7','ezk','에스겔',7,7,'이 땅 주민아 정한 재앙이 네게 임하도다 때가 이르렀고 날이 가까웠으니 요란한 날이요 산에서 즐거이 부르는 날이 아니로다',20585),
('ezk-7-8','ezk','에스겔',7,8,'이제 내가 속히 분을 네게 쏟고 내 진노를 네게 이루어서 네 행위대로 너를 심판하여 네 모든 가증한 일을 네게 보응하되',20586),
('ezk-7-9','ezk','에스겔',7,9,'내가 너를 불쌍히 여기지 아니하며 긍휼히 여기지도 아니하고 네 행위대로 너를 벌하여 너의 가증한 일이 너희 중에 나타나게 하리니 나 여호와가 때리는 이임을 네가 알리라',20587),
('ezk-7-10','ezk','에스겔',7,10,'볼지어다 그 날이로다 볼지어다 임박하도다 정한 재앙이 이르렀으니 몽둥이가 꽃이 피며 교만이 싹이 났도다',20588),
('ezk-7-11','ezk','에스겔',7,11,'포학이 일어나서 죄악의 몽둥이가 되었은즉 그들도, 그 무리도, 그 재물도 하나도 남지 아니하며 그 중의 아름다운 것도 없어지리로다',20589),
('ezk-7-12','ezk','에스겔',7,12,'때가 이르렀고 날이 가까웠으니 사는 자도 기뻐하지 말고 파는 자도 근심하지 말 것은 진노가 그 모든 무리에게 임함이로다',20590),
('ezk-7-13','ezk','에스겔',7,13,'파는 자가 살아 있다 할지라도 다시 돌아가서 그 판 것을 얻지 못하리니 이는 묵시가 그 모든 무리에게 돌아오지 아니하고, 사람이 그 죄악으로 말미암아 자기의 목숨을 유지할 수 없으리라 하였음이로다',20591),
('ezk-7-14','ezk','에스겔',7,14,'그들이 나팔을 불어 온갖 것을 준비하였을지라도 전쟁에 나갈 사람이 없나니 이는 내 진노가 그 모든 무리에게 이르렀음이라',20592),
('ezk-7-15','ezk','에스겔',7,15,'밖에는 칼이 있고 안에는 전염병과 기근이 있어서 밭에 있는 자는 칼에 죽을 것이요 성읍에 있는 자는 기근과 전염병에 망할 것이며',20593),
('ezk-7-16','ezk','에스겔',7,16,'도망하는 자는 산 위로 피하여 다 각기 자기 죄악 때문에 골짜기의 비둘기들처럼 슬피 울 것이며',20594),
('ezk-7-17','ezk','에스겔',7,17,'모든 손은 피곤하고 모든 무릎은 물과 같이 약할 것이라',20595),
('ezk-7-18','ezk','에스겔',7,18,'그들이 굵은 베로 허리를 묶을 것이요 두려움이 그들을 덮을 것이요 모든 얼굴에는 수치가 있고 모든 머리는 대머리가 될 것이며',20596),
('ezk-7-19','ezk','에스겔',7,19,'그들이 그 은을 거리에 던지며 그 금을 오물 같이 여기리니 이는 여호와 내가 진노를 내리는 날에 그들의 은과 금이 능히 그들을 건지지 못하며 능히 그 심령을 족하게 하거나 그 창자를 채우지 못하고 오직 죄악의 걸림돌이 됨이로다',20597),
('ezk-7-20','ezk','에스겔',7,20,'그들이 그 화려한 장식으로 말미암아 교만을 품었고 또 그것으로 가증한 우상과 미운 물건을 만들었은즉 내가 그것을 그들에게 오물이 되게 하여',20598),
('ezk-7-21','ezk','에스겔',7,21,'타국인의 손에 넘겨 노략하게 하며 세상 악인에게 넘겨 그들이 약탈하여 더럽히게 하고',20599),
('ezk-7-22','ezk','에스겔',7,22,'내가 또 내 얼굴을 그들에게서 돌이키리니 그들이 내 은밀한 처소를 더럽히고 포악한 자도 거기 들어와서 더럽히리라',20600),
('ezk-7-23','ezk','에스겔',7,23,'너는 쇠사슬을 만들라 이는 피 흘리는 죄가 그 땅에 가득하고 포악이 그 성읍에 찼음이라',20601),
('ezk-7-24','ezk','에스겔',7,24,'내가 극히 악한 이방인들을 데려와서 그들이 그 집들을 점령하게 하고 강한 자의 교만을 그치게 하리니 그들의 성소가 더럽힘을 당하리라',20602),
('ezk-7-25','ezk','에스겔',7,25,'패망이 이르리니 그들이 평강을 구하여도 없을 것이라',20603),
('ezk-7-26','ezk','에스겔',7,26,'환난에 환난이 더하고 소문에 소문이 더할 때에 그들이 선지자에게서 묵시를 구하나 헛될 것이며 제사장에게는 율법이 없어질 것이요 장로에게는 책략이 없어질 것이며',20604),
('ezk-7-27','ezk','에스겔',7,27,'왕은 애통하고 고관은 놀람을 옷 입듯 하며 주민의 손은 떨리리라 내가 그 행위대로 그들에게 갚고 그 죄악대로 그들을 심판하리니 내가 여호와인 줄을 그들이 알리라',20605),
('ezk-8-1','ezk','에스겔',8,1,'여섯째 해 여섯째 달 초닷새에 나는 집에 앉았고 유다의 장로들은 내 앞에 앉아 있는데 주 여호와의 권능이 거기에서 내게 내리기로',20606),
('ezk-8-2','ezk','에스겔',8,2,'내가 보니 불 같은 형상이 있더라 그 허리 아래의 모양은 불 같고 허리 위에는 광채가 나서 단 쇠 같은데',20607),
('ezk-8-3','ezk','에스겔',8,3,'그가 손 같은 것을 펴서 내 머리털 한 모숨을 잡으며 주의 영이 나를 들어 천지 사이로 올리시고 하나님의 환상 가운데에 나를 이끌어 예루살렘으로 가서 안뜰로 들어가는 북향한 문에 이르시니 거기에는 질투의 우상 곧 질투를 일어나게 하는 우상의 자리가 있는 곳이라',20608),
('ezk-8-4','ezk','에스겔',8,4,'이스라엘 하나님의 영광이 거기에 있는데 내가 들에서 본 모습과 같더라',20609),
('ezk-8-5','ezk','에스겔',8,5,'그가 내게 이르시되 인자야 이제 너는 눈을 들어 북쪽을 바라보라 하시기로 내가 눈을 들어 북쪽을 바라보니 제단문 어귀 북쪽에 그 질투의 우상이 있더라',20610),
('ezk-8-6','ezk','에스겔',8,6,'그가 또 내게 이르시되 인자야 이스라엘 족속이 행하는 일을 보느냐 그들이 여기에서 크게 가증한 일을 행하여 나로 내 성소를 멀리 떠나게 하느니라 너는 다시 다른 큰 가증한 일을 보리라 하시더라',20611),
('ezk-8-7','ezk','에스겔',8,7,'그가 나를 이끌고 뜰 문에 이르시기로 내가 본즉 담에 구멍이 있더라',20612),
('ezk-8-8','ezk','에스겔',8,8,'그가 내게 이르시되 인자야 너는 이 담을 헐라 하시기로 내가 그 담을 허니 한 문이 있더라',20613),
('ezk-8-9','ezk','에스겔',8,9,'또 내게 이르시되 들어가서 그들이 거기에서 행하는 가증하고 악한 일을 보라 하시기로',20614),
('ezk-8-10','ezk','에스겔',8,10,'내가 들어가 보니 각양 곤충과 가증한 짐승과 이스라엘 족속의 모든 우상을 그 사방 벽에 그렸고',20615),
('ezk-8-11','ezk','에스겔',8,11,'이스라엘 족속의 장로 중 칠십 명이 그 앞에 섰으며 사반의 아들 야아사냐도 그 가운데에 섰고 각기 손에 향로를 들었는데 향연이 구름 같이 오르더라',20616),
('ezk-8-12','ezk','에스겔',8,12,'또 내게 이르시되 인자야 이스라엘 족속의 장로들이 각각 그 우상의 방안 어두운 가운데에서 행하는 것을 네가 보았느냐 그들이 이르기를 여호와께서 우리를 보지 아니하시며 여호와께서 이 땅을 버리셨다 하느니라',20617),
('ezk-8-13','ezk','에스겔',8,13,'또 내게 이르시되 너는 다시 그들이 행하는 바 다른 큰 가증한 일을 보리라 하시더라',20618),
('ezk-8-14','ezk','에스겔',8,14,'그가 또 나를 데리고 여호와의 전으로 들어가는 북문에 이르시기로 보니 거기에 여인들이 앉아 담무스를 위하여 애곡하더라',20619),
('ezk-8-15','ezk','에스겔',8,15,'그가 또 내게 이르시되 인자야 네가 그것을 보았느냐 너는 또 이보다 더 큰 가증한 일을 보리라 하시더라',20620),
('ezk-8-16','ezk','에스겔',8,16,'그가 또 나를 데리고 여호와의 성전 안뜰에 들어가시니라 보라 여호와의 성전 문 곧 현관과 제단 사이에서 약 스물다섯 명이 여호와의 성전을 등지고 낯을 동쪽으로 향하여 동쪽 태양에게 예배하더라',20621),
('ezk-8-17','ezk','에스겔',8,17,'또 내게 이르시되 인자야 네가 보았느냐 유다 족속이 여기에서 행한 가증한 일을 적다 하겠느냐 그들이 그 땅을 폭행으로 채우고 또 다시 내 노여움을 일으키며 심지어 나뭇가지를 그 코에 두었느니라',20622),
('ezk-8-18','ezk','에스겔',8,18,'그러므로 나도 분노로 갚아 불쌍히 여기지 아니하며 긍휼을 베풀지도 아니하리니 그들이 큰 소리로 내 귀에 부르짖을지라도 내가 듣지 아니하리라',20623),
('ezk-9-1','ezk','에스겔',9,1,'또 그가 큰 소리로 내 귀에 외쳐 이르시되 이 성읍을 관할하는 자들이 각기 죽이는 무기를 손에 들고 나아오게 하라 하시더라',20624),
('ezk-9-2','ezk','에스겔',9,2,'내가 보니 여섯 사람이 북향한 윗문 길로부터 오는데 각 사람의 손에 죽이는 무기를 잡았고 그 중의 한 사람은 가는 베 옷을 입고 허리에 서기관의 먹 그릇을 찼더라 그들이 들어와서 놋 제단 곁에 서더라',20625),
('ezk-9-3','ezk','에스겔',9,3,'그룹에 머물러 있던 이스라엘 하나님의 영광이 성전 문지방에 이르더니 여호와께서 그 가는 베 옷을 입고 서기관의 먹 그릇을 찬 사람을 불러',20626),
('ezk-9-4','ezk','에스겔',9,4,'여호와께서 이르시되 너는 예루살렘 성읍 중에 순행하여 그 가운데에서 행하는 모든 가증한 일로 말미암아 탄식하며 우는 자의 이마에 표를 그리라',20627),
('ezk-9-5','ezk','에스겔',9,5,'그들에 대하여 내 귀에 이르시되 너희는 그를 따라 성읍 중에 다니며 불쌍히 여기지 말며 긍휼을 베풀지 말고 쳐서',20628),
('ezk-9-6','ezk','에스겔',9,6,'늙은 자와 젊은 자와 처녀와 어린이와 여자를 다 죽이되 이마에 표 있는 자에게는 가까이 하지 말라 내 성소에서 시작할지니라 하시매 그들이 성전 앞에 있는 늙은 자들로부터 시작하더라',20629),
('ezk-9-7','ezk','에스겔',9,7,'그가 또 그들에게 이르시되 너희는 성전을 더럽혀 시체로 모든 뜰에 채우라 너희는 나가라 하시매 그들이 나가서 성읍 중에서 치더라',20630),
('ezk-9-8','ezk','에스겔',9,8,'그들이 칠 때에 내가 홀로 있었는지라 엎드려 부르짖어 이르되 아하 주 여호와여 예루살렘을 향하여 분노를 쏟으시오니 이스라엘의 남은 자를 모두 멸하려 하시나이까',20631),
('ezk-9-9','ezk','에스겔',9,9,'그가 내게 이르시되 이스라엘과 유다 족속의 죄악이 심히 중하여 그 땅에 피가 가득하며 그 성읍에 불법이 찼나니 이는 그들이 이르기를 여호와께서 이 땅을 버리셨으며 여호와께서 보지 아니하신다 함이라',20632),
('ezk-9-10','ezk','에스겔',9,10,'그러므로 내가 그들을 불쌍히 여기지 아니하며 긍휼을 베풀지 아니하고 그들의 행위대로 그들의 머리에 갚으리라 하시더라',20633),
('ezk-9-11','ezk','에스겔',9,11,'보라 가는 베 옷을 입고 허리에 먹 그릇을 찬 사람이 복명하여 이르되 주께서 내게 명령하신 대로 내가 준행하였나이다 하더라',20634),
('ezk-10-1','ezk','에스겔',10,1,'이에 내가 보니 그룹들 머리 위 궁창에 남보석 같은 것이 나타나는데 그들 위에 보좌의 형상이 있는 것 같더라',20635),
('ezk-10-2','ezk','에스겔',10,2,'하나님이 가는 베 옷을 입은 사람에게 말씀하여 이르시되 너는 그룹 밑에 있는 바퀴 사이로 들어가 그 속에서 숯불을 두 손에 가득히 움켜 가지고 성읍 위에 흩으라 하시매 그가 내 목전에서 들어가더라',20636),
('ezk-10-3','ezk','에스겔',10,3,'그 사람이 들어갈 때에 그룹들은 성전 오른쪽에 서 있고 구름은 안뜰에 가득하며',20637),
('ezk-10-4','ezk','에스겔',10,4,'여호와의 영광이 그룹에서 올라와 성전 문지방에 이르니 구름이 성전에 가득하며 여호와의 영화로운 광채가 뜰에 가득하였고',20638),
('ezk-10-5','ezk','에스겔',10,5,'그룹들의 날개 소리는 바깥뜰까지 들리는데 전능하신 하나님이 말씀하시는 음성 같더라',20639),
('ezk-10-6','ezk','에스겔',10,6,'하나님이 가는 베 옷을 입은 자에게 명령하시기를 바퀴 사이 곧 그룹들 사이에서 불을 가져 가라 하셨으므로 그가 들어가 바퀴 옆에 서매',20640),
('ezk-10-7','ezk','에스겔',10,7,'그 그룹이 그룹들 사이에서 손을 내밀어 그 그룹들 사이에 있는 불을 집어 가는 베 옷을 입은 자의 손에 주매 그가 받아 가지고 나가는데',20641),
('ezk-10-8','ezk','에스겔',10,8,'그룹들의 날개 밑에 사람의 손 같은 것이 나타나더라',20642),
('ezk-10-9','ezk','에스겔',10,9,'내가 보니 그룹들 곁에 네 바퀴가 있는데 이 그룹 곁에도 한 바퀴가 있고 저 그룹 곁에도 한 바퀴가 있으며 그 바퀴 모양은 황옥 같으며',20643),
('ezk-10-10','ezk','에스겔',10,10,'그 모양은 넷이 꼭 같은데 마치 바퀴 안에 바퀴가 있는 것 같으며',20644),
('ezk-10-11','ezk','에스겔',10,11,'그룹들이 나아갈 때에는 사방으로 몸을 돌리지 아니하고 나아가되 몸을 돌리지 아니하고 그 머리 향한 곳으로 나아가며',20645),
('ezk-10-12','ezk','에스겔',10,12,'그 온 몸과 등과 손과 날개와 바퀴 곧 네 그룹의 바퀴의 둘레에 다 눈이 가득하더라',20646),
('ezk-10-13','ezk','에스겔',10,13,'내가 들으니 그 바퀴들을 도는 것이라 부르며',20647),
('ezk-10-14','ezk','에스겔',10,14,'그룹들에게는 각기 네 면이 있는데 첫째 면은 그룹의 얼굴이요 둘째 면은 사람의 얼굴이요 셋째는 사자의 얼굴이요 넷째는 독수리의 얼굴이더라',20648),
('ezk-10-15','ezk','에스겔',10,15,'그룹들이 올라가니 그들은 내가 그발 강 가에서 보던 생물이라',20649),
('ezk-10-16','ezk','에스겔',10,16,'그룹들이 나아갈 때에는 바퀴도 그 곁에서 나아가고 그룹들이 날개를 들고 땅에서 올라가려 할 때에도 바퀴가 그 곁을 떠나지 아니하며',20650),
('ezk-10-17','ezk','에스겔',10,17,'그들이 서면 이들도 서고 그들이 올라가면 이들도 함께 올라가니 이는 생물의 영이 바퀴 가운데에 있음이더라',20651),
('ezk-10-18','ezk','에스겔',10,18,'여호와의 영광이 성전 문지방을 떠나서 그룹들 위에 머무르니',20652),
('ezk-10-19','ezk','에스겔',10,19,'그룹들이 날개를 들고 내 눈 앞의 땅에서 올라가는데 그들이 나갈 때에 바퀴도 그 곁에서 함께 하더라 그들이 여호와의 전으로 들어가는 동문에 머물고 이스라엘 하나님의 영광이 그 위에 덮였더라',20653),
('ezk-10-20','ezk','에스겔',10,20,'그것은 내가 그발 강 가에서 보던 이스라엘의 하나님 아래에 있던 생물이라 그들이 그룹인 줄을 내가 아니라',20654),
('ezk-10-21','ezk','에스겔',10,21,'각기 네 얼굴과 네 날개가 있으며 날개 밑에는 사람의 손 형상이 있으니',20655),
('ezk-10-22','ezk','에스겔',10,22,'그 얼굴의 형상은 내가 그발 강 가에서 보던 얼굴이며 그 모양과 그 몸도 그러하며 각기 곧게 앞으로 가더라',20656),
('ezk-11-1','ezk','에스겔',11,1,'그 때에 주의 영이 나를 들어올려서 여호와의 전 동문 곧 동향한 문에 이르시기로 보니 그 문에 사람이 스물다섯 명이 있는데 내가 그 중에서 앗술의 아들 야아사냐와 브나야의 아들 블라댜를 보았으니 그들은 백성의 고관이라',20657),
('ezk-11-2','ezk','에스겔',11,2,'그가 내게 이르시되 인자야 이 사람들은 불의를 품고 이 성 중에서 악한 꾀를 꾸미는 자니라',20658),
('ezk-11-3','ezk','에스겔',11,3,'그들의 말이 집 건축할 때가 가깝지 아니한즉 이 성읍은 가마가 되고 우리는 고기가 된다 하나니',20659),
('ezk-11-4','ezk','에스겔',11,4,'그러므로 인자야 너는 그들을 쳐서 예언하고 예언할지니라',20660),
('ezk-11-5','ezk','에스겔',11,5,'여호와의 영이 내게 임하여 이르시되 너는 말하기를 여호와의 말씀에 이스라엘 족속아 너희가 이렇게 말하였도다 너희 마음에서 일어나는 것을 내가 다 아노라',20661),
('ezk-11-6','ezk','에스겔',11,6,'너희가 이 성읍에서 많이 죽여 그 거리를 시체로 채웠도다',20662),
('ezk-11-7','ezk','에스겔',11,7,'그러므로 주 여호와께서 이같이 말씀하셨느니라 이 성읍 중에서 너희가 죽인 시체는 그 고기요 이 성읍은 그 가마인데 너희는 그 가운데에서 끌려 나오리라',20663),
('ezk-11-8','ezk','에스겔',11,8,'나 주 여호와가 말하노라 너희가 칼을 두려워하니 내가 칼로 너희에게 이르게 하고',20664),
('ezk-11-9','ezk','에스겔',11,9,'너희를 그 성읍 가운데에서 끌어내어 타국인의 손에 넘겨 너희에게 벌을 내리리니',20665),
('ezk-11-10','ezk','에스겔',11,10,'너희가 칼에 엎드러질 것이라 내가 이스라엘 변경에서 너희를 심판하리니 너희는 내가 여호와인 줄을 알리라',20666),
('ezk-11-11','ezk','에스겔',11,11,'이 성읍은 너희 가마가 되지 아니하고 너희는 그 가운데에 고기가 되지 아니할지라 내가 너희를 이스라엘 변경에서 심판하리니',20667),
('ezk-11-12','ezk','에스겔',11,12,'너희는 내가 여호와인 줄을 알리라 너희가 내 율례를 행하지 아니하며 규례를 지키지 아니하고 너희 사방에 있는 이방인의 규례대로 행하였느니라 하셨다 하라',20668),
('ezk-11-13','ezk','에스겔',11,13,'이에 내가 예언할 때에 브나야의 아들 블라댜가 죽기로 내가 엎드려 큰 소리로 부르짖어 이르되 오호라 주 여호와여 이스라엘의 남은 자를 다 멸절하고자 하시나이까 하니라',20669),
('ezk-11-14','ezk','에스겔',11,14,'여호와의 말씀이 내게 임하여 이르시되',20670),
('ezk-11-15','ezk','에스겔',11,15,'인자야 예루살렘 주민이 네 형제 곧 네 형제와 친척과 온 이스라엘 족속을 향하여 이르기를 너희는 여호와에게서 멀리 떠나라 이 땅은 우리에게 주어 기업이 되게 하신 것이라 하셨나니',20671),
('ezk-11-16','ezk','에스겔',11,16,'그런즉 너는 말하기를 주 여호와의 말씀에 내가 비록 그들을 멀리 이방인 가운데로 쫓아내어 여러 나라에 흩었으나 그들이 도달한 나라들에서 내가 잠깐 그들에게 성소가 되리라 하셨다 하고',20672),
('ezk-11-17','ezk','에스겔',11,17,'너는 또 말하기를 주 여호와의 말씀에 내가 너희를 만민 가운데에서 모으며 너희를 흩은 여러 나라 가운데에서 모아 내고 이스라엘 땅을 너희에게 주리라 하셨다 하라',20673),
('ezk-11-18','ezk','에스겔',11,18,'그들이 그리로 가서 그 가운데의 모든 미운 물건과 모든 가증한 것을 제거하여 버릴지라',20674),
('ezk-11-19','ezk','에스겔',11,19,'내가 그들에게 한 마음을 주고 그 속에 새 영을 주며 그 몸에서 돌 같은 마음을 제거하고 살처럼 부드러운 마음을 주어',20675),
('ezk-11-20','ezk','에스겔',11,20,'내 율례를 따르며 내 규례를 지켜 행하게 하리니 그들은 내 백성이 되고 나는 그들의 하나님이 되리라',20676),
('ezk-11-21','ezk','에스겔',11,21,'그러나 미운 것과 가증한 것을 마음으로 따르는 자는 내가 그 행위대로 그 머리에 갚으리라 나 주 여호와의 말이니라',20677),
('ezk-11-22','ezk','에스겔',11,22,'그 때에 그룹들이 날개를 드는데 바퀴도 그 곁에 있고 이스라엘 하나님의 영광도 그 위에 덮였더니',20678),
('ezk-11-23','ezk','에스겔',11,23,'여호와의 영광이 성읍 가운데에서부터 올라가 성읍 동쪽 산에 머무르고',20679),
('ezk-11-24','ezk','에스겔',11,24,'주의 영이 나를 들어 하나님의 영의 환상 중에 데리고 갈대아에 있는 사로잡힌 자 중에 이르시더니 내가 본 환상이 나를 떠나 올라간지라',20680),
('ezk-11-25','ezk','에스겔',11,25,'내가 사로잡힌 자에게 여호와께서 내게 보이신 모든 일을 말하니라',20681),
('ezk-12-1','ezk','에스겔',12,1,'또 여호와의 말씀이 내게 임하여 이르시되',20682),
('ezk-12-2','ezk','에스겔',12,2,'인자야 네가 반역하는 족속 중에 거주하는도다 그들은 볼 눈이 있어도 보지 아니하고 들을 귀가 있어도 듣지 아니하나니 그들은 반역하는 족속임이라',20683),
('ezk-12-3','ezk','에스겔',12,3,'인자야 너는 포로의 행장을 꾸리고 낮에 그들의 목전에서 끌려가라 네가 네 처소를 다른 곳으로 옮기는 것을 그들이 보면 비록 반역하는 족속이라도 혹 생각이 있으리라',20684),
('ezk-12-4','ezk','에스겔',12,4,'너는 낮에 그들의 목전에서 네 포로의 행장을 밖에 내놓기를 끌려가는 포로의 행장 같이 하고 저물 때에 너는 그들의 목전에서 밖으로 나가기를 포로되어 가는 자 같이 하라',20685),
('ezk-12-5','ezk','에스겔',12,5,'너는 그들의 목전에서 성벽을 뚫고 그리로 따라 옮기되',20686),
('ezk-12-6','ezk','에스겔',12,6,'캄캄할 때에 그들의 목전에서 어깨에 메고 나가며 얼굴을 가리고 땅을 보지 말지어다 이는 내가 너를 세워 이스라엘 족속에게 징조가 되게 함이라 하시기로',20687),
('ezk-12-7','ezk','에스겔',12,7,'내가 그 명령대로 행하여 낮에 나의 행장을 끌려가는 포로의 행장 같이 내놓고 저물 때에 내 손으로 성벽을 뚫고 캄캄할 때에 행장을 내다가 그들의 목전에서 어깨에 메고 나가니라',20688),
('ezk-12-8','ezk','에스겔',12,8,'이튿날 아침에 여호와의 말씀이 또 내게 임하여 이르시되',20689),
('ezk-12-9','ezk','에스겔',12,9,'인자야 이스라엘 족속 곧 그 반역하는 족속이 네게 묻기를 무엇을 하느냐 하지 아니하더냐',20690),
('ezk-12-10','ezk','에스겔',12,10,'너는 그들에게 말하기를 주 여호와의 말씀에 이것은 예루살렘 왕과 그 가운데에 있는 이스라엘 온 족속에 대한 묵시라 하셨다 하고',20691),
('ezk-12-11','ezk','에스겔',12,11,'또 말하기를 나는 너희 징조라 내가 행한 대로 그들도 포로로 사로잡혀 가리라',20692),
('ezk-12-12','ezk','에스겔',12,12,'무리가 성벽을 뚫고 행장을 그리로 가지고 나가고 그 중에 왕은 어두울 때에 어깨에 행장을 메고 나가며 눈으로 땅을 보지 아니하려고 자기 얼굴을 가리리라 하라',20693),
('ezk-12-13','ezk','에스겔',12,13,'내가 또 내 그물을 그의 위에 치고 내 올무에 걸리게 하여 그를 끌고 갈대아 땅 바벨론에 이르리니 그가 거기에서 죽으려니와 그 땅을 보지 못하리라',20694),
('ezk-12-14','ezk','에스겔',12,14,'내가 그 호위하는 자와 부대들을 다 사방으로 흩고 또 그 뒤를 따라 칼을 빼리라',20695),
('ezk-12-15','ezk','에스겔',12,15,'내가 그들을 이방인 가운데로 흩으며 여러 나라 가운데에 헤친 후에야 내가 여호와인 줄을 그들이 알리라',20696),
('ezk-12-16','ezk','에스겔',12,16,'그러나 내가 그 중 몇 사람을 남겨 칼과 기근과 전염병에서 벗어나게 하여 그들이 이르는 이방인 가운데에서 자기의 모든 가증한 일을 자백하게 하리니 내가 여호와인 줄을 그들이 알리라',20697),
('ezk-12-17','ezk','에스겔',12,17,'여호와의 말씀이 또 내게 임하여 이르시되',20698),
('ezk-12-18','ezk','에스겔',12,18,'인자야 너는 떨면서 네 음식을 먹고 놀라고 근심하면서 네 물을 마시며',20699),
('ezk-12-19','ezk','에스겔',12,19,'이 땅 백성에게 말하되 주 여호와께서 예루살렘 주민과 이스라엘 땅에 대하여 이르시기를 그들이 근심하면서 그 음식을 먹으며 놀라면서 그 물을 마실 것은 이 땅 모든 주민의 포악으로 말미암아 땅에 가득한 것이 황폐하게 됨이라',20700),
('ezk-12-20','ezk','에스겔',12,20,'사람이 거주하는 성읍들이 황폐하며 땅이 적막하리니 내가 여호와인 줄을 너희가 알리라 하셨다 하라',20701),
('ezk-12-21','ezk','에스겔',12,21,'여호와의 말씀이 또 내게 임하여 이르시되',20702),
('ezk-12-22','ezk','에스겔',12,22,'인자야 이스라엘 땅에서 이르기를 날이 더디고 모든 묵시가 사라지리라 하는 너희의 이 속담이 어찌 됨이냐',20703),
('ezk-12-23','ezk','에스겔',12,23,'그러므로 너는 그들에게 이르기를 주 여호와께서 이같이 말씀하시기를 내가 이 속담을 그치게 하리니 사람이 다시는 이스라엘 가운데에서 이 속담을 사용하지 못하리라 하셨다 하고 또 그들에게 이르기를 날과 모든 묵시의 응함이 가까우니',20704),
('ezk-12-24','ezk','에스겔',12,24,'이스라엘 족속 중에 허탄한 묵시나 아첨하는 복술이 다시 있지 못하리라 하라',20705),
('ezk-12-25','ezk','에스겔',12,25,'나는 여호와라 내가 말하리니 내가 하는 말이 다시는 더디지 아니하고 응하리라 반역하는 족속이여 내가 너희 생전에 말하고 이루리라 나 주 여호와의 말이니라 하셨다 하라',20706),
('ezk-12-26','ezk','에스겔',12,26,'여호와의 말씀이 또 내게 임하여 이르시되',20707),
('ezk-12-27','ezk','에스겔',12,27,'인자야 이스라엘 족속의 말이 그가 보는 묵시는 여러 날 후의 일이라 그가 멀리 있는 때에 대하여 예언하였다 하느니라',20708),
('ezk-12-28','ezk','에스겔',12,28,'그러므로 너는 그들에게 이르기를 주 여호와의 말씀에 나의 말이 하나도 다시 더디지 아니할지니 내가 한 말이 이루어지리라 나 주 여호와의 말이니라 하라',20709),
('ezk-13-1','ezk','에스겔',13,1,'여호와의 말씀이 내게 임하여 이르시되',20710),
('ezk-13-2','ezk','에스겔',13,2,'인자야 너는 이스라엘의 예언하는 선지자들에게 경고하여 예언하되 자기 마음대로 예언하는 자에게 말하기를 너희는 여호와의 말씀을 들으라',20711),
('ezk-13-3','ezk','에스겔',13,3,'주 여호와의 말씀에 본 것이 없이 자기 심령을 따라 예언하는 어리석은 선지자에게 화가 있을진저',20712),
('ezk-13-4','ezk','에스겔',13,4,'이스라엘아 너의 선지자들은 황무지에 있는 여우 같으니라',20713),
('ezk-13-5','ezk','에스겔',13,5,'너희 선지자들이 성 무너진 곳에 올라가지도 아니하였으며 이스라엘 족속을 위하여 여호와의 날에 전쟁에서 견디게 하려고 성벽을 수축하지도 아니하였느니라',20714),
('ezk-13-6','ezk','에스겔',13,6,'여호와께서 말씀하셨다고 하는 자들이 허탄한 것과 거짓된 점괘를 보며 사람들에게 그 말이 확실히 이루어지기를 바라게 하거니와 그들은 여호와가 보낸 자가 아니라',20715),
('ezk-13-7','ezk','에스겔',13,7,'너희가 말하기는 여호와의 말씀이라 하여도 내가 말한 것이 아닌즉 어찌 허탄한 묵시를 보며 거짓된 점괘를 말한 것이 아니냐',20716),
('ezk-13-8','ezk','에스겔',13,8,'그러므로 주 여호와께서 이같이 말씀하셨느니라 너희가 허탄한 것을 말하며 거짓된 것을 보았은즉 내가 너희를 치리라 주 여호와의 말씀이니라',20717),
('ezk-13-9','ezk','에스겔',13,9,'그 선지자들이 허탄한 묵시를 보며 거짓 것을 점쳤으니 내 손이 그들을 쳐서 내 백성의 공회에 들어오지 못하게 하며 이스라엘 족속의 호적에도 기록되지 못하게 하며 이스라엘 땅에도 들어가지 못하게 하리니 너희가 나를 여호와인 줄 알리라',20718),
('ezk-13-10','ezk','에스겔',13,10,'이렇게 칠 것은 그들이 내 백성을 유혹하여 평강이 없으나 평강이 있다 함이라 어떤 사람이 담을 쌓을 때에 그들이 회칠을 하는도다',20719),
('ezk-13-11','ezk','에스겔',13,11,'그러므로 너는 회칠하는 자에게 이르기를 그것이 무너지리라 폭우가 내리며 큰 우박덩이가 떨어지며 폭풍이 몰아치리니',20720),
('ezk-13-12','ezk','에스겔',13,12,'그 담이 무너진즉 어떤 사람이 너희에게 말하기를 그것에 칠한 회가 어디 있느냐 하지 아니하겠느냐',20721),
('ezk-13-13','ezk','에스겔',13,13,'그러므로 나 주 여호와가 말하노라 내가 분노하여 폭풍을 퍼붓고 내가 진노하여 폭우를 내리고 분노하여 큰 우박덩어리로 무너뜨리리라',20722),
('ezk-13-14','ezk','에스겔',13,14,'회칠한 담을 내가 이렇게 허물어서 땅에 넘어뜨리고 그 기초를 드러낼 것이라 담이 무너진즉 너희가 그 가운데에서 망하리니 나를 여호와인 줄 알리라',20723),
('ezk-13-15','ezk','에스겔',13,15,'이와 같이 내가 내 노를 담과 회칠한 자에게 모두 이루고 또 너희에게 말하기를 담도 없어지고 칠한 자들도 없어졌다 하리니',20724),
('ezk-13-16','ezk','에스겔',13,16,'이들은 예루살렘에 대하여 예언하기를 평강이 없으나 평강의 묵시를 보았다고 하는 이스라엘의 선지자들이니라 주 여호와의 말씀이니라',20725),
('ezk-13-17','ezk','에스겔',13,17,'너 인자야 너의 백성 중 자기 마음대로 예언하는 여자들에게 경고하며 예언하여',20726),
('ezk-13-18','ezk','에스겔',13,18,'이르기를 주 여호와의 말씀에 사람의 영혼을 사냥하려고 손목마다 부적을 꿰어 매고 키가 큰 자나 작은 자의 머리를 위하여 수건을 만드는 여자들에게 화 있을진저 너희가 어찌하여 내 백성의 영혼은 사냥하면서 자기를 위하여는 영혼을 살리려 하느냐',20727),
('ezk-13-19','ezk','에스겔',13,19,'너희가 두어 움큼 보리와 두어 조각 떡을 위하여 나를 내 백성 가운데에서 욕되게 하여 거짓말을 곧이 듣는 내 백성에게 너희가 거짓말을 지어내어 죽지 아니할 영혼을 죽이고 살지 못할 영혼을 살리는도다',20728),
('ezk-13-20','ezk','에스겔',13,20,'그러므로 나 주 여호와가 이같이 말하노라 너희가 새를 사냥하듯 영혼들을 사냥하는 그 부적을 내가 너희 팔에서 떼어 버리고 너희가 새처럼 사냥한 그 영혼들을 놓아 주며',20729),
('ezk-13-21','ezk','에스겔',13,21,'또 너희 수건을 찢고 내 백성을 너희 손에서 건지고 다시는 너희 손에 사냥물이 되지 아니하게 하리니 내가 여호와인 줄을 너희가 알리라',20730),
('ezk-13-22','ezk','에스겔',13,22,'내가 슬프게 하지 아니한 의인의 마음을 너희가 거짓말로 근심하게 하며 너희가 또 악인의 손을 굳게 하여 그 악한 길에서 돌이켜 떠나 삶을 얻지 못하게 하였은즉',20731),
('ezk-13-23','ezk','에스겔',13,23,'너희가 다시는 허탄한 묵시를 보지 못하고 점복도 못할지라 내가 내 백성을 너희 손에서 건져내리니 내가 여호와인 줄을 너희가 알리라 하라',20732),
('ezk-14-1','ezk','에스겔',14,1,'이스라엘 장로 두어 사람이 나아와 내 앞에 앉으니',20733),
('ezk-14-2','ezk','에스겔',14,2,'여호와의 말씀이 내게 임하여 이르시되',20734),
('ezk-14-3','ezk','에스겔',14,3,'인자야 이 사람들이 자기 우상을 마음에 들이며 죄악의 걸림돌을 자기 앞에 두었으니 그들이 내게 묻기를 내가 조금인들 용납하랴',20735),
('ezk-14-4','ezk','에스겔',14,4,'그런즉 너는 그들에게 말하여 이르라 나 주 여호와가 말하노라 이스라엘 족속 중에 그 우상을 마음에 들이며 죄악의 걸림돌을 자기 앞에 두고 선지자에게로 가는 모든 자에게 나 여호와가 그 우상의 수효대로 보응하리니',20736),
('ezk-14-5','ezk','에스겔',14,5,'이는 이스라엘 족속이 다 그 우상으로 말미암아 나를 배반하였으므로 내가 그들이 마음먹은 대로 그들을 잡으려 함이라',20737),
('ezk-14-6','ezk','에스겔',14,6,'그런즉 너는 이스라엘 족속에게 이르기를 주 여호와의 말씀에 너희는 마음을 돌이켜 우상을 떠나고 얼굴을 돌려 모든 가증한 것을 떠나라',20738),
('ezk-14-7','ezk','에스겔',14,7,'이스라엘 족속과 이스라엘 가운데에 거류하는 외국인 중에 누구든지 나를 떠나고 자기 우상을 마음에 들이며 죄악의 걸림돌을 자기 앞에 두고 자기를 위하여 내게 묻고자 하여 선지자에게 가는 모든 자에게는 나 여호와가 친히 응답하여',20739),
('ezk-14-8','ezk','에스겔',14,8,'그 사람을 대적하여 그들을 놀라움과 표징과 속담 거리가 되게 하여 내 백성 가운데에서 끊으리니 내가 여호와인 줄을 너희가 알리라',20740),
('ezk-14-9','ezk','에스겔',14,9,'만일 선지자가 유혹을 받고 말을 하면 나 여호와가 그 선지자를 유혹을 받게 하였음이거니와 내가 손을 펴서 내 백성 이스라엘 가운데에서 그를 멸할 것이라',20741),
('ezk-14-10','ezk','에스겔',14,10,'선지자의 죄악과 그에게 묻는 자의 죄악이 같은즉 각각 자기의 죄악을 담당하리니',20742),
('ezk-14-11','ezk','에스겔',14,11,'이는 이스라엘 족속이 다시는 미혹되어 나를 떠나지 아니하게 하며 다시는 모든 죄로 스스로 더럽히지 아니하게 하여 그들을 내 백성으로 삼고 나는 그들의 하나님이 되려 함이라 주 여호와의 말씀이니라',20743),
('ezk-14-12','ezk','에스겔',14,12,'여호와의 말씀이 또 내게 임하여 이르시되',20744),
('ezk-14-13','ezk','에스겔',14,13,'인자야 가령 어떤 나라가 불법을 행하여 내게 범죄하므로 내가 손을 그 위에 펴서 그 의지하는 양식을 끊어 기근을 내려 사람과 짐승을 그 나라에서 끊는다 하자',20745),
('ezk-14-14','ezk','에스겔',14,14,'비록 노아, 다니엘, 욥, 이 세 사람이 거기에 있을지라도 그들은 자기의 공의로 자기의 생명만 건지리라 나 주 여호와의 말이니라',20746),
('ezk-14-15','ezk','에스겔',14,15,'가령 내가 사나운 짐승을 그 땅에 다니게 하여 그 땅을 황폐하게 하여 사람이 그 짐승 때문에 능히 다니지 못하게 한다 하자',20747),
('ezk-14-16','ezk','에스겔',14,16,'비록 이 세 사람이 거기에 있을지라도 나의 삶을 두고 맹세하노니 그들도 자녀는 건지지 못하고 자기만 건지겠고 그 땅은 황폐하리라 주 여호와의 말씀이니라',20748),
('ezk-14-17','ezk','에스겔',14,17,'가령 내가 칼이 그 땅에 임하게 하고 명령하기를 칼아 그 땅에 돌아다니라 하고 내가 사람과 짐승을 거기에서 끊는다 하자',20749),
('ezk-14-18','ezk','에스겔',14,18,'비록 이 세 사람이 거기에 있을지라도 나의 삶을 두고 맹세하노니 그들도 자녀는 건지지 못하고 자기만 건지리라 나 주 여호와의 말이니라',20750),
('ezk-14-19','ezk','에스겔',14,19,'가령 내가 그 땅에 전염병을 내려 죽임으로 내 분노를 그 위에 쏟아 사람과 짐승을 거기에서 끊는다 하자',20751),
('ezk-14-20','ezk','에스겔',14,20,'비록 노아, 다니엘, 욥이 거기에 있을지라도 나의 삶을 두고 맹세하노니 그들도 자녀는 건지지 못하고 자기의 공의로 자기의 생명만 건지리라 주 여호와의 말씀이니라',20752),
('ezk-14-21','ezk','에스겔',14,21,'주 여호와께서 이같이 이르시되 내가 나의 네 가지 중한 벌 곧 칼과 기근과 사나운 짐승과 전염병을 예루살렘에 함께 내려 사람과 짐승을 그 중에서 끊으리니 그 해가 더욱 심하지 아니하겠느냐',20753),
('ezk-14-22','ezk','에스겔',14,22,'그러나 그 가운데에 피하는 자가 남아 있어 끌려 나오리니 곧 자녀들이라 그들이 너희에게로 나아오리니 너희가 그 행동과 소행을 보면 내가 예루살렘에 내린 재앙 곧 그 내린 모든 일에 대하여 너희가 위로를 받을 것이라',20754),
('ezk-14-23','ezk','에스겔',14,23,'너희가 그 행동과 소행을 볼 때에 그들에 의해 위로를 받고 내가 예루살렘에서 행한 모든 일이 이유 없이 한 것이 아닌 줄을 알리라 주 여호와의 말씀이니라',20755),
('ezk-15-1','ezk','에스겔',15,1,'여호와의 말씀이 내게 임하여 이르시되',20756),
('ezk-15-2','ezk','에스겔',15,2,'인자야 포도나무가 모든 나무보다 나은 것이 무엇이랴 숲속의 여러 나무 가운데에 있는 그 포도나무 가지가 나은 것이 무엇이랴',20757),
('ezk-15-3','ezk','에스겔',15,3,'그 나무를 가지고 무엇을 제조할 수 있겠느냐 그것으로 무슨 그릇을 걸 못을 만들 수 있겠느냐',20758),
('ezk-15-4','ezk','에스겔',15,4,'불에 던질 땔감이 될 뿐이라 불이 그 두 끝을 사르고 그 가운데도 태웠으면 제조에 무슨 소용이 있겠느냐',20759),
('ezk-15-5','ezk','에스겔',15,5,'그것이 온전할 때에도 아무 제조에 합당하지 아니하였거든 하물며 불에 살라지고 탄 후에 어찌 제조에 합당하겠느냐',20760),
('ezk-15-6','ezk','에스겔',15,6,'그러므로 주 여호와께서 이같이 말씀하셨느니라 내가 수풀 가운데에 있는 포도나무를 불에 던질 땔감이 되게 한 것 같이 내가 예루살렘 주민도 그같이 할지라',20761),
('ezk-15-7','ezk','에스겔',15,7,'내가 그들을 대적한즉 그들이 그 불에서 나와도 불이 그들을 사르리니 내가 그들을 대적할 때에 내가 여호와인 줄 너희가 알리라',20762),
('ezk-15-8','ezk','에스겔',15,8,'내가 그 땅을 황폐하게 하리니 이는 그들이 범법함이니라 나 주 여호와의 말이니라 하시니라',20763),
('ezk-16-1','ezk','에스겔',16,1,'또 여호와의 말씀이 내게 임하여 이르시되',20764),
('ezk-16-2','ezk','에스겔',16,2,'인자야 예루살렘으로 그 가증한 일을 알게 하여',20765),
('ezk-16-3','ezk','에스겔',16,3,'이르기를 주 여호와께서 예루살렘에 관하여 이같이 말씀하시되 네 근본과 난 땅은 가나안이요 네 아버지는 아모리 사람이요 네 어머니는 헷 사람이라',20766),
('ezk-16-4','ezk','에스겔',16,4,'네가 난 것을 말하건대 네가 날 때에 네 배꼽 줄을 자르지 아니하였고 너를 물로 씻어 정결하게 하지 아니하였고 네게 소금을 뿌리지 아니하였고 너를 강보로 싸지도 아니하였나니',20767),
('ezk-16-5','ezk','에스겔',16,5,'아무도 너를 돌보아 이 중에 한 가지라도 네게 행하여 너를 불쌍히 여긴 자가 없었으므로 네가 나던 날에 네 몸이 천하게 여겨져 네가 들에 버려졌느니라',20768),
('ezk-16-6','ezk','에스겔',16,6,'내가 네 곁으로 지나갈 때에 네가 피투성이가 되어 발짓하는 것을 보고 네게 이르기를 너는 피투성이라도 살아 있으라 다시 이르기를 너는 피투성이라도 살아 있으라 하고',20769),
('ezk-16-7','ezk','에스겔',16,7,'내가 너를 들의 풀 같이 많게 하였더니 네가 크게 자라고 심히 아름다우며 유방이 뚜렷하고 네 머리털이 자랐으나 네가 여전히 벌거벗은 알몸이더라',20770),
('ezk-16-8','ezk','에스겔',16,8,'내가 네 곁으로 지나며 보니 네 때가 사랑을 할 만한 때라 내 옷으로 너를 덮어 벌거벗은 것을 가리고 네게 맹세하고 언약하여 너를 내게 속하게 하였느니라 나 주 여호와의 말이니라',20771),
('ezk-16-9','ezk','에스겔',16,9,'내가 물로 네 피를 씻어 없애고 네게 기름을 바르고',20772),
('ezk-16-10','ezk','에스겔',16,10,'수 놓은 옷을 입히고 물돼지 가죽신을 신기고 가는 베로 두르고 모시로 덧입히고',20773),
('ezk-16-11','ezk','에스겔',16,11,'패물을 채우고 팔고리를 손목에 끼우고 목걸이를 목에 걸고',20774),
('ezk-16-12','ezk','에스겔',16,12,'코고리를 코에 달고 귀고리를 귀에 달고 화려한 왕관을 머리에 씌웠나니',20775),
('ezk-16-13','ezk','에스겔',16,13,'이와 같이 네가 금, 은으로 장식하고 가는 베와 모시와 수 놓은 것을 입으며 또 고운 밀가루와 꿀과 기름을 먹음으로 극히 곱고 형통하여 왕후의 지위에 올랐느니라',20776),
('ezk-16-14','ezk','에스겔',16,14,'네 화려함으로 말미암아 네 명성이 이방인 중에 퍼졌음은 내가 네게 입힌 영화로 네 화려함이 온전함이라 나 주 여호와의 말이니라',20777),
('ezk-16-15','ezk','에스겔',16,15,'그러나 네가 네 화려함을 믿고 네 명성을 가지고 행음하되 지나가는 모든 자와 더불어 음란을 많이 행하므로 네 몸이 그들의 것이 되도다',20778),
('ezk-16-16','ezk','에스겔',16,16,'네가 네 의복을 가지고 너를 위하여 각색으로 산당을 꾸미고 거기에서 행음하였나니 이런 일은 전무후무하니라',20779),
('ezk-16-17','ezk','에스겔',16,17,'네가 또 내가 준 금, 은 장식품으로 너를 위하여 남자 우상을 만들어 행음하며',20780),
('ezk-16-18','ezk','에스겔',16,18,'또 네 수 놓은 옷을 그 우상에게 입히고 나의 기름과 향을 그 앞에 베풀며',20781),
('ezk-16-19','ezk','에스겔',16,19,'또 내가 네게 주어 먹게 한 내 음식물 곧 고운 밀가루와 기름과 꿀을 네가 그 앞에 베풀어 향기를 삼았나니 과연 그렇게 하였느니라 주 여호와의 말씀이니라',20782),
('ezk-16-20','ezk','에스겔',16,20,'또 네가 나를 위하여 낳은 네 자녀를 그들에게 데리고 가서 드려 제물로 삼아 불살랐느니라 네가 네 음행을 작은 일로 여겨서',20783),
('ezk-16-21','ezk','에스겔',16,21,'나의 자녀들을 죽여 우상에게 넘겨 불 가운데로 지나가게 하였느냐',20784),
('ezk-16-22','ezk','에스겔',16,22,'네가 어렸을 때에 벌거벗은 몸이었으며 피투성이가 되어서 발짓하던 것을 기억하지 아니하고 네가 모든 가증한 일과 음란을 행하였느니라',20785),
('ezk-16-23','ezk','에스겔',16,23,'주 여호와의 말씀이니라 너는 화 있을진저 화 있을진저 네가 모든 악을 행한 후에',20786),
('ezk-16-24','ezk','에스겔',16,24,'너를 위하여 누각을 건축하며 모든 거리에 높은 대를 쌓았도다',20787),
('ezk-16-25','ezk','에스겔',16,25,'네가 높은 대를 모든 길 어귀에 쌓고 네 아름다움을 가증하게 하여 모든 지나가는 자에게 다리를 벌려 심히 음행하고',20788),
('ezk-16-26','ezk','에스겔',16,26,'하체가 큰 네 이웃 나라 애굽 사람과도 음행하되 심히 음란히 하여 내 진노를 샀도다',20789),
('ezk-16-27','ezk','에스겔',16,27,'그러므로 내가 내 손을 네 위에 펴서 네 일용할 양식을 감하고 너를 미워하는 블레셋 여자 곧 네 더러운 행실을 부끄러워하는 자에게 너를 넘겨 임의로 하게 하였거늘',20790),
('ezk-16-28','ezk','에스겔',16,28,'네가 음욕이 차지 아니하여 또 앗수르 사람과 행음하고 그들과 행음하고도 아직도 부족하게 여겨',20791),
('ezk-16-29','ezk','에스겔',16,29,'장사하는 땅 갈대아에까지 심히 행음하되 아직도 족한 줄을 알지 못하였느니라',20792),
('ezk-16-30','ezk','에스겔',16,30,'주 여호와의 말씀이니라 네가 이 모든 일을 행하니 이는 방자한 음녀의 행위라 네 마음이 어찌 그리 약한지',20793),
('ezk-16-31','ezk','에스겔',16,31,'네가 누각을 모든 길 어귀에 건축하며 높은 대를 모든 거리에 쌓고도 값을 싫어하니 창기 같지도 아니하도다',20794),
('ezk-16-32','ezk','에스겔',16,32,'그 남편 대신에 다른 남자들과 내통하여 간음하는 아내로다',20795),
('ezk-16-33','ezk','에스겔',16,33,'사람들은 모든 창기에게 선물을 주거늘 오직 너는 네 모든 정든 자에게 선물을 주며 값을 주어서 사방에서 와서 너와 행음하게 하니',20796),
('ezk-16-34','ezk','에스겔',16,34,'네 음란함이 다른 여인과 같지 아니함은 행음하려고 너를 따르는 자가 없음이며 또 네가 값을 받지 아니하고 도리어 값을 줌이라 그런즉 다른 여인과 같지 아니하니라',20797),
('ezk-16-35','ezk','에스겔',16,35,'그러므로 너 음녀야 여호와의 말씀을 들을지어다',20798),
('ezk-16-36','ezk','에스겔',16,36,'주 여호와께서 이같이 말씀하셨느니라 네가 네 누추한 것을 쏟으며 네 정든 자와 행음함으로 벗은 몸을 드러내며 또 가증한 우상을 위하며 네 자녀의 피를 그 우상에게 드렸은즉',20799),
('ezk-16-37','ezk','에스겔',16,37,'내가 너의 즐거워하는 정든 자와 사랑하던 모든 자와 미워하던 모든 자를 모으되 사방에서 모아 너를 대적하게 할 것이요 또 네 벗은 몸을 그 앞에 드러내 그들이 그것을 다 보게 할 것이며',20800),
('ezk-16-38','ezk','에스겔',16,38,'내가 또 간음하고 사람의 피를 흘리는 여인을 심판함 같이 너를 심판하여 진노의 피와 질투의 피를 네게 돌리고',20801),
('ezk-16-39','ezk','에스겔',16,39,'내가 또 너를 그들의 손에 넘기리니 그들이 네 누각을 헐며 네 높은 대를 부수며 네 의복을 벗기고 네 장식품을 빼앗고 네 몸을 벌거벗겨 버려 두며',20802),
('ezk-16-40','ezk','에스겔',16,40,'무리를 데리고 와서 너를 돌로 치며 칼로 찌르며',20803),
('ezk-16-41','ezk','에스겔',16,41,'불로 네 집들을 사르고 여러 여인의 목전에서 너를 벌할지라 내가 너에게 곧 음행을 그치게 하리니 네가 다시는 값을 주지 아니하리라',20804),
('ezk-16-42','ezk','에스겔',16,42,'그리한즉 나는 네게 대한 내 분노가 그치며 내 질투가 네게서 떠나고 마음이 평안하여 다시는 노하지 아니하리라',20805),
('ezk-16-43','ezk','에스겔',16,43,'네가 어렸을 때를 기억하지 아니하고 이 모든 일로 나를 분노하게 하였은즉 내가 네 행위대로 네 머리에 보응하리니 네가 이 음란과 네 모든 가증한 일을 다시는 행하지 아니하리라 주 여호와의 말씀이니라',20806),
('ezk-16-44','ezk','에스겔',16,44,'속담을 말하는 자마다 네게 대하여 속담을 말하기를 어머니가 그러하면 딸도 그러하다 하리라',20807),
('ezk-16-45','ezk','에스겔',16,45,'너는 그 남편과 자녀를 싫어한 어머니의 딸이요 너는 그 남편과 자녀를 싫어한 형의 동생이로다 네 어머니는 헷 사람이요 네 아버지는 아모리 사람이며',20808),
('ezk-16-46','ezk','에스겔',16,46,'네 형은 그 딸들과 함께 네 왼쪽에 거주하는 사마리아요 네 아우는 그 딸들과 함께 네 오른쪽에 거주하는 소돔이라',20809),
('ezk-16-47','ezk','에스겔',16,47,'네가 그들의 행위대로만 행하지 아니하며 그 가증한 대로만 행하지 아니하고 그것을 적게 여겨서 네 모든 행위가 그보다 더욱 부패하였도다',20810),
('ezk-16-48','ezk','에스겔',16,48,'주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 네 아우 소돔 곧 그와 그의 딸들은 너와 네 딸들의 행위 같이 행하지 아니하였느니라',20811),
('ezk-16-49','ezk','에스겔',16,49,'네 아우 소돔의 죄악은 이러하니 그와 그의 딸들에게 교만함과 음식물의 풍족함과 태평함이 있음이며 또 그가 가난하고 궁핍한 자를 도와 주지 아니하며',20812),
('ezk-16-50','ezk','에스겔',16,50,'거만하여 가증한 일을 내 앞에서 행하였음이라 그러므로 내가 보고 곧 그들을 없이 하였느니라',20813),
('ezk-16-51','ezk','에스겔',16,51,'사마리아는 네 죄의 절반도 범하지 아니하였느니라 네가 그들보다 가증한 일을 심히 행하였으므로 네 모든 가증한 행위로 네 형과 아우를 의롭게 하였느니라',20814),
('ezk-16-52','ezk','에스겔',16,52,'네가 네 형과 아우를 유리하게 판단하였은즉 너도 네 수치를 담당할지니라 네가 그들보다 더욱 가증한 죄를 범하므로 그들이 너보다 의롭게 되었나니 네가 네 형과 아우를 의롭게 하였은즉 너는 놀라며 네 수치를 담당할지니라',20815),
('ezk-16-53','ezk','에스겔',16,53,'내가 그들의 사로잡힘 곧 소돔과 그의 딸들의 사로잡힘과 사마리아와 그의 딸들의 사로잡힘과 그들 중에 너의 사로잡힌 자의 사로잡힘을 풀어 주어',20816),
('ezk-16-54','ezk','에스겔',16,54,'네가 네 수욕을 담당하고 네가 행한 모든 일로 말미암아 부끄럽게 하리니 이는 네가 그들에게 위로가 됨이라',20817),
('ezk-16-55','ezk','에스겔',16,55,'네 아우 소돔과 그의 딸들이 옛 지위를 회복할 것이요 사마리아와 그의 딸들도 그의 옛 지위를 회복할 것이며 너와 네 딸들도 너희 옛 지위를 회복할 것이니라',20818),
('ezk-16-56','ezk','에스겔',16,56,'네가 교만하던 때에 네 아우 소돔을 네 입으로 말하지도 아니하였나니',20819),
('ezk-16-57','ezk','에스겔',16,57,'곧 네 악이 드러나기 전이며 아람의 딸들이 너를 능욕하기 전이며 너의 사방에 둘러 있는 블레셋의 딸들이 너를 멸시하기 전이니라',20820),
('ezk-16-58','ezk','에스겔',16,58,'네 음란과 네 가증한 일을 네가 담당하였느니라 나 여호와의 말이니라',20821),
('ezk-16-59','ezk','에스겔',16,59,'나 주 여호와가 이같이 말하노라 네가 맹세를 멸시하여 언약을 배반하였은즉 내가 네 행한 대로 네게 행하리라',20822),
('ezk-16-60','ezk','에스겔',16,60,'그러나 내가 너의 어렸을 때에 너와 세운 언약을 기억하고 너와 영원한 언약을 세우리라',20823),
('ezk-16-61','ezk','에스겔',16,61,'네가 네 형과 아우를 접대할 때에 네 행위를 기억하고 부끄러워할 것이라 내가 그들을 네게 딸로 주려니와 네 언약으로 말미암음이 아니니라',20824),
('ezk-16-62','ezk','에스겔',16,62,'내가 네게 내 언약을 세워 내가 여호와인 줄 네가 알게 하리니',20825),
('ezk-16-63','ezk','에스겔',16,63,'이는 내가 네 모든 행한 일을 용서한 후에 네가 기억하고 놀라고 부끄러워서 다시는 입을 열지 못하게 하려 함이니라 주 여호와의 말씀이니라',20826),
('ezk-17-1','ezk','에스겔',17,1,'여호와의 말씀이 내게 임하여 이르시되',20827),
