('ezk-17-3','ezk','에스겔',17,3,'여호와께서 이같이 말씀하여 이르시되 색깔이 화려하고 날개가 크고 깃이 길고 털이 숱한 큰 독수리가 레바논에 이르러 백향목 높은 가지를 꺾되',20829),
('ezk-17-4','ezk','에스겔',17,4,'그 연한 가지 끝을 꺾어 가지고 장사하는 땅에 이르러 상인의 성읍에 두고',20830),
('ezk-17-5','ezk','에스겔',17,5,'또 그 땅의 종자를 꺾어 옥토에 심되 수양버들 가지처럼 큰 물 가에 심더니',20831),
('ezk-17-6','ezk','에스겔',17,6,'그것이 자라며 퍼져서 높지 아니한 포도나무 곧 굵은 가지와 가는 가지가 난 포도나무가 되어 그 가지는 독수리를 향하였고 그 뿌리는 독수리 아래에 있었더라',20832),
('ezk-17-7','ezk','에스겔',17,7,'또 날개가 크고 털이 많은 큰 독수리 하나가 있었는데 그 포도나무가 이 독수리에게 물을 받으려고 그 심어진 두둑에서 그를 향하여 뿌리가 뻗고 가지가 퍼졌도다',20833),
('ezk-17-8','ezk','에스겔',17,8,'그 포도나무를 큰 물 가 옥토에 심은 것은 가지를 내고 열매를 맺어서 아름다운 포도나무를 이루게 하려 하였음이라',20834),
('ezk-17-9','ezk','에스겔',17,9,'너는 이르기를 주 여호와의 말씀에 그 나무가 능히 번성하겠느냐 이 독수리가 어찌 그 뿌리를 빼고 열매를 따며 그 나무가 시들게 하지 아니하겠으며 그 연한 잎사귀가 마르게 하지 아니하겠느냐 많은 백성이나 강한 팔이 아니라도 그 뿌리를 뽑으리라',20835),
('ezk-17-10','ezk','에스겔',17,10,'볼지어다 그것이 심어졌으나 번성하겠느냐 동풍에 부딪힐 때에 아주 마르지 아니하겠느냐 그 자라던 두둑에서 마르리라 하셨다 하라',20836),
('ezk-17-11','ezk','에스겔',17,11,'여호와의 말씀이 또 내게 임하여 이르시되',20837),
('ezk-17-12','ezk','에스겔',17,12,'너는 반역하는 족속에게 묻기를 너희가 이 비유를 깨닫지 못하겠느냐 하고 그들에게 말하기를 바벨론 왕이 예루살렘에 이르러 왕과 고관을 사로잡아 바벨론 자기에게로 끌어 가고',20838),
('ezk-17-13','ezk','에스겔',17,13,'그 왕족 중에서 하나를 택하여 언약을 세우고 그에게 맹세하게 하고 또 그 땅의 능한 자들을 옮겨 갔나니',20839),
('ezk-17-14','ezk','에스겔',17,14,'이는 나라를 낮추어 스스로 서지 못하고 그 언약을 지켜야 능히 서게 하려 하였음이거늘',20840),
('ezk-17-15','ezk','에스겔',17,15,'그가 사절을 애굽에 보내 말과 군대를 구함으로 바벨론 왕을 배반하였으니 형통하겠느냐 이런 일을 행한 자가 피하겠느냐 언약을 배반하고야 피하겠느냐',20841),
('ezk-17-16','ezk','에스겔',17,16,'주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 바벨론 왕이 그를 왕으로 세웠거늘 그가 맹세를 저버리고 언약을 배반하였은즉 그 왕이 거주하는 곳 바벨론에서 왕과 함께 있다가 죽을 것이라',20842),
('ezk-17-17','ezk','에스겔',17,17,'대적이 토성을 쌓고 사다리를 세우고 많은 사람을 멸절하려 할 때에 바로가 그 큰 군대와 많은 무리로도 그 전쟁에 그를 도와 주지 못하리라',20843),
('ezk-17-18','ezk','에스겔',17,18,'그가 이미 손을 내밀어 언약하였거늘 맹세를 업신여겨 언약을 배반하고 이 모든 일을 행하였으니 피하지 못하리라',20844),
('ezk-17-19','ezk','에스겔',17,19,'그러므로 주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 그가 내 맹세를 업신여기고 내 언약을 배반하였은즉 내가 그 죄를 그 머리에 돌리되',20845),
('ezk-17-20','ezk','에스겔',17,20,'그 위에 내 그물을 치며 내 올무에 걸리게 하여 끌고 바벨론으로 가서 나를 반역한 그 반역을 거기에서 심판할지며',20846),
('ezk-17-21','ezk','에스겔',17,21,'그 모든 군대에서 도망한 자들은 다 칼에 엎드러질 것이요 그 남은 자는 사방으로 흩어지리니 나 여호와가 이것을 말한 줄을 너희가 알리라',20847),
('ezk-17-22','ezk','에스겔',17,22,'주 여호와께서 이같이 말씀하시되 내가 백향목 꼭대기에서 높은 가지를 꺾어다가 심으리라 내가 그 높은 새 가지 끝에서 연한 가지를 꺾어 높고 우뚝 솟은 산에 심되',20848),
('ezk-17-23','ezk','에스겔',17,23,'이스라엘 높은 산에 심으리니 그 가지가 무성하고 열매를 맺어서 아름다운 백향목이 될 것이요 각종 새가 그 아래에 깃들이며 그 가지 그늘에 살리라',20849),
('ezk-17-24','ezk','에스겔',17,24,'들의 모든 나무가 나 여호와는 높은 나무를 낮추고 낮은 나무를 높이며 푸른 나무를 말리고 마른 나무를 무성하게 하는 줄 알리라 나 여호와는 말하고 이루느니라 하라',20850),
('ezk-18-1','ezk','에스겔',18,1,'또 여호와의 말씀이 내게 임하여 이르시되',20851),
('ezk-18-2','ezk','에스겔',18,2,'너희가 이스라엘 땅에 관한 속담에 이르기를 아버지가 신 포도를 먹었으므로 그의 아들의 이가 시다고 함은 어찌 됨이냐',20852),
('ezk-18-3','ezk','에스겔',18,3,'주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 너희가 이스라엘 가운데에서 다시는 이 속담을 쓰지 못하게 되리라',20853),
('ezk-18-4','ezk','에스겔',18,4,'모든 영혼이 다 내게 속한지라 아버지의 영혼이 내게 속함 같이 그의 아들의 영혼도 내게 속하였나니 범죄하는 그 영혼은 죽으리라',20854),
('ezk-18-5','ezk','에스겔',18,5,'사람이 만일 의로워서 정의와 공의를 따라 행하며',20855),
('ezk-18-6','ezk','에스겔',18,6,'산 위에서 제물을 먹지 아니하며 이스라엘 족속의 우상에게 눈을 들지 아니하며 이웃의 아내를 더럽히지 아니하며 월경 중에 있는 여인을 가까이 하지 아니하며',20856),
('ezk-18-7','ezk','에스겔',18,7,'사람을 학대하지 아니하며 빚진 자의 저당물을 돌려 주며 강탈하지 아니하며 주린 자에게 음식물을 주며 벗은 자에게 옷을 입히며',20857),
('ezk-18-8','ezk','에스겔',18,8,'변리를 위하여 꾸어 주지 아니하며 이자를 받지 아니하며 스스로 손을 금하여 죄를 짓지 아니하며 사람과 사람 사이에 진실하게 판단하며',20858),
('ezk-18-9','ezk','에스겔',18,9,'내 율례를 따르며 내 규례를 지켜 진실하게 행할진대 그는 의인이니 반드시 살리라 주 여호와의 말씀이니라',20859),
('ezk-18-10','ezk','에스겔',18,10,'가령 그가 아들을 낳았다 하자 그 아들이 이 모든 선은 하나도 행하지 아니하고 이 죄악 중 하나를 범하여 강포하거나 살인하거나',20860),
('ezk-18-11','ezk','에스겔',18,11,'산 위에서 제물을 먹거나 이웃의 아내를 더럽히거나',20861),
('ezk-18-12','ezk','에스겔',18,12,'가난하고 궁핍한 자를 학대하거나 강탈하거나 빚진 자의 저당물을 돌려 주지 아니하거나 우상에게 눈을 들거나 가증한 일을 행하거나',20862),
('ezk-18-13','ezk','에스겔',18,13,'변리를 위하여 꾸어 주거나 이자를 받거나 할진대 그가 살겠느냐 결코 살지 못하리니 이 모든 가증한 일을 행하였은즉 반드시 죽을지라 자기의 피가 자기에게로 돌아가리라',20863),
('ezk-18-14','ezk','에스겔',18,14,'또 가령 그가 아들을 낳았다 하자 그 아들이 그 아버지가 행한 모든 죄를 보고 두려워하여 그대로 행하지 아니하고',20864),
('ezk-18-15','ezk','에스겔',18,15,'산 위에서 제물을 먹지도 아니하며 이스라엘 족속의 우상에게 눈을 들지도 아니하며 이웃의 아내를 더럽히지도 아니하며',20865),
('ezk-18-16','ezk','에스겔',18,16,'사람을 학대하지도 아니하며 저당을 잡지도 아니하며 강탈하지도 아니하고 주린 자에게 음식물을 주며 벗은 자에게 옷을 입히며',20866),
('ezk-18-17','ezk','에스겔',18,17,'손을 금하여 가난한 자를 압제하지 아니하며 변리나 이자를 받지 아니하여 내 규례를 지키며 내 율례를 행할진대 이 사람은 그의 아버지의 죄악으로 죽지 아니하고 반드시 살겠고',20867),
('ezk-18-18','ezk','에스겔',18,18,'그의 아버지는 심히 포학하여 그 동족을 강탈하고 백성들 중에서 선을 행하지 아니하였으므로 그는 그의 죄악으로 죽으리라',20868),
('ezk-18-19','ezk','에스겔',18,19,'그런데 너희는 이르기를 아들이 어찌 아버지의 죄를 담당하지 아니하겠느냐 하는도다 아들이 정의와 공의를 행하며 내 모든 율례를 지켜 행하였으면 그는 반드시 살려니와',20869),
('ezk-18-20','ezk','에스겔',18,20,'범죄하는 그 영혼은 죽을지라 아들은 아버지의 죄악을 담당하지 아니할 것이요 아버지는 아들의 죄악을 담당하지 아니하리니 의인의 공의도 자기에게로 돌아가고 악인의 악도 자기에게로 돌아가리라',20870),
('ezk-18-21','ezk','에스겔',18,21,'그러나 악인이 만일 그가 행한 모든 죄에서 돌이켜 떠나 내 모든 율례를 지키고 정의와 공의를 행하면 반드시 살고 죽지 아니할 것이라',20871),
('ezk-18-22','ezk','에스겔',18,22,'그 범죄한 것이 하나도 기억함이 되지 아니하리니 그가 행한 공의로 살리라',20872),
('ezk-18-23','ezk','에스겔',18,23,'주 여호와의 말씀이니라 내가 어찌 악인이 죽는 것을 조금인들 기뻐하랴 그가 돌이켜 그 길에서 떠나 사는 것을 어찌 기뻐하지 아니하겠느냐',20873),
('ezk-18-24','ezk','에스겔',18,24,'만일 의인이 돌이켜 그 공의에서 떠나 범죄하고 악인이 행하는 모든 가증한 일대로 행하면 살겠느냐 그가 행한 공의로운 일은 하나도 기억함이 되지 아니하리니 그가 그 범한 허물과 그 지은 죄로 죽으리라',20874),
('ezk-18-25','ezk','에스겔',18,25,'그런데 너희는 이르기를 주의 길이 공평하지 아니하다 하는도다 이스라엘 족속아 들을지어다 내 길이 어찌 공평하지 아니하냐 너희 길이 공평하지 아니한 것이 아니냐',20875),
('ezk-18-26','ezk','에스겔',18,26,'만일 의인이 그 공의를 떠나 죄악을 행하고 그로 말미암아 죽으면 그 행한 죄악으로 말미암아 죽는 것이요',20876),
('ezk-18-27','ezk','에스겔',18,27,'만일 악인이 그 행한 악을 떠나 정의와 공의를 행하면 그 영혼을 보전하리라',20877),
('ezk-18-28','ezk','에스겔',18,28,'그가 스스로 헤아리고 그 행한 모든 죄악에서 돌이켜 떠났으니 반드시 살고 죽지 아니하리라',20878),
('ezk-18-29','ezk','에스겔',18,29,'그런데 이스라엘 족속은 이르기를 주의 길이 공평하지 아니하다 하는도다 이스라엘 족속아 나의 길이 어찌 공평하지 아니하냐 너희 길이 공평하지 아니한 것 아니냐',20879),
('ezk-18-30','ezk','에스겔',18,30,'주 여호와의 말씀이니라 이스라엘 족속아 내가 너희 각 사람이 행한 대로 심판할지라 너희는 돌이켜 회개하고 모든 죄에서 떠날지어다 그리한즉 그것이 너희에게 죄악의 걸림돌이 되지 아니하리라',20880),
('ezk-18-31','ezk','에스겔',18,31,'너희는 너희가 범한 모든 죄악을 버리고 마음과 영을 새롭게 할지어다 이스라엘 족속아 너희가 어찌하여 죽고자 하느냐',20881),
('ezk-18-32','ezk','에스겔',18,32,'주 여호와의 말씀이니라 죽을 자가 죽는 것도 내가 기뻐하지 아니하노니 너희는 스스로 돌이키고 살지니라',20882),
