('ezk-19-3','ezk','에스겔',19,3,'그 새끼 하나를 키우매 젊은 사자가 되어 먹이 물어뜯기를 배워 사람을 삼키매',20885),
('ezk-19-4','ezk','에스겔',19,4,'이방이 듣고 함정으로 그를 잡아 갈고리로 꿰어 끌고 애굽 땅으로 간지라',20886),
