('ezk-19-9','ezk','에스겔',19,9,'우리에 넣고 갈고리를 꿰어 끌고 바벨론 왕에게 이르렀나니 그를 옥에 가두어 그 소리가 다시 이스라엘 산에 들리지 아니하게 하려 함이라',20891),
('ezk-19-10','ezk','에스겔',19,10,'네 피의 어머니는 물 가에 심겨진 포도나무 같아서 물이 많으므로 열매가 많고 가지가 무성하며',20892),
('ezk-19-11','ezk','에스겔',19,11,'그 가지들은 강하여 권세 잡은 자의 규가 될 만한데 그 하나의 키가 굵은 가지 가운데에서 높았으며 많은 가지 가운데에서 뛰어나 보이다가',20893),
('ezk-19-12','ezk','에스겔',19,12,'분노 중에 뽑혀서 땅에 던짐을 당하매 그 열매는 동풍에 마르고 그 강한 가지들은 꺾이고 말라 불에 탔더니',20894),
('ezk-19-13','ezk','에스겔',19,13,'이제는 광야, 메마르고 가물이 든 땅에 심어진 바 되고',20895),
('ezk-19-14','ezk','에스겔',19,14,'불이 그 가지 중 하나에서부터 나와 그 열매를 태우니 권세 잡은 자의 규가 될 만한 강한 가지가 없도다 하라 이것이 애가라 후에도 애가가 되리라',20896),
('ezk-20-1','ezk','에스겔',20,1,'일곱째 해 다섯째 달 열째 날에 이스라엘 장로 여러 사람이 여호와께 물으려고 와서 내 앞에 앉으니',20897),
('ezk-20-2','ezk','에스겔',20,2,'여호와의 말씀이 내게 임하여 이르시되',20898),
