('ezk-20-4','ezk','에스겔',20,4,'인자야 네가 그들을 심판하려느냐 네가 그들을 심판하려느냐 너는 그들에게 그들의 조상들의 가증한 일을 알게 하여',20900),
('ezk-20-5','ezk','에스겔',20,5,'이르라 주 여호와께서 이같이 말씀하셨느니라 옛날에 내가 이스라엘을 택하고 야곱 집의 후예를 향하여 내 손을 들어 맹세하고 애굽 땅에서 그들에게 나타나 맹세하여 이르기를 나는 여호와 너희 하나님이라 하였노라',20901),
('ezk-20-6','ezk','에스겔',20,6,'그 날에 내가 내 손을 들어 그들에게 맹세하기를 애굽 땅에서 인도하여 내어 그들을 위하여 찾아 두었던 땅 곧 젖과 꿀이 흐르는 땅이요 모든 땅 중의 아름다운 곳에 이르게 하리라 하고',20902),
('ezk-20-7','ezk','에스겔',20,7,'또 그들에게 이르기를 너희는 눈을 끄는 바 가증한 것을 각기 버리고 애굽의 우상들로 말미암아 스스로 더럽히지 말라 나는 여호와 너희 하나님이니라 하였으나',20903),
('ezk-20-8','ezk','에스겔',20,8,'그들이 내게 반역하여 내 말을 즐겨 듣지 아니하고 그들의 눈을 끄는 바 가증한 것을 각기 버리지 아니하며 애굽의 우상들을 떠나지 아니하므로 내가 말하기를 내가 애굽 땅에서 그들에게 나의 분노를 쏟으며 그들에게 진노를 이루리라 하였노라',20904),
('ezk-20-9','ezk','에스겔',20,9,'그러나 내가 그들이 거주하는 이방인의 눈 앞에서 그들에게 나타나 그들을 애굽 땅에서 인도하여 내었나니 이는 내 이름을 위함이라 내 이름을 그 이방인의 눈 앞에서 더럽히지 아니하려고 행하였음이라',20905),
('ezk-20-10','ezk','에스겔',20,10,'그러므로 내가 그들을 애굽 땅에서 나와서 광야에 이르게 하고',20906),
('ezk-20-11','ezk','에스겔',20,11,'사람이 준행하면 그로 말미암아 삶을 얻을 내 율례를 주며 내 규례를 알게 하였고',20907),
('ezk-20-12','ezk','에스겔',20,12,'또 내가 그들을 거룩하게 하는 여호와인 줄 알게 하려고 내 안식일을 주어 그들과 나 사이에 표징을 삼았노라',20908),
('ezk-20-13','ezk','에스겔',20,13,'그러나 이스라엘 족속이 광야에서 내게 반역하여 사람이 준행하면 그로 말미암아 삶을 얻을 나의 율례를 준행하지 아니하며 나의 규례를 멸시하였고 나의 안식일을 크게 더럽혔으므로 내가 이르기를 내가 내 분노를 광야에서 그들에게 쏟아 멸하리라 하였으나',20909),
('ezk-20-14','ezk','에스겔',20,14,'내가 내 이름을 위하여 달리 행하였었나니 내가 그들을 인도하여 내는 것을 본 나라들 앞에서 내 이름을 더럽히지 아니하려 하였음이로라',20910),
('ezk-20-15','ezk','에스겔',20,15,'또 내가 내 손을 들어 광야에서 그들에게 맹세하기를 내가 그들에게 허락한 땅 곧 젖과 꿀이 흐르는 땅이요 모든 땅 중의 아름다운 곳으로 그들을 인도하여 들이지 아니하리라 한 것은',20911),
('ezk-20-16','ezk','에스겔',20,16,'그들이 마음으로 우상을 따라 나의 규례를 업신여기며 나의 율례를 행하지 아니하며 나의 안식일을 더럽혔음이라',20912),
('ezk-20-17','ezk','에스겔',20,17,'그러나 내가 그들을 아껴서 광야에서 멸하여 아주 없이하지 아니하였었노라',20913),
('ezk-20-18','ezk','에스겔',20,18,'내가 광야에서 그들의 자손에게 이르기를 너희 조상들의 율례를 따르지 말며 그 규례를 지키지 말며 그 우상들로 말미암아 스스로 더럽히지 말라',20914),
('ezk-20-19','ezk','에스겔',20,19,'나는 여호와 너희 하나님이라 너희는 나의 율례를 따르며 나의 규례를 지켜 행하고',20915),
('ezk-20-20','ezk','에스겔',20,20,'또 나의 안식일을 거룩하게 할지어다 이것이 나와 너희 사이에 표징이 되어 내가 여호와 너희 하나님인 줄을 너희가 알게 하리라 하였노라',20916),
('ezk-20-21','ezk','에스겔',20,21,'그러나 그들의 자손이 내게 반역하여 사람이 지켜 행하면 그로 말미암아 삶을 얻을 나의 율례를 따르지 아니하며 나의 규례를 지켜 행하지 아니하였고 나의 안식일을 더럽힌지라 이에 내가 이르기를 내가 광야에서 그들에게 내 분노를 쏟으며 그들에게 내 진노를 이루리라 하였으나',20917),
('ezk-20-22','ezk','에스겔',20,22,'내가 내 이름을 위하여 내 손을 막아 달리 행하였나니 내가 그들을 인도하여 내는 것을 본 여러 나라 앞에서 내 이름을 더럽히지 아니하려 하였음이로라',20918),
('ezk-20-23','ezk','에스겔',20,23,'또 내가 내 손을 들어 광야에서 그들에게 맹세하기를 내가 그들을 이방인 중에 흩으며 여러 민족 가운데에 헤치리라 하였나니',20919),
('ezk-20-24','ezk','에스겔',20,24,'이는 그들이 나의 규례를 행하지 아니하며 나의 율례를 멸시하며 내 안식일을 더럽히고 눈으로 그들의 조상들의 우상들을 사모함이며',20920),
('ezk-20-25','ezk','에스겔',20,25,'또 내가 그들에게 선하지 못한 율례와 능히 지키지 못할 규례를 주었고',20921),
('ezk-20-26','ezk','에스겔',20,26,'그들이 장자를 다 화제로 드리는 그 예물로 내가 그들을 더럽혔음은 그들을 멸망하게 하여 나를 여호와인 줄 알게 하려 하였음이라',20922),
('ezk-20-27','ezk','에스겔',20,27,'그런즉 인자야 이스라엘 족속에게 말하여 이르라 주 여호와께서 이같이 말씀하셨느니라 너희 조상들이 또 내게 범죄하여 나를 욕되게 하였느니라',20923),
('ezk-20-28','ezk','에스겔',20,28,'내가 내 손을 들어 그들에게 주기로 맹세한 땅으로 그들을 인도하여 들였더니 그들이 모든 높은 산과 모든 무성한 나무를 보고 거기에서 제사를 드리고 분노하게 하는 제물을 올리며 거기서 또 분향하고 전제물을 부어 드린지라',20924),
('ezk-20-29','ezk','에스겔',20,29,'이에 내가 그들에게 이르기를 너희가 다니는 산당이 무엇이냐 하였노라 (그것을 오늘날까지 바마라 일컫느니라)',20925),
('ezk-20-30','ezk','에스겔',20,30,'그러므로 너는 이스라엘 족속에게 이르라 주 여호와께서 이같이 말씀하셨느니라 너희가 조상들의 풍속을 따라 너희 자신을 더럽히며 그 모든 가증한 것을 따라 행음하느냐',20926),
('ezk-20-31','ezk','에스겔',20,31,'너희가 또 너희 아들을 화제로 삼아 불 가운데로 지나게 하며 오늘까지 너희 자신을 우상들로 말미암아 더럽히느냐 이스라엘 족속아 너희가 내게 묻기를 내가 용납하겠느냐 주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 너희가 내게 묻기를 내가 용납하지 아니하리라',20927),
('ezk-20-32','ezk','에스겔',20,32,'너희가 스스로 이르기를 우리가 이방인 곧 여러 나라 족속 같이 되어서 목석을 경배하리라 하거니와 너희 마음에 품은 것을 결코 이루지 못하리라',20928),
('ezk-20-33','ezk','에스겔',20,33,'주 여호와의 말씀이니라 내가 나의 삶을 두고 맹세하노니 내가 능한 손과 편 팔로 분노를 쏟아 너희를 반드시 다스릴지라',20929),
('ezk-20-34','ezk','에스겔',20,34,'능한 손과 편 팔로 분노를 쏟아 너희를 여러 나라에서 나오게 하며 너희의 흩어진 여러 지방에서 모아내고',20930),
('ezk-20-35','ezk','에스겔',20,35,'너희를 인도하여 여러 나라 광야에 이르러 거기에서 너희를 대면하여 심판하되',20931),
('ezk-20-36','ezk','에스겔',20,36,'내가 애굽 땅 광야에서 너희 조상들을 심판한 것 같이 너희를 심판하리라 주 여호와의 말씀이니라',20932),
('ezk-20-37','ezk','에스겔',20,37,'내가 너희를 막대기 아래로 지나가게 하며 언약의 줄로 매려니와',20933),
('ezk-20-38','ezk','에스겔',20,38,'너희 가운데에서 반역하는 자와 내게 범죄하는 자를 모두 제하여 버릴지라 그들을 그 머물러 살던 땅에서는 나오게 하여도 이스라엘 땅에는 들어가지 못하게 하리니 너희가 나는 여호와인 줄을 알리라',20934),
('ezk-20-39','ezk','에스겔',20,39,'주 여호와께서 이같이 말씀하셨느니라 이스라엘 족속아 너희가 내 말을 듣지 아니하려거든 가서 각각 그 우상을 섬기라 그렇게 하려거든 이 후에 다시는 너희 예물과 너희 우상들로 내 거룩한 이름을 더럽히지 말지니라',20935),
('ezk-20-40','ezk','에스겔',20,40,'주 여호와의 말씀이니라 이스라엘 온 족속이 그 땅에 있어서 내 거룩한 산 곧 이스라엘의 높은 산에서 다 나를 섬기리니 거기에서 내가 그들을 기쁘게 받을지라 거기에서 너희 예물과 너희가 드리는 첫 열매와 너희 모든 성물을 요구하리라',20936),
('ezk-20-41','ezk','에스겔',20,41,'내가 너희를 인도하여 여러 나라 가운데에서 나오게 하고 너희가 흩어진 여러 민족 가운데에서 모아 낼 때에 내가 너희를 향기로 받고 내가 또 너희로 말미암아 내 거룩함을 여러 나라의 목전에서 나타낼 것이며',20937),
('ezk-20-42','ezk','에스겔',20,42,'내가 내 손을 들어 너희 조상들에게 주기로 맹세한 땅 곧 이스라엘 땅으로 너희를 인도하여 들일 때에 너희는 내가 여호와인 줄 알고',20938),
('ezk-20-43','ezk','에스겔',20,43,'거기에서 너희의 길과 스스로 더럽힌 모든 행위를 기억하고 이미 행한 모든 악으로 말미암아 스스로 미워하리라',20939),
('ezk-20-44','ezk','에스겔',20,44,'이스라엘 족속아 내가 너희의 악한 길과 더러운 행위대로 하지 아니하고 내 이름을 위하여 행한 후에야 내가 여호와인 줄 너희가 알리라 주 여호와의 말씀이니라',20940),
('ezk-20-45','ezk','에스겔',20,45,'여호와의 말씀이 또 내게 임하여 이르시되',20941),
('ezk-20-46','ezk','에스겔',20,46,'인자야 너는 얼굴을 남으로 향하라 남으로 향하여 소리내어 남쪽의 숲을 쳐서 예언하라',20942),
('ezk-20-47','ezk','에스겔',20,47,'남쪽의 숲에게 이르기를 여호와의 말씀을 들을지어다 주 여호와께서 이같이 말씀하셨느니라 내가 너의 가운데에 불을 일으켜 모든 푸른 나무와 모든 마른 나무를 없애리니 맹렬한 불꽃이 꺼지지 아니하고 남에서 북까지 모든 얼굴이 그슬릴지라',20943),
('ezk-20-48','ezk','에스겔',20,48,'혈기 있는 모든 자는 나 여호와가 그 불을 일으킨 줄을 알리니 그것이 꺼지지 아니하리라 하셨다 하라 하시기로',20944),
('ezk-20-49','ezk','에스겔',20,49,'내가 이르되 아하 주 여호와여 그들이 나를 가리켜 말하기를 그는 비유로 말하는 자가 아니냐 하나이다 하니라',20945),
('ezk-21-1','ezk','에스겔',21,1,'또 여호와의 말씀이 내게 임하여 이르시되',20946),
('ezk-21-2','ezk','에스겔',21,2,'인자야 너는 얼굴을 예루살렘으로 향하며 성소를 향하여 소리내어 이스라엘 땅에게 예언하라',20947),
('ezk-21-3','ezk','에스겔',21,3,'이스라엘 땅에게 이르기를 여호와의 말씀에 내가 너를 대적하여 내 칼을 칼집에서 빼어 의인과 악인을 네게서 끊을지라',20948),
('ezk-21-4','ezk','에스겔',21,4,'내가 의인과 악인을 네게서 끊을 터이므로 내 칼을 칼집에서 빼어 모든 육체를 남에서 북까지 치리니',20949),
('ezk-21-5','ezk','에스겔',21,5,'모든 육체는 나 여호와가 내 칼을 칼집에서 빼낸 줄을 알지라 칼이 다시 꽂히지 아니하리라 하셨다 하라',20950),
('ezk-21-6','ezk','에스겔',21,6,'인자야 탄식하되 너는 허리가 끊어지듯 탄식하라 그들의 목전에서 슬피 탄식하라',20951),
('ezk-21-7','ezk','에스겔',21,7,'그들이 네게 묻기를 네가 어찌하여 탄식하느냐 하거든 대답하기를 재앙이 다가온다는 소문 때문이니 각 마음이 녹으며 모든 손이 약하여지며 각 영이 쇠하며 모든 무릎이 물과 같이 약해지리라 보라 재앙이 오나니 반드시 이루어지리라 주 여호와의 말씀이니라 하라',20952),
('ezk-21-8','ezk','에스겔',21,8,'여호와의 말씀이 또 내게 임하여 이르시되',20953),
('ezk-21-9','ezk','에스겔',21,9,'인자야 너는 예언하여 여호와의 말씀을 이같이 말하라 칼이여 칼이여 날카롭고도 빛나도다',20954),
('ezk-21-10','ezk','에스겔',21,10,'그 칼이 날카로움은 죽임을 위함이요 빛남은 번개 같이 되기 위함이니 우리가 즐거워하겠느냐 내 아들의 규가 모든 나무를 업신여기는도다',20955),
('ezk-21-11','ezk','에스겔',21,11,'그 칼을 손에 잡아 쓸 만하도록 빛나게 하되 죽이는 자의 손에 넘기기 위하여 날카롭고도 빛나게 하였도다 하셨다 하라',20956),
('ezk-21-12','ezk','에스겔',21,12,'인자야 너는 부르짖어 슬피 울지어다 이것이 내 백성에게 임하며 이스라엘 모든 고관에게 임함이로다 그들과 내 백성이 함께 칼에 넘긴 바 되었으니 너는 네 넓적다리를 칠지어다',20957),
('ezk-21-13','ezk','에스겔',21,13,'이것이 시험이라 만일 업신여기는 규가 없어지면 어찌할까 주 여호와의 말씀이니라',20958),
('ezk-21-14','ezk','에스겔',21,14,'그러므로 인자야 너는 예언하며 손뼉을 쳐서 칼로 두세 번 거듭 쓰이게 하라 이 칼은 죽이는 칼이라 사람들을 둘러싸고 죽이는 큰 칼이로다',20959),
('ezk-21-15','ezk','에스겔',21,15,'내가 그들이 낙담하여 많이 엎드러지게 하려고 그 모든 성문을 향하여 번쩍번쩍하는 칼을 세워 놓았도다 오호라 그 칼이 번개 같고 죽이기 위하여 날카로웠도다',20960),
('ezk-21-16','ezk','에스겔',21,16,'칼아 모이라 오른쪽을 치라 대열을 맞추라 왼쪽을 치라 향한 대로 가라',20961),
('ezk-21-17','ezk','에스겔',21,17,'나도 내 손뼉을 치며 내 분노를 다 풀리로다 나 여호와가 말하였노라',20962),
('ezk-21-18','ezk','에스겔',21,18,'여호와의 말씀이 내게 임하여 이르시되',20963),
('ezk-21-19','ezk','에스겔',21,19,'인자야 너는 바벨론 왕의 칼이 올 두 길을 한 땅에서 나오도록 그리되 곧 성으로 들어가는 길 어귀에다가 길이 나뉘는 지시표를 하여',20964),
('ezk-21-20','ezk','에스겔',21,20,'칼이 암몬 족속의 랍바에 이르는 길과 유다의 견고한 성 예루살렘에 이르는 길을 그리라',20965),
('ezk-21-21','ezk','에스겔',21,21,'바벨론 왕이 갈랫길 곧 두 길 어귀에 서서 점을 치되 화살들을 흔들어 우상에게 묻고 희생제물의 간을 살펴서',20966),
('ezk-21-22','ezk','에스겔',21,22,'오른손에 예루살렘으로 갈 점괘를 얻었으므로 공성퇴를 설치하며 입을 벌리고 죽이며 소리를 높여 외치며 성문을 향하여 공성퇴를 설치하고 토성을 쌓고 사다리를 세우게 되었나니',20967),
('ezk-21-23','ezk','에스겔',21,23,'전에 그들에게 맹약한 자들은 그것을 거짓 점괘로 여길 것이나 바벨론 왕은 그 죄악을 기억하고 그 무리를 잡으리라',20968),
('ezk-21-24','ezk','에스겔',21,24,'그러므로 주 여호와께서 이같이 말씀하셨느니라 너희의 악이 기억을 되살리며 너희의 허물이 드러나며 너희 모든 행위의 죄가 나타났도다 너희가 기억한 바 되었은즉 그 손에 잡히리라',20969),
('ezk-21-25','ezk','에스겔',21,25,'너 극악하여 중상을 당할 이스라엘 왕아 네 날이 이르렀나니 곧 죄악의 마지막 때이니라',20970),
('ezk-21-26','ezk','에스겔',21,26,'주 여호와께서 이같이 말씀하셨느니라 관을 제거하며 왕관을 벗길지라 그대로 두지 못하리니 낮은 자를 높이고 높은 자를 낮출 것이니라',20971),
('ezk-21-27','ezk','에스겔',21,27,'내가 엎드러뜨리고 엎드러뜨리고 엎드러뜨리려니와 이것도 다시 있지 못하리라 마땅히 얻을 자가 이르면 그에게 주리라',20972),
('ezk-21-28','ezk','에스겔',21,28,'인자야 너는 주 여호와께서 암몬 족속과 그의 능욕에 대하여 이같이 말씀하셨다고 예언하라 너는 이르기를 칼이 뽑히도다 칼이 뽑히도다 죽이며 멸절하며 번개 같이 되기 위하여 빛났도다',20973),
('ezk-21-29','ezk','에스겔',21,29,'네게 대하여 허무한 것을 보며 네게 대하여 거짓 복술을 하는 자가 너를 중상 당한 악인의 목 위에 두리니 이는 그의 날 곧 죄악의 마지막 때가 이름이로다',20974),
('ezk-21-30','ezk','에스겔',21,30,'그러나 칼을 그 칼집에 꽂을지어다 네가 지음을 받은 곳에서, 네가 출생한 땅에서 내가 너를 심판하리로다',20975),
('ezk-21-31','ezk','에스겔',21,31,'내가 내 분노를 네게 쏟으며 내 진노의 불을 네게 내뿜고 너를 짐승 같은 자 곧 멸하기에 익숙한 자의 손에 넘기리로다',20976),
('ezk-21-32','ezk','에스겔',21,32,'네가 불에 섶과 같이 될 것이며 네 피가 나라 가운데에 있을 것이며 네가 다시 기억되지 못할 것이니 나 여호와가 말하였음이라 하라',20977),
('ezk-22-1','ezk','에스겔',22,1,'또 여호와의 말씀이 내게 임하여 이르시되',20978),
('ezk-22-2','ezk','에스겔',22,2,'인자야 네가 심판하려느냐 이 피흘린 성읍을 심판하려느냐 그리하려거든 자기의 모든 가증한 일을 그들이 알게 하라',20979),
('ezk-22-3','ezk','에스겔',22,3,'너는 말하라 주 여호와께서 이같이 말씀하셨느니라 자기 가운데에 피를 흘려 벌 받을 때가 이르게 하며 우상을 만들어 스스로 더럽히는 성아',20980),
('ezk-22-4','ezk','에스겔',22,4,'네가 흘린 피로 말미암아 죄가 있고 네가 만든 우상으로 말미암아 스스로 더럽혔으니 네 날이 가까웠고 네 연한이 찼도다 그러므로 내가 너로 이방의 능욕을 받으며 만국의 조롱 거리가 되게 하였노라',20981),
('ezk-22-5','ezk','에스겔',22,5,'너 이름이 더럽고 어지러움이 많은 자여 가까운 자나 먼 자나 다 너를 조롱하리라',20982),
('ezk-22-6','ezk','에스겔',22,6,'이스라엘 모든 고관은 각기 권세대로 피를 흘리려고 네 가운데에 있었도다',20983),
('ezk-22-7','ezk','에스겔',22,7,'그들이 네 가운데에서 부모를 업신여겼으며 네 가운데에서 나그네를 학대하였으며 네 가운데에서 고아와 과부를 해하였도다',20984),
('ezk-22-8','ezk','에스겔',22,8,'너는 나의 성물들을 업신여겼으며 나의 안식일을 더럽혔으며',20985),
('ezk-22-9','ezk','에스겔',22,9,'네 가운데에 피를 흘리려고 이간을 붙이는 자도 있었으며 네 가운데에 산 위에서 제물을 먹는 자도 있었으며 네 가운데에 음행하는 자도 있었으며',20986),
('ezk-22-10','ezk','에스겔',22,10,'네 가운데에 자기 아버지의 하체를 드러내는 자도 있었으며 네 가운데에 월경하는 부정한 여인과 관계하는 자도 있었으며',20987),
('ezk-22-11','ezk','에스겔',22,11,'어떤 사람은 그 이웃의 아내와 가증한 일을 행하였으며 어떤 사람은 그의 며느리를 더럽혀 음행하였으며 네 가운데에 어떤 사람은 그 자매 곧 아버지의 딸과 관계하였으며',20988),
('ezk-22-12','ezk','에스겔',22,12,'네 가운데에 피를 흘리려고 뇌물을 받는 자도 있었으며 네가 변돈과 이자를 받았으며 이익을 탐하여 이웃을 속여 빼앗았으며 나를 잊어버렸도다 주 여호와의 말씀이니라',20989),
('ezk-22-13','ezk','에스겔',22,13,'네가 불의를 행하여 이익을 얻은 일과 네 가운데에 피 흘린 일로 말미암아 내가 손뼉을 쳤나니',20990),
('ezk-22-14','ezk','에스겔',22,14,'내가 네게 보응하는 날에 네 마음이 견디겠느냐 네 손이 힘이 있겠느냐 나 여호와가 말하였으니 내가 이루리라',20991),
('ezk-22-15','ezk','에스겔',22,15,'내가 너를 뭇 나라 가운데에 흩으며 각 나라에 헤치고 너의 더러운 것을 네 가운데에서 멸하리라',20992),
('ezk-22-16','ezk','에스겔',22,16,'네가 자신 때문에 나라들의 목전에서 수치를 당하리니 내가 여호와인 줄 알리라 하셨다 하라',20993),
('ezk-22-17','ezk','에스겔',22,17,'여호와의 말씀이 내게 임하여 이르시되',20994),
('ezk-22-18','ezk','에스겔',22,18,'인자야 이스라엘 족속이 내게 찌꺼기가 되었나니 곧 풀무 불 가운데에 있는 놋이나 주석이나 쇠나 납이며 은의 찌꺼기로다',20995),
('ezk-22-19','ezk','에스겔',22,19,'그러므로 주 여호와께서 이와 같이 말씀하셨느니라 너희가 다 찌꺼기가 되었은즉 내가 너희를 예루살렘 가운데로 모으고',20996),
('ezk-22-20','ezk','에스겔',22,20,'사람이 은이나 놋이나 쇠나 납이나 주석이나 모아서 풀무 불 속에 넣고 불을 불어 녹이는 것 같이 내가 노여움과 분으로 너희를 모아 거기에 두고 녹이리라',20997),
('ezk-22-21','ezk','에스겔',22,21,'내가 너희를 모으고 내 분노의 불을 너희에게 불면 너희가 그 가운데에서 녹되',20998),
('ezk-22-22','ezk','에스겔',22,22,'은이 풀무 불 가운데에서 녹는 것 같이 너희가 그 가운데에서 녹으리니 나 여호와가 분노를 너희 위에 쏟은 줄을 너희가 알리라',20999),
('ezk-22-23','ezk','에스겔',22,23,'여호와의 말씀이 내게 임하여 이르시되',21000)
on conflict (id) do update set
  book_key = excluded.book_key,
  book_name = excluded.book_name,
  chapter = excluded.chapter,
  verse = excluded.verse,
  content = excluded.content,
  sort_order = excluded.sort_order;
